/* Catalogue update of 2026-10-29.
   - OCT29_REMOVED: NYC DYCD "Out of School Time" sites at elementary, intermediate
     and middle schools (P.S., I.S., M.S., C.E.S.), which serve younger grades, not high
     school. Their old URLs go to the NYC hub.
   - OCT29_FIXES: rewritten descriptions for thin listings, each from the
     program's official page. */

import type { Opportunity } from "@/data/opportunities";

export const OCT29_FIXES: Record<string, Partial<Opportunity>> = {
  // https://about.asianart.org/art-speak/
  "asian-art-museum-art-speak": { blurb: "A paid internship at the Asian Art Museum in San Francisco for students in grades 10 through 12, with no prior museum experience required. Interns learn about Asian art, work with local artists, interview museum staff about arts careers, and design and teach art activities for visitors on Sundays. The program has a summer session and an academic-year session that meet Thursday afternoons and Sundays, and interns earn a $300 stipend." },
  // https://www.wavehill.org/education/youth-internships/aces
  "wave-hill-aces": { blurb: "A paid, year-long internship at Wave Hill in the Bronx for New York City high school students. Interns help run the Family Art Project, a nature-inspired art program for families, assist with a related storytime, and work together to create a weekend workshop for Wave Hill families as a final project. Interns work about four to eight hours each weekend at $17 per hour and also take field trips to cultural institutions and natural areas." },
  // https://madmuseum.org/learn/artslife
  "mad-artslife": { blurb: "A paid summer internship at the Museum of Arts and Design in New York City for 10 rising sophomores and juniors from New York City public and charter high schools. After a first week of team building and an introduction to the museum, interns work on group projects with museum staff, local designers, and arts professionals who serve as mentors. Interns develop and lead peer-to-peer tours and can create a podcast series on a topic they choose." },
  // https://artswestchester.org/internships-at-artswestchester/
  "artswestchester-internship": { blurb: "Internships at ArtsWestchester, a nonprofit arts council in White Plains, open to high school juniors and seniors. Interns support the organization's work in roles such as an Arts in Education intern or a business administration intern. The hybrid positions have a flexible schedule of about 10 to 12 hours a week over two or three weekdays. Internships are typically unpaid, though ArtsWestchester may cover travel costs." },
  // https://precollege.barnard.edu/athena-summer-innovation-institute-1
  "barnard-athena-summer-innovation": { blurb: "A three-week entrepreneurship boot camp from Barnard College and its Athena Center for Leadership for rising sophomores, juniors, and seniors. Teams build a startup, nonprofit, or advocacy campaign while studying product ideation, customer research, branding, marketing, and startup finances. Students meet with a Mentor-in-Residence, and the program ends with a Pitchfest where teams present their ideas. It runs in New York City from late June into July." },
  // https://go.the-bac.edu/summer-academy-boston
  "bac-summer-academy": { blurb: "A summer architecture and design studio at the Boston Architectural College for high school students. Students practice ideation, sketching, drawing, digital design, digital fabrication, model making, and presentation skills, often working toward a group design project. The Boston program meets on weekday afternoons in July and is non-residential, so housing is not provided. The college offers scholarships through its Pre-College Design Access Fund." },
  // https://ansep.net/high-school/acceleration-academy
  "state-alaska-ansep-acceleration": { blurb: "A free program from the Alaska Native Science & Engineering Program where Alaska high school students in grades 9 through 12 take university courses that count toward both high school graduation and a college degree. The full-time school-year version meets weekdays at sites in Anchorage, Mat-Su, Bethel, Nome, and Kotzebue. A five-week summer session lets students live on the UAA campus while taking one college course. Students interested in any degree program may apply." },
  // https://keys.arizona.edu/
  "state-arizona-keys": { blurb: "A seven-week summer research internship run by the University of Arizona BIO5 Institute for Arizona high school students. Interns work in university research labs with faculty mentors after first completing assignments in science literacy, data science, and biotechnology, and they present their work at a public showcase. Applicants must be at least 16, U.S. citizens or permanent residents, and Arizona residents for at least one year, with cohorts in Tucson and Phoenix." },
  // https://cosmos-ucop.ucdavis.edu/app/main/page/program-overview
  "state-california-cosmos": { blurb: "COSMOS is a four-week summer residential STEM program run by the University of California for California high school students. Students apply to one UC campus and join a cluster of two science or math courses plus a science communication course, working with UC faculty and researchers and completing a related research project. Clusters usually have 20 to 25 students, and participants live on campus. The program cost is $5,793." },
  // https://www.udel.edu/apply/undergraduate-admissions/precollege-programs/edge/
  "state-delaware-edge": { blurb: "A residential summer college program at the University of Delaware for rising high school juniors and seniors with a 3.0 or higher GPA. Students take one or two courses taught by UD faculty for up to six transferable credits, plus a required seminar on the transition to college. The program runs from mid-July into early August, and the $5,495 fee covers tuition, housing, meals, and campus recreation. Limited need-based scholarships are available." },
  // https://www.imsa.edu/admissions/eligibility/
  "state-illinois-imsa": { blurb: "The Illinois Mathematics and Science Academy is a public residential high school in Aurora for Illinois students with strong interest in math and science. Applicants must be Illinois residents and have completed or be taking Algebra 1 and a high school science course, and students apply before tenth grade since current tenth through twelfth graders are not eligible. There is no minimum test score, and the fee is based on family income and size." },
  // https://belinblank.education.uiowa.edu/students/sstp/
  "state-iowa-sstp": { blurb: "A selective summer research program at the University of Iowa Belin-Blank Center where high school students in grades 10 and 11 work on research projects in university labs with faculty mentors. The in-person program lasts 5.5 weeks from June into July and begins with a two-day orientation. Participants enroll as University of Iowa students and earn 3 semester hours of credit when they complete the program." },
  // https://mites.mit.edu/discover-mites/mites-semester/
  "state-massachusetts-mites": { blurb: "A free six-month STEM and college-prep program from MIT for students in 11th grade, run mostly online from June through December. In the summer, students take two online STEM courses on weekday evenings, spending 25 to 30 hours a week, and present team projects at a symposium. The fall phase takes 3 to 5 hours a week and focuses on college application support. Applicants must be U.S. citizens or permanent residents." },
  // https://www.muw.edu/news/mississippi-governors-school-applications-open-for-2027-summer-program/
  "state-mississippi-governors-school": { blurb: "A two-week residential honors program at Mississippi University for Women for Mississippi students finishing 10th or 11th grade who show advanced ability in an area such as academics, creative thinking, leadership, or the arts. Tuition, room, meals, and program activities are free for selected scholars. Students live on campus in June and earn three hours of honors college credit." },
  // https://montanalearning.org/student-programs/
  "state-montana-learning-center": { blurb: "Residential STEM summer camps run by the Montana Learning Center on the shores of Canyon Ferry Lake near Helena. Camps for high school students include Camp Explore the Universe, a five-day overnight astronomy camp using the center's telescopes, a six-day overnight Camp Extreme Yellowstone, and Camp Dinosaur, run with the Carter County Museum for $1,495. Scholarships are available." },
  // https://www.govstemscholars.com/program
  "state-new-jersey-stem-scholars": { blurb: "A free, year-long STEM program led by the Research & Development Council of New Jersey with the Governor's Office and state education agencies, open to New Jersey students in 10th through 12th grade and college. Scholars attend four Saturday conferences on government, academia, and industry plus a commencement, and they complete a year-long research or engineering design project tied to the UN Sustainable Development Goals. Applicants are expected to have a 3.5 GPA or higher." },
  // https://supercomputingchallenge.org/
  "state-new-mexico-supercomputing": { blurb: "A year-long statewide research competition where New Mexico students in grades 4 through 12 turn their questions into computational research projects. Teams use modeling, simulation, and data analysis on topics such as artificial intelligence and machine learning, environmental science, engineering, data science, and social impact. Recent winning high school projects have covered neutron stars, surface reconstruction, and machine learning to detect orbital debris." },
  // https://www.osc.edu/education/si
  "state-ohio-osc-si": { blurb: "A residential summer program at the Ohio Supercomputer Center, now called the STEM Institute, for Ohio high school students currently in their freshman, sophomore, or junior year. Working in small teams, students use the center's supercomputers to solve science and engineering problems, practice network forensics, study bird flu, and design computer games. Students live in Ohio State dorms in Columbus in June, and the center covers half the program cost." },
  // https://oaiquartz.org/OSAI
  "state-oklahoma-osai": { blurb: "A two-week residential arts program at Quartz Mountain State Park in southwest Oklahoma for artistically advanced Oklahoma high school students. Students train with professionals in acting, chorus, creative writing, dance, drawing and painting, film and video, orchestra, or photography. Selected students receive a full scholarship and pay a $375 commitment fee, and the program takes place in June with about 230 spots each year." },
  // https://www.saturdayacademy.org/ase
  "state-oregon-saturday-ase": { blurb: "A summer internship program from Saturday Academy, now called Apprenticeships in STEAM Exploration, that places rising 10th, 11th, and 12th graders with STEM mentors in the Portland and Corvallis areas. Internships last four to eight weeks, part-time or full-time, and are designed by the mentors themselves. Interns receive a learning stipend of $1,500, $1,000, or $500 based on total hours, and the application has a $40 fee that is waived for some students." },
  // https://www.nyc.gov/site/dycd/services/jobs-internships/syep-career-ready.page
  "nyc-careerready": { blurb: "A school-based track of the New York City Summer Youth Employment Program, run by the Department of Youth and Community Development (DYCD), for students ages 14 to 21 at select NYC public schools. Students explore careers through work-readiness training and paid work experience, with paid project-based activities for ages 14 to 15 and summer jobs for older teens. Schools select participants instead of the SYEP lottery, and the program runs for six weeks in July and August." },
  // https://industryscholarsprogram.com/for-students/
  "nyc-industry-scholars": { blurb: "A paid internship program funded by the New York City Public Schools Office of Student Pathways for students at FutureReadyNYC and Career and Technical Education (CTE) high schools. Students spend six weeks during the school year interning at a company in their academic field, in sectors such as healthcare, IT, and construction. Interns attend a pre-internship orientation, submit regular timesheets, and are paid the New York State minimum hourly wage every two weeks." },
  // https://www.nyc.gov/site/dcas/employment/internship-and-fellowships-high-school-automotive-internship-program.page
  "dcas-auto-hs": { blurb: "A paid internship run by the NYC Department of Citywide Administrative Services (DCAS) for students at NYC Public Schools career and technical education automotive high schools. Interns work in city vehicle garages at agencies such as NYPD, FDNY, DSNY, DOT, and Parks, diagnosing equipment, performing basic maintenance, and learning fleet management. The program runs year-round, and summer internships start in early July and last six weeks or 150 hours." },
  // https://www.schools.nyc.gov/learning/subjects/stem
  "nyc-stem-matters": { blurb: "Free summer STEM camps run by NYC Public Schools, offering one-week camps for younger students and multi-week programs for high school students. High school programs last two or three weeks in July and August and take place in all five boroughs. Topics have included animal science, aerospace, marine biology, mechanics, ecology, and engineering." },
  // https://www.civichall.org/high-school-program
  "civic-hall-stem-camp": { blurb: "A free four-week summer camp at Civic Hall's Bernard Goldstein Center near Union Square where high school students build projects in vibe coding, AI, natural language processing, prompt engineering, and emerging technologies. The camp runs on weekdays in July, and students commit to the full four weeks to complete a capstone project. The top five high school capstone projects each earn a $1,000 scholarship, and free meals and transportation are included." },
  // https://jobs.nyc.gov/jobseekers/programs/sound-thinking-nyc/
  "sound-thinking-nyc": { blurb: "A free music production program run by the NYC Mayor's Office of Media and Entertainment with CUNY for high school students in grades 10 to 12. It starts with a three-week, full-day summer camp in audio technology, engineering, and sound recording, with Pro Tools workshops, studio field trips, and talks with women working in music. Participants can then take free CUNY college credit courses and apply for paid summer internships the following summer." },
  // https://www.thetownhall.org/civics/civic-leadership-day
  "town-hall-civic-leadership": { blurb: "A free civic leadership program from The Town Hall that begins with a one-day event for high school students at Fordham University's Lincoln Center campus. Afterward, students spend about four weeks developing a proposed solution to a community issue, with virtual support from mentors. In the spring they return to Fordham to present their work to local council members, community leaders, and activists at a final showcase." },
  // https://www.nyc.gov/site/stophate/initiatives/youth-ambassador-leadership-program.page
  "ophc-youth-ambassadors": { blurb: "A free leadership program run by the NYC Office for the Prevention of Hate Crimes for students ages 8 to 18 from public, charter, and private schools in all five boroughs. Participants train in leadership, public speaking, civic engagement, and organizing, with a focus on inclusion and respect. They lead peer projects, receive mentorship, meet city officials, educators, and nonprofits, and present their work at an annual summit." },
  // https://dol.ny.gov/youthjobs
  "ny-youth-jobs": { blurb: "A New York State Department of Labor program that connects young people ages 16 to 24 with jobs at businesses that receive a tax credit for hiring certified youth. Applicants must live in New York State, be unemployed, and meet a listed risk factor, such as family receipt of SNAP or TANF, free or reduced-cost school lunch, homelessness, or foster care. Teens ages 16 to 17 must be attending high school or an equivalency program and need a guardian's permission." },
  // https://www.door.org/career/
  "the-door-jobs": { blurb: "Free career programs at The Door for young New Yorkers ages 16 to 24, with free Door membership required. Workforce training tracks cover IT support, culinary arts, construction trades, retail, green building operations, and healthcare roles, and many include paid internships. For example, Train and Earn offers an optional paid internship at $18 per hour for up to 150 hours, and the CUT culinary program runs about 10 weeks." },
  // https://hcz.org/our-programs/the-employment-and-technology-center/
  "hcz-etc": { blurb: "A free Harlem Children's Zone after-school program that prepares high school students for careers in STEM and the technical arts. Students pick a focus area modeled on a college major, such as architecture, audio engineering, coding, robotics and engineering, pre-med, virtual reality, or graphic design. Over four years they build core skills, complete an independent study, co-teach younger students, and move into internships, with SAT prep, Regents prep, and tutoring." },
  // https://hcz.org/our-programs/countee-cullen-community-center/
  "hcz-countee-cullen": { blurb: "A free Harlem Children's Zone after-school program for students in grades 9 to 12, centered on broadcasting and media arts, at 3 East 118th Street in Harlem. Students build career-ready skills, gain real-world experience, and work with industry experts in areas such as journalism, podcasting, fashion, and design. Over four years they move from core technical skills to an independent study project, leading project teams, and career immersion." },
  // https://genesysworks.org/locations/new-york/
  "genesys-works-nyc": { blurb: "A New York City career program where high school juniors complete eight weeks of summer training in IT, business operations, and professional development. Students who succeed are then placed in a paid, year-long internship at a partner company during senior year. Applicants must be on track to graduate, be authorized to work in the U.S., and be able to adjust their senior-year schedule, and many schools offer credit for the training and internship." },
  // https://www.bellvoices.org/programs
  "bell-journalism": { blurb: "A paid school-year journalism internship from The Bell for New York City public high school students. Interns learn audio journalism and produce stories for the Miseducation and P.S. Weekly podcasts. The program runs from October to May, and recent cohorts have included about 15 public high school students." },
  // https://www.bklynlibrary.org/support/volunteer/storyteen
  "bpl-storyteen": { blurb: "A Brooklyn Public Library internship for students in grades 10 to 12 who are interested in literacy and early childhood education. Interns complete 20 hours of training and 80 hours of hands-on work, supporting children's librarians with storytime and early literacy programs. The commitment is 3 to 5 hours a week outside school from November through May, and interns receive a stipend, volunteer service hours, and resume-building experience." },
  // https://www.nypl.org/remote-learning-resources/teen-center-ambassadors
  "nypl-teen-ambassadors": { blurb: "A paid internship at The New York Public Library where teens build job readiness and leadership skills, with a focus on library resources and peer-to-peer engagement. Interns are paid to create events and resources for other teens. The program was formerly called Teen Civics Ambassadors, and a recent cohort worked in small groups to identify community issues, research solutions, and present them to local officials." },
  // https://whitney.org/education/teens/youth-insights
  "whitney-youth-insights": { blurb: "A paid, year-long program at the Whitney Museum of American Art for New York City high school students in grades 11 and 12 who have completed at least one semester of YI Artists or YI Arts Careers, or who graduated from YI Introductions. Leaders plan events for other teens, help with family and community programs, lead tours, and write for the museum's teen blog. The commitment is 3 to 10 hours per week." },
  // https://www.moma.org/calendar/programs/86
  "moma-teens": { blurb: "Free programs at the Museum of Modern Art for New York City teens interested in art. In the Making offers free summer studio art classes for high school students ages 15 to 18 that meet three times a week for six weeks, with no experience needed. Other options include Open Art Space, a weekly after-school program for LGBTQ+ students and allies, drop-in More Art Mondays studio sessions, and the paid Teens-in-Residence program." },
  // https://www.nybg.org/education/childrens-education/kids-teens/explainers
  "nybg-explainers": { blurb: "A tiered teen science-education program at the New York Botanical Garden's Everett Children's Adventure Garden for teens ages 14 to 17. Intern Explainers complete at least 125 volunteer hours of orientation, training, and weekend shifts and do citizen science plant research in the Thain Family Forest. Advanced, Mentor, and Senior Explainers are paid roles, and families get free Garden admission." },
  // https://www.nybg.org/plant-research-and-conservation/science-programs/commodore-matthew-perry-graduate-studies-program/internships/
  "nybg-internships": { blurb: "Paid plant science internships at the New York Botanical Garden, where high school, undergraduate, and graduate students work directly with Garden scientists on topics such as molecular biology and taxonomy. Part-time school-year internships run in the fall and spring for New York City students through the Sci Network NYC, and a small number of summer internships may also be available." },
  // https://hudsonriverpark.org/app/uploads/2023/09/2023-SLP-Summary-Report-AC-Presentation.pdf
  "hudson-river-slp": { blurb: "A paid six-week summer research program at Hudson River Park for New York City high school students from communities underrepresented in STEM. Students do field science, such as studying plastic in gull droppings, work with mentors from CUNY City College, and present research posters at the American Museum of Natural History. The program mixes remote days with in-person field days." },
  // https://www.amnh.org/learn-teach/teens/science-communication-internship-program
  "amnh-scip": { blurb: "A paid summer internship at the American Museum of Natural History where New York City high school students learn to explain science to museum visitors using the collections and hands-on stations. It runs in July and August, Monday through Friday, for about 25 hours per week at the Museum. Applicants are in 10th grade, no prior experience is required, and interns earn a $2,000 stipend." },
  // https://wp.nyu.edu/gstem/about-us/
  "nyu-gstem": { blurb: "A six-week summer research program at NYU for high school juniors interested in STEM, with a mission to serve groups underrepresented in the field. Each student works one-on-one with a faculty mentor on an individual project, joins weekly field trips, and presents at a final symposium. Tuition was $5,750 in 2026, with optional campus housing and meals, and financial aid is available." },
  // https://med.nyu.edu/departments-institutes/population-health/divisions-sections-centers/medical-ethics/education/high-school-bioethics-project
  "nyu-medical-ethics": { blurb: "A free bioethics education project from the Section of Medical Ethics at NYU Langone, offering high school lesson plans and case studies on topics such as organ donation, genetic testing, CRISPR, and vaccines. High school interns help faculty build the lesson plans, and students from all schools are encouraged to apply. The materials can be used freely in classrooms for non-commercial purposes." },
  // https://www.cancer.columbia.edu/education/educational-opportunities/high-school-and-undergraduate-programs/yes-heights-program
  "columbia-yes-heights": { blurb: "A paid summer research internship at Columbia's Herbert Irving Comprehensive Cancer Center for high school and undergraduate students. Each student is paired with a faculty mentor, attends a weekly cancer biology journal club, and writes a scientific abstract over 8 weeks of full-time work at 35 hours per week. Applicants must be at least 14 and U.S. citizens or permanent residents, and no housing is provided." },
  // https://freedomandcitizenship.columbia.edu/apply
  "columbia-freedom-citizenship": { blurb: "A free Columbia program for New York City students entering their senior year of high school, with preference for low-income and first-generation college applicants. Scholars take a summer seminar on political philosophy, get support with college applications, and complete a year-long civic leadership project. Scholars who complete the year receive a $2,500 stipend." },
  // https://ddc.college.columbia.edu/content/double-discovery-centers-summer-academy
  "columbia-double-discovery": { blurb: "A free college-prep program at Columbia for first-generation and low-income high school students from Harlem, Washington Heights, and nearby neighborhoods. Students attend Saturday Academy during the school year, taking a college-prep session and two enrichment courses, and 9th and 10th graders can join a four-week commuter Summer Academy. Tutoring, college application and financial aid help, and wellness support are included." },
  // https://www.rockefeller.edu/outreach/ssrp/
  "rockefeller-ssrp": { blurb: "A seven-week, full-time summer biomedical research program at Rockefeller University for high school juniors and seniors who are at least 16 by the start date. Each summer 32 to 40 students join research teams of 8 to 10 scholars with at least 3 mentors and work about 35 hours a week. No minimum GPA is required, full attendance is mandatory, and the work cannot be entered in science competitions." },
  // https://crest.cuny.edu/hires/curriculum-courses/
  "cuny-hires": { blurb: "A seven-week summer research internship run by CUNY CREST at City College for New York City high school students from groups underrepresented in STEM. Students complete a three-credit college-level course in scientific computing, remote sensing, and geographic information systems tied to their own research project, with mentoring from City College faculty and students. The program runs June through August." },
  // https://www.citytech.cuny.edu/collegenow/stem-research-academy.aspx
  "citytech-stem-ra": { blurb: "A free College Now research program at City Tech for New York City public high school sophomores and juniors from partner schools under-served by science programs. Students build research skills in a Saturday course in the spring, then can apply for a six-week summer lab internship with a City Tech faculty researcher that pays a $1,575 stipend and ends with a presentation at the American Museum of Natural History." },
  // https://cooper.edu/engineering/stem/summer
  "cooper-summer-stem": { blurb: "A summer program at The Cooper Union where high school students take engineering, computer science, and design courses such as digital fabrication and app development, then present their projects on the final day. Classes run 3 or 6 weeks, Monday through Thursday from 9:00 am to 3:00 pm, at 41 Cooper Square. It is open to students who have completed 9th, 10th, or 11th grade, and financial aid is available." },
  // https://mindsmatternyc.org/students/
  "minds-matter-nyc": { blurb: "A free 7-year mentoring and college-prep program for low-income New York City students who would be the first in their families to attend college. Starting in sophomore year, each student is matched with two adult mentors and spends most Saturdays from October through April on mentoring, writing and critical thinking, and SAT prep. Rising juniors and seniors attend summer programs, and support continues through college." },
  // https://www.girlsincnyc.org/our-programs
  "girls-inc-nyc": { blurb: "Free programs from Girls Inc. of New York City for high school girls and gender-expansive youth, covering leadership, college readiness, STEM, and health. In Teen Leadership Circles, students train as peer leaders who run workshops for classmates, and College Shower offers a 10 to 12 week college and career readiness course. Other programs teach data analytics, personal finance, mental health, and media literacy." },
  // https://nywici.org/advance/students/scholarships/
  "nywici-scholarship": { blurb: "Scholarships from New York Women in Communications for high school seniors and college students studying communications who live in New York, New Jersey, Connecticut, or Pennsylvania or attend school in New York. Awards range from $2,500 to $10,000 and are based on academic excellence, financial need, and commitment to the field. Many are sponsored awards, and winners may be invited to NYWICI events." },
  // https://www.newvisions.org/program/postsecondary-pathways/scholarships
  "new-visions-scholarship": { blurb: "A scholarship from New Visions for Public Schools for high-achieving seniors at its partner high schools, most of them first-generation college students. Winners receive up to $20,000 over four years, chosen for academic rigor, community engagement, leadership, and financial need. New Visions also offers the Beattie Scholarship of $10,000 over four years and the Kriegel Scholarship of $5,000 for civically engaged seniors." },
  // https://www.pratt.edu/continuing-and-professional-studies/precollege/summer-precollege/
  "pratt-precollege": { blurb: "A four-week summer intensive on Pratt Institute's Brooklyn campus where students ages 15.5 to 18 take college-level courses in art, design, architecture, and writing, build portfolios, and earn four college credits. It runs in July, and a two-week non-credit PreCollege Explore option is also offered. Students budget $300 to $500 for supplies, and a limited number of full scholarships are available." },
  // https://sva.edu/academics/youth-and-teen-programs/pre-college
  "sva-precollege": { blurb: "Pre-college studio courses at the School of Visual Arts in Manhattan in fields such as animation, design, film, fine arts, illustration, and photography, taught by SVA undergraduate faculty. Students sharpen skills and build portfolios, earning three college credits in the summer session or one in fall or spring. The July summer session is open to rising high school freshmen through seniors, and residence hall housing is available." },
  // https://www.schools.nyc.gov/about-us/news/morning-bell/contentdetails/morning-bell/2025/12/08/opportunities-for-students-december-2025
  "nyc-youth-action-50": { blurb: "A free citywide leadership program from NYC Public Schools for public high school students in grades 9 to 12 who want to act on issues they care about. Members meet regularly with peers and adult facilitators, plan community service projects, and build civic engagement and organizing experience. Applications are accepted on a rolling basis, meeting times vary by site, and participants can earn community service hours." },
  // https://www.mcny.org/reach
  "mcny-reach": { blurb: "A free teen program at the Museum of the City of New York built around research, education, arts, community, and history, meant to support the city's young people socially and culturally. The museum has run visual, performing, and media arts sessions for summer youth employment participants from all five boroughs. It has also offered a nine-week Saturday documentary photography intensive for high schoolers aged 14 to 18, with lectures, labs, field trips, and guest speakers." },
  // https://www.brooklynmuseum.org/careers/internships-fellowships/museum-apprentice-program
  "brooklyn-museum-map": { blurb: "A paid teen internship at the Brooklyn Museum where NYC high school students learn about art and museum education, build lesson plans, and teach audiences of all ages with guidance from museum educators and curators. Apprentices earn $17 per hour, and second-year apprentices serve as leaders at $18 per hour, for up to 180 hours a year. The cohort runs from November to August, meeting Thursday afternoons during the school year and Wednesday through Friday in July and August." },
  // https://see.isbscience.org/resources/for-students/high-school-intern-program/
  "isb-baliga-hs-internship": { blurb: "An 8-week in-person summer research internship at the Institute for Systems Biology's Baliga Lab in Seattle, open only to current 11th graders. Interns spend 40 hours per week at ISB from late June to late August. Both paid positions and unpaid service learning positions are available. Housing is not provided, so students who need it must arrange their own with guardian approval." },
  // https://precollege.sps.columbia.edu/programs/academic-year/academic-year-weekend
  "columbia-precollege-ay-weekend": { blurb: "A Columbia University pre-college program where students in grades 9 to 12 take live online college-style courses on weekends during the school year. Students choose up to four courses per term and study over seven weekends, with fall and spring terms. A single course costs $2,868, and each additional course costs $2,700. Financial aid is not offered, and courses do not carry college credit, but participants receive a certificate of participation." },
  // https://precollege.sps.columbia.edu/programs/academic-year/academic-year-weekend
  "columbia-precollege-ay-weekend-early": { blurb: "The spring term of Columbia University's weekend pre-college program, running from January to March, where students in grades 9 to 12 take live online college-style courses. Students choose up to four courses and study over seven weekends. A single course costs $2,868, and each additional course costs $2,700. Financial aid is not offered and courses carry no college credit, but participants receive a certificate of participation." },
  // https://delamed.org/programs/student-internship/
  "delamed-dpha-spring": { blurb: "A spring semester internship in medicine and public health from the Delaware Academy of Medicine and the Delaware Public Health Association, running from January to April. The high school track is entirely virtual, and the schedule can be built around other commitments. Applicants must be enrolled in a Delaware high school in grades 10 to 12, and they meet with the internship coordinator to review the position, requirements, and deliverables." },
  // https://delamed.org/programs/student-internship/
  "delamed-dpha-summer": { blurb: "A summer internship in medicine and public health from the Delaware Academy of Medicine and the Delaware Public Health Association, running from May to August. The high school track is entirely virtual, with a schedule that can fit around other commitments. Applicants must be enrolled in a Delaware high school in grades 10 to 12. High school applicants meet with the internship coordinator to go over the position, requirements, and deliverables." },
  // https://www.kucancercenter.org/training-education/high-school-undergraduate/summer-research-program
  "ku-cancer-ace": { blurb: "A six-week paid summer research program at the University of Kansas Cancer Center for high school juniors and seniors interested in biomedical careers. Each student works with a faculty mentor on a project in a lab, clinical, or office setting and presents a poster at the end, earning a $2,940 stipend on completion. Applicants must attend high school in Wyandotte County, Kansas or Jackson County, Missouri, have a 3.0 GPA or higher, and be at least 16." },
  // https://haslam.utk.edu/access/accounting-and-information-management-aim-academy/
  "utk-haslam-aim-academy": { blurb: "A six-day summer program at the University of Tennessee, Knoxville's Haslam College of Business, sponsored by Crowe LLP, for rising high school juniors interested in accounting. Students attend workshops in accounting, finance, entrepreneurship, and professional development, plus college readiness sessions such as ACT prep. Applicants need at least a 3.0 GPA and an interest in business, and selected students attend the full program and stay in campus dorms." },
  // https://www.adlerplanetarium.org/youth-teen-programs/
  "adler-teen-internship": { blurb: "Paid summer internships at the Adler Planetarium that place Chicago teens in roles across the museum. Interns work as paid employees with managers in departments throughout the Adler. Along the way they build professional communication and teamwork skills and gain experience in space visualization and computer science, a fit for students interested in astronomy, science education, and museums." },
  // https://afterschoolmatters.org/apply/
  "after-school-matters": { blurb: "Paid after-school and summer programs in arts, STEM, sports, and communications run by After School Matters for Chicago teens, mostly ages 14 to 18. Apprenticeships are open to teens 14 and older and pay a stipend for successful participation and completion, with amounts that vary by program. Internships and outreach assistantships require teens to be 16 or older, and internships pay an hourly wage. Applicants must live in Chicago and attend a Chicago high school." },
  // https://aimi.stanford.edu/education/aimi-summer-bootcamp
  "stanford-aimi-bootcamp": { blurb: "A two-week virtual summer program from Stanford's Center for Artificial Intelligence in Medicine and Imaging (AIMI) that introduces high school students to AI in health and medicine. Students of any technical background learn machine learning fundamentals alongside healthcare applications. Alumni who are still in high school can be invited to AIMI's Academic Year Research Internship, which has limited admission." },
  // https://aimi.stanford.edu/education/summer-research-internship
  "stanford-aimi-summer-research": { blurb: "A two-week virtual summer research internship from Stanford's Center for Artificial Intelligence in Medicine and Imaging (AIMI) where high school students explore the technical and clinical sides of AI in healthcare. Students do mentored research on real-world health data, with daily lectures from mentors and team breakout sessions to apply each lesson to a project. Alumni can be invited to a follow-on academic year research internship." },
  // https://afrlscholars.usra.edu/scholarsprogram/eligibility/
  "afrl-scholars": { blurb: "Paid summer research internships at Air Force Research Laboratory sites across the U.S., such as Kirtland and Eglin/Hurlburt, for upper-level high school students and university students. Interns work full time at 40 hours a week, usually write a technical report, and present to their branch. Applicants must be U.S. citizens, at least 16 (18 at California locations), willing to relocate to the work site, and able to pass a background check." },
  // https://www.sama-tx.org/education-and-internships
  "alamo-academies-internship": { blurb: "Paid summer manufacturing and technical internships offered through a partnership between the San Antonio Manufacturers Association and Alamo Academies, which teaches high-demand STEM curriculum to high school students. Students are placed with SAMA member businesses to see industry careers firsthand and plan their education and careers after graduation. SAMA also gives an annual scholarship to Alamo Academies students planning to study manufacturing or aerospace fields." },
  // https://www.uno.edu/amri/summer-outreach/research-program-high-school-students
  "uno-amri-hs-research": { blurb: "An eight-week, full-time paid summer research program at the University of New Orleans' Advanced Materials Research Institute, running since 2002, where high school students work alongside lab researchers. Projects span chemistry, physics, materials science, engineering, psychology, and math, and students attend weekly seminars on topics like lab safety and research ethics. Each student receives a $2,000 stipend, and applicants must attend high school within 40 miles of UNO." },
  // http://engineering.nyu.edu/k12stem/arise/
  "nyu-arise": { blurb: "A free seven-week summer research program at NYU Tandon for New York City high school students in 10th and 11th grade who show interest in STEM. Students spend five weeks in a participating NYU faculty lab with mentoring from a graduate or postdoctoral student, plus two weeks of workshops and college advising, and receive a stipend. Applicants must live in one of the five boroughs and apply to the program as a whole rather than to a specific lab." },
  // https://www.archildrens.org/careers/job-shadowing/high-school-students
  "arkansas-childrens-job-shadowing": { blurb: "Rolling job shadowing at Arkansas Children's Hospital for high school students 16 and older who are exploring healthcare careers. Students submit an online application naming a health care area of interest, and the hospital tries to match them to it. Shadowing runs for 1 to 3 days, and students observe without taking part in direct patient care. Participants follow a conservative dress code with no jeans, shorts, or sandals." },
  // https://yefa.org/ysic-2024/
  "yefa-ysic": { blurb: "An online investment competition run by the nonprofit Youth Entrepreneurship and Finance Association, in which high school students build and manage a stock portfolio with an ESG focus. Students compete alone or in teams of up to three, using virtual money to manage the portfolio over roughly three months. Top finalists pitch to judges and compete for prizes. The 2026 challenge drew 373 teams and more than 540 students from 48 countries." },
  // https://globalscholars.yale.edu/tuition
  "ylc": { blurb: "A two-week residential academic program on Yale's campus in New Haven for current high school sophomores and juniors from any country. Students choose academic tracks in science and technology, politics, law and economics, or global challenges, and attend one of three sessions in June and July. Tuition is $7,500 per session and covers on-campus housing, meals and materials but not travel. Need-based aid covers up to full tuition, and local commuters get a $1,000 discount." },
  // https://www.nyas.org/learning/high-school-research-programs/the-junior-academy/
  "junior-academy": { blurb: "A free online program of the New York Academy of Sciences in which students ages 13 to 17 join international teams and work with STEM expert mentors to solve real-world challenges. Each challenge is a 10-week virtual competition, held from mid-September to mid-November in the fall or mid-February to mid-April in the spring. Students who complete a challenge receive a certificate and a Young Membership to the Academy, and there is no travel." },
  // https://diamondchallenge.org/competition/
  "diamond-challenge": { blurb: "A year-long entrepreneurship competition for high school students run by Horn Entrepreneurship at the University of Delaware. Teams of 2 to 4 students aged 14 to 18, with an adult advisor aged 21 or older, develop a business or social innovation concept and pitch it at a regional event or by pitch deck and recorded video. The prize pool is about $100,000, with first place in each track listed at $12,000, and finalists can be invited to a multi-day summit." },
  // https://www.unesco.org/en/articles/14th-edition-unesco-youth-forum
  "unesco-youth": { blurb: "A youth forum held every two years as part of UNESCO's General Conference, where young people exchange ideas, debate pressing issues and present their recommendations and solutions to UNESCO Member States. The 14th edition took place in Samarkand, Uzbekistan, on October 27 to 28, 2025, bringing together 145 youth leaders from 135 Member States and Associate Members to focus on climate action. Participants draft recommendations and a Call to Action for governments." },
  // https://pumac.princeton.edu/competition-rules/
  "pumac": { blurb: "A high school math competition held each November at Princeton University. Teams of 8 compete in a Power Round and a Main Competition with A and B divisions, and individual applicants are combined into teams of 8. Teams usually come from a single high school, though regional teams may be allowed. Members must not turn 20 before the competition date or have enrolled full-time in college, and a coach registers the team." },
  // https://berkeley.mt/events/bmt-2026/
  "bmt": { blurb: "An annual math tournament held at UC Berkeley in November for high school students in grade 12 or below, with no lower age limit. Students compete in teams of up to 6 or register alone, across Power, Individual and Guts rounds, and the team rounds are designed for 4 to 6 students. The Power Round is a 90-minute proof-based team round. Registration is $15 per student, rising to $25 for late registration, and fee waivers are available." },
  // https://ioinformatics.org/
  "ioi": { blurb: "An annual international programming olympiad in which secondary school students compete individually, solving a set of informatics problems over two competition days. Each country typically sends a delegation of four contestants and two accompanying adults, headed by a delegation leader. Contestants must be students no older than twenty on July 1 of the competition year. In the U.S., USACO picks the four team members at its summer training camp." },
  // https://ieso-info.org/
  "ieso": { blurb: "An annual international Earth science olympiad for secondary school students, where the winners of each country's national competition are invited to compete in national delegations. It covers geology, geophysics, meteorology, oceanography, astronomy and environmental science. Each participant takes theoretical and practical exams plus a field work test, and students from different countries are also graded together as a group in the International Team Field Investigation." },
  // https://technovationchallenge.org/program-overview/
  "technovation": { blurb: "A free program in which girls and nonbinary and gender non-conforming youth ages 8 to 18 form teams of 1 to 5, choose a community problem and build an AI or mobile app to address it. The season runs from August to May, and teams are placed in Beginner, Junior or Senior divisions by the age of the oldest member. Junior and Senior teams also make a technical video and a user adoption plan or business plan." },
  // https://www.firstinspires.org/robotics/frc/cost-and-registration
  "first-robotics": { blurb: "A robotics competition run by FIRST in which teams of high school students design, build and program industrial-sized robots and compete at events. Season registration is $6,500 per team and includes one regional event, while additional regional events cost $3,200 each and some district events cost $1,000 each. Teams that qualify for the Championship pay $6,000 to register. Teams also cover parts and travel, and grant opportunities are available." },
  // https://summer.jhu.edu/programs-courses/pre-college-programs/
  "syp-jhu": { blurb: "Two-week pre-college summer programs at Johns Hopkins University for students who have completed 9th grade and hold a GPA of 3.0 or higher. Programs run online or on the Homewood campus in Baltimore between late June and early August, in medicine and health, STEM, social sciences and humanities. Each program earns one college credit. Tuition is $6,140 on campus, $4,660 for commuters and $1,950 online, plus an $85 application fee." },
  // https://hs.sas.upenn.edu/summer-programs
  "syp-penn": { blurb: "Summer programs for high school students run by Penn Arts and Sciences at the University of Pennsylvania. Options include two- or three-week non-credit residential Summer Academies and online seminars for 9th through 11th graders, plus credit-bearing Pre-College courses on campus or online for 10th and 11th graders. Academy and seminar students earn a certificate. Applicants submit essays and a recommendation, need a minimum 3.5 GPA, and no financial aid is offered." },
  // https://math.mit.edu/research/highschool/primes/usa/
  "prim-usa": { blurb: "A free year-long remote research program at MIT for high school sophomores and juniors living in the U.S. outside the Boston area. Students meet weekly online with mentors to work on unsolved problems in mathematics and bioinformatics, spending at least 10 hours a week including a 1.5-hour weekly mentor meeting. Applicants submit an entrance problem set, recommendations and an online interview, and students present their research at a fall conference." },
  // https://girlswhocode.com/programs/pathways
  "girls-who-code": { blurb: "A free, self-paced virtual coding program from Girls Who Code for high school girls and nonbinary students, including rising 9th graders and graduating seniors. Students take courses in AI and society, data science and AI, cybersecurity, game design or web development, and each course takes 3 to 6 hours to complete. Students get support through advisor events, student hours and Discord, and earn certificates for completed courses." },
  // https://www.kodewithklossy.com/programs
  "kode-with-klossy": { blurb: "Free two-week summer coding camps for young women and gender-expansive teens ages 13 to 18, held in June, July and August both virtually and in person in several U.S. cities. No prior coding experience is required. Students are placed in one of four tracks: web development with JavaScript, HTML and CSS, mobile apps in Swift, data science, or AI and machine learning. Each camp is co-taught by 2 instructors who are licensed educators." },
  // https://www.rotary.org/get-involved/youth-programs/rotary-youth-leadership-awards
  "rotary": { blurb: "A leadership training program organized by Rotary clubs and districts for young people ages 14 to 30, held at the club, district or multidistrict level. Participants build leadership skills and make connections, and formats vary by area from a one-day seminar to a three-day retreat or a weeklong camp. Participants are nominated by local Rotary clubs, and costs and application steps differ by area, so interested students contact a local club." },
  // https://www.harvardmun.org/about
  "harvard-mun": { blurb: "A four-day international relations simulation for high school students held each year in downtown Boston, where delegates take on the roles of world leaders and work on global issues in general assembly, crisis and specialized committees. The conference draws more than 3,000 high school students from schools around the world and meets in January. A smaller online version with sessions in October and December is also offered for students who cannot travel to Boston." },
  // https://ymun.org/what-is-ymun
  "yale-mun": { blurb: "A four-day international relations simulation for high school students on Yale University's campus in New Haven, Connecticut, hosted by the Yale International Relations Association. Delegates debate in committees that meet in Yale classrooms and are led by over 240 Yale students, and most committees have no more than 30 delegates. Only delegates 18 and under may attend, financial aid is offered, and three virtual committees cost $30 per delegate." },
  // https://www.artandwriting.org/frequently-asked-questions/
  "scholastic": { blurb: "A national competition in which students in grades 7-12 who are at least 13 years old submit original art and writing in 28 categories through an online portal. Entrants must live in the U.S. or a U.S. territory or military base, and some students outside the U.S., including teens at U.S.-accredited schools abroad, also qualify. Entries cost $15 each or $40 per portfolio, fee waivers are available for financial need, and only graduating seniors may enter the Art Portfolio." },
  // https://theadroitjournal.org/adroit-prizes/
  "ayla": { blurb: "An annual writing contest run by The Adroit Journal for all secondary and undergraduate students, including international students and those who graduated a semester early. Entrants submit up to ten packets, each holding up to six poems or up to three prose pieces of fiction or creative nonfiction totaling 3,500 words. Winners receive $200 and publication in The Adroit Journal, and runners-up and finalists receive a copy of their judge's latest book." },
  // https://horatioalger.org/scholarships-and-services/undergraduate-scholarships/
  "horatio-alger": { blurb: "A need-based college scholarship from the Horatio Alger Association for full-time U.S. high school juniors who have shown perseverance through adversity. Recipients receive up to $25,000 each, and 105 juniors were selected for the Class of 2027. Applicants must be U.S. citizens with financial need, community service, a minimum 2.5 GPA and an adjusted gross family income of $100,000 or lower, and must plan to earn a bachelor's degree." },
  // https://www.questbridge.org/apply-to-college/programs/national-college-match
  "questbridge-match": { blurb: "A college admissions and scholarship program run by QuestBridge that matches high-achieving, low-income high school seniors with full four-year scholarships from 55 partner colleges. Students can be considered for early admission at up to 15 colleges, and a match is binding, with MIT as the exception. The scholarship covers the full cost of attendance, including tuition, housing and food, books and supplies, and travel, with no loans or parental contribution." },
  // https://www.davidsongifted.org/gifted-programs/fellows-scholarship/scholarship-categories/
  "davidson-fellows": { blurb: "A scholarship program from the Davidson Institute that awards $100,000, $50,000 and $25,000 to students 18 and under who have completed a significant piece of work. Categories are Science, Technology, Engineering, Mathematics, Literature, Music, Philosophy and Outside the Box, and two-person teams are eligible. Applicants must be U.S. citizens or permanent residents living in the United States, or stationed overseas on active U.S. military duty." },
  // https://news.prudential.com/latest-news/prudential-news/prudential-news-details/2024/Prudential-Financial-introduces-its-next-class-of-Emerging-Visionaries/
  "prudential-emerging-visionaries": { blurb: "A national award from Prudential Financial and Ashoka that honors students ages 14-18 who have created solutions to financial and societal challenges in their communities. Winners are recognized in two categories, Financial Solutions for a Changing World and Societal Solutions for a Changing World. Each winner receives $5,000 and an all-expenses-paid trip to Prudential's headquarters in Newark, New Jersey for a summit where finalists pitch for a grand prize." },
  // https://swe.org/apply-for-a-swe-scholarship/
  "swe-scholarships": { blurb: "Scholarships from the Society of Women Engineers for women entering their first year of college, including current high school seniors, who plan to study engineering or computer science full time in an ABET-accredited program. Applicants in the Emerging First Year round need a minimum unweighted GPA of 3.5 on a 4.0 scale and do not need to be SWE members. A single application is considered for every Society-Selected scholarship the student qualifies for." },
  // https://www.nationalmerit.org/s/1758/images/gid2/editor_documents/merit_about_leaflet.pdf
  "national-merit": { blurb: "A competition run by the National Merit Scholarship Corporation that high school juniors enter by taking the PSAT/NMSQT. More than 16,000 high scorers are named Semifinalists on a state allocation basis, and those who meet further requirements, such as a principal endorsement and confirming SAT or ACT scores, can become Finalists. About 6,700 scholarships are offered in 2027, including $2,500 National Merit Scholarships and corporate- and college-sponsored awards." },
  // https://jackierobinson.org/scholarship/
  "jackie-robinson": { blurb: "A four-year, merit- and need-based scholarship from the Jackie Robinson Foundation for graduating high school seniors who are U.S. citizens with financial need, academic excellence, leadership potential and a commitment to community service. Scholars receive up to $35,000 over four years at an accredited four-year college, plus conference sponsorship. Applicants submit four essays, one recommendation, a transcript, activities and honors, and the CSS Profile." },
  // https://www.reaganfoundation.org/education/ge-reagan-foundation-scholarship
  "ge-reagan": { blurb: "A college scholarship from the Ronald Reagan Presidential Foundation and Institute and GE for high school seniors nationwide who show leadership, drive, integrity and citizenship. Recipients receive a $10,000 scholarship renewable for up to three more years, for a total of up to $40,000. Applicants must be U.S. citizens with a minimum 3.0 GPA who plan to enroll full time at an accredited four-year U.S. college, and they write an essay on leadership and service." },
  // https://www.hsf.net/scholarship/
  "hsf-scholar": { blurb: "A scholarship and support program from the Hispanic Scholarship Fund for students who plan to attend an accredited public or not-for-profit four-year university in the U.S. full time. High school applicants need a minimum 3.0 GPA, must be U.S. citizens, permanent legal residents or DACA recipients, and must complete the FAFSA. Selection is merit-based, awards range from $500 to $5,000 based on each student's financial aid package, and all Scholars can use support services." },
  // https://www.aspirations.org/award-programs/aic-high-school-award
  "ncwit-aspirations": { blurb: "A national award from the National Center for Women & Information Technology for students in grades 9-12 who are active in computing and technology. Applicants must be at least 13, attend school in the U.S., a U.S. territory or a U.S. overseas military base, and join the free Aspirations in Computing Community. Recipients are chosen at National and Regional Affiliate levels based on computing experience, leadership, persistence and future plans." },
  // https://doodleforgoogle.doodles.google/rules/
  "doodle-for-google": { blurb: "An annual art contest from Google in which K-12 students create and submit their own Google Doodle. Entrants must be U.S. citizens or permanent legal residents enrolled in a K-12 school or homeschool in the U.S., Puerto Rico, a U.S. territory or D.C. Each of the five Finalists receives a $10,000 college scholarship and a Chromebook, and the National Winner receives a $55,000 college scholarship plus a $50,000 technology package for their school." },
  // https://carsonscholars.org/scholarships/
  "carson-scholars": { blurb: "A $1,000 college scholarship from the Carson Scholars Fund for students in grades 4 through 11 at accredited U.S. K-12 schools who have at least a 3.75 GPA and a record of community service. Students cannot apply on their own; each school may nominate one student, who then submits an essay, a teacher recommendation and a current report card. The award is invested toward a four-year college or university and is not based on financial need." },
  // https://www.engineerteen.org/4586/contest
  "engineergirl-writing": { blurb: "A writing contest from the National Academy of Engineering, formerly the EngineerGirl Writing Contest, with its own division for high school students. The 2027 contest has a robot-training theme and asks students to explain how they would train an AI robot to behave in their learning community. Recent contest rules award $1,000 for first place, $750 for second place and $500 for third place." },
  // https://www.risefortheworld.org/
  "rise-challenge": { blurb: "A global program from Schmidt Futures and the Rhodes Trust that finds young people ages 15 to 17 and supports them as they work in service of others. Applicants complete a challenge, up to 500 Finalists take part in Finalist Days, and 100 are selected as Global Winners. Winners can receive a need-based four-year scholarship with tuition and a living stipend, mentoring, a technology package and a fully-funded residential summit." },
  // https://www.nationalgeographic.com/expeditions/trip-types/student-1/
  "nat-geo": { blurb: "Summer travel programs from National Geographic, run with Putney Student Travel, for students completing 9th through 12th grades, with separate trips for middle school students. Trips take place in the U.S. and abroad, vary in length and focus, and some include up to 30 community service hours spent building schools, tutoring in English or cleaning up parks. An admissions committee reviews each application." },
  // https://www.med.upenn.edu/student/hs-premed.html
  "rsi-medicine": { blurb: "A set of high school programs listed by Penn's Perelman School of Medicine for students exploring medicine and health careers, most aimed at Philadelphia-area students. Options include a four-week Summer Mentorship Program for Philadelphia rising 10th and 11th graders, a 6-week research internship hosted by Penn faculty with a seventh week of clinical exploration, and PhysicianTrack, which offers two summers of wilderness medicine." },
  // https://www.generationcitizen.org/what-we-do/in-youth-leadership/
  "ywp": { blurb: "Youth civic leadership opportunities from Generation Citizen that give students training, support and leadership roles, often after its in-school Action Civics course. In Rhode Island, the Youth Voice and Youth Research Fellowships offer a year-long cohort in which students work on their own state civics policy. In New York City, the Civic Connections Fellowship places Action Civics alumni at a government agency, elected official's office or advocacy organization." },
  // https://www.speechanddebate.org/district-tournaments/
  "youth-debate": { blurb: "The National Speech & Debate Tournament is the annual national tournament of the National Speech & Debate Association for high school members. Students qualify mainly through their district's tournament series, where events are often held on different dates so students can enter several. Qualifiers need a paid NSDA membership and at least 25 Honor Society points. Students in grades 9 to 12 who miss out at districts can try the online Last-Chance Qualifier." },
  // https://www.legion.org/get-involved/youth-programs/boys-state-boys-nation
  "girls-state": { blurb: "American Legion Boys State is a civic leadership program for top high school juniors in which students run mock state governments. It is organized state by state, and in most cases schools recommend students to their local American Legion post, which interviews and selects the delegates. Two delegates from each Boys State program go on to Boys Nation in Washington, D.C., where they serve as U.S. senators in a week of mock sessions, party conventions and landmark visits." },
  // https://www.indigoresearch.org/program/high-school
  "indigo": { blurb: "Indigo Research runs one-on-one virtual research programs in which high school students are matched with a mentor and complete a research project on a flexible timeline of 3 to 12 months. Tiers include Explorer (10 hours, about 3 months), Researcher (20 hours, about 6 months) and Innovator (45 hours, about 12 months), which includes two credits from UCSB Extension. Tuition starts at $3,900, and no scholarships are currently offered." },
  // https://www.immerse.education/pathways/online
  "immerse-research": { blurb: "Immerse Education's online research programme pairs students aged 13 to 18 one-to-one with a tutor from Oxford, Cambridge or an Ivy League university to complete an assessed research project in one of over 20 subjects. The Classic version runs 10 hours, while 15-hour accredited versions are open to students 14 and older and can carry UCAS points or US college credit. A group version for up to 10 students and a publication version are also offered." },
  // https://careers.microsoft.com/v2/global/en/discoveryprogram
  "microsoft-discovery": { blurb: "A four-week paid summer internship at Microsoft for graduating high school seniors heading into a bachelor's program. Interns work full-time and onsite in Redmond, Washington or Atlanta, Georgia, on projects with mentorship from Microsoft employees between July and August. Applicants must live and attend high school within 50 miles of Redmond or around Atlanta and must have completed pre-calculus, an equivalent course, or 3 consecutive years of math including senior year." },
  // https://www.carnegiehall.org/Education/Programs/National-Youth-Ensembles/NYO-Jazz
  "nyojazz": { blurb: "NYO Jazz is Carnegie Hall's national youth jazz orchestra for musicians ages 16 to 19 who are U.S. citizens or permanent residents enrolled in high school or the homeschool equivalent. Each summer the musicians train in a two-week residency with jazz artists, perform a concert at Carnegie Hall with a guest artist and go on an international tour. The program is tuition-free and covers room, board and tour costs, and all applicants audition by video and receive jury feedback." },
  // https://www.bu.edu/summer/high-school-programs/summer-challenge/
  "bu-summer": { blurb: "A two-week, non-credit summer program at Boston University for rising high school sophomores, juniors and seniors. Students take two seminars of their choice from about 20 options in areas such as humanities, health and life sciences, technology and engineering, media, and business, law and politics, with lectures, discussions, field trips and project-based assignments. Students receive evaluation letters instead of grades and can attend as commuters or live on campus." },
  // https://highschool.utexas.edu/apply
  "syp-utexas": { blurb: "UT High School is the University of Texas at Austin's public online school, and middle and high school students from any location can take one or a few high school credit courses there without enrolling full time. Courses cover core subjects, electives, world languages and AP classes, run on Canvas with proctored testing included, and can be started at any time of year. Each independent course costs $285 and allows 140 days to finish." },
  // https://www.orau.org/arc-ornl/high-school/index.html
  "ornl": { blurb: "A fully funded two-week residential summer program in Oak Ridge, Tennessee, run by ORAU and sponsored by the Appalachian Regional Commission and Oak Ridge National Laboratory. High school students work on short research projects with ORNL and ORAU mentor scientists and present their work at a closing poster session in July. Applicants must be U.S. citizens, at least 16 by the program start date, and live in or attend school in a designated Appalachian county." },
  // https://beamlineforschools.cern/terms-and-conditions/
  "cern-summer": { blurb: "A physics competition run by CERN in which teams of secondary school students aged 16 to 19 propose an experiment that uses a particle accelerator beamline. A winning team must have at least 5 members, and up to 9 students from each winning team travel with one or two adult supervisors to carry out their experiment in August. Winners have gone to CERN, DESY or partner labs depending on the year. Students under 16 can take part but cannot travel." },
  // https://www.nsliforyouth.org/programs/summer-abroad/
  "nsli-y": { blurb: "A U.S. Department of State scholarship for U.S. citizen high school students aged 15 to 18 to study a critical language such as Arabic, Chinese, Korean or Russian. The summer program runs 6 to 7 weeks abroad, and the academic year program runs 8 to 10 months with a host family or in a supervised dormitory. No prior language study is required for the summer program, and a 10-week online Virtual NSLI-Y course is also offered for beginners." },
  // https://globalscholars.yale.edu/programs/politics-law-and-economics-program-ple
  "yale-law-summer": { blurb: "A two-week residential summer session of Yale Young Global Scholars for students ages 16 to 18 interested in economic theory, government and legal frameworks. Topics include public policy, human rights, market regulation, governance structures and international law, and students attend lectures by Yale faculty, seminars and breakout sessions and complete a group capstone project. It runs in each of three sessions from June through July, and no online sessions are offered." },
  // https://www.juilliard.edu/music/preparatory-division/juilliard-pre-college
  "juilliard-pre": { blurb: "A Saturday music program at Juilliard in New York, held September through May, where students ages 8 to 18 study with Juilliard faculty. Majors include orchestral strings, woodwinds, brass, harp, guitar, organ, percussion, piano, voice and composition, and admission is by competitive audition in the major, with pre-screening recordings for some instruments. Beginners are not accepted, and financial aid up to and including full-tuition scholarships is available." },
  // https://www.nyc.gov/site/dycd/services/jobs-internships/about-syep.page
  "nyc-syep": { blurb: "A six-week paid summer program run by the NYC Department of Youth and Community Development for New York City residents ages 14 to 24 who are legally allowed to work in the U.S. It takes place in July and August. Teens ages 14 and 15 do paid project-based activities and receive a stipend, while those ages 16 to 24 work in paid summer jobs at minimum wage. There is no fee to apply or participate." },
  // https://www.nyc.gov/assets/dycd/downloads/pdf/Ladders_for_Leader_2026_FAQS.pdf
  "nyc-ladders-leaders": { blurb: "A paid summer internship program within NYC's Summer Youth Employment Program, run by the Department of Youth and Community Development, that places participants with corporations, nonprofits and government agencies in New York City. It is open to rising high school seniors and college students ages 16 to 24 with prior paid or volunteer experience who live in the five boroughs. Internships last 6 weeks at 25 to 40 hours per week and pay at least $16.50 an hour." },
  // https://www.nyc.gov/site/dycd/services/jobs-internships/work-learn-grow-employment-program.page
  "nyc-work-learn-grow": { blurb: "A 22-week paid school-year program run by the NYC Department of Youth and Community Development for high school students ages 16 to 20 who took part in the Summer Youth Employment Program. Participants build work-readiness skills, learn about postsecondary education and can earn college credit, working up to 12 hours a week while school is in session and up to 20 hours during breaks. Students are paid local minimum wage by the City of New York." },
  // https://naturalhistory.si.edu/education/youth-programs/high-school-internship-program
  "smithsonian-nmnh-high-school-internship": { blurb: "A paid eight-week summer internship at the Smithsonian National Museum of Natural History in Washington, D.C., for high school students ages 15 to 18 in grades 9 to 12. Interns work on projects in areas such as exhibits and communications, botany, anthropology, paleobiology, and science education, and take field trips and behind-the-scenes tours. Interns work Tuesday through Friday, earn a $5,600 stipend, and must live within commuting distance in D.C., Maryland, or Virginia." },
  // https://www.chick-fil-a.com/customer-support/who-we-are/giving-back/does-chick-fil-a-give-out-scholarships
  "chick-fil-a-remarkable-futures": { blurb: "A scholarship program from Chick-fil-A, Inc. for restaurant Team Members continuing their education, restricted to Chick-fil-A employees. Team Members at independently owned or corporate-operated Chick-fil-A restaurants, or at affiliated S. Truett Cathy brands, can apply for awards of $1,500 or $25,000. Scholarships are paid up front, apply at any qualifying school, college, or university, and have no employment tenure requirement. Scholarship America administers the program." },
  // https://www.dar.org/outreach/education/essay-contests
  "dar-american-history-essay": { blurb: "A history essay contest from the National Society Daughters of the American Revolution, run for high schoolers as the Patriots of the American Revolution contest, open to students in grades 9 through 12 in public, private, parochial, and home schools. Winners advance from chapter to state, division, and national judging. Essays are judged on accuracy, originality, and use of primary sources, and the national winner receives a certificate, pin, and monetary award." },
  // https://www.dar.org/national-society/scholarships/dar-related
  "dar-good-citizens": { blurb: "A recognition and scholarship program from the National Society Daughters of the American Revolution for high school seniors who show dependability, service, leadership, and patriotism. Teachers and peers choose one senior per school each year as its DAR Good Citizen. The honoree may then enter an optional scholarship contest with references, activities, a transcript, and an essay on American heritage, with awards at the chapter, state, division, and national levels." },
  // https://www.zonta.org/Web/Web/Programs/Education/Zonta_Young_Women_in_Leadership_Award.aspx
  "zonta-young-women-leadership": { blurb: "An award from Zonta International that recognizes young women ages 16 to 19 for leadership and public service. Applicants show volunteer commitment, leadership experience, and knowledge of Zonta, and apply first through a local Zonta club. Recipients are chosen at the club, district, and international levels, with 37 international awards of US$5,000 each. Zonta club members and past district and international recipients are not eligible." },
  // https://syf.org/scholarships/
  "simon-youth-shari-greenberg": { blurb: "A scholarship program from the Simon Youth Foundation for high school seniors who live near a Simon mall community. Awards come in two types: Awards of Excellence, renewable for up to 4 years, and one-time Community Awards. The program honors the foundation's late Vice Chair and Founding Board Member, and priority goes to first-generation college students and students with financial need." },
  // https://syf.org/scholarships/
  "simon-youth-academy-scholarship": { blurb: "A scholarship from the Simon Youth Foundation for graduates of Simon Youth Academies, alternative classroom settings located in Simon malls, who go on to postsecondary education. It offers two-year and four-year renewable scholarships. Each Academy has 1 to 2 scholarships, and priority goes to first-generation college students and students with financial need." },
  // https://syf.org/scholarships/
  "simon-youth-greg-saunders": { blurb: "A scholarship from the Simon Youth Foundation reserved for children of Simon Property Group employees heading to college. It honors a former Simon employee and foundation supporter, and it grew out of the foundation's employee assistance scholarship fund. Priority goes to first-generation college students and students with financial need." },
  // https://www.onr.navy.mil/education-outreach/k-12-programs/seap
  "naval-seap": { blurb: "A paid summer apprenticeship from the Office of Naval Research that places high school students with interest and ability in STEM in Department of Navy laboratories and warfare centers. During eight weeks, apprentices work alongside scientists and engineers who serve as their mentors. Applicants must be U.S. citizens, and some labs require a security clearance. Selection weighs grades, coursework, test scores, teacher recommendations, and a personal statement." },
  // https://www.nsa.gov/Careers/Student-Programs/
  "nsa-high-school-work-study": { blurb: "A paid, part-time program from the National Security Agency for high school juniors who plan to join a school-sponsored work experience program during their senior year. Students must live near NSA headquarters in Maryland or a field site in Colorado, Georgia, Texas, Hawaii, Utah, Alaska, or West Virginia. Roles include office assistant, computer aide, and intelligence analysis aide. Applicants must be U.S. citizens, at least 16, and able to receive a security clearance." },
  // https://www.nationalww2museum.org/events-programs/educational-travel/student-travel-national-wwii-museum/student-leadership-academy
  "national-wwii-leadership-academy": { blurb: "A summer leadership program at The National WWII Museum in New Orleans for students in grades 9-12 who will be at least 16 by the program date. It combines online learning with behind-the-scenes time at the museum in July, where participants analyze strategic decisions and ethical dilemmas. Tuition is $1,840, and accepted participants receive full scholarship coverage. Optional Nicholls State University coursework can earn three college credits for a separate fee." },
  // https://www.vfw.org/community/youth-and-education/youth-scholarships
  "vfw-voice-of-democracy": { blurb: "An audio-essay scholarship competition from the Veterans of Foreign Wars for students in grades 9 through 12. Students record an essay on a yearly patriotic theme and submit it with an entry form to a local participating VFW Post, with awards at the local, state, and national levels. The national first-place winner receives a $35,000 college scholarship, and each state first-place winner earns a trip to a youth leadership experience at Valley Forge." },
  // https://youngarts.org/apply/
  "youngarts-national-arts": { blurb: "A national arts competition run by YoungArts for artists ages 15 to 18 or in grades 10 to 12, covering ten disciplines across the visual, literary, and performing arts, including film, dance, and jazz. Artists may apply in as many disciplines as they like. Applicants must be U.S. citizens, permanent residents, or legally able to receive taxable income in the U.S. The fee is $35 per application, and fee waivers are available." },
  // https://www.cmu.edu/pre-college/academic-programs/sams.html
  "cmu-sams": { blurb: "A free six-week residential summer program at Carnegie Mellon University in Pittsburgh for high school students from minoritized groups who plan to pursue STEM undergraduate majors. Scholars take math and science courses, complete a collaborative STEM research project, and earn credit in a course on the move from high school to college. Virtual sessions come before and after. It is merit-based and fully funded, and scholars pay only for travel to and from Pittsburgh." },
  // https://summer.stanford.edu/students/high-school
  "stanford-summer-high-school": { blurb: "A summer program at Stanford University where high school students take university courses for credit from June to August. Students choose from over 130 courses in seven interest areas, such as natural sciences, computer science and engineering, creativity and design, and writing and public speaking, and earn an official Stanford transcript. On-campus living with a minimum of 8 units starts at $18,771, and commuter costs start at $8,226 with a minimum of 5 units." },
  // https://www.stonybrook.edu/simons/
  "simons-summer-research": { blurb: "A six-week summer research program at Stony Brook University for high school juniors, who are matched with a faculty mentor and work on an active research project. Fellows spend at least four hours a day with their mentors and finish with a research abstract and a poster presentation, and some receive a stipend at the closing symposium. Applicants need a school nomination and two math or science teacher letters, and must be U.S. citizens or permanent residents." },
  // https://engineering.nyu.edu/research-innovation/k12-stem-education/student-programs/innovation-entrepreneurship-and-science
  "nyu-iesosc": { blurb: "A free summer program at the NYU Tandon School of Engineering in Brooklyn for New York City high school students in grades 9 to 11, offered on full scholarship. During five weeks in July and August, students receive STEM instruction and mentoring in coding, electronics, smart-city technology, entrepreneurship, and presentation skills, and work in teams to build a smart-city device or app. Teams present their work publicly to engineers, urban planners, and families." },
  // https://ai4all.ucsf.edu/apply.html
  "ucsf-ai4all": { blurb: "A free summer internship at UCSF Mission Bay for San Francisco Unified School District juniors interested in artificial intelligence, biology, and medicine. It is aimed at juniors who are taking or have taken AP Statistics or AP Computer Science, and no AI background is required. Interns commute daily, provide their own transportation and laptop, and the program ends with a symposium. The internship is unpaid." },
  // https://ai4all.spcs.stanford.edu/ai4all-admissions
  "stanford-ai4all": { blurb: "A two-week summer program run by Stanford Pre-Collegiate Studies and the Stanford Institute for Human-Centered Artificial Intelligence for current 9th graders, offered as an online or a residential session. Participants work on small-group research projects led by graduate students and postdocs in computer science and AI. No previous AI or programming experience is required, and participants must be older than 14 and younger than 16 during the program." },
  // https://www.deca.org/scholarships
  "deca-scholarships": { blurb: "A scholarship program run by DECA Inc. that offers over $200,000 a year to current high school and college DECA members. Awards are merit-based and weigh DECA involvement, leadership ability, community service, and academic performance, and corporate partners set their own criteria. One example is the DECA Inc. scholarship, which gives five $2,000 awards to members studying entrepreneurship, finance, hospitality, management, or marketing." },
  // https://sciences.pa-gov-schools.org/
  "state-pennsylvania-pgss": { blurb: "A free five-week residential summer science program held on the campus of Carnegie Mellon University for academically talented Pennsylvania high school students who are juniors when they apply. Students take college-level courses, carry out laboratory experiments, and choose electives such as laser technology. Admission is merit-based, with at least one qualified student accepted from each intermediate unit, and program expenses are fully funded for all accepted students." },
  // https://precollege.brown.edu/
  "state-rhode-island-brown-precollege": { blurb: "Brown University runs summer pre-college study for high school students, with over 300 non-credit courses lasting one to six weeks on campus in Providence, online, and at domestic and international locations. Options include Summer@Brown, the Leadership Institute, 12-day study-away trips abroad for ages 16 to 18, and a seven-week online credit-bearing program for rising or recently graduated seniors. Aid includes fee waivers and the Sibley Scholarship." },
  // https://stem.utah.gov/mystem/
  "state-utah-mystem": { blurb: "A competitive, application-based program from the Utah STEM Action Center for Utah students in grades 6 through 12 that builds leadership skills through citizen science and community service. Each participant works with a mentor and STEM advisors to design and carry out an Action Plan, a STEM-focused service project. Participants meet monthly on Saturdays for training and meetings with STEM professionals, and can apply for Utah STEM Foundation funding for their plans." },
  // https://precollege.wisc.edu/
  "state-wisconsin-badger": { blurb: "UW-Madison's precollege office runs summer programs for advanced middle and high school students on the Madison campus. Badger Summer Scholars is a residential or commuter college-prep program for students finishing grades 9-12, with courses on topics such as veterinary science, and the Accelerated Learning Program offers three weeks of rigorous learning in one non-credit course. Other options include the one-week Summer Arts Clinic and the Summer Music Clinic." },
  // https://wyomingspacegrant.org/
  "state-wyoming-space-grant": { blurb: "The Wyoming NASA Space Grant Consortium runs K-12 STEM programs centered on high-altitude balloon flights with Wyoming schools, homeschool groups, afterschool programs, and summer camps. High school students build payloads that test a scientific question or engineering challenge, and flight data can support science fair projects. Other offerings include a space radiation unit for grades 9-12 where teams fly shielding and annual Youth in STEM conferences for grades 7-12." },
  // https://summerjobs.dc.gov/page/mbsyep
  "state-dc-mbsyep": { blurb: "A six-week paid summer work program run by the DC Department of Employment Services for District youth ages 14 to 24. Participants are placed with public, nonprofit, and private employers for structured summer work experience and are paid by the hour at rates set by age group. DC residents in college can apply if they meet the age requirement, and the program runs from late June to early August with a limited number of spots." },
  // https://www.afsascholarship.org/high-school-scholarships/
  "csv-sch-afsa-high-school-senior-scholarship-contest": { blurb: "A no-essay scholarship contest from the American Fire Sprinkler Association for high school seniors who are U.S. citizens or legal residents and plan to attend an accredited college, university, or trade school in the U.S. Entrants learn about fire sprinkler safety and careers in the industry, then complete a short online form that takes about 10 minutes. Home-schooled students may apply, there are no GPA or income requirements, and winners receive $1,000 scholarships." },
  // https://kfcfoundation.org/scholarships/
  "csv-sch-kfc-colonel-s-scholarship": { blurb: "A college scholarship from the KFC Foundation for employees of participating KFC franchise or company-owned restaurants in the United States. Awards of $5,000, $10,000, or $20,000 can be used at accredited two- or four-year colleges, trade or vocational schools, or graduate school. The $10,000 and $20,000 awards require at least a 3.5 GPA, financial information, and an additional essay scored by judges, while the $5,000 award requires a 2.5 GPA." },
  // https://www.uft.org/your-union/uft-programs/uft-scholarship-fund
  "csv-sch-uft-scholarship-fund": { blurb: "A college scholarship from the United Federation of Teachers for New York City public high school seniors graduating from vocational, academic, or alternative schools. Applicants need high academic standing and leadership in school and community, and must apply for federal Pell Grant aid. Winners receive $5,000 paid in installments of $625 twice a year and must be accepted into a full-time, degree-granting program at an accredited college." },
  // https://www.jimmyranefoundation.org/scholarship-eligibility
  "csv-sch-jimmy-rane-foundation-scholarships": { blurb: "A need-based college scholarship from the Jimmy Rane Foundation for students whose permanent home is in an eligible state, such as Alabama, Texas, New York, or West Virginia, or the District of Columbia. High school seniors need at least a 3.0 GPA, and college freshmen and sophomores need at least a 2.75. Awards start at $500 per year and renew for up to four academic years, and online-only programs and intercollegiate athletes are not eligible." },
  // https://www.goarmy.com/careers-and-jobs/find-your-path/army-officers/rotc/scholarships
  "csv-sch-army-rotc-scholarships": { blurb: "Merit-based Army ROTC scholarships for high school students who have finished their junior year and plan to attend one of more than 1,000 participating colleges. Awards can cover up to full tuition and fees or room and board, plus $420 per month for personal expenses and $1,200 per year for books. Applicants must be U.S. citizens with at least a 2.50 unweighted GPA and SAT or ACT scores, and accepting a scholarship carries an eight-year service obligation." },
  // https://beyondtheboroughs.org/scholarship-eligibility
  "csv-sch-beyond-the-boroughs-scholarship": { blurb: "A national scholarship that helps low-income students attend college and offers recipients mentorship opportunities. Applicants are high school seniors or GED recipients entering college for the first time who plan to enroll full-time at an accredited two- or four-year or vocational-technical school, have a FAFSA Student Aid Index below $8,000, and are U.S. citizens or eligible non-citizens. First-generation students get priority, and recipients must keep a 2.5 GPA." },
  // https://foundation649.com/
  "csv-sch-foundation-649-scholarship": { blurb: "An annual scholarship from Foundation 649, a 501c3 nonprofit, for Asian American and Pacific Islander students with financial need who are involved in AAPI communities or causes. Each recipient receives a $4,000 grant paid over four years toward tuition and expenses, with a brief renewal check-in each year. Applicants enter a U.S. accredited university full-time as freshmen or community college transfers and submit a personal video about AAPI identity." },
  // https://www.elks.org/scholars/scholarships/mvs.cfm
  "csv-sch-elks-national-foundation-scholarship": { blurb: "The Elks Most Valuable Student contest awards 500 four-year scholarships each year to U.S. citizen high school seniors, with male and female applicants competing separately. Awards range from $1,000 to $7,500 per year for students enrolling in four-year degree programs at accredited U.S. colleges, and Elks membership is not required. The top 20 winners attend Leadership Weekend, and the contest has waived its standardized test requirement." },
  // https://learnmore.scholarsapply.org/equitableexcellence/
  "csv-sch-equitable-excellence-scholarship": { blurb: "A scholarship from the Equitable Foundation, administered by Scholarship America, for high school seniors in the 50 states, D.C., or Puerto Rico who plan to attend an accredited two- or four-year school full-time. Applicants need at least a 2.5 GPA on a 4.0 scale, and financial need is considered. Recent cycles offered renewable $5,000 awards and one-time $2,500 awards, plus a $500 gift card for each recipient's teacher of choice." },
  // https://imagine-america.org/scholarships/high-school-scholarships
  "csv-sch-imagine-america-high-school-scholarship": { blurb: "A scholarship from the Imagine America Foundation that gives graduating high school seniors a $1,000 award toward tuition at participating accredited career colleges and trade schools. Each high school in the United States and Puerto Rico may nominate up to five graduating seniors. Suggested criteria include a GPA of 2.5 or higher, financial need, a likelihood of completing postsecondary education, and voluntary community service during senior year." },
  // https://poetryoutloud.org/faq/
  "poetry-out-loud": { blurb: "A national poetry recitation contest from the National Endowment for the Arts and the Poetry Foundation in which high school students recite poems and advance from classroom and school contests to state and national finals. State winners receive $200 and an all-expenses-paid trip to Washington, DC, with an adult chaperone. At the national finals, the champion receives $20,000, second place $10,000, and third place $5,000, and finalists' schools get $500 for poetry materials." },
  // https://www.ecybermission.com/
  "ecybermission": { blurb: "A free web-based STEM competition from Army STEM, formerly the Army Educational Outreach Program, for students in grades 6 through 9. Teams of 2 to 4 students, led by an adult Team Advisor such as a teacher or parent, choose a community problem to investigate with science or solve with engineering. Volunteer STEM professionals support teams through live chats and a message board, and top teams are recognized at state, regional, and national levels." },
  // https://mikvachallenge.org/our-work/programs/youth-led-advocacy/
  "mikva-challenge-nli-challenge": { blurb: "A community-based civic leadership program run by Mikva Challenge in Chicago for youth ages 13 to 15 from North Lawndale, Gage Park, and New City/Back of the Yards. Members research the violence they experience in their community, build leadership skills, and develop youth-led safety strategies that they present to local stakeholders and officials. Activities run in the summer and during the school year." },
  // https://engineering.buffalo.edu/home/outreach/camps/csexplore.html
  "university-of-buffalo-csexplore-camp": { blurb: "A free three-day summer day camp at the University at Buffalo's North Campus, run by the School of Engineering and Applied Sciences, for high school students in grades 9-12. Campers move from basic circuits to writing software, program a robot, and design a video game, with occasional visits to campus research labs. No programming background is needed, and local high schools get priority." },
  // https://chrissmith.house.gov/constituentservices/internships.htm
  "congressman-chris-smith-internship-program": { blurb: "A congressional internship in the offices of Rep. Chris Smith, who represents New Jersey's Fourth District, open to a limited number of upperclassman high school students. Interns work in either the New Jersey district office or the Washington, D.C. office. Internships are unpaid, D.C. interns may need to cover their own travel and living costs, and interns in any office can seek academic credit." },
  // https://www.rsa-al.gov/about-rsa/job-postings/summer-interns/
  "the-retirement-systems-of-alabama-the-retirement-systems-summer": { blurb: "A paid summer internship at the Retirement Systems of Alabama, the state's public pension agency in Montgomery, for students who are in high school or have graduated and enrolled in college or trade school. Interns fill temporary Clerical Aide or Laborer positions, typically from early June through mid-August. Applicants must be under age 25, and positions are limited, with a focus on returning interns." },
  // https://mohanlab.bme.uh.edu/open-positions/high-school-students/
  "university-of-houston-mohan-lab-summer-internship": { blurb: "An eight-week summer research internship in the Mohan Lab at the University of Houston's biomedical engineering department for rising high school seniors who have completed 11th grade. After one to two weeks of lab instruction, students do bench research under a scientist or graduate student in areas such as biomedical sciences, big data analytics, and neuroscience, then give an oral presentation. No funding is provided." },
  // https://www.booker.senate.gov/services/internships
  "senator-cory-booker-s-office-high-school-internship": { blurb: "A summer internship for high school students in Senator Cory Booker's offices in Washington, D.C., Newark, and Camden, New Jersey, offered through the Summer High School Accelerated Session. The session runs 14 consecutive business days in August. Newark and Camden interns support constituent work and research, while D.C. interns attend hearings and briefings and give Capitol tours. New Jersey residents get preference." },
  // https://outreach.engineering.columbia.edu/content/shape-summer-high-school-academic-program-engineers
  "columbia-university-summer-high-school-academic-program-for-engi": { blurb: "A tuition-based summer engineering program at Columbia Engineering in New York City for rising high school sophomores, juniors, and seniors. Students take three-week courses taught by Columbia faculty in areas such as robotics, computer science, machine learning, and biomedical engineering, along with electives and college-prep workshops. Two three-week sessions run in July and August, and a commuter option is available." },
  // https://ocfa.org/residents/fire-cadet-interest/
  "orange-county-fire-authority-fire-cadet-program": { blurb: "A youth program run by the Orange County Fire Authority in California that gives young people practical insight into the fire protection profession. Recruits complete a ten-week Fire Cadet Trainee Academy held once per year, then do non-hazardous work such as pre-fire planning and door-to-door fire prevention, plus drills and field trips. Cadets must keep a 2.0 GPA or above and have no arrests or convictions." },
  // https://thefoodproject.org/youth/seedcrew/
  "the-food-project-seed-crew-north-shore-region": { blurb: "A paid six-week summer farm job run by The Food Project for 72 high school students ages 14 to 17, with farms in Boston, Lincoln, Lynn, Beverly, and Wenham, Massachusetts. Crew members farm each morning and spend most afternoons in workshops on sustainable agriculture and food access, and they distribute produce at farmers' markets and hunger relief sites. Students must be available every day of the program." },
  // https://soe.rutgers.edu/academics/pre-college-engineering-programs/new-jersey-governors-school-engineering-and-technology
  "the-governor-s-school-of-new-jersey-program-in-engineering-techn": { blurb: "A free four-week residential summer program at the Rutgers School of Engineering for New Jersey high school juniors, starting near the beginning of July. Students take four academic courses, complete a small research and design project that ends with a research symposium, and visit 2-3 local companies. Donors cover tuition, room, and board, and students pay only a refundable $65 key deposit." },
  // https://lockwoodmathewsmansion.com/education-programs-3/high-school-internship-program/
  "lockwood-mathews-mansion-museum-internship-program": { blurb: "An unpaid internship at the Lockwood-Mathews Mansion Museum, a National Historic Landmark in Norwalk, Connecticut, that accepts up to 5 students from middle school to college each year. Interns assist museum staff with data entry, database management, archival materials, mailings, and school tours. Students may ask the Education Coordinator about earning academic credit." },
  // https://www.writopialab.org/who-we-are/join-the-team
  "writopia-lab-high-school-summer-internships": { blurb: "An unpaid volunteer internship at Writopia Lab, a creative writing nonprofit in New York, for teens at least 15 who have taken a Writopia workshop in the past year. Interns help instructors with typing, story brainstorming, and editorial support and mentor young writers ages 6 to 10. Interns attend a one-hour training and commit to two week-long summer workshops or a trimester-long weekly workshop, and they can earn service hours." },
  // https://www.hypothekids.org/hkmakerlab
  "columbia-engineering-hk-maker-lab": { blurb: "A free five-week summer engineering design program run by HYPOTHEkids with Columbia Engineering in New York City for high school sophomores and juniors. The first three weeks are a session of Columbia's SHAPE program, followed by a two-week hackathon on health equity, running from early July into August. Completers can join NY Bioforce the next year, which includes a paid summer internship." },
  // https://www.medill.northwestern.edu/journalism/high-school-programs/medill-cherubs.html
  "northwestern-university-medill-cherubs": { blurb: "A four-week summer journalism institute at Northwestern University's Medill School in Evanston, Illinois, for up to 90 rising high school seniors. Students study reporting, writing, and editing for print, broadcast, and online media, plus video, audio, photojournalism, and digital storytelling. Each student has an instructor-mentor who critiques work and meets one on one, students live in supervised dorms, and financial aid is available." },
  // https://csp.colorado.gov/community-outreach/youth-academy
  "colorado-state-patrol-colorado-state-patrol-youth-academy": { blurb: "A free one-week summer leadership program run by the Colorado State Patrol for Colorado residents ages 16 to 18, with a three-night stay at the CSP Academy in Golden and all meals provided. Training has covered defensive driving, firearm safety, ethics in law enforcement, self-defense, and crime scene investigation. Applicants need a driver's license or permit, a recommendation letter, and an interview." },
  // https://summer.tulane.edu/newcomb-summer-session
  "tulane-university-newcomb-summer-session": { blurb: "A tuition-based pre-college summer program run by the Newcomb Institute at Tulane University in New Orleans for rising 9th through 12th graders. Students take selective gender studies courses built around discussion seminars and workshops, with topics such as civil rights, media and reproductive health, Louisiana women's activism, and women's life writing. Admission is rolling, and the program grants a certificate of completion." },
  // https://www.pomona.edu/administration/draper-center/pays
  "pomona-college-pomona-college-academy-for-youth-success-pays": { blurb: "A free multi-year college access program run by Pomona College's Draper Center that enrolls up to 90 local high school students, starting as rising sophomores, from Los Angeles, Orange, Ventura, Riverside, and San Bernardino counties. Each summer, students live on campus for a four-week liberal arts session with math and critical inquiry courses taught by Pomona faculty. The college covers housing, food, activities, and field trips." },
  // https://www.ncleg.gov/Senate/PageProgram
  "north-carolina-senate-senate-page-program": { blurb: "A page program at the North Carolina Senate in Raleigh for students in 10th, 11th, or 12th grade who are sponsored by a state senator and in good academic standing. Pages assist senators and staff during the legislative session, working on the Senate floor and in committee meetings. Pages receive a $150 weekly stipend or may choose thirty hours of community service credit instead." },
  // https://www.stamfordmyep.com/application-and-requirements
  "stamford-mayor-s-office-the-mayor-s-youth-employment-program": { blurb: "A paid six-week summer internship program run by the Stamford Mayor's Office for Stamford high school juniors and seniors who live in the city and are authorized to work in the U.S. Participants get 140 hours of real-world work experience plus 27 hours of mandatory leadership workshops on Fridays. The internship runs from late June through July, and applicants prepare a resume and cover letter and interview." },
  // https://mayorsfundlv.org/strong-future-las-vegas-youth-employment-program/
  "mayor-s-fund-for-las-vegas-life-strong-future-las-vegas-youth-em": { blurb: "A youth jobs program run by the Mayor's Fund for Las Vegas LIFE that provides workforce readiness training and paid work to young people in Las Vegas. Participants first take a seven-session course taught by the University of Nevada Cooperative Extension on resumes, time management, interviewing, and professionalism. They are then matched with a summer or after-school job and supported by an adult advisor." },
  // https://genesysworks.org/for-students-and-families/
  "genesys-works-genesys-works-internship-program": { blurb: "A national nonprofit program in which high school students from underserved communities complete summer training, including 160 hours of professional development in business technology and soft skills, before starting a paid year-long corporate internship. Interns work roughly 20 hours a week during senior year and get college and career coaching. Students must be on track to graduate, able to work in the U.S., and able to adjust their senior-year schedule." },
  // https://www.masslifesciences.com/programs/high-school-apprenticeship/
  "massachusetts-life-sciences-center-high-school-apprenticeship-ch": { blurb: "A program of the Massachusetts Life Sciences Center that funds paid internships for underrepresented and low-income high school students at research institutions and small life sciences companies across Massachusetts. Students first take after-school and summer training in biotechnology, biomedical, and professional skills. The center reimburses host organizations up to $4,080 per intern, based on $17 per hour for six weeks of full-time work." },
  // https://www.vai.org/graduate-school/hs-program/
  "van-andel-institute-high-school-graduate-research-program": { blurb: "An eight-week paid summer research program at Van Andel Institute in Grand Rapids for recent high school graduates from the area, focused on biomedical research. Alongside lab work, participants attend workshops, tour other local research facilities, join Q&A sessions with undergraduate fellows, and present a final project. The program runs in June and July, pays $15/hour, and is open to students 17 or older with a minimum 3.0 GPA who are U.S. citizens or permanent residents." },
  // https://www.portseattle.org/programs/high-school-internships
  "port-of-seattle-high-school-internships": { blurb: "Paid summer and winter internships at the Port of Seattle for high school students, with work in areas such as Aviation Operations, Maritime Operations, Governance, Community Engagement, and Green Jobs. The Port states that 100 percent of its internships are paid. Applicants must be at least 16 and eligible to work in the United States, and may be enrolled in high school, recent graduates, or in a GED program." },
  // https://internships.fnal.gov/high-school-student-programs/
  "fermilab-high-school-programs-prism-valor-jrotc": { blurb: "Fermilab in Batavia, Illinois, runs two summer programs for high school students. PRISM is a four-week summer school for Illinois seniors and recent graduates covering particle physics, quantum science, engineering design, and artificial intelligence through hands-on activities, lectures, and lab tours, with a $500 weekly stipend. VALOR JROTC is a paid, six-week in-person internship for Illinois JROTC cadets who are juniors, seniors, or recent graduates, at $18 per hour." },
  // https://cancerresearch.uci.edu/high-school-students/summer-youth-science-fellowship-program/
  "uci-chao-family-comprehensive-cancer-center-high-school-student": { blurb: "A six-week summer research program at the UCI Cancer Research Institute in which Orange County high school students do mentored research in UCI labs. Fellows work about 30 hours a week, mostly in a single lab under an assigned mentor, and also attend seminars and workshops. The program runs from late June to early August and ends with a poster symposium where students present their work." },
  // https://www.loc.gov/item/internships/high-school-summer-internship/
  "library-of-congress-high-school-summer-internship": { blurb: "An unpaid four-week summer internship run by the Library of Congress Informal Learning Office for high school students who want to work with primary sources. Interns research the collections and create materials for families and young readers, and past interns have volunteered at the National Book Festival. The program hosts twelve students in virtual and hybrid formats and is open to current high school students or recent graduates who are 16 or older." },
  // https://dornsife.usc.edu/center-for-political-future/jesse-m-unruh-institute-of-politics/high-school-summer-internship-program/
  "usc-dornsife-center-for-the-political-future-high-school-summer": { blurb: "A fully online summer internship from the USC Dornsife Center for the Political Future with the USC Wrigley Institute, in which high school students study an environmental or sustainability bill at the local, state, or federal level. Interns write a legislative policy memo and a legislative process analysis, attend five check-in sessions and guest speakers, and may publish one assignment online. It is open to rising sophomores, juniors, and seniors with a minimum 3.5 GPA." },
  // https://www.austintexas.gov/economic-development/programs/high-school-internship-opportunities
  "city-of-austin-economic-development-high-school-summer-internshi": { blurb: "Paid summer internships run by the City of Austin and co-funded with Bank of America and the Quality of Life Foundation, with one application covering tracks such as Emerging Leaders, a STEAM-focused Get Ready track, Automotive/Entrepreneurial, and the Aviation Department at Austin-Bergstrom airport. Interns work 20 hours per week for six weeks at $13/hr. Applicants must live in Austin, attend an Austin-area high school, and be between 15 and 18 years old." },
  // https://www.jbei.org/education/research-experiences/iclem-program/
  "joint-bioenergy-institute-iclem-experience": { blurb: "A paid summer research internship at the Joint BioEnergy Institute in Emeryville for income-eligible sophomores and juniors living in Alameda, Contra Costa, or San Francisco County. After a prep week, students spend six weeks on in-person lab research, plus industry field trips, career exploration, and college preparation. Applicants need a GPA of at least 2.5, must have passed Algebra 1 and Biology, and must be U.S. citizens or permanent residents." },
  // https://www.bostonfed.org/community-development/expanding-employment-opportunities/todays-interns-tomorrows-professionals.aspx
  "federal-reserve-bank-of-boston-internship-program": { blurb: "A paid work and learning internship at the Federal Reserve Bank of Boston, run with the Boston Private Industry Council, for eligible students who have completed sophomore year in the Boston Public Schools. It starts with a summer work experience that includes job coaching and skill-building workshops. About 20 students take part each summer, and some are selected for a year-round internship that can last up to three years." },
  // https://www.artic.edu/learn-with-us/teens/opportunities-for-teens
  "the-art-institute-of-chicago-internships": { blurb: "Paid internships and leadership roles for high school students at the Art Institute of Chicago, which states that all of its teen internships are paid. The Summer Internship runs June through August for Chicago high school students who will be at least 16 when it starts, with applications through After School Matters. The Teen Council meets at the museum on most Saturdays from September to June, about 3 to 4 hours a week, and is open to teens at any Chicagoland high school." },
  // https://msgc.org/students/internships/
  "maine-space-grant-consortium-merits-program": { blurb: "A six-week paid summer research internship from the Maine Space Grant Consortium that places Maine high school students at STEM research or technology labs and companies around the state. Interns receive a stipend and present their work at a closing celebration. Applicants must be U.S. citizens, residents of Maine, and enrolled as juniors at a Maine school, and they apply with a student application form and a teacher recommendation." },
  // https://www.metmuseum.org/opportunities/internships/summer-internships-for-high-school-students
  "the-metropolitan-museum-of-art-met-high-school-internship-progra-2": { blurb: "A paid summer internship at The Metropolitan Museum of Art for students in grade 10 or 11 at schools in New York, New Jersey, or Connecticut. Interns attend a bootcamp and complete a departmental placement totaling 40 hours, typically working about 10 to 20 hours per week from early July to early August. Interns receive a $1,100 stipend, housing is not provided, and applicants cannot have completed another Met internship." },
  // https://www.enterpriseforyouth.org/high-school-student
  "enterprise-for-youth-paid-internships": { blurb: "Paid internships arranged by Enterprise for Youth, a San Francisco nonprofit serving youth ages 14 to 24, with placements in sectors such as healthcare, arts, retail, and climate work. Applicants usually start with a six-week job readiness training covering resumes, interview practice, and professional email. Internships last a total of 75 hours at about 12 hours a week, pay $20 an hour, and include weekly workshops and check-ins with a job coach." },
  // https://www.fs.usda.gov/working-with-us/careers/pathways-internships
  "u-s-forest-service-pathways-internships": { blurb: "Paid federal internships with the U.S. Forest Service for students enrolled in accredited high schools, colleges, and trade schools. Interns are hired on a temporary basis for up to one year or for an indefinite period, on full-time or part-time schedules, and can convert to permanent positions after meeting work and education requirements. Openings are posted on USAJOBS, and high school interns are hired at the GS-02 pay grade." },
  // https://med.stanford.edu/pediatrics/education/pediatrics-internship-program.html
  "stanford-medicine-pediatrics-internship-program-at-stanford-pips": { blurb: "A seven-week summer research internship in Stanford Pediatrics for rising high school juniors and seniors, designed for students with little or no prior research exposure. Interns take part 30 hours per week, in person with some remote work. Applicants must live and attend high school in one of seven Northern California counties and have an unweighted GPA of at least 3.0, and students with financial need can receive a $3,000 stipend." },
  // https://www.jshs.org/
  "jshs": { blurb: "A free STEM research competition sponsored by the Department of War and administered by the National Science Teaching Association, for high school students doing original research. Students start at regional symposia hosted by partner universities, open to U.S. citizens and legal permanent residents. About 245 qualify for the national symposium, where the top two regional delegates present orally for tuition scholarships and others present posters for cash awards." },
  // https://www.councilforeconed.org/programs/for-students/national-economic-challenge/
  "national-economics-challenge": { blurb: "An economics competition for high school teams run by the Council for Economic Education, with state-level rounds followed by national semifinals and finals. The semifinals are an online test, and the finals include a written critical-thinking round and a quiz bowl. Teams compete in the Adam Smith Division for AP, IB, and honors students or the David Ricardo Division for first-time competitors with little economics coursework." },
  // https://breakthroughjuniorchallenge.org/
  "breakthrough-junior-challenge": { blurb: "A global science video competition from the Breakthrough Prize Foundation for students ages 13 to 18. Entrants create an original video of up to two minutes explaining a scientific concept or theory in the life sciences, physics, or mathematics. The winner receives a $250,000 post-secondary scholarship, the winner's teacher gets $50,000, and the school receives a $100,000 Breakthrough Science Lab." },
  // https://geniusolympiad.org/
  "genius-olympiad": { blurb: "An international high school project competition on environmental issues, founded and organized by Terra Science and Education and hosted by St. John Fisher University, for students in grades 8 to 12. Students present projects in disciplines including science, art, short film, music, robotics, entrepreneurship, speech, coding, and artificial intelligence. The event brings together more than 1,200 finalists from over 70 countries and 35 U.S. states." },
  // https://envirothon.org/the-competition/
  "envirothon": { blurb: "A team environmental science competition run by the National Conservation Foundation for students in grades 9 to 12, ages 14 to 19. Teams are trained and tested on aquatic ecology, forestry, soils and land use, wildlife, and current environmental issues, and each team also gives an oral presentation. State and provincial winners advance to an annual international competition held each July in a different U.S. state or Canadian province." },
  // https://www.soinc.org/events/2027-division-c-events
  "science-olympiad-national": { blurb: "A team STEM tournament run by Science Olympiad Inc., with 23 events in Division C for high school students. Events span life, personal and social science, earth and space science, physical science and chemistry, and technology and engineering, mixing study, lab, and build events such as Disease Detectives, Chemistry Lab, and Electric Vehicle. Teams advance from regional to state to national tournaments, and invitational tournaments run during the season." },
  // https://mathkangaroo.org/mks/math-kangaroo-competition/
  "math-kangaroo": { blurb: "An international mathematics competition run by Math Kangaroo USA that emphasizes problem solving, with levels for grades 1 through 12. High school students take the grades 9-10 or 11-12 test, a 75-minute multiple-choice exam with 30 questions held in March. A separate in-person team competition in the fall lets teams of 2 to 4 students from different grades and schools compete. Individual registration is $18 per student during regular registration." },
  // https://m3challenge.siam.org/the-challenge/
  "m3-challenge": { blurb: "A free, internet-based applied math contest run by SIAM in which teams of three to five high school students build a mathematical model of a real-world problem. Once a team downloads the problem, it has exactly 14 continuous hours to submit a solution during Challenge weekend. Teams compete for scholarships from a pool of over $100,000, with $20,000 for the champion team, and extra awards go to teams coding mainly in MATLAB." },
  // https://www.acsl.org/get-started/divisions
  "acsl": { blurb: "A computer science contest series run by the American Computer Science League, with four contests during the regular season. In the Senior Division, aimed at high school students with programming experience such as those in AP Computer Science, each contest has an online 30-minute, 6-question short-answer test and a programming problem solved within 72 hours. Schools enter 5-score or 3-score teams, and high scorers are invited to an online Finals at the end of the year." },
  // https://www.congressionalaward.org/prospective-participants/
  "congressional-award": { blurb: "Congress's award for young Americans, earned by setting goals and logging hours in four areas: voluntary public service, personal development, physical fitness, and expedition or exploration. Young people may register at 13 1/2, submit activities starting at 14, and must finish by their 24th birthday. Bronze, Silver, and Gold levels set different hour and month minimums, and every level requires goals in all four areas." },
  // https://www.johnlockeinstitute.com/essay-competition
  "john-locke-essay": { blurb: "An international essay competition run by the John Locke Institute, with questions in ten subjects: economics, history, international relations, law, philosophy, politics, psychology, public policy, science and technology, and theology. Entrants under 19 are judged in Junior or Senior categories by age, with 1st, 2nd, and 3rd prizes in each subject plus a Grand Prize. First-place winners receive a US$5000 scholarship toward any John Locke Institute program." },
  // https://aynrand.org/students/essay-contests
  "ayn-rand-essay": { blurb: "Annual essay contests run by the Ayn Rand Institute on Ayn Rand's novels, open to students worldwide. The Anthem and The Fountainhead contests are open to middle and high school students ages 13 and older, with prizes totaling up to $2,000 for Anthem and up to $25,000 for The Fountainhead. A separate Atlas Shrugged contest is open to high school, college, and graduate students, and entrants may receive a free Rand book." },
  // https://www.theearthprize.org/competition
  "earth-prize": { blurb: "A free global environmental sustainability competition from the Earth Foundation for students ages 13 to 19, who enter alone or in teams of up to five, across classes and schools. Volunteer mentors answer teams' questions online without writing or building the projects, and teams are matched one-to-one with mentors in the later Scholar Phase. The 2027 cycle offers $104,500 in total prizes, and winning teams receive prize funding." },
  // https://aapt.org/programs/physicsbowl/
  "physics-bowl": { blurb: "An international high school physics competition run by the American Association of Physics Teachers. Students take a 40-question, 45-minute timed multiple-choice test under their school's supervision in the spring, online or as a printable PDF. Division 1 is for first-year physics students and Division 2 for second-year students or anyone wanting a challenge, with regional and national recognition. The exam costs $10 per student." },
  // https://www.asdrp.org/about
  "asdrp": { blurb: "A nonprofit research program in Fremont, California, where students in grades 9 through 12 work with mentors from academia or industry to design original projects in fields such as chemistry, biomedical science, and computing. Students write research papers, go through mock peer review, publish in the ASDRP Communications journal, and present posters at an expo. Students outside the Bay Area may work remotely, and terms run in summer, fall, and spring." },
  // https://www.cshl.edu/education/partners-for-the-future/
  "cshl-partners-future": { blurb: "A selective research internship at Cold Spring Harbor Laboratory for Long Island high school students, who are nominated by their school's science chair during junior year and interviewed by lab scientists. Selected seniors spend at least 10 hours a week from September through March doing original research with a scientist mentor in cancer, neuroscience, genetics, plant biology, or quantitative biology labs. Students present their work at a symposium." },
  // https://btiscience.org/education-and-outreach/research-experiences/high-school-research-experience/
  "bti-high-school": { blurb: "A paid summer research internship at the Boyce Thompson Institute on the Cornell campus in Ithaca, for local or regional students who are at least 16 by the program start. Interns spend six to seven weeks full-time on existing projects, mostly in plant science with some bioinformatics, working with a mentor and attending weekly professional development sessions. They present a poster at a symposium in August, and the stipend is about $4,200, without housing or meals." },
  // https://www.jeffersonscholars.org/scholarships/selection
  "jefferson-scholars": { blurb: "A full merit scholarship to the University of Virginia awarded by the Jefferson Scholars Foundation for excellence in leadership, scholarship, and citizenship. Students cannot apply directly; eligible schools nominate a senior, who then submits activities, awards, a personal essay, and a leadership essay. Nominees must also be admitted to UVA and go through regional review and final virtual interviews, and financial need and test scores are not considered." },
  // https://park.ncsu.edu/apply/selection-criteria/
  "park-scholarships": { blurb: "A four-year merit scholarship at NC State University for incoming first-year students, selected on scholarship, leadership, service, and character. It covers tuition and fees, room and board, books and supplies, travel, and personal expenses, and is renewable for eight semesters. Applicants need a minimum unweighted GPA of 3.8 and move through semifinalist, interview, and finalist rounds, and finalists who enroll receive at least a $10,000 scholarship." },
  // https://www.nasa.gov/learning-resources/internship-programs/
  "nasa-ostem-internships": { blurb: "Paid internships run by NASA's Office of STEM Engagement at NASA facilities, offered in fall, spring, and summer sessions. The summer session lasts 10 weeks and fall and spring sessions 15 weeks, and most interns receive a stipend based on academic level and session length. Applicants must be U.S. citizens with at least a 3.0 GPA who are 18 by the session start, so high school seniors may apply only for the summer session right after graduation." },
  // https://4-h.org/about/ways-to-participate/
  "national-4h": { blurb: "A nationwide youth development network delivered mainly through the U.S. Cooperative Extension System that reaches young people in every county and parish. Youth join school and community clubs, 4-H camps, and in-school and after-school programs, and choose projects in science, healthy living, agriculture, and civic engagement. Clubs often meet in the evenings and on weekends, sometimes virtually, and camps are run by state and county offices, so costs vary." },
  // https://www.scgsah.org/residential-high-school
  "sc-governors-school-arts": { blurb: "A public residential arts high school in South Carolina that is tuition-free and serves juniors and seniors, plus exceptional sophomores in Music and Dance; accepted students pay a residence hall deposit and a meal plan fee. The school also runs overnight summer programs of about one to two weeks in creative writing, dance, drama, film, music, and visual arts for 7th to 9th graders, with dance open to 6th to 11th graders. Summer fees vary, and financial aid is available." },
  // https://www.asfaschool.org/apply/financial-aid
  "alabama-school-fine-arts": { blurb: "A tuition-free public specialty school in Birmingham, funded by the State of Alabama, for talented students in grades 7 to 12. Students audition into one of six departments: creative writing, dance, math-science, music, theatre arts, or visual arts. Alabama residents pay no tuition or boarding costs, though some classes and departments carry fees, and students from outside Alabama pay tuition that the school sets each year." },
  // https://ignitefindyourfire.org/
  "ignite-paid-internship": { blurb: "Ignite is a free online mentorship program in which high school mentors teach three-week practical-skills courses over Zoom to students in grades 4 to 8, including during the summer. The organization recruits interns to help support the program, and its site says no prior experience or perfect grades are needed. The site does not list intern pay rates, so applicants should confirm compensation on the hiring page." },
  // https://www.metmuseum.org/opportunities/internships/spring-semester-internships-for-high-school-students
  "the-metropolitan-museum-of-art-met-high-school-internship-progra": { blurb: "A paid spring-semester internship at The Metropolitan Museum of Art for students in grades 10 and 11, or those working toward a High School Equivalency, who attend a high school or home school in New York City. Interns work mainly in museum education, with a focus on educational programming, and no prior experience or knowledge of art or art history is required. Interns receive a $1,100 stipend after completing the program, and those under 18 need working papers." },
  // https://www.stjude.org/education-training/predoctoral-training/k-12/high-school-research-immersion-program.html
  "st-jude-children-s-research-hospital-high-school-research-immers": { blurb: "An eight-week paid summer research program at St. Jude Children's Research Hospital in Memphis for rising high school seniors from the Memphis area and nearby counties in Tennessee, Mississippi, and Arkansas. Students take part in mentored research in laboratory, clinical, or data science settings and are expected to attend all 8 weeks, working 40 hours per week. The program pays a $4,800 stipend and runs from June to July." },
  // https://conrad.spacecenter.org/the-challenge/
  "conrad-foundation-conrad-challenge": { blurb: "A team STEM innovation competition hosted by Space Center Houston for students ages 13 to 18 working in teams of two to five. Teams develop an original innovation in aerospace and aviation, cyber-technology and security, energy and environment, health and nutrition, or water, build a business case, and get feedback from industry experts. The Activation Stage is free, the Innovation Stage costs $499 per team, and finalists pitch at the Innovation Summit in Houston in April." },
  // https://sip.ucsc.edu/applying-to-sip/
  "university-of-california-science-internship-program-sip": { blurb: "A summer research internship at UC Santa Cruz where high school students ages 14 to 17 join existing university research projects in fields such as astronomy, chemistry, computer science, and psychology. UCSC faculty, graduate students, and postdocs mentor small groups of about three interns. It runs 8 weeks, with 1 week of online preparation and 7 weeks of in-person research; there is a $68 application fee, and need-based aid covers 25% to 100% of tuition and fees." },
  // https://internships.fnal.gov/fermilab-program-for-research-innovation-and-stem-mentorship-prism/
  "fermilab-prism-program-for-research-innovation-and-stem-mentorsh": { blurb: "A four-week paid summer program at Fermilab for high school seniors and recent graduates enrolled in an Illinois high school. Each week focuses on a different scientific theme, with topics including particle physics, quantum science, engineering design, and AI. Applicants must be U.S. citizens with proof of medical insurance. The stipend is $500 per week, Fermilab does not provide housing, and transportation assistance is available; the program runs from July to August." },
  // https://www.genesinspace.org/news/press/2025-genes-in-space-contest-opens-call-for-student-proposals/
  "genes-in-space-genes-in-space": { blurb: "A free national contest, co-founded by miniPCR bio and Boeing with support from the ISS National Laboratory and New England Biolabs, in which students in grades 7 to 12 design DNA experiments that use the International Space Station as a testbed. Students enter alone or in pairs and can draw on tools such as PCR and BioBits, and no special lab equipment is needed. Astronauts carry out one winning experiment aboard the station." },
  // https://www.apollotheater.org/education/apollo-theater-academy
  "the-apollo-theater-apollo-theater-academy-high-school-internship": { blurb: "Paid summer internships at the Apollo Theater in Harlem for 12th graders who live in New York City's five boroughs. The Arts Administration Internship explores administrative and programming careers, centered on planning the summer event Teen Takeover. The Technical Stage Production Internship teaches lighting, audio, projection, carpentry, and production design alongside the Apollo's production crew. Applicants under 18 need New York State working papers." },
  // https://www.jhuapl.edu/education/stem-outreach/aspire/internship-timeline
  "johns-hopkins-applied-physics-laboratory-aspire-high-school-inte": { blurb: "An unpaid STEM internship at the Johns Hopkins Applied Physics Laboratory in Laurel, Maryland, where high school juniors and seniors work on a project with an APL staff mentor to explore STEM careers before choosing a college major. The summer session requires 30 to 40 on-site hours per week and at least 190 hours, with a school-year option. Applicants must be U.S. citizens, at least 15 by June 1, with a 2.8 GPA, living in set Maryland, Virginia, or D.C. areas." },
  // https://jobs.fidelity.com/en/students/career-discovery-programs/
  "fidelity-investments-boundless-high-school-internship-program": { blurb: "Fidelity Investments' Boundless program introduces female high school students to careers in financial services through a one-day summit, job shadowing in Boston, and a high school internship. The internship is a 5-week program geared toward upperclassmen in Boston and Merrimack, and it takes applications from community partnerships and eligible students in the Boundless network. Job shadowing pairs each student with a Fidelity associate to learn about that person's role." },
  // https://www.anl.gov/education/bridge-into-internships
  "argonne-national-laboratory-bridge-into-internships": { blurb: "A pre-internship summer program at Argonne National Laboratory, part of the DOE Office of Science's RENEW initiative, that helps recent graduates of Chicagoland high schools prepare for college-level STEM internships. Students spend two days a week with scientific mentors at Argonne and the rest of the week building professional skills with the lab's Institutional Partnerships team. Applicants must be 18 by mid-June and headed to college full-time; it pays a stipend." },
  // https://citylimits.org/apply-now-clarify-reporting-internship-for-nyc-high-school-students/
  "city-limits-clarify-reporting-internship": { blurb: "A paid youth journalism training program run by the New York City newsroom City Limits that has taught high school students public service reporting and news writing since 2014. It is open to New York City students in grade 10 and up, and interns have covered topics such as climate change and the city's cooling centers. The summer session runs six weeks, meeting Monday to Thursday from 10 a.m. to 4 p.m., and a past fall session paid a $500 stipend." },
  // https://www.cc.nih.gov/training/students/summer-internships
  "nih-clinical-center-clinical-center-summer-internship-program": { blurb: "A paid summer internship at the NIH Clinical Center in Bethesda, Maryland, the research hospital of the National Institutes of Health, where about 40 students are chosen each year to work with researchers and health professionals. Applicants must be high school seniors who turn 18 by September 30 of the program year. Interns take part for eight uninterrupted weeks, running from June to August." },
  // https://mtsgreenway.org/get-involved/education/clean-water-ambassadors-internship/
  "mountains-to-sound-greenway-trust-conservation-high-school-inter": { blurb: "The Mountains to Sound Greenway Trust offers paid summer conservation internships for high school students in King County, Washington. Its Clean Water Ambassadors internship, run with King County's Wastewater Treatment Division, is open to local students at least 16, pays $22 an hour, and runs on weekdays in July and August at about 27 hours a week. Interns learn about clean water, explore environmental careers, and build public speaking skills by teaching students." },
  // https://www.cyber.nj.gov/connect/careers/internships/high-school-internship-program
  "new-jersey-cybersecurity-communications-integration-cell-cyberse": { blurb: "A one-week virtual summer internship from the New Jersey Cybersecurity and Communications Integration Cell that teaches cybersecurity basics to New Jersey high school students in grades 9 through 12. Students join either a morning session from 9:00 am to 1:00 pm or an afternoon session from 2:00 pm to 6:00 pm in August and must attend every session. Accepted students provide a letter of support from a parent, guardian, mentor, or teacher." },
  // https://www.emmabowenfoundation.org/apply
  "emma-bowen-foundation-emma-bowen-foundation-internship": { blurb: "A multi-year paid internship program from the Emma Bowen Foundation that places students at companies in media, entertainment, technology, and business, with Business, Content, and Innovation tracks. High school seniors may apply if admitted to a four-year U.S. college with at least a 3.0 GPA. Interns work 35 to 40 hours a week for 8 to 12 consecutive weeks, usually starting in May or June, and must be at least 18 when the internship begins." },
  // https://www.usda.gov/farming-and-ranching/agricultural-education-and-outreach/youth-agriculture/internships-and-career-opportunities
  "usda-youth-internships-and-career-opportunities": { blurb: "A USDA guide to youth work routes with paid options for high school students. Through the Pathways Internship Program, current high school students can hold year-round paid internships, part-time or full-time, with possible conversion to a permanent job after at least 640 hours. Others include the Forest Service Youth Conservation Corps, a paid summer conservation team for teens ages 15 to 18, and an AMS high school intern program at select schools in four cities." },
  // https://www.depts.ttu.edu/clarkscholars/ProgramDetails.php
  "texas-tech-university-anson-l-clark-scholars-program": { blurb: "An intensive seven-week summer research program at Texas Tech University for twelve highly qualified rising high school seniors and recent high school graduates, each working one-to-one with a faculty mentor. There are no program fees, meals and on-campus housing are provided, and a $750 stipend is paid after a successful research project report. Travel is not covered. Applicants must be at least 17 by the start date, and there is a $25 application fee." },
  // https://www.summer.ucsb.edu/programs/research-mentorship-program/overview
  "uc-santa-barbara-research-mentorship-program-rmp": { blurb: "A competitive summer research program at UC Santa Barbara where high school students are paired with a graduate student, postdoc or faculty mentor on an interdisciplinary research project. The 7-week, 8-unit program begins with a virtual component, followed by about six weeks on campus. It is aimed at current 10th and 11th graders, with outstanding 9th graders considered case by case, and requires a minimum 3.80 weighted GPA. Prior research experience is not required." },
  // https://www.bu.edu/summer/high-school-programs/rise-internship-practicum/
  "boston-university-rise-internship-practicum": { blurb: "A six-week summer research program at Boston University for rising high school seniors who are U.S. citizens or permanent residents. Internship students are matched with a faculty, postdoc or graduate student mentor and do research in a university lab for 40 hours per week. Practicum students do group research in a structured lab on subjects such as computational neurobiology and data science. RISE is noncredit, and participants receive a certificate of completion." },
  // https://wssp.rutgers.edu/
  "rutgers-university-waksman-student-scholars-program": { blurb: "A yearlong Rutgers program in which high school biology teachers and their students carry out a molecular biology and bioinformatics research investigation and publish the results. Students analyze DNA sequences and submit vetted analyses to GenBank, the international DNA sequence repository. Students need at least one high school biology course and must be entering grade 10, 11 or 12. Its summer session at the Waksman Institute in Piscataway is two weeks and non-residential." },
  // https://www.janestreet.com/join-jane-street/programs-and-events/amp/
  "jane-street-academy-of-math-and-programming-amp": { blurb: "A free five-week summer program in New York City, run by Jane Street, for recent high school graduates interested in math and computer science who have faced barriers to advanced STEM opportunities. Students study mathematics, programming, data analysis and game theory through classes, problem sets and games like Figgie. Jane Street covers tuition, housing, meals and travel, and each participant who finishes receives a $5,000 scholarship." },
  // https://summer.berklee.edu/programs/aspire-five-week-music-performance-intensive
  "berklee-college-of-music-aspire-five-week-music-performance-inte": { blurb: "A five-week summer music performance intensive in Boston for students ages 15 and up, built to mirror an undergraduate Berklee experience. Each student picks one principal instrument, including voice, for weekly private lessons and takes labs, ensembles, theory and musicianship classes, ending with a week of concerts. Tuition is $5,430 and housing is $4,200. Merit scholarships run from $1,000 to $3,000 up to full tuition, and a credit option offers three elective credits." },
  // https://www.csssa.ca.gov/about-csssa/
  "california-state-summer-school-for-the-arts-california-state-sum": { blurb: "A state-funded, month-long residential arts program for high school students, created by the California Legislature and first held in 1987. Students get pre-professional training in departments such as film, theater, music, writing, animation and visual arts, and graduates are named California Arts Scholars. California residents in grades eight through twelve may apply, along with up to 20 out-of-state students. The 2026 resident fee was $5,174, with need-based aid." },
  // https://www.mathcamp.org/admission/how_to_apply/
  "mathcamp-mathcamp": { blurb: "An intensive summer program in advanced mathematics run by Mathcamp for middle and high school students ages 13 to 18 from around the world. Admission rests mainly on the Qualifying Quiz, an untimed set of 5 to 10 proof-style problems that applicants work on over about two months. Applicants should have finished Precalculus or the equivalent, and top competition scores are not required. Most admitted students solve at least half the problems." },
  // https://fte.org/students/economics-for-leaders-program/
  "foundation-for-teaching-economics-economics-for-leaders": { blurb: "A week-long residential summer program from the Foundation for Teaching Economics, held on college campuses nationwide, that teaches economics alongside teamwork, communication and leadership. Students live in residence halls and attend university classes. It is open to high school sophomores and juniors, with roughly two applicants per spot, and students can earn 3 undergraduate credit hours through UCCS for about $390. The application fee is $35." },
  // https://globalyouth.wharton.upenn.edu/programs-courses/leadership-in-the-business-world/
  "wharton-school-leadership-in-the-business-world-lbw": { blurb: "A selective residential summer program on Penn's Philadelphia campus for 11th graders with demonstrated leadership and a 3.5 unweighted GPA or higher. Coursework covers organizational strategy, negotiation and business model generation, with simulations, a capstone case competition and a speaker series led by Wharton faculty. Wharton selects approximately 120 students per session, with sessions in June, July and August. International applicants are welcome." },
  // https://www.nysacademy.org/programs/nyscamp/
  "national-youth-science-academy-national-youth-science-camp": { blurb: "A free residential summer science camp run by the National Youth Science Academy at Camp Horseshoe in Tucker County, West Virginia, with a kickoff in Washington, D.C. Typically two delegates are selected from each state and the District of Columbia by representatives appointed by their governor, joined by delegates from other Western Hemisphere nations. Delegates attend at no expense, transportation included. The 2026 session ran from July 11 to August 1." },
  // https://www.usna.edu/Admissions/Programs/NASS.php
  "united-states-naval-academy-naval-academy-summer-seminar": { blurb: "A six-day summer program at the U.S. Naval Academy for students who have just completed their junior year of high school. The fast-paced course covers academics, athletics and Navy and Marine Corps service options, showing what life is like as a midshipman and helping students decide whether to pursue an appointment. Sessions run in late May and June, and the 2025 program fee was $550. Students seeking an appointment are urged to attend." },
  // https://sab.org/summer-course/
  "school-of-american-ballet-sab-summer-course": { blurb: "A five-week summer ballet course at the School of American Ballet, the official school of New York City Ballet, for students ages 12 to 18, with entry by audition. Students take classes six days per week in the School's Lincoln Center facility, and all are evaluated as candidates for the Winter Term. Auditions are an abbreviated ballet technique class held on a national tour or in New York, with video applications as an option. The course enrolls just over 200 students." },
  // https://www.scu.edu/engineering/beyond-the-classroom/outreach/summer-engineering-seminar-ses/
  "santa-clara-university-summer-engineering-seminar-ses": { blurb: "A free five-day residential engineering program at Santa Clara University for high school sophomores and juniors with little prior exposure to engineering. Students take introductory workshops taught by engineering faculty and undergraduates, and accepted students receive no-cost campus housing and three daily meals. Sessions run in July, and applications are encouraged from first-generation, women, non-binary, low-income and underrepresented students." },
  // https://education.wolfram.com/summer-research-high-school/admission/
  "wolfram-research-wolfram-high-school-summer-research-program": { blurb: "A summer research program run by Wolfram for students ages 14 to 17, in which each student completes an original computational project mentored by Wolfram staff. Admission involves an online form, a short coding challenge and a video interview, and weighs problem solving and logic over coding ability. About 80 students are admitted each year. The 2026 program ran in late June and July and cost $5,500, with need-based aid covering up to 90% of costs." },
  // https://engineering.buffalo.edu/home/outreach/camps/nsti.html
  "university-of-buffalo-national-summer-transportation-institute": { blurb: "A free one-week, non-residential summer program at the University at Buffalo's North Campus for students entering grades 9-12 who are interested in engineering and STEM. Students take part in design competitions, explore topics such as traffic operations and bridge engineering, and visit regional transportation sites. The program admits 30 students, provides free field trip transportation and lunches, and especially encourages minority and underrepresented students." },
  // https://www.leahknoxscholars.org/
  "leah-knox-the-leah-knox-data-science-and-biomedical-research-sum": { blurb: "A two-year, NIH-funded biomedical research track of the LEAH Project for high school students from Boston, Cambridge and Everett. The first summer is a lab experience at MIT. During the school year, students mentor younger students, get college counseling and attend monthly STEM events, and the second summer is a research placement at a university or industry lab. All program activities are paid by stipend." },
  // https://www.chla.org/research/samuels-family-latino-and-african-american-high-school-internship-program-la-hip
  "children-s-hospital-los-angeles-samuels-family-latino-african-am": { blurb: "A yearlong internship at Children's Hospital Los Angeles for Latino and African American juniors at public high schools in Los Angeles County. Interns spend seven weeks of the summer working full time, 9 a.m. to 5 p.m. on weekdays, in mentored biomedical labs at the Saban Research Institute, and receive college counseling through senior year. Participants get a stipend, a Metro card and meals at the hospital cafeteria." },
  // https://compression.stanford.edu/outreach/shtem-summer-internships-high-schoolers
  "stanford-compression-forum-shtem-summer-internships-for-high-sch": { blurb: "A seven-week summer research internship run by the Stanford Compression Forum, where high school students work on projects in areas such as generative AI, EEG analysis and power grids. It meets in person at Stanford from 9am to 3pm, Monday through Friday, from late June to early August. Rising juniors and seniors who are U.S. citizens or permanent residents and at least 14 may apply. Tuition is $2,500 with financial aid available, and housing is not provided.", cost: "Paid", format: "In-person" },
  // https://www.soche.org/high-school-students/
  "southwestern-ohio-council-for-higher-education-soche-high-school": { blurb: "SOCHEintern, run by the Strategic Ohio Council for Higher Education in the Dayton region, uses one application to match high school students with multiple internship openings. Staff review each applicant's credentials and preferences, refer candidates to hiring managers and notify those selected. The program employs hundreds of students in roles supporting Wright Patterson Air Force Base, the City of Dayton, Montgomery County and many small and mid-sized companies." },
  // https://www.scsjip.org/highschooldivision
  "sotomayor-judicial-internship-program-sonia-celina-sotomayor-jud": { blurb: "A summer judicial internship program that encourages diverse and underrepresented high school students from New York City's five boroughs to pursue careers in law. Interns spend July working for a state or federal judge in New York City while taking part in educational programming, college preparation and mentorship. Applicants must be high school juniors (rising seniors) who live and attend school in the five boroughs and hold a Student General Employment Certificate." },
  // https://csr.utexas.edu/education-outreach/high-school-internships/sees/
  "ut-austin-center-for-space-research-stem-enhancement-in-earth-sc": { blurb: "A summer internship for high school students hosted by the University of Texas Center for Space Research as part of NASA's Science Activation initiative. Students complete distance-learning modules and work remotely with project mentors, then spend two weeks in Austin in July on projects such as astronomy, mission design or virtual geology. It is open to 10th and 11th graders, and scholarship recipients receive housing, meals and local transportation." },
  // https://www.cityofhope.org/academics/students-and-youth/step/step-science-nutrition-summer-research-program
  "city-of-hope-step-high-school-science-nutrition-summer-research": { blurb: "A four-week summer course at City of Hope's Duarte campus where high school students learn nutrition and health concepts while building research skills. It stresses scientific literacy, critical thinking and collaboration, with visits to the Garden of Hope community garden. Sessions meet on select July mornings from 9:00 a.m. to 12:00 p.m. and end with student research presentations. It is open to 9th through 12th graders, and housing is not provided." },
  // https://inl.gov/internships/
  "idaho-national-laboratory-student-internships": { blurb: "A paid summer internship of six to eight weeks at Idaho National Laboratory, where high school students work on real projects under INL researchers. Applicants must be at least 16 years old, U.S. citizens or lawful permanent residents, and hold a minimum 3.0 GPA. The application asks for a statement of interest, high school transcripts, a class schedule, a resume and the names of two teachers who can write recommendation letters." },
  // https://farmvet2b.vetmed.ucdavis.edu/opportunities
  "uc-davis-school-of-veterinary-medicine-student-opportunities-in": { blurb: "The UC Davis School of Veterinary Medicine's livestock medicine outreach program offers high school opportunities in veterinary and animal science. Its Farm Vet internship is a roughly 40-hour spring-break program for Tulare County juniors at the Veterinary Medicine Teaching and Research Center, with visits to a cow dairy, goat dairy and beef feedlot. Applicants need a 3.0 GPA and a letter of interest, and a Milk Quality Lab internship also serves Tulare schools." },
  // https://www.nist.gov/ship
  "nist-summer-high-school-intern-program-ship": { blurb: "A seven-week, unpaid summer research internship that places high school students in NIST research labs on its Gaithersburg, Maryland and Boulder, Colorado campuses. It runs from mid-June to early August. Applicants must be U.S. citizens in their junior or senior year with an unweighted GPA of at least 3.0 who live within 50 miles of the host campus, and families provide their own housing and transportation." },
  // https://fri.cns.utexas.edu/community-outreach/summer-high-school-research-academy
  "university-of-texas-at-austin-summer-high-school-research-academ": { blurb: "A five-week, in-person summer research program run by UT Austin's Freshman Research Initiative, where high school students work with undergraduates and faculty in science labs. Projects span biochemistry, biology, chemistry and related fields, and the program ends with a poster symposium. It is open to Texas residents at least 15 years old entering grades 11 or 12. Tuition is $4,500, participants earn three credit hours through UT Extension, and housing is not provided." },
  // https://mpfi.org/training/high-school-internship/
  "max-planck-florida-institute-for-neuroscience-summer-research-in": { blurb: "A six-week summer research internship at the Max Planck Florida Institute for Neuroscience in which high school students work full time, 40 hours a week, in tracks such as neuroscience wet lab work, scientific programming and mechanical engineering in the machine shop. Interns are paid $14/hour and present their work at the end. It is open to students entering junior or senior year at a Palm Beach or Martin County high school who live in those counties and are at least 16." },
  // https://summerstudents.ucsf.edu/
  "ucsf-benioff-children-s-hospital-oakland-summer-student-research": { blurb: "A seven-week summer research program at UCSF Benioff Children's Hospital Oakland that places high school students in research internships, mostly at the hospital and the MLK Research Building in Oakland, with some at UCSF sites in San Francisco. Applicants must be at least 16 and be sophomores, juniors or seniors who have completed a year each of math and biology. Eligible students receive a stipend of about $3,000, and housing is not provided." },
  // https://lawrencehallofscience.org/teen-internship-programs/teen-internship-2026/
  "lawrence-hall-of-science-teen-internship-program": { blurb: "A paid summer internship at UC Berkeley's Lawrence Hall of Science for teens entering 11th or 12th grade. Interns first complete Saturday workshop trainings in May, then work a full-time summer placement at the Lawrence from early June through early August. Full participation earns a $3,500 stipend, with a deduction for each missed day, and both the workshops and the summer placement are required." },
  // https://www.dmns.org/about/teen-science-scholars/
  "denver-museum-of-nature-science-teen-science-scholar-internship": { blurb: "A summer internship program at the Denver Museum of Nature & Science for about 20 Colorado teens ages 14 to 17 from underserved or underrepresented communities or schools. Scholars work alongside museum scientists in tracks such as paleontology, space sciences, zoology and entomology, while building skills like public speaking and college planning. Sessions run in June or July, and each summer ends with a Showcase where scholars present their work." },
  // https://www.theinternproject.org/
  "the-intern-project-the-intern-project-tip": { blurb: "An 8-week summer internship program in Los Angeles that places high school students with partner companies in fields such as arts and media, engineering and tech, business, government, sports, and healthcare. Interns attend evening workshops, are paid at least minimum wage, get a transportation stipend and earn college credit through Los Angeles Trade Tech College. It is open to first-time applicants in 10th to 12th grade at LA County high schools." },
  // https://futuresandoptions.org/internship-program-application/
  "futures-and-options-the-internship-program": { blurb: "A program of the New York City nonprofit Futures and Options that provides paid, mentored internships and career readiness workshops to high school juniors and seniors. School-year interns work 5 to 10 hours per week after school, while the summer track covers 20 to 30 hours per week over six weeks. Applicants must attend an NYC high school, hold a valid working card and be eligible to work in the United States, and they apply online with a resume before an interview." },
  // https://www.nycbar.org/diversity/thurgood-marshall-summer-law-internship-program/
  "new-york-city-bar-association-thurgood-marshall-summer-law-inter": { blurb: "A New York City Bar Association program that places New York City public high school students in paid summer jobs at law firms, corporations, nonprofits and government offices. Students first complete three mandatory pre-employment workshops, then work 35 to 40 hours a week for 6 to 8 weeks. Applicants from the five boroughs submit a resume, transcript, recommendation letter, working papers and two personal essays, followed by an interview." },
  // https://pageprogram.senate.gov/apply/
  "united-states-senate-us-senate-page-program": { blurb: "A program in Washington, D.C., where high school pages work as Senate Sergeant at Arms employees and attend the Page School, which teaches junior-year Honors courses. Semester pages are juniors aged 16 or 17 who live at the Daniel Webster Senate Page Residence, and summer pages may be rising juniors or seniors. Applicants need a 3.0 GPA and apply through their own senator, with 30 page positions serving 100 senators. Pay is at an annual rate of $38,547." },
  // https://americananthro.org/practice-teach/virtual-high-school-internship/
  "american-anthropological-association-virtual-high-school-interns": { blurb: "A four-week summer virtual internship with the American Anthropological Association in which high school students adapt current anthropological scholarship for students in grades 6 to 12. Interns work about 10 hours a week on a primary project and on a secondary project that usually focuses on accessibility or public education. The program runs in June, and past interns' work appears on the association's Understanding Migration site." },
  // https://www.nps.gov/subjects/youthprograms/jobs-and-internships.htm
  "u-s-national-park-service-youth-conservation-corps-ycc": { blurb: "A paid summer job program from the National Park Service in which teens ages 15 through 18 work on conservation crews at individual national parks. Positions last about 8 to 10 weeks and are non-residential, except at Yellowstone National Park. Students apply directly to the park they are interested in, since each park sets its own dates, pay and application process, and most parks do not provide housing." },
  // https://manhattanda.org/careers/internship-opportunities/high-school-internship/
  "manhattan-district-attorney-s-office-high-school-internship-prog": { blurb: "A paid five-week summer internship at the Manhattan District Attorney's Office for high school juniors and seniors who live in Manhattan. Interns take part in workshops and discussions, a mock trial program and professionalism training in an office setting. The program is in person, Monday through Friday from 9:30 am to 4:30 pm, and interns are paid minimum wage. Applicants submit a one-page resume and a 300-word essay on their interest in criminal justice." },
  // https://www.greenguerillas.org/summer-youth-tiller
  "green-guerillas-summer-youth-tillers-internship": { blurb: "A paid summer internship run by Green Guerillas that places young people ages 14 to 17 in New York City community gardens, where they support gardeners through the busiest part of the season. Interns explore community gardening, food justice and environmental stewardship through composting, mulching, weeding, building simple tables and pathways, and workshops. No prior gardening experience is needed. The 2025 session paid $16.50 an hour." },
  // https://sjvpremed.ucsf.edu/sbi
  "ucsf-fresno-summer-biomedical-internship-program": { blurb: "A summer research internship at UCSF Fresno that matches high school juniors with faculty members who have research projects, in the summer between junior and senior year. Interns help with data collection and background research and get early exposure to medical careers. It runs from mid June to early August at no cost to students. Applicants must be at least 16 by June 1, have a 3.0 GPA or better, and live in Fresno, Madera, Merced, Kings, Tulare or Mariposa County." },
  // https://precollege.barnard.edu/health-society-institute
  "barnard-college-health-and-society-institute": { blurb: "A three-week tuition-based summer program at Barnard College in New York City for rising high school juniors and seniors that looks at how science and medicine shape what counts as disease. Students take one course on themes such as biomedicine as a cultural system, surveillance and care, and the US public health system, plus a concurrent course in qualitative research methods. Faculty include anthropologists, and students can commute or live on campus.", url: "https://precollege.barnard.edu/health-society-institute" },
  // https://www.morgan.edu/saams
  "morgan-state-university-summer-academy-of-actuarial-and-mathemat": { blurb: "A free summer academy at Morgan State University for rising 11th and 12th graders interested in math, actuarial science and computer science. Students take actuarial and math coursework, attend professional development seminars and field trips, and compete in an actuarial case competition judged by industry professionals. Most of the program is virtual, with a final week on campus where room and board are provided. There is no cost to apply or enroll." },
  // https://history.idaho.gov/gem/
  "idaho-state-historical-society-gem-high-school-internship-progra": { blurb: "A paid internship at the Idaho State Museum in Boise, run by the Idaho State Historical Society, where high school students get behind-the-scenes access and work with historians, curators and designers. Interns take part in exhibit design, youth and family programming and event planning. Each cohort curates, develops and designs a poster exhibition and helps plan and host an opening event, and interns can take field trips to other historical society sites." },
  // https://www.genspace.org/biorocket
  "genspace-biobus-junior-scientist-internship": { blurb: "A six-month science research internship at Genspace in Brooklyn for New York City public and charter high school students ages 16 and up. The spring part is an after-school program and the summer part is a research internship, mostly in person Monday through Thursday with a virtual Friday session. Interns learn lab techniques, genetic engineering and science communication with mentors. No transcript or minimum GPA is required, and the program offers a $2,000 stipend." },
  // https://tisch.nyu.edu/special-programs/high-school-programs/tisch-spring-future-artists-program
  "new-york-university-tisch-future-artists": { blurb: "A free 14-week arts program at NYU Tisch School of the Arts that meets on Saturdays each spring for high school freshmen, sophomores and juniors. Students join one track, such as Future Dancers and Dancemakers, Future Dramatic Writers, Future Filmmakers, Future Game Designers, Future Imagemakers, Future Music Moguls or Future Theatre Artists. It is designed for students who may not have access to other arts programs, has no minimum GPA, and requires attendance at every class." },
  // https://www.areteeducation.org/programs
  "arete-education-the-arete-internship-program": { blurb: "Aret\u00e9 Education offers paid internships for high school students in teaching, STEM and the arts at its New York City campuses during the school year. In its Career Connected Learning initiative, interns are placed in academic intervention classrooms, where they partner with middle school teachers to support student learning. Other tracks have included small group tutoring for middle schoolers in ELA or math and financial literacy work with Citizens Bank branch managers." },
  // https://naturemuseum.org/programs/teens
  "peggy-notebaert-nature-museum-teenagers-exploring-and-explaining": { blurb: "A paid internship at the Peggy Notebaert Nature Museum for Chicago high school students, with fall, spring and summer sessions. Participants run field and lab investigations on urban ecology, contribute data to community science projects, add specimens to the Chicago Academy of Sciences' collections and join local habitat restoration. In summer, teens work in groups of two to four on their own field investigations. Applications go through After School Matters.", url: "https://naturemuseum.org/programs/teens" },
  // https://camdencityschools.org/students/swag-summer-intern-program/
  "s-w-a-g-camden-summer-intern-program": { blurb: "A summer youth employment program run by the Camden City School District for Camden middle and high school students ages 14 to 19, meant to prepare them for future work. Recent sessions have run five weeks, with students working Monday through Thursday from 9:30 am to 3:00 pm, up to 20 hours a week. Students cannot be failing core courses required for graduation, and applicants submit two letters of recommendation, immunization records and a recent report card." },
  // https://omsi.edu/teens/science-squad/
  "oregon-museum-of-science-and-industry-science-squad": { blurb: "A free teen volunteer group at the Oregon Museum of Science and Industry in Portland where high school students lead science activities on the museum floor and build communication and leadership skills. It is part of the Teen Science Alliance, a multi-tiered program for students in 9th through 12th grade, and teens join after completing 60 hours in Thinkineers: Outdoors. Members commit to 72 hours of service and can then apply for apprenticeships with museum departments." },
  // https://www.philaculture.org/bloomberg-arts-internship
  "greater-philadelphia-cultural-alliance-bloomberg-arts-internship": { blurb: "A paid eight-week summer internship run by the Greater Philadelphia Cultural Alliance, with funding from Bloomberg Philanthropies, that places rising high school seniors in Philadelphia at arts and culture organizations to prepare for careers in the creative economy. Pay was $20 or more per hour for summer 2026, with transportation and meal support. Select interns can continue in a school-year track during senior year." },
  // https://marktwainhouse.org/edu/educational-programs-internships/
  "the-mark-twain-house-museum-student-internship-program": { blurb: "The Mark Twain House & Museum in Hartford, Connecticut, hosts on-site and remote interns from high school through graduate school, with high school students working on writing, history and museum projects in the summer and during the school year. The museum also runs the Nook Farm Writers Collaborative, a six-week paid summer writing apprenticeship for ages 14 to 18 that meets Monday through Wednesday and Friday, 9 AM to 3 PM, with an $800 stipend." },
  // https://www.shetechexplorer.com/students/summer-internship
  "shetech-shetech-summer-internship-exploration-program": { blurb: "A free two-week hybrid summer program run by the Women Tech Council's SheTech initiative in Utah for high school girls in grades 9 through 12. Participants tour technology companies, meet women in tech, work with Silicon Slopes tech companies and take part in brainstorming sessions on tech problems while learning about the real-world impact of STEM degrees. Sessions take place in June, and the program has run since 2017." },
  // https://www.moffitt.org/education/research-education-and-training/pre-college-programs/hip-imo/
  "moffitt-cancer-center-high-school-internship-program-in-integrat": { blurb: "An eight-week summer team-science internship at Moffitt Cancer Center in Tampa where high school students apply mathematical modeling to cancer research. Interns attend daily from 10 a.m. to 4 p.m. at the Stabile Research Building, give a 15-minute presentation at a research day and write a three-page scientific report. Applicants must be at least 16 by the start date and in grade 11 or below. Selected students receive a $1,000 scholarship, and housing is not funded." },
  // https://ccreadiness.uchicago.edu/pages/uchicago-youth-internship-program
  "university-of-chicago-university-of-chicago-youth-internship-pro": { blurb: "A paid two-summer internship run by the University of Chicago Office of Civic Engagement for Chicago public high school students, including charter school students, who are at least 16. Year 1 covers workshops, seminars, college tours and career preparation. Year 2 is a six-week placement in a university unit in health sciences, computer sciences or IT services. Interns earn Chicago's minimum wage for up to 20 hours a week." },
  // https://www.getty.edu/education/teen-programs/teen-gallery-guides/
  "the-getty-villa-teen-gallery-guide": { blurb: "A paid summer internship at the Getty Center and Getty Villa in Los Angeles where high school students research artworks and learn to lead gallery tours for school groups and visitors. Interns receive a stipend, lunch and transportation, and must attend every scheduled day from mid-June to early August. Applicants must be current sophomores or juniors in Los Angeles County, be 16 by the program start, and live within 25 miles of the Getty Center." },
  // https://vancortlandt.org/programs-overview/internships/
  "the-van-cortlandt-park-alliance-urban-ecology-teen-internship": { blurb: "A paid summer high school internship run by the Van Cortlandt Park Alliance since 2012 to prepare students for college and environmental careers. Interns work in the park alongside horticulturists and restoration staff, take nature-focused field trips and meet natural resource professionals. First-year interns can earn a tuition-free, three-credit SUNY ESF course in climate justice, and returning interns have tracked invasive Japanese knotweed and the Asian jumping worm." },
  // https://www.studentresearchnyc.org/our_programs/brooklyn-college-now-stem-research-academy/
  "cuny-brooklyn-college-now-stem-research-academy": { blurb: "A free two-semester research program run by CUNY College Now at Brooklyn College for New York City public high school sophomores and juniors. In the spring, students take a Saturday ocean ecology course and earn three college credits while learning research practices. Selected students then join a 6-week summer research experience with CUNY research faculty, on projects such as wildlife studies in Jamaica Bay, and receive a MetroCard and a stipend on completion." },
  // https://www.charlestoncounty.gov/ads/slip.php
  "charleston-county-student-leadership-intern-program-cdc-ems": { blurb: "A paid two-year public safety internship run by Charleston County's Consolidated 9-1-1 Center and Emergency Medical Services in Charleston, South Carolina. Interns get on-the-job training and earn credits toward high school graduation. They work weekdays for four to six weeks in the summer and some weekends during the school year, at $16.30 an hour. Applicants must live in the county and be juniors at a Charleston County public high school." },
  // https://www.wheaton.edu/wheaton-college-summer-institute/
  "wheaton-college-wheaton-college-summer-institute": { blurb: "A two-week residential pre-college program at Wheaton College in Illinois for rising high school sophomores, juniors and seniors. Students live on campus and take one college-level course for 2 college credits, with classes averaging about 15 students. The program usually runs during the last two weeks of June and costs $2,500. Students who complete the course and later enroll at Wheaton can receive a $500 scholarship, renewable for four years." },
  // https://precollege.barnard.edu/plate-planet-lab
  "barnard-college-sustainable-food-institute-sustainable-food-inst": { blurb: "A three-week, tuition-based summer program at Barnard College in New York City where rising high school sophomores, juniors and seniors study sustainable food systems. Units cover agriculture, health, policy and justice, food systems and climate change, and soil health. Each week students visit farms across the city and New York state to learn from farmers, and they finish with a final project. Students can attend as exploratory, commuter or residential participants." },
  // https://portal.ct.gov/dot/ct-careers/student-opportunities
  "ct-department-of-transportation-high-school-cooperative-educatio": { blurb: "A paid cooperative education role with the Connecticut Department of Transportation for high school students in technical programs or related studies. Interns gain practical experience in areas such as maintenance, automotive, carpentry, electrical, HVACR and plumbing at department locations around the state. Applicants must be high school juniors or seniors, at least 16 years old. Students who want academic credit alongside the hourly wage can arrange it with their academic advisor." },
  // https://www.brookfieldzoo.org/KingScholars
  "chicago-zoological-society-king-conservation-leadership-academy": { blurb: "A free, year-round conservation and STEAM program at Brookfield Zoo Chicago, run by the Chicago Zoological Society, whose Science Scholars track serves high school students in grades 9-12. Scholars choose workshops, courses and activities, log a minimum number of engagement hours each year and complete a capstone project. Active participants can qualify for behind-the-scenes tours, job shadowing and trips, and those at least 16 can apply for paid teen roles." },
  // https://wtp.mit.edu/
  "massachusetts-institute-of-technology-women-s-technology-program": { blurb: "A four-week residential summer program at MIT in Cambridge, Massachusetts, for students between 11th and 12th grade who are strong in math and science but have little or no engineering background. The program focuses on mechanical engineering coursework and gives priority to students whose high schools offer limited access to STEM classes. Applying is free, and the program reports that 95% of participants received financial assistance and 70% attended at no cost." },
  // https://psjp.princeton.edu/
  "princeton-university-the-princeton-summer-journalism-program": { blurb: "A free, year-long journalism and college prep program at Princeton University for high school juniors from limited-income backgrounds. The summer intensive is hybrid and ends with a 10-day residential stay on campus, where students produce a newspaper. Up to 40 students are admitted each year, and each is matched with a college adviser through senior year. Applicants need at least a 3.5 unweighted GPA and a household income at or under $65,000, and all travel, housing and meal costs are covered." },
  // https://www.neaq.org/engage/teen-programs/teen-internships/
  "new-england-aquarium-summer-teen-internships": { blurb: "A paid summer internship at the New England Aquarium in Boston for about 40 teens from Boston, Cambridge and nearby communities. Interns join the Visitor Experience team or the Interpretation and Engagement team, teaching guests about animals and ocean conservation. After a week-long orientation, they work two days a week for six weeks and take two hours of professional development each week. Teens are eligible from age 14 through the summer after high school graduation." },
  // https://discoverykidslv.org/support/volunteer/youthworks-internship/
  "discovery-children-s-museum-youthworks-internship": { blurb: "A paid internship at DISCOVERY Children's Museum in Las Vegas for current high school students ages 15 to 17. Started in 1993, it combines career guidance and life-skills training with work in the museum's galleries. Applicants must already be active museum volunteers in good standing who have completed volunteer training in all eight galleries. Positions are limited, and interns earn income for personal needs while gaining work experience." },
  // https://chicagophilharmonic.org/community-engagement/
  "chicago-philharmonic-chicago-philharmonic-paid-summer-internship": { blurb: "A paid summer internship with the Chicago Philharmonic for four Chicago high school students each year. Interns work across the orchestra's arts administration departments, including marketing, development, operations and community engagement. The program also includes a performance component led by orchestra musicians, who mentor the interns. The internship has run each summer since 2018." },
  // https://forsyth.org/forsyth-student-scholars-summer-program/
  "forsyth-institute-forsyth-student-scholars-summer-internship-pro": { blurb: "A paid summer research internship at the ADA Forsyth Institute for high school students in the Boston and Eastern Massachusetts area. Interns work in labs alongside research scientists on oral and craniofacial science and present findings from their own research project at the end. The program runs from late June through August, 35 hours a week at minimum wage, with a transportation pass. Students in 9th, 10th or 11th grade at the time of application can apply." },
  // https://www.iit.edu/academics/elevate-college-prep/summer-programs
  "illinois-institute-of-technology-summer-programs": { blurb: "Tuition-based summer programs from Illinois Tech's Elevate College Prep for rising high school freshmen through seniors, typically ages 14 to 17. Students choose virtual, daytime or overnight programs on the Mies Campus in Chicago, with some daytime programs at the Rice Campus in Wheaton. Topics include chemistry, architecture, robotics, coding, game design, cybersecurity, pre-health, law and AI. Most daytime programs last one week in late June or July, and some classes offer college credit." },
  // https://ucnj.org/dhs/youth-services/youth-forward/
  "union-county-youth-forward-program": { blurb: "A free job readiness and employment program run by Union County, New Jersey, through its American Job Center for residents ages 14 to 24. Participants receive job placements, internships, tutoring, GED help, career and college counseling, and training and certification courses. It is funded by a federal Workforce Innovation and Opportunity Act grant and serves low-income young people who face barriers to employment. In-school youth must be 14 to 21 and low-income." },
  // https://icahn.mssm.edu/about/departments-offices/oped/academic-community-culture/ceye
  "the-icahn-school-of-medicine-at-mount-sinai-cultivating-neurolog": { blurb: "Summer and school-year science and medicine programs for New York City high school students run by the Center for Excellence in Youth Education at the Icahn School of Medicine at Mount Sinai. Options include a hybrid Medical and Scientific Exploration Program taught by department leaders, and a competitive Internship Placement Program where students work daily with a Mount Sinai mentor in tracks such as Hospital Placement, Veterinary Sciences and NeuroSurgery Scholars. Summer programs are open to all NYC high school students." },
  // https://mikvachallenge.org/our-work/programs/youth-led-advocacy/
  "mikva-challenge-citywide-youth-council": { blurb: "A youth policy council run by Mikva Challenge in Chicago where high school students act as policy advisors and advocates to city leaders such as the CEO of Chicago Public Schools and the Cook County Board President. Each council has 20 to 25 members working on an issue such as schools or safety and justice. In summer, members meet about 20 hours a week for six weeks, and during the school year they meet every other week." },
  // https://www.unomaha.edu/college-of-information-science-and-technology/engagement/high-school-internship-program.php
  "the-university-of-nebraska-omaha-high-school-internships": { blurb: "A summer internship at the University of Nebraska Omaha's College of Information Science and Technology where high school students work on-site in research labs alongside faculty and college students. Projects span robotics, bioinformatics, software engineering, cybersecurity, public health informatics, web development and mobile apps. Interns work 20 hours a week for 6 weeks. Applicants must be 16, entering 10th, 11th or 12th grade, and have their own transportation to campus." },
  // https://greenheartsc.org/2026/02/17/summer-2026-job-opportunities/
  "the-green-heart-project-crew-member": { blurb: "A paid summer job with The Green Heart Project, a nonprofit that runs urban farms in the Charleston, South Carolina area. Crew members grow and harvest crops, help at the onsite farm stand and join educational workshops and field trips. The role runs for about six weeks in June and July, 25 hours a week Monday through Thursday, at $12 an hour for new employees and $13 for returning ones. Applicants must be 14 to 18 and have completed 9th grade." },
  // https://gccri.uthscsa.edu/gccri-donald-g-mcewen-memorial-summer-research-program/
  "the-university-of-texas-health-science-center-at-san-antonio-gre": { blurb: "A ten-week summer research program at the Greehey Children's Cancer Research Institute at UT Health San Antonio where high school and undergraduate students carry out hypothesis-driven childhood cancer research in an institute lab. Principal investigators match students to projects by interest, and the program ends with a research symposium. High school applicants must be at least 16 by the start date and do not receive a stipend." },
  // https://research.sanfordhealth.org/academic-programs/k-12-programs/high-school-research-scholars-program
  "sanford-research-promise-scholars-summer-internship": { blurb: "A 10-week summer research internship at Sanford Research in Sioux Falls, South Dakota, where high school students work on biomedical science projects under a Sanford mentor. Scholars present a scientific poster at the Sanford Research Symposium and earn three University of South Dakota credits plus a $4,000 scholarship. Applicants must be entering their senior year and at least 16 by June 1. Housing is not provided." },
  // https://www.lavote.gov/home/voting-elections/pollworker-information/student-election-worker-program/student-pollworker-program
  "los-angeles-county-registrar-recorder-county-clerk-los-angeles-c": { blurb: "A paid program run by the Los Angeles County Registrar-Recorder/County Clerk that places high school students as election workers at vote centers. Students attend training, help open and close the vote center and assist voters during a 3-day assignment. They earn $100 per day served and $80 for completing training, up to $480 in total. Applicants must be at least 16 by Election Day, have a GPA of at least 2.5 and be U.S. citizens or green card holders." },
  // https://uco.edu/cms/students/soe-academy
  "university-of-central-oklahoma-engineering-summer-academy": { blurb: "A free engineering summer academy run by the University of Central Oklahoma School of Engineering where students try 3D printing, robotics, aerodynamics and other engineering activities. It runs as two separate 5-day sessions, each limited to 15 students. The academy is for commuting students only, and every participant receives a stipend for daily travel costs along with daily lunch. The most recent camp listing is for rising 8th to 10th graders." },
  // https://www.audubon.org/vermont/projects/vermont-youth-conservation-leadership-program
  "audubon-vermont-junior-conservation-technician-program": { blurb: "A set of paid, work-based and service-learning programs at Audubon Vermont for young people, based at the Green Mountain Audubon Center in Huntington. Teens ages 14 to 18 can join the Junior Conservation Technician program, a six-month role doing conservation work such as bird banding and invasive plant removal, or work as paid summer Counselors in Training who help lead environmental activities for younger campers." },
  // https://www.nycgovparks.org/programs/rangers/conservation-corps
  "new-york-city-department-of-parks-recreation-the-ranger-conserva": { blurb: "A free internship with the NYC Parks Urban Park Rangers where high school students in grades 9 to 12 do environmental restoration work in natural areas of the city's flagship parks. It runs in two sessions each year, in the fall and spring, each lasting about eight weeks, and meets one school-day afternoon a week for 2 to 2.5 hours. Interns earn community service hours, and some sessions include field trips such as canoeing and overnight camping." },
  // https://www.unmc.edu/alliance/admissions/student-criteria.html
  "high-school-alliance-program-of-the-university-of-nebraska-medic": { blurb: "A selective school-year program run by the University of Nebraska Medical Center and Nebraska Medicine for high school juniors and seniors from participating public school districts who are interested in medicine. Applicants must be at least 16 at the start of the school year and have a B or better in Algebra 1, Biology, a physical science course and a third year of science. Only 65 spots are open each year, and applicants submit an essay and recommendations and complete an in-person interview." },
  // https://www.price.utah.edu/k12/high-school-summer-research-internship
  "university-of-utah-john-and-marcia-price-college-of-engineering": { blurb: "A free eight-week summer research internship at the University of Utah Price College of Engineering where high school students are matched with a faculty lab and work on a project assigned by a principal investigator. Interns do 30 hours of research per week, Monday through Friday, and present their work at a symposium at the end of the program. The internship is for rising seniors, is unpaid and does not include housing." },
  // https://www.dpr.com/build-up-high-school-internship
  "dpr-construction-high-school-internship": { blurb: "A paid eight-week summer internship with DPR Construction in Houston, Texas, where high school students work 35 to 40 hours per week on an active jobsite. Interns support subcontractor coordination, document control, quality inspections and safety training, and complete a capstone project. It is open to rising juniors and seniors and recent graduates from families with income below 80% of the area median, and transportation stipends are available." },
  // https://voelckeracademy.uthscsa.edu/students/
  "the-university-of-texas-health-science-center-at-san-antonio-voe": { blurb: "A three-year biomedical research program at UT Health San Antonio for San Antonio-area high school students that begins with a seven-week summer research intensive on campus. Scholars learn lab skills, medical terminology and how to read research articles, then do faculty-mentored research in later summers and join activities during the school year. Scholars receive stipends and transportation help. Applicants are nominated by their schools and must be rising sophomores." },
  // https://www.uwyo.edu/ceps/resources/outreach/programs/esp.html
  "university-of-wyoming-engineering-summer-program": { blurb: "A week-long June summer program at the University of Wyoming where high school juniors from Wyoming and other states take part in engineering experiences. Students choose two courses from topics such as additive manufacturing, robotics with Raspberry Pi and aerodynamics, and stay in campus residence halls with meals at Washakie Dining Center. The program selects 36 students, and the 2026 session cost $350." },
  // https://langston.edu/academics/special-programs/high-school-summer-programs/
  "langston-university-math-and-science-academy": { blurb: "A free two-week residential summer academy at Langston University for students entering their sophomore, junior or senior year with a B average or higher in math or science. Students do lab work in math, chemistry and biology, visit the university's Aquatic Center and Goat Research Center, and take ACT preparation classes before sitting the official ACT on the last day. Students who complete the academy receive $100." },
  // https://www.uchicagomedicine.org/cancer/education-outreach/student-education/high-school-undergraduate/researchstart
  "uchicago-medicine-university-of-chicago-medicine-researchstart-p": { blurb: "A paid eight-week summer cancer research training program run by the UChicago Medicine Comprehensive Cancer Center for high school students from the Chicago and Urbana-Champaign areas. Students do lab research with cancer researchers, supported by workshops on career and skill building. The program focuses on students from backgrounds underrepresented in the sciences, and prior research experience is not required." },
  // https://outreach.engineering.columbia.edu/SHP
  "columbia-university-science-honors-program-shp": { blurb: "A selective Saturday science program at Columbia University for high school sophomores, juniors and seniors with a strong interest in science and math. Classes meet on the Morningside campus from September through May, from 10:00 AM to 12:30 PM, and cover the physical, chemical, biological, behavioral and computing sciences, taught by research-active faculty. Students must live within 75 miles of campus. Tuition is waived, and families are asked for voluntary contributions." },
  // https://sps.northwestern.edu/pre-college/college-bridge/
  "northwestern-university-northwestern-pre-college-college-bridge": { blurb: "A summer partnership between Northwestern University and Chicago Public Schools that lets high school juniors take a college course for credit. Each of the 25 admitted students enrolls in one undergraduate course, generally at the 100 or 200 level, on the Evanston or Chicago campus or online, with courses lasting three to ten weeks. Tuition and textbooks are free. Applicants must be current CPS juniors with a cumulative GPA of at least 3.5." },
  // https://www.bbg.org/learn/gap
  "brooklyn-botanic-garden-the-garden-apprentice-program-gap": { blurb: "A nine-month apprenticeship at Brooklyn Botanic Garden for teens in grades 9 to 11, running from March to November, with tiers that build on each other. Apprentices commit about 4 to 6 hours a week in spring and fall and 20 to 25 hours a week in summer. There is no fee, Tier 1 to 3 apprentices receive a one-time reimbursement of $600 to $800, and Tier 4 apprentices earn $17 per hour. Each tier accepts 12 to 14 apprentices." },
  // https://inspire.cincinnatichildrens.org/inspire-august-september-2021/brims/
  "university-of-cincinnati-biomedical-research-internship-for-mino": { blurb: "A paid nine-week research internship at Cincinnati Children's Hospital Medical Center, started in 2010 to build a pipeline of minority students into STEM careers. High school seniors and college freshmen from Greater Cincinnati work full time as research assistants guided by faculty mentors. The program also includes weekly networking and diversity luncheons, shadowing of minority faculty, and workshops on scientific writing and research ethics." },
  // https://today.uconn.edu/2026/07/connecticut-high-school-and-college-students-present-their-summer-research/
  "uconn-health-high-school-student-research-apprentice-program": { blurb: "A paid summer research program run by UConn Health's Health Career Opportunity Programs where Connecticut high school students in 11th and 12th grade who are interested in medicine, dental medicine or biomedical research work in a basic science or clinical laboratory. Students earn a stipend and present their research at a symposium at the end of the six weeks. Placements have included the UConn School of Medicine, the UConn School of Dental Medicine and Central Connecticut State University." },
  // https://smc-foundation.org/education/high-school-fellowships/
  "stillwater-medical-foundation-high-school-fellowships": { blurb: "A summer healthcare fellowship from the Stillwater Medical Foundation in Oklahoma that selects four high school students each year to explore healthcare careers. Fellows shadow physicians, nurses and allied health staff and typically take field trips to Oklahoma's medical schools and specialty centers. The six-week program usually begins in the first week of June, and fellows earn a $2,000 stipend. Applicants must attend a high school in the Stillwater Medical service area." },
  // https://mcachicago.org/learn/youth/tca
  "museum-of-contemporary-art-teen-creative-agency": { blurb: "A paid cultural leadership program at the Museum of Contemporary Art Chicago where Chicago-area teens use contemporary art to address issues they care about. Members meet at the museum every Saturday from September through June, building collaboration skills and developing projects and public events with two Lead Artists. The group curates 21Minus, an annual showcase of teen creativity, and members receive a monthly stipend. The current call lists ages 14 to 18." },
  // https://summer.yale.edu/apply/pre-college-students
  "yale-university-yale-summer-session": { blurb: "Yale University's summer session admits high school students finishing their junior or senior year to take Yale courses alongside college students, most of them undergraduates. Full-time pre-college students take two courses (2 credits) per session, in person or online, and in-person students generally live on campus. Applicants must be at least 16 by the program start date. The program charges tuition and does not offer financial assistance to high school students." },
  // https://ragoninstitute.org/rise-ragon-institute-summer-experience/
  "ragon-institute-rise-ragon-institute-summer-experience": { blurb: "A paid summer immunology internship at the Ragon Institute where high school students are assigned to projects in faculty labs with mentors. The seven-week program includes a first-week boot camp, a twice-weekly introduction to immunology course, lectures, college and career workshops, field trips and a final presentation. High school interns work 25 hours per week at $17/hr. Rising seniors age 16 or older from Boston, Cambridge and other Massachusetts Gateway cities can apply." },
  // https://www.studentresearchnyc.org/our_programs/cuny-college-now-lehman-college-stem-research-academy/
  "lehman-college-lehman-college-now-stem-research-academy": { blurb: "A two-part research program for New York City public high school students run by CUNY College Now at Lehman College. Students first take a spring high school credit course, DNA Detectives, then a six-week summer college credit course (BIO189, 1 credit) with placements in research labs with Lehman faculty and graduate students. Participants present at the AMNH August Symposium and receive a $750 stipend. Sophomores and juniors with an overall average of 80 or higher can apply." },
  // https://dnabarcoding101.org/programs/ubrp/
  "dna-learning-center-urban-barcode-research-program": { blurb: "A school-year research program from the DNA Learning Center where New York City high school students use DNA barcoding to study biodiversity. Accepted students take a training course on biodiversity, conservation biology and research methods with lab work, then carry out their own barcoding projects in teams matched with scientist mentors. About 36 students are invited each year, and no prior lab experience is required. Students who present at the Student Research Symposium receive a $500 stipend." },
  // https://hutton.fisheries.org/
  "american-fisheries-society-hutton-junior-fisheries-biology-progr": { blurb: "A paid summer mentoring internship from the American Fisheries Society that places students, called Hutton Scholars, with fisheries professionals for hands-on research in marine or freshwater settings. The eight-week program aims to draw underrepresented groups into fisheries careers. Scholars receive a $3,000 stipend and a trip to the Hutton Scholars Summit. It is open to rising high school seniors and rising college freshmen who are 16 by June 1." },
  // https://chemistry.stanford.edu/outreach-and-giving/community-outreach/ifss-program-high-school-students
  "stanford-department-of-chemistry-inspiring-future-scientists-thr": { blurb: "A free two-week summer program at the Stanford Department of Chemistry where high school students shadow several graduate-student researchers across different labs instead of working on one project. Rising juniors and seniors who are 16 by the first day and live and attend school in Alameda, Santa Clara, San Francisco or San Mateo county can apply. The program does not cover room, board or transportation, and applications require a recommendation." },
  // https://precollege.barnard.edu/summerprograms
  "barnard-college-the-young-women-s-leadership-institute": { blurb: "Barnard College's signature tuition-based summer pre-college program in New York City for rising high school sophomores, juniors and seniors, with courses in the humanities, social sciences, STEM and the arts. A weekly Leadership in Action series adds practical workshops that examine leadership in context, including how gender and identity can shape power and voice. Sessions run between late June and early August." },
  // https://k12stem.engineering.nyu.edu/programs/cs4cs
  "new-york-university-computer-science-for-cyber-security-cs4cs": { blurb: "A free four-week summer program at NYU Tandon School of Engineering in Brooklyn where high school students learn cybersecurity through Capture The Flag competitions, security challenges and research projects. The curriculum covers security-focused scripting, cryptography and digital forensics. Classes run Monday to Friday, 10 AM to 4 PM, on a full scholarship. It is open to students in 10th or 11th grade who live in New York City or specific New Jersey and Nassau County areas." },
  // https://goprojectnyc.org/get-involved/
  "go-project-go-getter-summer-internship": { blurb: "A summer internship with GO Project, a New York City nonprofit that provides academic support to students, where high school students build leadership skills by helping in elementary classrooms. During the five-week GO Summer program, interns support instruction in K to 4 classrooms under the guidance of a Head Teacher or Enrichment Teacher. In 2019, 75 high school students were accepted from more than 400 applicants." },
  // https://www.mos.org/careers/internships
  "museum-of-science-high-school-internship": { blurb: "A youth internship program at the Museum of Science in Boston for high school students aged 14 to 19, with summer and academic-year options. The 7-week summer program pairs weekly professional development workshops with department-specific projects, and past roles have included recruiting visitors for research studies and helping with data collection. Interns get free admission to the Exhibit Halls, IMAX films, Planetarium shows and Duck Tours, plus store and cafe discounts." },
  // https://apprenticelearning.org/our-programs/
  "apprentice-learning-city-summer-internship": { blurb: "A five-week paid summer program from Apprentice Learning in Boston for rising ninth-grade girls who have completed an Apprentice Learning apprenticeship and attend a partner school. It focuses on fields where women are underrepresented, including STEAM careers. Students combine classroom career education with weekly visits to local workplaces in July and early August and earn a weekly stipend for meeting professional expectations." },
  // https://vancortlandt.org/programs-overview/internships/
  "the-van-cortlandt-park-alliance-garden-2-market-internship": { blurb: "A paid 8-week internship with the Van Cortlandt Park Alliance where high school students learn the food system from growing to selling and eating. Interns work in the garden on horticulture and composting, then help run a weekly farm stand, learning ordering, pricing, stocking and completing sales. Interns earn a ServSafe Food Handlers Certificate, and a tuition-free 3-credit college course through SUNY Environmental Science and Forestry is available." },
  // https://www.law.nyu.edu/studentorganizations/highschoollawinstitute
  "new-york-university-high-school-law-institute-hsli": { blurb: "A free, student-run program at NYU School of Law where high school students take yearlong Saturday courses in constitutional law, criminal law, and speech and debate taught by teams of NYU Law students. Classes meet from 10 AM to 1 PM, October through March. The year ends with a mock trial for first-year students and a moot court for returning students, paired with Columbia Law counterparts. Students can enroll up to four times." },
  // https://www.thedoseum.org/internships
  "the-doseum-internship": { blurb: "An internship at The DoSeum, a children's museum in San Antonio, open to high school seniors and college students. Interns join museum teams in roles such as program educator, data and evaluation, education programs and special events. Internships run in summer, fall and spring cohorts, and positions fill quickly because each semester has limited space. Applicants must be a current high school senior or college student." },
  // https://www.alleypond.org/field-biology-internship.html
  "alley-pond-environmental-center-summer-field-biology-internships": { blurb: "A field biology internship at Alley Pond Environmental Center where high school students study local ecosystems through biodiversity surveys, water and soil quality sampling and native plant restoration at sites in Alley Pond Park and elsewhere in Queens. Cohorts run in spring, summer and fall, and interns must attend 5 of 6 classes and give a final presentation. Students must be at least 14, and a $200 fee applies, with financial aid available on request." },
  // https://datascience.uchicago.edu/education/summerlab/program-details/
  "university-of-chicago-data-science-institute-summer-lab": { blurb: "An 8-week paid summer research program at the University of Chicago Data Science Institute that pairs undergraduates and Chicago-area high school students with data science mentors in fields such as computer science, public policy and biomedical research. Students finish with a final video and a symposium presentation. High school students must commute to the Hyde Park campus, since housing is not offered to them. The 2026 stipend was $5,600." },
  // https://www.ghettofilm.org/nyfellows
  "ghetto-film-school-new-york-fellows-program": { blurb: "A free 20-month filmmaking program at Ghetto Film School in the Bronx for New York City high school students. Fellows learn from industry professionals, visit sets and studios, premiere their films at theaters and make an international thesis film. The program also offers college application advising, test prep and help entering the industry through opportunities at media and creative companies." },
  // https://cic.cs.washington.edu/
  "university-of-washington-allen-school-uw-allen-school-changemake": { blurb: "A free four-week summer program at the University of Washington Allen School that teaches coding to rising juniors and seniors at Washington state high schools. Students work in small groups led by UW undergraduate mentors on project-based coding and explore areas of computing. It meets in person in Seattle Monday through Thursday, roughly 9am to 3pm, and pays a $1200 stipend. It aims to reach economically disadvantaged and future first-generation college students." },
  // https://www.boston.gov/news/mayor-michelle-wu-and-office-youth-engagement-and-advancement-announce-2025-26-mayors-youth
  "city-of-boston-mayor-s-youth-council": { blurb: "A paid civic council run by the City of Boston's Office of Youth Engagement and Advancement that connects high school students with city government. Members voice young people's views to city officials and work on meetings, events, projects and outreach. It is open to Boston residents entering grades 9-12, and members serve a one-year term with a year-round commitment. The council has run since 1995." },
  // https://www.jcycworkhub.org/apply
  "the-japanese-community-youth-council-sf-youthworks-myeep": { blurb: "Two paid youth employment programs in San Francisco run by the Japanese Community Youth Council through its Workhub. MYEEP, the Mayor's Youth Employment and Education Program, pays students for work and adds academic support, with a school-year track for incoming 9th and 10th graders. SF YouthWorks places 11th and 12th graders in paid internships at $19.61 per hour. Both programs run school-year cycles." },
  // https://www.newvictory.org/about/ushers
  "the-new-victory-theater-new-victory-usher-corps": { blurb: "A paid after-school job program at the New Victory Theater in New York City, part of the New 42 Youth Corps, where high school students work as ushers at family theater shows. Alongside paid work, members get job training, academic support, mentorship and the chance to see live theater. Ushers start at $17 per hour, work at least three shifts a week and attend required weekday after-school workshops. It is open to high school juniors and seniors." },
  // https://www.wku.edu/academy/
  "western-kentucky-university-the-gatton-academy": { blurb: "A residential early-college STEM high school at Western Kentucky University in Bowling Green for Kentucky juniors and seniors. Students live together in a dedicated residence hall, take WKU courses alongside undergraduates and earn at least 60 college credit hours and an associate degree along with a high school diploma. Students apply as sophomores. The Commonwealth of Kentucky pays tuition, fees, housing and meals." },
  // https://www.wavehill.org/education/youth-internships/werm
  "wave-hill-woodland-ecology-research-mentorship-werm": { blurb: "A paid 14-month ecology research mentorship at Wave Hill in the Bronx for New York City high school students. Interns start with a summer session, attend Saturday workshops during the school year, then spend a second summer doing mentor-led research and present at an August symposium. Applicants must be 15 by July 1 and NYC residents. Interns earn about $3,500 and credit for three college courses." },
  // https://www.brla.gov/290/Student-Internship-Program
  "city-of-baton-rouge-high-school-and-college-student-internship-p": { blurb: "An internship program run by the City of Baton Rouge and Parish of East Baton Rouge that places high school and college students in City-Parish departments. Interns work in a department and learn about the Civil Service System. High school applicants must be at least 16, in grades 10 through 12 at a school in East Baton Rouge Parish, and recommended by their school counselor. Positions are limited and offered in the summer and during the school year." },
  // https://www.projectselfsufficiency.org/summer-youth-employment-program
  "project-self-sufficiency-the-summer-youth-employment-program": { blurb: "A paid summer job training program run by Project Self-Sufficiency in Newton, New Jersey, for rising high school sophomores and juniors in Sussex County. Teens get paid work experience at a community work site plus training in resume and cover letter writing, interviewing and workplace etiquette. It runs from July to August, and income and residency guidelines apply, with the program aimed at students from low-income households." },
  // https://www.ornl.gov/content/next-generation-stem-internship-program
  "oak-ridge-national-laboratory-next-generation-stem-internships-p": { blurb: "A paid summer research internship at Oak Ridge National Laboratory where high school students work on STEM projects with ORNL researchers. It is open to rising juniors and seniors from Anderson, Blount, Campbell, Knox, Loudon and Roane counties in East Tennessee. Interns must be at least 16, U.S. citizens or permanent residents with a 3.0 GPA, work 40 hours per week and receive a stipend of up to $500 a week." },
  // https://www.riserockaway.org/rise/programs/youth/environmentor-internship/
  "rockaway-initiative-for-sustainability-and-equity-environmentor": { blurb: "A paid summer science research mentorship at RISE in Rockaway, Queens, for NYC students in grades 9 to 11 who attend school in or near the Rockaways. Students work with scientists from local universities and research institutions on projects about the Rockaway shoreline and Jamaica Bay. Classes meet in person Monday through Thursday from June through mid-August, and students can earn up to $1,200 plus community service hours." },
  // https://www.montereybayaquarium.org/learning-programs/teen-programs/teen-conservation-leaders
  "monterey-bay-aquarium-teen-conservation-leaders": { blurb: "A summer service-learning program at the Monterey Bay Aquarium where high school students build career skills and earn community service hours. It starts with a training week on marine biology and conservation, then teens volunteer 3 to 4 days per week in one of three tracks: guest interpretation, animal care and engineering, or science communication. It is open to students entering 9th through 12th grade who are at least 14." },
  // https://journalism.nyu.edu/our-work/institute-projects/urban-journalism-workshop/
  "new-york-university-the-urban-journalism-workshop": { blurb: "A free one-week summer journalism program at NYU's Arthur L. Carter Journalism Institute for high school students from the New York City area. Students learn reporting from NYU faculty and visiting journalists, visit major newsrooms and produce multimedia stories for an online news site published on the last day. Participants stay in NYU residence halls, must be at least 16 and earn no credit. It runs in July." },
  // https://metasummeracademy.com/eligibility-3/
  "meta-meta-summer-academy": { blurb: "A paid six-week summer program at Meta in Menlo Park for local high school students. Participants commit 30 hours per week for all six weeks. It is open to sophomores who live in East Palo Alto, Belle Haven, North Fair Oaks or Redwood City and have at least a 2.0 cumulative GPA. No prior work or tech experience is needed, and applicants submit a transcript and one recommendation." },
  // https://www.rit.edu/science/summer-intern-program
  "rochester-institute-of-technology-center-for-imaging-science-sum": { blurb: "A paid six-week summer research internship at RIT's Chester F. Carlson Center for Imaging Science in Rochester, New York, for rising high school seniors. Interns join an imaging science research team on projects in areas such as cultural heritage imaging, machine learning and remote sensing. It runs from July to mid-August, and selection uses an essay, recommendations and interviews. RIT does not provide food, lodging or transportation." },
  // https://www.ochsner.org/giving/community-outreach/education-outreach/ochsner-star-program/
  "oschner-health-oschner-star-summer-scholars-program": { blurb: "A free four-week summer program run by Ochsner Health for Louisiana high school students interested in science and medicine careers. Students do research, learn practical medicine and clinical skills and build leadership skills, Monday through Friday from 8 a.m. to 4 p.m. in June. It is open to rising 12th graders who are at least 16 and attend a Louisiana high school, with no minimum GPA or test score. Sites include New Orleans, Baton Rouge and Shreveport." },
  // https://mtc.ca.gov/jobs-contracts/job-opportunities/internships-summer-academy/norman-mineta-high-school-summer-academy
  "metropolitan-transportation-commission-the-norman-mineta-bay-are": { blurb: "A summer academy sponsored by the Metropolitan Transportation Commission and three other regional agencies that introduces Bay Area high school students to public sector careers in transportation, housing, environmental justice and air quality. Students attend online sessions on Thursdays in July, then give a presentation on a local challenge at a final in-person day in San Francisco. Applicants must be at least 15 and have finished ninth grade. Completers receive a stipend." },
  // https://einsteinmed.edu/education/phd/summer-hs-research-program
  "albert-einstein-college-of-medicine-einstein-montefiore-summer-h": { blurb: "A five-week, full-time summer research program at Albert Einstein College of Medicine in the Bronx for high school students aged 16 and older. Each student works in a research lab with a mentor, usually the lab's principal investigator, from about 9 a.m. to 5 or 6 p.m. daily. Students present their work at Einstein's Summer Research Day. Applicants need a recommendation from a high school science teacher or science chair." },
  // https://louisville.edu/mcconnellcenter/news/archived/mcconnell-center-announces-2024-young-leaders-academy
  "university-of-louisville-young-leaders-academy": { blurb: "A free one-week residential summer leadership conference at the University of Louisville's McConnell Center for Kentucky high school students. Led by university faculty and staff, students study American constitutionalism through discussions and debates. It is open to students who have finished at least one year of high school, and a full scholarship covers lodging, meals and materials. Applicants submit a resume and an essay." },
  // https://www.americaontech.org/tech360.html
  "america-on-tech-tech360-summer-bootcamp-program": { blurb: "A free summer AI literacy bootcamp run by the nonprofit America On Tech for rising high school juniors and seniors at public high schools in New York City, Los Angeles, Miami and Atlanta. Sessions meet Monday through Thursday, 11 AM to 3 PM, mostly online with two required in-person sessions. Priority goes to students from high-need schools and first-generation college students. Those who finish earn a $500 stipend." },
  // https://www.bu.edu/lernet/grow/about.html
  "boston-university-greater-boston-research-opportunities-for-youn": { blurb: "A six-week paid summer research internship for young women run by Boston University's LERNet. Students work in a BU biology or chemistry lab with a graduate student or faculty mentor, attend seminars, visit a local biotech or pharmaceutical company, and present a research poster. Lab work runs weekdays from 9:30 a.m. to 4:30 p.m. in July and August, with a stipend of up to $2,000. Applicants must be juniors at a Massachusetts school, live within 30 miles of Boston and be at least 16." },
  // https://www.rdoequipment.com/careers/access-your-future-internship-programs/high-school-programs
  "rdo-equipment-co-high-school-intern": { blurb: "A paid internship at an RDO Equipment Co. dealership through the company's Access Your Future program for high school students, which also offers store tours and job shadows. Interns work in service, parts, technology or sales, and many arrange the role through a school work-based learning program for class credit. Part-time work is available during the school year, after classes, on weekends and during breaks, and interns must be 16." },
  // https://www.uvu.edu/bridge/
  "utah-valley-university-empowered-professionals": { blurb: "A tuition-free summer program at Utah Valley University for Utah high school students in grades 9 to 11 who want an early college experience in STEAM fields, business or education. Students take seven-week university courses with career exploration and hands-on learning. Sessions meet in person on Tuesdays, Wednesdays and Thursdays from 9:00 AM to 3:15 PM, and students cover their own transportation and lunches." },
  // https://www.sheddaquarium.org/about-shedd/press-releases/shedd-aquarium-offers-refreshed-teen-work-study-program
  "shedd-aquarium-teen-work-study-program": { blurb: "A paid work-study job at Shedd Aquarium in Chicago for high school students, focused on science and the environment. Teens contribute to large-scale projects with Shedd staff, such as community garden plans and signage for the aquarium's outdoor green spaces, while getting professional coaching. Participants come to Shedd each Saturday for 16 weeks, are paid for their time, and practice resume writing, interviewing and networking." },
  // https://www.innovatingjustice.org/program/youth-action-institute/
  "center-for-justice-innovation-youth-action-institute": { blurb: "A paid public policy research fellowship run by the Center for Justice Innovation in New York City for young people ages 16 to 21. Each cohort researches a current public safety issue, writes policy recommendations and presents them to community organizations, government offices and advocacy groups. Fellows earn $15 per hour for up to 5 hours per week during the school year, and applicants must have attended at least one year of school in New York City." },
  // https://skillsforri.com/prepareri-high-school-internship-program
  "skills-for-rhode-island-s-future-prepareri-high-school-internshi": { blurb: "A paid 7-week summer internship run by Skills for Rhode Island's Future for Rhode Island public high school juniors, including charter and home school students. Interns start with a 40-hour paid work-readiness bootcamp in late June, then work at least 150 hours over six weeks in July and August with one of more than 200 employer partners. Interns earn $17.00 an hour for up to 280 hours, and applicants must be at least 16." },
  // https://stem.northeastern.edu/summer/ysp/
  "northeastern-university-young-scholars-program-ysp": { blurb: "A free six-week summer research program at Northeastern University in Boston for Massachusetts students who have completed their junior year and live within commuting distance. Scholars work in university labs in fields such as chemistry, biology, pharmaceutical sciences and engineering. The day program also includes seminars, field trips, and college and career counseling, and runs in person from late June through July." },
  // https://tallgrassfilm.org/programs/emerging-filmmaker-program/
  "tallgrass-film-association-emerging-filmmaker-program": { blurb: "A free program run by the Tallgrass Film Association in Wichita, Kansas, for local students from 8th grade through high school seniors, ages 13 to 18. Participants learn from film professionals about directing, producing, screenwriting and editing, tied to the Tallgrass Film Festival. Students who complete the program receive an all-access festival pass, plus a second all-access pass for a parent or guardian." },
  // https://summer.harvard.edu/high-school-programs/pre-college-program/
  "harvard-college-harvard-pre-college-program": { blurb: "A two-week, non-credit residential summer program run by Harvard Summer School for high school students who are at least 16. Students live on the Harvard campus and take one college course, with classes meeting every day for three hours, plus advising and required co-curricular activities. Three two-week sessions run each summer, and the cost of $6,250 covers tuition, housing, meals, activities and insurance." },
  // https://www.vermontadaptive.org/apprenticeships/
  "vermont-adaptive-ski-sports-vermont-adaptive-s-apprenticeship-pr": { blurb: "A volunteer apprenticeship at Vermont Adaptive Ski & Sports for students ages 14 to 17 who support adaptive athletes. Apprentices learn seasonal programming, event planning and volunteer management, set written goals, meet regularly with a coordinator and attend required training. In return they can earn high school credit or clinical hours and community service credit, and receive free skiing and riding and access to instructor clinics." },
  // https://www.climate.columbia.edu/pre-college-programs
  "columbia-university-the-columbia-climate-school-in-the-green-mou": { blurb: "A two-week, tuition-based summer program from the Columbia Climate School, held each July at Vermont State University's Castleton campus, for students in grades 9 to 12 and rising 9th graders. Students study climate change and sustainability with Columbia faculty and local climate leaders through lectures, fieldwork and excursions. Each student designs a Climate Action Project to carry out at home and receives a certificate of participation, and scholarships are available." },
  // https://www.bcri.org/legacy/
  "birmingham-civil-rights-institute-legacy-youth-leadership-progra": { blurb: "A youth leadership program at the Birmingham Civil Rights Institute for high school students, built around civil rights history. Participants attend twelve weekly workshops on Tuesday evenings from March to May covering the museum's exhibitions, African American history and culture, and leadership, along with public programs and college visits. Graduates then serve as museum docents for at least 80 hours over the summer and can receive a $1,000 stipend." },
  // https://raleighnc.gov/careers-jobs-and-volunteering/services/raleigh-summer-youth-employment
  "city-of-raleigh-raleigh-summer-youth-employment-program-rsyep": { blurb: "A paid eight-week summer job program run by the City of Raleigh for high school students ages 15 to 18 who live within Raleigh city limits. Participants work for the city, explore career pathways, and build professional and life skills from June to August. Only one applicant per household is accepted, and a parent or guardian must attend the required orientation sessions." },
  // https://www.artic.edu/learn-with-us/teens/opportunities-for-teens
  "art-institute-of-chicago-teen-council": { blurb: "A paid teen council at the Art Institute of Chicago where 15 high school students work with museum staff to create programs and resources for Chicagoland youth, such as teen-led tours. Any teen enrolled in a Chicagoland high school can apply. The council runs from September to June, with members committing about 3 to 4 hours a week, mostly at Saturday meetings at the museum and occasional virtual Wednesday meetings." },
  // https://www.marjotfoundation.org/about
  "the-marjot-foundation-student-environmental-research-grants": { blurb: "A $5,000 research grant from the Marjot Foundation for students in grades 9 to 12 to carry out an environmental research project they design over the school year. The student receives $1,000, $2,500 covers research costs, and the mentor and school science department receive $1,000 and $500. Grants traditionally served New England and New York, and since spring 2026 a portion is open nationwide, with proposals reviewed twice a year." },
  // https://suny.oneonta.edu/biological-field-station/internships
  "suny-oneonta-biological-field-station-high-school-internship": { blurb: "An 8-week paid summer research internship at SUNY Oneonta's Biological Field Station on Otsego Lake for New York State residents who are at least 16. Interns do fisheries and plant surveys and water sampling, analyze samples and data in the lab, and finish with a poster, technical report and presentation. One to three positions are offered, with at least one for an Otsego County resident, and interns receive $3,500 on completion." },
  // https://umaineppf.org/consider-engineering/
  "university-of-maine-pulp-and-paper-foundation-chip-moody-conside": { blurb: "A free four-day overnight engineering camp at the University of Maine, run by the University of Maine Pulp and Paper Foundation, for students who have completed their junior year and excel in math and science. Participants stay in campus dorms, meet engineering students and faculty, and do hands-on activities across engineering fields. Groups of 44 students attend three July sessions, and food and lodging are provided, though students cover their own travel." },
  // https://www.engr.washington.edu/about/k12/engineering-academy
  "university-of-washington-college-of-engineering-engineering-acad": { blurb: "A free one-week introductory engineering program run by the University of Washington College of Engineering for high school sophomores and juniors in the greater Seattle area. Students work on hands-on design challenges, tour campus, and spend time with engineering students and faculty. It meets in person in July from 10:00 AM to 4:00 PM each day on the UW Seattle campus, no prior engineering experience is needed, and families provide transportation." },
  // https://plasticsurgery.stanford.edu/research/stars.html
  "stanford-medicine-division-of-plastic-and-reconstructive-surgery": { blurb: "A fully funded eight-week summer research internship in Stanford's Division of Plastic and Reconstructive Surgery for high school and community college students who are at least 16. About 20 interns do full-time research in a Stanford lab, learning techniques such as histology, imaging and genotyping, and present at a final research showcase. No prior lab experience is needed, and interns arrange their own housing and travel." },
  // https://www.cyber.pitt.edu/cybercamp
  "university-of-pittsburgh-pitt-cyber-air-force-association-cyberc": { blurb: "A free week-long cybersecurity camp run by Pitt Cyber at the University of Pittsburgh for Greater Pittsburgh students entering 9th grade through graduating seniors. Students learn cyber hygiene and Windows and Ubuntu system administration in Standard or Advanced tracks, ending with a competition to find and fix vulnerabilities in a virtual machine. It runs in late June at the Oakland campus, with a Standard classroom at Pitt's Greensburg campus." },
  // https://www.mitchellinstitute.org/a-10000-college-scholarship-plus-so-much-more/
  "mitchell-institute-mitchell-scholarship": { blurb: "A $10,000 college scholarship from the Mitchell Institute for seniors graduating from Maine public high schools who are full-time Maine residents and plan to attend a two- or four-year college the next fall. At least one scholar is chosen from every public high school in Maine, based on academics, community impact and financial need. The award is paid in four annual installments of $2,500 and comes with leadership and career programming and an alumni network." },
  // https://www.fisherhouse.org/programs/scholarship-programs/scholarships-for-military-children/
  "fisher-house-foundation-scholarships-for-military-children": { blurb: "A merit-based college scholarship run by Fisher House Foundation with the Defense Commissary Agency for children of active-duty, reserve/guard, retired and deceased U.S. service members. Each year 500 scholarships of $2,000 are awarded, with at least one recipient at every commissary location that receives qualified applications. Applicants must be unmarried dependents under age 23, high school applicants need a 3.0 GPA, and the application includes a 500-word essay." },
  // https://lulac.org/programs/education/scholarships/
  "lulac-national-educational-service-centers-lulac-national-schola": { blurb: "Scholarships for Hispanic high school seniors and college students run by the LULAC National Educational Service Centers and awarded through participating local LULAC councils, which raise money in their communities. The national office supplements council funds with matching money from corporations and individual donors. Since 1975 the fund has awarded over $31 million to more than 36,000 students, and applications go to the local council." },
  // https://robertsonscholars.org/high-school-students-2/
  "duke-university-and-unc-chapel-hill-robertson-scholars-leadershi": { blurb: "A full scholarship program at Duke University and UNC-Chapel Hill that covers eight semesters of tuition, room, board and mandatory fees, with funded summers and access to both campuses. Any high school senior may apply without a nomination, including international students who can obtain a U.S. student visa. Applicants must also apply separately to Duke or UNC-Chapel Hill, and selection includes group activities and interviews during the winter." },
  // https://www.wlu.edu/admissions/the-johnson-scholarship
  "washington-and-lee-university-johnson-scholarship": { blurb: "A merit scholarship at Washington and Lee University, run through the Johnson Program in Leadership and Integrity, that recognizes academic achievement, leadership and integrity. Up to 44 incoming students each year receive tuition, housing and meals plus a stipend of up to $10,000 for domestic, international or virtual experiences. Candidates submit the W&L application with a supplemental essay, and finalists are invited to an all-expenses-paid campus visit in early March." },
  // https://www.usamts.org/
  "art-of-problem-solving-initiative-usa-mathematical-talent-search": { blurb: "A free online proof-based math contest from the Art of Problem Solving Initiative for U.S. middle and high school students. The year has three rounds, each with five problems (one puzzle and four proof problems) that students work on at home for about a month and submit as fully justified written solutions. Every solution receives written feedback, and the top 45% of students receive prizes after the final round." },
  // https://purplecomet.org/information
  "purple-comet-purple-comet-math-meet": { blurb: "A free annual online team math competition for middle and high school students, held every year since 2003. Teams of one to six students, each with an adult supervisor who registers at the contest site, choose a start time within a ten-day window in April. High school teams have 90 minutes to solve 30 problems, and results are ranked in divisions for small schools, large schools and mixed teams." },
  // https://www.caltechmathmeet.org/registration
  "caltech-caltech-math-meet": { blurb: "A team math competition for high school students run by Caltech students (formerly CHMMC) and held in Pasadena in late January. Teams of up to six compete in Team, Guts and Individual rounds, with optional events such as an Integration Bee and an admissions session, and breakfast, lunch and t-shirts are provided. Contestants must be 19 or younger and enrolled in high school full time, and selected teams pay $120 per team or $20 per individual." },
  // https://www.sphinxmusic.org/sphinx-competition
  "sphinx-organization-sphinx-competition-junior-division": { blurb: "A national competition run by the Sphinx Organization for young Black and Latino string players, with a Junior Division for musicians ages 17 and under. Junior Division winners receive $10,000, $5,000 and $3,000 for first through third place, and the first-place winner also earns solo appearances with major orchestras. Finalists perform with the Sphinx Symphony Orchestra, and finals take place in Detroit in January." },
  // https://www.sejongculturalsociety.org/writing/current/sijo.php
  "sejong-cultural-society-sejong-writing-competition": { blurb: "An annual creative writing competition run by the Sejong Cultural Society on Korean literature and the sijo, a Korean poetry form, with a pre-college division for writers 18 and under living in the U.S. Each entrant submits one sijo written in English on a topic of their choice, and a title is optional. Pre-college winners receive $500, $400 and $300 for first through third place, with $50 for each honorable mention." },
  // https://www.nationalhonorsociety.org/the-nhs-scholarship/
  "national-honor-society-nassp-nhs-scholarship": { blurb: "A national scholarship from the National Association of Secondary School Principals for seniors who are members of the National Honor Society, judged on leadership, service and character. This year the program awards $2 million in scholarships to 600 students, with a top national award of up to $25,000. In a recent cycle, four top finalists received $10,625 each and twenty finalists received $5,625 each." },
  // https://naclo.org/
  "naclo-north-american-computational-linguistics-open-competition": { blurb: "A linguistics puzzle contest for middle and high school students, held at schools and university sites across North America, that needs no prior knowledge of linguistics, programming or foreign languages. The three-hour Open Round in January has 6 to 12 problems, and top scorers advance to a harder four-hour Invitational Round in March. The top U.S. and Canadian scorers are chosen to represent their countries at the International Linguistics Olympiad." },
  // https://www.thenrc.org/
  "national-robotics-challenge-national-robotics-challenge": { blurb: "A set of open-platform robotics contests for students from grade 6 through graduate school, first held in 1986 and run under its current name since 2004. Students build robots for twelve contests such as Sumo Robot, Micromouse, Rescue Robot, Robot Hockey and the Autonomous Vehicle Challenge, with no required kit and low entry fees. Awards are given separately for middle school, high school and post-secondary entrants at a championship in April." },
  // https://www.aba.com/advocacy/community-programs/lights-camera-save
  "american-bankers-association-foundation-lights-camera-save-video": { blurb: "A video contest from the American Bankers Association Foundation in which teens ages 13 to 18 make videos of 30 seconds or less about saving and money and submit them to a participating local bank each fall. Local banks pick winners to advance, and national finalists are chosen by public voting on Instagram and a final judging round. National prizes are $10,000, $5,000 and $2,500, and the winners' teachers receive $300, $200 and $100." },
  // https://kennedyhumanrights.org/our-impact/education/educators/speak-truth-to-power-video-contest/
  "robert-and-ethel-kennedy-human-rights-center-speak-truth-to-powe": { blurb: "An annual short-film contest run by the Robert & Ethel Kennedy Human Rights Center with the American Federation of Teachers and the Tribeca Festival, open to middle school, high school and college students. Students make three- to five-minute documentary, narrative or experimental films about a human rights issue that matters to them, with no filmmaking experience or special equipment needed. Winning films premiere at a Tribeca Festival showcase in June." },
  // https://www.nle.org/scholarships
  "american-classical-league-national-latin-exam": { blurb: "A national Latin exam run by the American Classical League and taken each spring through a registered teacher, with certificates and medals for high scorers. High school seniors who win gold medals on the advanced exams can apply for up to 15 O'Donnell Scholarships of $2,000, which require taking Latin or classical Greek in the first year of college. Other awards include a travel grant of up to $5,000 and $2,000 scholarships for future Latin teachers." },
  // https://adc-kb.recf.org/hc/en-us/articles/16640573083543-Aerial-Drone-Competition-Frequently-Asked-Questions-FAQ
  "rec-foundation-aerial-drone-competition": { blurb: "A team drone competition run by the REC Foundation in which middle and high school students pilot and program drones in four challenges: Solo Piloting, Solo Autonomous Flight, Alliance and Communication. Teams of 3-5 students compete at qualifying events from October through March and can qualify for a Regional Championship from April through June. Season registration is $200 per team, and local events usually cost $50 to $100 per team." },
  // https://www.houstonmethodist.org/academic-institute/education/research/summer-internship-program/highschoolresearchinternship/
  "houston-methodist-summer-high-school-research-internship": { blurb: "A summer research internship at Houston Methodist where high school juniors and seniors work in translational research labs with faculty mentors. Interns take part in lab research and finish with a poster presentation. Applicants must be in their junior or senior year and 16 years of age. The internship takes place at the main Houston Methodist Hospital campus in the Texas Medical Center in Houston." },
  // https://www.griffinmsi.org/youth-and-families/rise-teen-program
  "griffin-museum-of-science-and-industry-rise-teen-program": { blurb: "A free STE(A)M program at the Griffin Museum of Science and Industry in Chicago for high school students in grades 9 through 12. Students choose between a 12-week structured track focused on deeper learning and leadership or a flexible drop-in option with no long-term commitment. Sessions meet on Saturdays from 10 a.m. to 2 p.m., and participants get free museum admission, free garage parking and volunteer hours on request." },
  // https://www.mira.org/intern_program.htm
  "monterey-institute-for-research-in-astronomy-summer-internship-p": { blurb: "A 10-week summer astronomy internship at the Monterey Institute for Research in Astronomy in Marina, California. Interns work one-on-one with research astronomers on current research problems in astronomy and astrophysics. Typical high school interns are juniors or seniors, though well-qualified sophomores have been successful. The program fee is $3,000, waived for all Monterey County residents, and housing is not provided." },
  // https://partners.sbceo.org/our-services/job-readiness-training-internships/
  "partners-in-education-job-trainings-internships": { blurb: "A paid job readiness and internship program from Partners in Education for public high school students ages 15-18 in Santa Barbara County. Students attend weekly 1-hour workshops, mixing in-person and virtual sessions, on resume building, financial literacy, networking and interview skills, and each student gets a career coach. Students can earn a stipend, and those who finish can move into minimum-wage internships of at least 10 hours weekly and 80 hours total." },
  // https://www.uchicagomedicine.org/cancer/education-outreach/student-education/high-school-undergraduate/eyes
  "uchicago-medicine-chicago-eyes-on-cancer-program": { blurb: "A two-year cancer research training program at the UChicago Medicine Comprehensive Cancer Center for high school sophomores, juniors and seniors. Students work full time in cancer research labs for two consecutive summers, attend a lecture series and career workshops, and present at a research symposium. Applicants must be at least 16 and live in Cook, Lake, Will or DuPage counties in Illinois or Lake County, Indiana. The stipend is $5,000 per year." },
  // https://lamont.columbia.edu/education-outreach/student-summer-opportunities-SSFRP
  "columbia-climate-school-lamont-doherty-earth-observatory-seconda": { blurb: "A six-week summer field and lab research program at Lamont-Doherty Earth Observatory in Palisades, New York. High school students work alongside undergraduate mentors, science teachers and Lamont scientists, using Piermont Marsh as the main field site, and present posters at an end-of-summer symposium. Students receive stipends. Applicants must be at least 16 at the start of the internship, and housing is not provided." },
  // https://www.pawschicago.org/how-to-help/internships/high-school-internships
  "pawschicago-high-school-internship": { blurb: "An unpaid school-year internship at PAWS Chicago for students at least 16 years of age who are part of a formal job-readiness or career program run by a school or community organization. Interns work in person at the PAWS Medical Center or the Lincoln Park Adoption Center on a recurring weekday daytime schedule between 8 a.m. and 6 p.m. Housing is not provided, and the internship can be used for class credit." },
  // https://www.uclahealth.org/volunteer/westwood/student-programs/pre-med-summer-scholar-program
  "ucla-health-pre-med-summer-scholar-program": { blurb: "A fee-based summer program run by UCLA Health for high school students who are at least 16 years old and not yet attending college. Each five-day session at UCLA facilities includes medical guest speakers and hands-on activities, and past sessions covered suturing, laparoscopic skills and CPR training. The $1,450 fee covers instruction, materials and a polo shirt but not lodging or meals, and need-based scholarships are available." },
  // https://www.lpzoo.org/youth-programs/malott-family-zoo-intern-program-zip/
  "lincoln-park-zoo-in-chicago-malott-family-zoo-intern-program": { blurb: "A paid seven-week summer internship at Lincoln Park Zoo for Chicago residents ages 16 to 18 who are entering grades 10 through 12 or their first year of college. Interns work as on-grounds interpreters who teach zoo guests about animal science and conservation, and each completes an independent conservation project. The program runs Monday through Friday, and no prior animal experience is required." },
  // https://mikvachallenge.org/general-program-application-english/
  "mikva-challenge-mikva-summer-fellowship": { blurb: "A paid summer fellowship from Mikva Challenge in Chicago that places high school students as interns in public offices, such as those of aldermen, state representatives and senators. Fellows work 30 hours a week for six weeks between June and August, earn $17 per hour, and attend weekly workshops on leadership and workplace readiness. Fellows are typically rising seniors or recent graduates, and Illinois eligibility depends on state risk criteria." },
  // https://www.ll.mit.edu/outreach/llrise
  "massachusetts-institute-of-technology-llrise-workshop": { blurb: "A free two-week summer radar workshop held at the MIT campus in Cambridge and MIT Lincoln Laboratory in Lexington, Massachusetts. Students learn radar basics, build their own radars, tour laboratory facilities and complete group projects on radar operations. Applicants must be U.S. citizens completing their junior year of high school. The program is free apart from travel to and from MIT, and transportation to the laboratory is provided." },
  // https://www.masscec.com/vocational-internship-program-students
  "massachusetts-clean-energy-commission-vocational-internship-prog": { blurb: "A paid work and learning program from MassCEC that places vocational high school students in clean energy jobs during the school year and summer, now part of its Clean Energy Internship Program. Students build a profile in a student database, and employers choose whom to interview and hire. Vocational students are generally rising seniors or recent graduates approved for co-op by their school, and employers must pay at least $15 per hour." },
  // https://k12education.lbl.gov/programs/high-school/sea-bilingual-stem-camp
  "berkeley-lab-k-12-sea-bilingual-stem-camp": { blurb: "A free four-day spring break STEM camp at Berkeley Lab for Spanish-English bilingual high school students. Students tour lab facilities, hear career talks from scientists and attend workshops at Berkeley Lab and UC Berkeley, and the camp can lead to a summer internship at the lab. The camp is hybrid, starting online and moving on site. Students in grades 9 to 12 can apply, and meals and materials are provided." },
  // https://riversideparknyc.org/2026-teen-corps-application/
  "riverside-park-conservancy-riverside-teen-corps-horticulture-int": { blurb: "A paid summer horticulture program from Riverside Park Conservancy where high school students care for trees, shrubs and perennials and help with weeding, invasive species removal, mulching and park cleanup. Corps members meet Tuesdays and Thursdays from 9:00am to 12:00pm in parks from 110th St to 181st St in Manhattan. Teens who complete 48 hours of service receive a $1,000 stipend, and applicants must live in Manhattan Community Board 9." },
  // https://education.mjhnyc.org/high-school-apprenticeship-program/
  "museum-of-jewish-heritage-high-school-apprenticeship-program": { blurb: "A paid summer apprenticeship at the Museum of Jewish Heritage in Manhattan for New York City public high school students. Apprentices follow a program of study and work and spend the summer working part-time in different museum departments, four days per week, Monday through Thursday from 10 AM to 3 PM. Apprentices are paid for their participation and may also lead tours for school groups." },
  // https://www.kumc.edu/institute-for-community-engagement/areas-of-interest/ku-medical-center-educational-experience-(kee)/kee-system-eligibility.html
  "kansas-university-medical-center-ku-medical-center-educational-e": { blurb: "A research and clinical observation program at the University of Kansas Medical Center for students age 16 or older who are U.S. citizens, permanent residents or DACA recipients. High school students can observe or take part as active learners in a lab, research area or animal facility, and clinical observation excludes emergency departments and operating rooms. The experience is not for school credit, and applicants complete HIPAA and safety training online." },
  // https://www.slorep.org/teen-internships/
  "san-luis-obispo-repertory-theatre-the-act-program-at-slo-rep-tee": { blurb: "A volunteer teen internship with the Academy of Creative Theatre, the youth program of SLO REP in San Luis Obispo, for teens ages 14-18. Interns help teaching artists lead class warm-ups and activities and support staff by preparing scripts, gathering class supplies and making costume and set pieces. Interns choose the hours that fit their schedule and earn $100 off ACT class tuition for each class they volunteer." },
  // https://www.studentresearchnyc.org/our_programs/york-college-now-stem-research-academy/
  "york-college-york-college-now-stem-research-academy": { blurb: "A CUNY research program at York College for New York City public high school juniors, run through the NYC Science Research Mentoring Consortium. Students take a spring Backyard Toxicology course, and those who finish can join a six-week summer research program in July and August. Applicants need Regents scores of 80+ in Math and 75+ in Living Environment and ELA. Participants receive a $750 stipend, free lunch and a summer MetroCard." },
  // https://himes.house.gov/services/for-students/internships/
  "office-of-congressman-jim-himes-district-internship-program": { blurb: "An internship in Congressman Jim Himes's district offices in Bridgeport and Stamford, Connecticut, open to high school and college students and recent graduates. Interns conduct research, help with constituent casework, draft correspondence and answer phones. High school students in the district are encouraged to apply during the school year and generally intern two to five days a week after school. Stipends go to applicants with demonstrated financial need." },
  // https://www.naturalsciences.org/learn/junior-curators
  "the-north-carolina-museum-of-natural-sciences-junior-curators": { blurb: "A volunteer program at the North Carolina Museum of Natural Sciences in Raleigh for teens in grades 9 to 12 who are interested in conservation, animal care and field biology. Junior Curators help care for the museum's live animal collection, join educational programs and events, take trips to natural areas and work on service projects. The program runs from September to April with monthly meetings, and the fee is $75 per year." },
  // https://www.afhboston.org/teen-jobs
  "artists-for-humanity-youth-arts-enterprise": { blurb: "A paid apprenticeship at Artists For Humanity in Boston where high school freshmen, sophomores and juniors work as teen artists in the visual arts and creative industries. New teens first complete 36 volunteer hours in the Foundation Studio, which can count as community service, and are then assigned to a studio with an open paid position. Teens work in the summer from June through the end of August and during the school year, and artistic experience is not required." },
  // https://newarkmuseumart.org/program/explorers/
  "newark-museum-of-art-explorers-teen-program": { blurb: "A multi-year college, career and life readiness program at the Newark Museum of Art for high school students who attend school or live in Newark. Explorers take part in paid internships, leadership and STEM workshops, and group trips to other cultural institutions. Students commit to six after-school hours per week during the school year, 60 hours of community service per year and 25 hours per week each summer, and rising freshmen, sophomores and juniors may apply." },
  // https://my.clevelandclinic.org/departments/education/center-for-youth-and-college-education/internships
  "cleveland-clinic-high-school-summer-internship-program": { blurb: "A paid seven-week summer internship at Cleveland Clinic for students in grades 9 to 12 who live and attend school in one of eight Northeast Ohio counties. Interns join clinical tracks such as nursing, pharmacy and radiology, the non-clinical Louis Stokes track in areas like finance and healthcare administration, or an advanced technology track covering AI and IT. Interns earn $15 per hour and work 9:00 a.m. to 3:30 p.m., Monday through Friday." },
  // https://www.uwyo.edu/seo/upward-bound/summer-program/index.html
  "university-of-wyoming-upward-bound-math-science-summer-program": { blurb: "A free five-week residential summer program at the University of Wyoming in Laramie for high school students enrolled in its Upward Bound or Upward Bound Math Science programs. Students live on campus, take English, literature, science, math, foreign language and college prep classes, and complete a research project they present at a closing symposium. Room and board, books, activities and stipends are covered, and the program serves students from low-income households." },
  // https://www.umassmed.edu/gsbs/outreach-programs/high-school-health-careers-program/
  "umass-chan-medical-school-high-school-health-careers-program-hsh": { blurb: "A tuition-free four-week residential summer program at UMass Chan Medical School in Worcester for Massachusetts high school sophomores and juniors interested in health care careers. Students get intensive SAT preparation, learn about current health care issues and complete a health disparities research project on a cultural group in Massachusetts. Participants stay at Worcester State University on weeknights and return home each weekend during July and August." },
  // https://aeopinternships-fellowships.org/internships/
  "army-educational-outreach-program-the-aeop-high-school-apprentic": { blurb: "A paid research internship through the Army Educational Outreach Program that places high school students in participating labs across the U.S. Interns work in person on science, engineering and computer science research under formal mentorship from a professional scientist or engineer, and receive an educational stipend. Applicants must be U.S. citizens or permanent residents, at least 14 years old and enrolled in high school, and each lab runs its own selection." },
  // https://www.rockefeller.edu/outreach/lab-jumpstart/
  "the-rockefeller-university-learning-at-the-bench-lab-jumpstart": { blurb: "A paid after-school and summer research program run by RockEDU at The Rockefeller University for New York City high school juniors and seniors interested in science. Students build molecular biology lab skills on Tuesdays and Thursdays from February to June, then do full-time summer research in the Summer Science Research Program. Applicants must be at least 16, each student is paired with a practicing scientist, and stipends are $500 for spring and $3,250 for summer." },
  // https://butlermachinery.com/careers/educational-programs/
  "butler-machinery-company-work-study-nd-high-school-program": { blurb: "A work-study internship at Butler Machinery Company in Minot, North Dakota, for high school students interested in ag equipment and diesel technology. Students work alongside a full-time service technician mentor and rotate through company departments to help decide whether to pursue diesel technology training. Applicants must be at least 16, the program runs in the summer and during the school year, and it can lead to a technician placement with Butler." },
  // https://www.brooklynda.org/internships/
  "the-brooklyn-district-attorney-s-office-high-school-internship": { blurb: "An internship at the Brooklyn District Attorney's Office for high school students, offered three times a year in summer, winter and spring. Interns are placed in a general trial zone or in a specialized unit such as Homicide, Special Victims or Domestic Violence. Summer sessions have been open to students who live or attend high school in Brooklyn, and applicants submit a transcript, resume, letters of recommendation and a typed essay." },
  // https://nmu.edu/cte/high-school-internships
  "northern-michigan-university-s-career-and-technical-education-de": { blurb: "An unpaid internship course for high school seniors, run by the Marquette-Alger Regional Educational Service Agency with Northern Michigan University's Career and Technical Education program. Students spend 6 to 10 hours per week during the school year at a local business or agency, such as a hospital, vet clinic or NMU department, where site employees train and supervise them. Applicants need a resume and counselor recommendation and must interview." },
  // https://www.dana-farber.org/about/careers/workforce-development/student-training-program
  "dana-farber-cancer-institute-office-of-workforce-development-stu": { blurb: "A paid training program at Dana-Farber Cancer Institute in Boston for public high school students, mainly from Boston, who are interested in health care careers. In the summer, students work full-time internships in hospital departments for 30 hours a week over seven weeks and attend weekly college and career readiness workshops. Summer graduates interested in clinical, research or health administration careers can continue for 8 to 15 hours a week from October to June." },
  // https://www.noguchi.org/museum/education/teens/teen-advisory-board/
  "the-isamu-noguchi-foundation-and-garden-museum-teen-advisory-boa": { blurb: "A paid teen leadership program at The Noguchi Museum in Long Island City for rising junior and senior New York City public high school students. Members study the museum's history and the work of Isamu Noguchi, then design and present a culminating project in the Education Studio. The group meets on Wednesdays from 4:30 to 6:30 pm from November through May, with some required Saturdays, and members receive a $750 stipend for full participation." },
  // https://www.brooklynmuseum.org/careers/internships-fellowships/intersextions
  "the-brooklyn-museum-intersextions-gender-sexuality": { blurb: "A paid internship at the Brooklyn Museum where New York City teens explore gender and sexuality in art through an activist lens and organize programming for queer and trans youth, including the annual LGBTQ+ Teen Night each June. Members meet Tuesdays from 4:30 to 6:30 pm from November to June, with occasional weekend or Friday events. First-year members earn $17 an hour and returning leaders earn $18, for up to 75 hours a year." },
  // https://www.rockefeller.edu/outreach/snp/
  "the-rockefeller-university-summer-neuroscience-program": { blurb: "A free two-week neuroscience course at The Rockefeller University in Manhattan for New York City public high school students, taught by Rockefeller graduate students. Students attend lectures, read and present a research paper, design and run their own experiment, dissect a brain and visit labs. Classes meet on weekdays in August, applicants must be at least 16, no transcripts or GPA are required, and the program covers meals and metro passes." },
  // https://wacofsa.org/community/internship-opportunities/
  "world-affairs-council-of-san-antonio-internships": { blurb: "An internship at the World Affairs Council of San Antonio where interns gain work experience in education, fund development, communications, membership and events while supporting the council's mission. Interns in education help with the council's high school and college programming and assist educators who bring international education to local students. Applicants send a cover letter, resume, one recommendation and two references to the executive director." },
  // https://www.sdsmt.edu/events/education-outreach/summer-camps/mining-and-explosives.html
  "the-south-dakota-school-of-mines-technology-mining-explosives-ca": { blurb: "A free summer camp at the South Dakota School of Mines & Technology in Rapid City for students entering their junior or senior year and recent graduates. Campers learn the science behind detonations through hands-on blasting, rock-breaking experiments and mine safety training. The camp runs in June, and applicants submit an online registration, a student statement and a teacher recommendation for faculty review." },
  // https://www.hypothekids.org/nybioforce
  "columbia-engineering-new-york-bioforce": { blurb: "A free biomedical research training program run by HYPOTHEkids for 11th and 12th graders at New York City public and charter high schools who face educational or economic disadvantage. Students complete 50 hours of Saturday training at Columbia University from April to July, then a six-week paid placement in a lab or health care setting at 25 hours per week. Interns present their research at a poster session, and no prior research experience is required." },
  // https://precollege.barnard.edu/pre-baccalaureate-program
  "barnard-college-pre-baccalaureate-program": { blurb: "A tuition-based summer program at Barnard College where high school students take a true undergraduate-level course in person on Barnard's campus in New York City. The commuter-only program runs from early July to mid-August, and students who complete it earn 3 credits and can request an official Barnard transcript. It is open to rising juniors, rising seniors and gap year students, and tuition is $7,065 plus an $835 registration fee." },
  // https://www.vermontsportsmedicinecenter.com/Careers/Internships-for-HS-Students/a~7047--c~356013/article.html
  "vermont-sports-medicine-center-clinical-internship-program": { blurb: "An unpaid clinical internship at Vermont Sports Medicine Center for high school juniors and seniors with a GPA of 3.0 who plan to study a medical field. Interns get exposure to physical and occupational therapy and help with daily operations under the Clinical Manager or Practice Director, preparing treatment spaces, setting up equipment and scheduling patients. Terms last about 2-4 months around the school schedule, at 6 to 20 hours per week." },
  // https://www.nm.org/about-us/workforce-development/high-school-programs/nm-discovery-program
  "northwestern-medicine-discovery-program": { blurb: "A free healthcare career exploration program run by Northwestern Medicine for students who may have limited access to opportunities to explore health careers. Participants take part in tours, guest speakers, group discussions and hands-on activities at monthly Saturday meetings from 9 am to noon during the school year. Applicants must be at least 15, entering sophomore or junior year, with a GPA of at least 3.0, and are placed in one of six chapters based on school location." },
  // https://www.lcfpd.org/assets/1/7/2025_Crew_Member_Application.pdf
  "lake-county-forest-perserves-youth-conservation-corp-crew-member": { blurb: "A paid summer job with the Youth Conservation Corps, run by the Lake County Forest Preserves in Illinois. Crew members work outdoors on projects such as building nature trails, planting and maintaining native plants, stream bank restoration and trail bridge construction. Applicants must live in Lake County and be at least 16 and no older than 18, crews are chosen by lottery, and workers provide their own transportation to work sites." },
  // https://www.nyhistory.org/education/student-historian-internship-program
  "new-york-historical-society-student-historian-internship-program": { blurb: "An in-person, school-year internship at the New-York Historical where high school students research history and create digital history projects that serve as public educational resources around a yearly theme. Interns meet on Wednesdays from 4:30 to 7 pm from October to June and receive a $1200 stipend on completion. It is open to students entering grades 10, 11 or 12 who live and attend school in the New York City metro area, and interns need working papers." },
  // https://www.charlestoncounty.gov/syip/
  "the-summer-youth-internship-program-summer-youth-internship-char": { blurb: "A paid summer internship run by Charleston County government in South Carolina for young people who live in the county. Interns gain experience in county government operations while building workplace readiness skills. The program runs each summer and is separate from the county's Student Leadership and Intern Program run by the 9-1-1 Center and EMS." },
  // https://wiep.uic.edu/communityoutreach/wiesp/
  "university-of-illinois-at-chicago-women-in-engineering-summer-pr": { blurb: "A free, 3-week, non-residential summer engineering program for young women at the University of Illinois Chicago, run by its Women in Engineering office. Students work on hands-on projects in fields such as electrical and computer engineering and mechanical engineering and visit corporate partners. It is open to students in 11th or 12th grade with a GPA of 3.2 or higher, runs in June and July, and pays a stipend on successful completion." },
  // https://besthealthcareinstitute.org/programs/
  "best-healthcare-institute-summer-program": { blurb: "A free, four-week summer program run by the BESt Healthcare Institute on WashU's Danforth Campus in St. Louis for aspiring healthcare workers. Students take math, science and ACT/SAT prep, learn about healthcare through lectures and site visits, and build leadership skills. It is open to St. Louis-area freshmen, sophomores and juniors with a GPA of at least 3.0, attendance is required all four weeks, and stipends reach up to $400 or $500 by level." },
  // https://www.hawaiipacifichealth.org/careers/find-your-career/students/health-careers-summer-internship/
  "hawaii-pacific-health-health-careers-summer-internship-program": { blurb: "A six-week paid summer internship at Hawaii Pacific Health and its medical centers on Oahu and Kauai for high school juniors and seniors and college students. Interns learn how hospitals operate, work alongside healthcare professionals and explore medical careers, with past placements in departments such as the emergency room, surgery, pharmacy and the neonatal intensive care unit. It runs from mid-June through July, and more than 900 students have taken part since 2004." },
  // https://scienceoutreach.princeton.edu/laboratory-learning-program
  "princeton-university-laboratory-learning-program": { blurb: "A free summer research program at Princeton University where local New Jersey high school students join faculty labs in the natural sciences and engineering. Internships typically last 5-6 weeks during regular office hours and are in person and non-residential, so students arrange their own daily travel to campus. Applicants must be at least sixteen years old, attend a local New Jersey high school and be U.S. citizens, and there are no fees to take part." },
  // https://www.gloucestercountynj.gov/237/Internship-Opportunities
  "gloucester-county-internships-for-credit-or-experience": { blurb: "Unpaid internships with the Gloucester County government in New Jersey, offered to both high school and college students who want to earn school credit, gain work experience, or both. High school students start by contacting their high school guidance office, and questions go to the county Human Resources Department." },
  // https://www.cairchicago.org/intern-center
  "cair-chicago-internship-program": { blurb: "An unpaid internship at the Chicago chapter of the Council on American-Islamic Relations, a civil rights group, open to high school students in grades 9-12 as well as older students. Interns join departments such as government affairs and outreach, and high school interns can earn community service hours. Sessions run in winter-spring, summer and fall, high school interns serve at least 8 weeks for a minimum of 10 hours per week, and orientation and training are required." },
  // https://med.emory.edu/departments/human-genetics/_documents/next_gen_flyer_2026.pdf
  "emory-university-school-of-medicine-next-gen-high-school-interns": { blurb: "A paid five-week summer internship run by the Department of Human Genetics at Emory University School of Medicine for Atlanta-area high school students. Interns combine lab work at Emory, such as analyzing genetic mutations and studying fruit flies, with classroom lessons in biology and genetics, field trips and career advice. It runs in June and July for rising juniors and seniors who are at least 16, and the internship pays $3,120." },
  // https://collegenow.baruch.cuny.edu/stem-research-academy/
  "cuny-baruch-college-now-stem-research-academy": { blurb: "A two-part research program through Baruch College Now for New York City public high school students in 10th or 11th grade from groups underrepresented in science. Students first take a 60-hour spring research prep course that earns college credit, then can join an optional six-week summer research project with CUNY faculty in fields such as biology and environmental science and receive a stipend. Twenty-five students are chosen, and applicants need an 80+ average." },
  // https://www.youthbridgeny.org/fellowship
  "youthbridge-ny-youthbridge-ny-fellowship": { blurb: "A free leadership fellowship from YouthBridge-NY that brings together high school students of different backgrounds from across the New York City metro area to build leadership skills and work across differences. Fellows apply as rising juniors and meet two weekday evenings per month at the group's office in Manhattan during the school year. They also attend quarterly Sunday or school-holiday programs held off site." },
  // https://themdc.org/learning-opportunities/
  "the-metropolitan-district-of-hartford-high-school-learn-and-earn": { blurb: "A high school work-based learning program from The Metropolitan District (MDC), the water and sewer utility in the Hartford, Connecticut area. Through its Try-A-Trade program, high school juniors and seniors who are at least 16 spend one week during spring break getting hands-on experience in MDC trades and learning about careers they could start right after high school. Applications are submitted online." },
  // https://www.abzuginstitute.org/summer-programs
  "bella-abzug-leadership-institute-journey-to-leadership-program": { blurb: "A free summer leadership and debate training program run by the Bella Abzug Leadership Institute in New York City. Trainees take part in workshops, seminars, guest speakers, networking and debate labs on weekdays, in a 6-week program split into 3 cohorts of 60 trainees. It is open to youth ages 13-21 from the NYC area with no academic requirements, and priority goes to youth from underserved neighborhoods and schools." },
  // https://oregonfederalbarassociation.org/community-initiatives/
  "oregon-chapter-of-the-federal-bar-association-haggerty-scholars": { blurb: "A free mentorship program from the Oregon Chapter of the Federal Bar Association for high school students interested in law and civil rights, named for Oregon's first African American federal judge. Each scholar is paired with an attorney mentor for a school year, including college essay help, courtroom visits and events on topics like juvenile justice and immigration. Students from under-served schools or underrepresented communities are encouraged to apply." },
  // https://engineering.buffalo.edu/home/outreach/camps/exlent-experiential-learning-in-emerging-stem-technologies.html
  "university-of-buffalo-ub-experiential-learning-in-emerging-stem": { blurb: "A free summer program at the University at Buffalo School of Engineering and Applied Sciences, funded by the National Science Foundation, on emerging technologies. Students take a core programming and databases course and an introduction to cybersecurity, plus electives in AI, the Internet of Things and robotics. It runs from late June through July for rising ninth- through twelfth-graders in Buffalo and Western New York, and eligible students may receive stipends." },
  // https://www.umc.edu/graduateschool/Base-Pair/About.html
  "base-pair-research-internship": { blurb: "A biomedical research mentorship program at the University of Mississippi Medical Center that pairs UMMC faculty with public high school students in Mississippi. Students take a Biomedical Research course that counts toward graduation, then do laboratory research at UMMC during the school year starting in January. Most participants are juniors and seniors, and students have co-authored or presented hundreds of abstracts, posters and papers since the program began in 1992." },
  // https://www.brooklynmuseum.org/careers/internships-fellowships/creative-practice
  "the-brooklyn-museum-creative-practice": { blurb: "A paid school-year internship at the Brooklyn Museum where teens assist teaching artists in leading art classes for students of all ages. Interns prepare studios and materials, learn lesson planning and practice classroom management, helping with weekend classes and meeting on Thursdays from September to June. It is open to NYC high school sophomores, juniors and seniors, pays $17 per hour for up to 120 hours a year, and provides MetroCards for weekend work." },
  // https://nosb.org/rules/
  "center-for-ocean-leadership-national-ocean-sciences-bowl-nosb": { blurb: "An ocean science quiz bowl for high school teams, held as regional bowls at universities, research institutions, laboratories, science centers and aquariums across the country. Teams of at least four students and a coach answer buzzer-style multiple-choice questions and open-ended team challenge questions on biology, physics, geology, chemistry, geography, policy and current events. Teams without a nearby bowl can compete on Zoom in the Virtual Sponge Bowl in March." },
  // https://www.futureengineers.org/nasatechrise
  "nasa-future-engineers-nasa-techrise-student-challenge": { blurb: "A national challenge from NASA and Future Engineers in which student teams in grades 6-12 design an experiment to fly on a NASA-sponsored high-altitude balloon. Teams need at least four students from the same U.S. public, private or charter school, led by a teacher or school employee. The 60 winning teams each receive $1,500 to build their experiment, a starter kit with a flight box, a spot on a flight of about 4 to 8 hours at 70,000 to 95,000 feet, and virtual mentoring." },
  // https://www.epa.gov/education/presidents-environmental-youth-award
  "u-s-environmental-protection-agency-presidents-environmental-you": { blurb: "A national award from the U.S. Environmental Protection Agency that recognizes K-12 students and youth groups for environmental stewardship projects. Projects must be completed while students are in kindergarten through 12th grade and sponsored by at least one adult 21 or older, and applicants must be U.S. citizens or lawful permanent residents living in a U.S. state, territory or Tribal land. Entries are judged in two categories, grades K-5 and grades 6-12." },
  // https://dillerteenawards.org/apply/
  "helen-diller-family-foundation-diller-teen-tikkun-olam-awards": { blurb: "An annual award that gives Jewish teens $36,000 each for leading volunteer projects that repair the world, or tikkun olam. Applicants must be 15 to 19, identify as Jewish, live in the U.S., and currently lead an unpaid initiative with measurable impact, though projects may have global reach. The award is merit-based, and recipients may use the money to further their philanthropic work or for their education." },
  // https://www.house.gov/educators-and-students/congressional-art-competition
  "u-s-house-of-representatives-congressional-art-competition": { blurb: "A nationwide high school visual art competition held each spring, in which students enter artwork through their own member of the U.S. House of Representatives and panels of district artists pick the winners. Each district's winning piece is displayed for one year at the U.S. Capitol. Accepted media include painting, drawing, prints, collage, mixed media, digital art and photography, and each entry must be one student's original work. Each office sets its own deadline." },
  // https://www.bennington.edu/news-and-features/9th-12th-grade-students-invited-submit-bennington-college-young-writers-awards
  "bennington-college-bennington-young-writers-awards": { blurb: "A free writing competition from Bennington College for students in grades 9-12, with categories in poetry (a group of three poems), fiction (a short story or one-act play) and nonfiction (a personal or academic essay). Entries must be original work sponsored by a high school teacher, and stories and essays must be under 1500 words. A first, second and third place winner is chosen in each category, with cash prizes up to $2,000, and winners are announced in the spring." },
  // https://kenyonreview.org/submit/patricia-grodd/
  "the-kenyon-review-patricia-grodd-poetry-prize-for-young-writers": { blurb: "An annual poetry contest from The Kenyon Review for high school sophomores and juniors, created in 2007 to recognize young poets. Students submit one unpublished poem during the November submission period. Poems by the winner and runners-up are published in The Kenyon Review, and the winner receives a full scholarship to a Kenyon Review Young Writers workshop." },
  // https://www.studentcam.org/rules/
  "c-span-studentcam-documentary-competition": { blurb: "A national documentary competition from C-SPAN in which middle and high school students make a 5 to 6 minute film on an annual civics theme, using clips of C-SPAN programming. Students may enter alone or in teams of up to 3, and high school entries are judged regionally in West, Central and East divisions. C-SPAN awards a total of $100,000 in cash prizes to the top 150 documentaries, with a grand prize of $5,000 per team." },
  // https://jazz.org/education/school-programs/essentially-ellington/
  "jazz-at-lincoln-center-essentially-ellington-high-school-jazz-ba": { blurb: "A program from Jazz at Lincoln Center for high school jazz bands that provides free transcriptions of original Duke Ellington recordings, teaching resources, free adjudication and regional festivals. Bands apply with recordings, and finalist bands travel to New York City in May for three days of workshops, jam sessions, rehearsals and performances at Frederick P. Rose Hall. Finalist bands are limited to 25 participating students." },
  // https://stosselintheclassroom.org/essay-contest/
  "stossel-in-the-classroom-stossel-in-the-classroom-essay-contest": { blurb: "An annual essay contest from Stossel in the Classroom on economics and civics questions, with a separate high school division for grades 9-12. The contest awards over $12,000 to students, and high school prizes are $2,500 for first place, $1,000 for second and $500 for third, plus smaller awards for finalists, semi-finalists and honorable mentions. Students who entered the AI Challenge are not eligible." },
  // https://dukemathmeet.org/
  "duke-university-mathematics-union-duke-math-meet": { blurb: "A regional math competition for high school students held each fall at Duke University. It is organized by members of the Duke University Mathematics Union and sponsored by the Duke Mathematics Department. Students compete as teams across power, team, guts, individual and relay rounds, and past problems, solutions and results are posted online." },
  // https://www.contest.comap.com/highschool/contests/himcm/instructions.html
  "comap-high-school-mathematical-contest-in-modeling-himcm": { blurb: "A team contest from COMAP in which high school students model a real-world problem and write a solution paper during a contest window in November. A faculty advisor registers each team, the registration fee is $100 per team and non-refundable, and payment is made by credit card through the COMAP website. A parallel contest, MidMCM, is offered for middle school teams." },
  // https://ww2.amstat.org/education/posterprojects/projectupload/index.cfm
  "american-statistical-association-asa-statistics-project-competit": { blurb: "A national competition from the American Statistical Association in which students in grades 7-12 answer a research question using statistical techniques and present their work in a written report. Entries are judged in two grade categories, grades 7-9 and grades 10-12, and each entry lists a teacher or advisor. In past years, first-place winners have received $300 and a certificate." },
  // https://www.amstat.org/education/asa-data-visualization-poster-competition-for-grades-k-12-
  "american-statistical-association-asa-data-visualization-poster-c": { blurb: "A national competition from the American Statistical Association in which K-12 students make posters that use data visualizations to support their conclusions. Entries are judged by grade group, and winners are announced in August. National prizes are $300 for first place, $200 for second and $100 for third, each with a certificate, and first-place winners in grades 4-12 also receive Texas Instruments graphing calculators." },
  // https://www.hollins.edu/academics/pre-college-experiences-camps/nancy-thorp-poetry-contest/
  "hollins-university-nancy-thorp-poetry-contest": { blurb: "A poetry contest from Hollins University for young women who are sophomores or juniors in high school, preparatory school or homeschool. Students submit one or two unpublished poems, and applicants must be U.S. citizens. The first-place winner receives a $350 cash prize, a renewable Hollins scholarship of up to $5,000, free tuition and housing for the Hollinsummer creative writing program, and publication in Cargoes, the student literary magazine." },
  // https://www.elks.org/scholars/scholarships/legacy.cfm
  "elks-national-foundation-elks-legacy-awards": { blurb: "A college scholarship from the Elks National Foundation for high school seniors who are children, stepchildren, legal wards or grandchildren of a living Elks member in good standing. The Foundation offers 400 awards of $6,000 each, paid as $1,500 per year for four years. Winners are chosen on leadership and the Foundation's core values, with no review of financial need, and children and grandchildren compete separately within their state." },
  // https://www.aopa.org/training-and-safety/students/aopa-flight-training-scholarships
  "aopa-foundation-aopa-high-school-flight-training-scholarships": { blurb: "A flight training scholarship from the AOPA Foundation that gives at least 90 students aged 16-18 $12,000 each toward earning a private pilot certificate. Applicants need a minimum 2.7 GPA, must pass the FAA Private Pilot written knowledge exam before applying, and must be AOPA members, which is free for high school students. Training must be completed within 12 months of the award, and applications are taken in fall and spring periods." },
  // https://mikeroweworks.org/scholarship/
  "mikeroweworks-foundation-work-ethic-scholarship-program": { blurb: "A scholarship from the mikeroweWORKS Foundation for U.S. citizens who are high school seniors or graduates and plan to enroll in an approved program of two years or less at an accredited school. It supports training for careers such as welding, plumbing, electrical, HVAC and construction, and every applicant must sign the S.W.E.A.T. Pledge. The foundation says it looks at work ethic rather than GPA, and applications are reviewed in rounds." },
  // https://www.mcsf.org/apply/eligibility/
  "marine-corps-scholarship-foundation-marine-corps-scholarship-fou": { blurb: "Need-based college and career-school scholarships from the Marine Corps Scholarship Foundation for children of active-duty, Reserve or honorably discharged veteran Marines, and of Navy Corpsmen, Chaplains or Religious Program Specialists attached to a Marine unit. Applicants need at least a 2.00 GPA, and family adjusted gross income must be $134,000 or less for the 2025 tax year. A Career and Technical Education scholarship for certificate programs is offered year-round." },
  // https://foldsofhonor.org/scholarships/
  "folds-of-honor-folds-of-honor-scholarships": { blurb: "Need-based scholarships from Folds of Honor for spouses and dependents of fallen or disabled U.S. service members and of first responders who have fallen or been catastrophically injured. Awards cover private school tuition or tutoring in grades K-12 and tuition for college, technical or trade school. Dependents applying for higher education must be 24 or younger, and students must reapply each year." },
  // https://www.kipr.org/botball
  "kiss-institute-for-practical-robotics-botball-educational-roboti": { blurb: "A team robotics program from the KISS Institute for Practical Robotics for middle and high school students, who build and code robots that run without a driver. Teams program autonomous robots in C, C++ or Java using a kit with a Wombat controller, LEGO and metal parts, motors, sensors and a camera. Each season starts with educator workshops, followed by a seven-week build period and regional tournaments. Any team with an adult leader can join." },
  // https://www.destinationimagination.org/challenge-experience/global-finals/
  "destination-imagination-destination-imagination": { blurb: "A creative problem-solving program in which student teams develop solutions to project-based STEAM challenges and present them live at tournaments. Challenge categories cover technical, scientific, engineering, fine arts, improvisational and service learning themes, and scoring combines a Team Challenge with an Instant Challenge. Teams compete at regional or affiliate tournaments, and top teams qualify for Global Finals, held each May in Kansas City, Missouri." },
  // https://wsb.wharton.upenn.edu/wharton-data-competition/
  "wharton-sports-analytics-and-business-initiative-wharton-high-sc": { blurb: "A free sports analytics competition run by the Wharton Sports Analytics and Business Initiative with Wharton Global Youth, open to high school students worldwide. Teams of 3-5 students from the same high school analyze a sports dataset, rank teams and predict outcomes, and the top teams present their work to judges over Zoom. Each team needs an advisor employed by the school or district, who registers the team. The 2027 edition uses American football data." },
  // https://www.ashg.org/dna-day/
  "american-society-of-human-genetics-dna-day-essay-contest": { blurb: "An annual essay contest from the American Society of Human Genetics for students in grades 9-12 worldwide, who write on a human genetics question that changes each year. Past topics include new genetic therapies and AI in genetic testing. ASHG members judge essays for accuracy, creativity and writing over three rounds of review. Winning students receive cash prizes, and eligible teachers can receive grants for genetics lab equipment." },
  // https://buffettscholarships.org/eligibility-selection
  "susan-thompson-buffett-foundation-susan-thompson-buffett-foundat": { blurb: "A need-based college scholarship from the Susan Thompson Buffett Foundation for Nebraska residents with a Nebraska high school diploma or GED who will enter a Nebraska public college as first-time freshmen. Applicants need at least a 2.0 unweighted GPA and a Student Aid Index below 10,000. Selection weighs need, grades, short answers and a recommendation. Scholars take at least 12 credits per term, and the award renews for up to 5 years at a four-year college." },
  // https://www.afrotc.com/scholarships/high-school/requirements/
  "u-s-air-force-rotc-air-force-rotc-high-school-scholarship": { blurb: "A college scholarship from Air Force ROTC for high school students who agree to serve as officers in the Air Force or Space Force for at least four years on active duty after graduation. Applicants need U.S. citizenship, a 3.3 unweighted GPA and a minimum 1310 SAT, 28 ACT or 93 CLT score. They must finish junior year, pass a medical exam and complete a fitness assessment with push-ups, crunches and a 2.0 mile run." },
  // https://biomed-focus.medicine.umich.edu/about
  "university-of-michigan-medical-school-biomed-focus-summer-resear": { blurb: "A paid, full-time 8-week summer research program at the University of Michigan and Michigan Medicine for rising high school juniors and seniors. Scholars work in campus labs, take science communication and college prep courses, write a manuscript and give a research talk at a closing symposium. It is a commuter program for Michigan students who live within commuting distance of Ann Arbor, and Scholars receive $4,000. No prior lab experience is needed." },
  // https://miahec.wayne.edu/southeast/bcap
  "wayne-state-university-school-of-medicine-biomedical-career-adva": { blurb: "A 6-week summer research program run by Wayne State University School of Medicine and the Michigan AHEC Southeast Regional Center for students in grades 10-12. Students complete independent projects with research mentors and present them at a symposium, with Fridays set aside for lab safety training, clinical skills and career panels. Those who finish receive a monetary award. Applicants need a 2.75 GPA, and Wayne County and Detroit students get priority." },
  // https://www.nasa.gov/learning-resources/for-students-grades-9-12/nasa-glenn-high-school-engineering-institute/
  "nasa-glenn-research-center-nasa-glenn-high-school-engineering-in": { blurb: "A free, week-long engineering program at NASA's Glenn Research Center in Cleveland for rising high school juniors and seniors. Students work on three projects designed by NASA engineers, tour labs and test facilities, and present their work to NASA experts. Three sessions run in July. Applicants must be U.S. citizens or permanent residents, at least 16 years old and hold at least a 3.2 GPA, and they provide their own housing and transportation." },
  // https://case.edu/cancer/training-education/yes
  "case-comprehensive-cancer-center-youth-engaged-in-science-yes-pr": { blurb: "A paid summer program at the Case Comprehensive Cancer Center for Cleveland-area high school students interested in cancer research and healthcare careers. Students start with a one-week science bootcamp on lab safety, research methods and cancer biology, then work 35 hours per week in cancer research labs through week 7. Applicants need a 3.0 GPA and must be at least 14. Students who finish receive a $2,500 stipend." },
  // https://my.clevelandclinic.org/about/community/hire
  "cleveland-clinic-lerner-research-institute-high-school-summer-re": { blurb: "A paid summer research internship run by Cleveland Clinic's Lerner Research Institute in partnership with the Cleveland School of Science and Medicine. Students from that high school spend 10 weeks doing research at the institute, with a mentor, weekly programming, tours of Cleveland Clinic and networking lunches with mentors and institute leaders. Admission is competitive, with eight to ten students accepted each year." },
  // https://www.akronchildrens.org/pages/Research-Student-Programs.html
  "akron-childrens-hospital-considine-research-institute-high-schoo": { blurb: "Paid and unpaid research internships at the Rebecca D. Considine Research Institute of Akron Children's Hospital that introduce high school and college students to careers in pediatric healthcare and research. Interns work alongside researchers, physicians and healthcare staff in clinical and nonclinical settings. Openings depend on the project, mentor availability and active research, so placements vary each term." },
  // https://holdenfg.org/education/green-corps/
  "holden-forests-and-gardens-green-corps-high-school-internship": { blurb: "Paid internships at Holden Forests & Gardens in Northeast Ohio for learners ages 14-18, introducing the skills of green practitioners, museum administrators and nonprofit professionals. Interns are placed in areas such as animal care, conservation, forest health, horticulture, guest services and research topics including soil ecology and plant physiology. Questions go to the Green Corps program coordinator." },
  // https://www.cincinnatichildrens.org/education/research/high-school/summer-internship
  "cincinnati-childrens-hospital-medical-center-high-school-summer": { blurb: "A one-month intensive summer program at Cincinnati Children's for graduating high school seniors from the Cincinnati area. It is a newly designed program that begins in summer 2027 as part of the hospital's high school research education programs. Cincinnati Children's says more program details will be shared in the coming months, and questions go to the hssummerinternship@cchmc.org address." },
  // https://collegeofphysicians.org/programs/wohlreich-junior-fellows-program/
  "the-college-of-physicians-of-philadelphia-wohlreich-junior-fello": { blurb: "A nine-month after-school program at the College of Physicians of Philadelphia for rising 9th through 12th graders in the School District of Philadelphia interested in science and medicine. Students meet weekly from September through May, study topics such as anatomy, biotechnology, forensic science and public health, and present an independent research project at a poster session in May. Students earn a stipend for each semester completed." },
  // https://www.phillyseaport.org/teen-ambassadors/
  "independence-seaport-museum-teen-ambassadors-program": { blurb: "A ten-week paid work and learning program at the Independence Seaport Museum for Philadelphia high school students entering grades 10-12. Ambassadors train in community leadership, research and museum education, hear weekly from experts, and teach visitors about topics such as environmental justice, Delaware River wildlife and Philadelphia history. It runs June through August with some Saturdays in September." },
  // https://summerresearchacademy.cos.gatech.edu/
  "georgia-tech-college-of-sciences-summer-research-academy-sra": { blurb: "A full-time summer research program at the Georgia Tech College of Sciences that matches local high school students with a lab in their field of interest, at no cost to students. Students spend the first week on lab safety and reading papers, work on individual projects, and present results in the final week. Applicants must be at least 16, and no research experience is needed. It is unpaid and not residential." },
  // https://winshipcancer.emory.edu/education-and-training/undergraduate-and-pre-college-programs/summer-scholars.php
  "winship-cancer-institute-of-emory-university-summer-scholars-res": { blurb: "A six-week cancer research internship at Emory's Winship Cancer Institute for rising or graduating high school seniors who are at least 16. Each student is paired with a Winship physician or lab researcher and does research in an active laboratory. Students who complete the program receive a $2,400 stipend, and housing is not provided. The in-person program requires U.S. citizenship or permanent residency, and a virtual option is available." },
  // https://sites.gsu.edu/ion-teach/
  "georgia-state-university-institute-on-neuroscience-ion-summer-re": { blurb: "A paid summer neuroscience research program run by Georgia State University's Center for Behavioral Neuroscience for high school students. Scholars take an introductory neuroscience course, work with a mentor on a lab project and present results at a research symposium. Applicants must be at least 16, and juniors and seniors with a 3.0 GPA are preferred. Students arrange their own transportation and meals, and no housing is provided." },
  // https://www.augusta.edu/cancer/education/summer-research-experience.php
  "georgia-cancer-center-at-augusta-university-georgia-cancer-cente": { blurb: "A six-week summer research program at the Georgia Cancer Center at Augusta University for high school students interested in biomedical science. Students are paired with mentors, help advance research projects alongside cancer researchers, and attend seminars and tours. Students must be at least 16 by the start of the program for lab bench projects, while younger students can apply for bioinformatics or community-based projects. Housing and stipends are not provided." },
  // https://atlantabg.org/school-tours/summer-high-school-internship/
  "atlanta-botanical-garden-summer-high-school-internship": { blurb: "A paid summer internship at the Atlanta Botanical Garden for students who are at least 16 and rising sophomores, juniors or seniors at Metro Atlanta Title I high schools. Interns help with plant conservation research, greenhouse plant care and garden grounds, keep a journal and present a personal project at the end. The 2026 cohort worked 18 hours a week, Tuesdays through Thursdays, for seven weeks at $12 an hour, with lunch and transit cards or parking passes included." },
  // https://www.biology.pitt.edu/k-12-outreach/gene-team
  "university-of-pittsburgh-department-of-biological-sciences-gene": { blurb: "A free four-week summer research program run by the University of Pittsburgh Department of Biological Sciences for Pittsburgh-area high school students. Students work together on a current research project in a Pitt lab and attend weekly sessions on college applications. Applicants need one year of high school biology but no prior research experience. Students receive a $1,000 honorarium at the end of the program, and free PRT bus passes are available." },
  // https://www.phipps.conservatory.org/classes-and-programs/for-educators/ecoleader-academy
  "phipps-conservatory-and-botanical-gardens-ecoleader-academy": { blurb: "A free seven-week environmental science course at Phipps Conservatory and Botanical Gardens for students ages 14 to 19 who have finished at least one year of high school. Participants meet one day a week in a Wednesday or Thursday cohort for expert-led classes, discussions, workshops and service projects on topics such as climate change, energy, pollution and green careers. Participants receive a stipend, and the course ends with a Youth Garden Summit." },
  // https://sites.wustl.edu/wustlysp/programs/summer-focus/
  "washington-university-in-st-louis-young-scientist-program-summer": { blurb: "A funded eight-week summer research internship at Washington University in St. Louis for high school students from the Greater St. Louis area who have completed junior year before the program begins in June. Each Scholar is paired with a research Mentor and a Tutor, and the program also offers college and career workshops. Scholars receive a $4,800 (pre-tax) stipend, and the program accepts 10 to 12 students each year." },
  // https://info.umkc.edu/stahr/scholars/high-school/
  "university-of-missouri-kansas-city-stahr-high-school-scholars-pr": { blurb: "A free six-week summer health careers program on UMKC's Health Sciences Campus for current high school sophomores and juniors. Students conduct a health-related research project with UMKC faculty, complete clinical observations and do community service, meeting in person Monday through Friday for 30 hours each week. Students who meet program expectations receive stipends and/or scholarships, and university housing is not offered." },
  // https://www.childrensmercy.org/childrens-mercy-research-institute/research-education/star-2.0-program
  "childrens-mercy-research-institute-star-2-0-summer-training-in-a": { blurb: "A six-week summer research program at the Children's Mercy Research Institute in Kansas City, Missouri, for high school freshmen, sophomores and juniors who live in Missouri or Kansas. Students work with Children's Mercy faculty on original research projects, develop a research publication for submission to a peer-reviewed journal, and tour departments. No research background is required, and students receive a $2,600 stipend." },
  // https://neuroscienceimmersion.wustl.edu/
  "washu-medicine-st-louis-summer-immersion-program-in-neuroscience": { blurb: "A paid eight-week neuroscience research program at WashU Medicine for rising high school juniors and seniors and graduating seniors who live in the St. Louis, MO-IL metro area and are U.S. citizens or permanent residents. Students do research 40 hours per week with long-term mentoring from a lab mentor and a WashU Medicine faculty member. No prior research experience is required, and benefits include $4,000 in compensation and free summer metro passes." },
  // https://tyson.wustl.edu/tera
  "tyson-research-center-washington-university-in-st-louis-tyson-en": { blurb: "A paid six-week summer field research apprenticeship at Washington University's Tyson Research Center for St. Louis-area high school students who completed the SIFT program the year before. Teens work as paid members of environmental biology research teams alongside WashU scientists, postdoctoral researchers, graduate students and undergraduates, applying field skills to ongoing projects at Tyson and partner research sites around St. Louis." },
  // https://dcri.org/education/dukes-star-program/star-program-undergraduate-high-school-students
  "duke-clinical-research-institute-summer-training-in-academic-res": { blurb: "A summer research training program at the Duke Clinical Research Institute in Durham, North Carolina, for high school and college students interested in science and medicine, with a separate track for medical students. Students join research teams with Duke faculty mentors, train in research methods, writing and career development, and take a medical ethics seminar on the responsible conduct of research. High school students receive a $4,000 stipend." },
  // https://sites.duke.edu/dukerep/
  "duke-university-biomedical-engineering-duke-research-in-engineer": { blurb: "A seven-week summer research program in Duke Biomedical Engineering labs for North Carolina rising high school juniors and seniors who are at least 16, with priority for Durham Public Schools students. Students work on research projects, attend required workshops and seminars, and spend eight hours a day on campus on weekdays. There is no cost to apply or attend, and students receive a stipend, transportation and daily lunch." },
  // https://dibs.duke.edu/education/dune/
  "duke-institute-for-brain-sciences-duke-university-neuroscience-e": { blurb: "A full-time, paid eight-week summer neuroscience research internship at Duke for current sophomores and juniors at public or charter high schools in Durham, North Carolina, who are at least 16. The program matches students with participating labs, where they work Monday through Friday, 9am to 5pm, and ends with a poster presentation to peers, family and Duke scientists. There is no cost to participate, and prior research experience is not required." },
  // https://www.ncssm.edu/summer/summer-ventures
  "north-carolina-school-of-science-and-mathematics-summer-ventures": { blurb: "A no-cost, state-funded summer program run by the North Carolina School of Science and Mathematics for North Carolina students in their second or third year of high school who are interested in STEM careers. Students live on a UNC System campus (Appalachian State, East Carolina, UNC Charlotte or UNC Wilmington) for four weeks and conduct research on topics of their interest. Meals and housing are covered, and students are selected by congressional district." },
  // https://school.wakehealth.edu/research/institutes-and-centers/wake-forest-institute-for-regenerative-medicine/education-and-training/high-school-summer-research-exposure-program
  "wake-forest-institute-for-regenerative-medicine-mentored-researc": { blurb: "A four-week mentored summer research program in regenerative medicine at Wake Forest University School of Medicine for North Carolina students ages 16 to 18. It is a commuter program with 8 to 10 spots, where students shadow research with faculty mentors. A separate one-week Virtual Academy on Zoom is open to middle and high school students ages 14 to 18, with an optional on-site tour on the Friday." },
  // https://www.worldfoodprize.org/en/youth_programs/world_food_prize_youth_institutes/indiana/
  "the-world-food-prize-foundation-purdue-youth-institute": { blurb: "A World Food Prize Foundation youth institute held at Purdue University in West Lafayette for students in grades 9 through 12. Students research a food security issue, write a paper under the supervision of a teacher or mentor, and present it while meeting local leaders and agriculture experts. There is no registration cost and meals are provided, and participants become Borlaug Scholars eligible for the Global Youth Institute and the Borlaug-Ruan internship." },
  // https://www.rose-hulman.edu/admissions-and-aid/early-planning/operation-catapult/index.html
  "rose-hulman-institute-of-technology-operation-catapult": { blurb: "A nearly two-week residential summer camp in science, engineering and math at Rose-Hulman Institute of Technology in Terre Haute, Indiana, for students in grades 10 and 11. Students live on campus and work in teams with faculty mentors on projects such as robotics, biodiesel and machine building. Students who finish the camp receive two hours of free elective credit if they later attend Rose-Hulman." },
  // https://science.indianapolis.iu.edu/physics/research/k-12-outreach.html
  "indiana-university-indianapolis-department-of-physics-summer-res": { blurb: "A six-week summer physics research program in the Department of Physics at IU Indianapolis for high school juniors and seniors and advanced sophomores. Students pick research topics and faculty mentors from the department's list and carry out research in June and July. Applicants need authorized working status in the U.S. and apply with a cover letter listing grades and teacher contacts plus an essay naming three research topics." },
  // https://cancer.iu.edu/education/summer/future-scientist.html
  "iu-melvin-and-bren-simon-comprehensive-cancer-center-future-scie": { blurb: "A summer cancer research program at the IU Simon Comprehensive Cancer Center for high school juniors at Indianapolis and Marion County public schools. Each student spends eight weeks on a research project under the mentorship of a university researcher on the IU School of Medicine's downtown Indianapolis campus. Admission weighs scholastic ability, maturity, attendance and interest in research, with a minimum 3.0 GPA, and participants receive a stipend." },
  // https://cancer.iu.edu/education/summer/future-deaf-scientist.html
  "iu-melvin-and-bren-simon-comprehensive-cancer-center-future-deaf": { blurb: "A four-week summer clinical shadowing internship at the IU Simon Comprehensive Cancer Center for students at the Indiana School for the Deaf. Interns shadow cancer center clinicians, gain pathology lab experience, observe surgical techniques and join daily video chats with deaf physicians and interns at other sites. Up to five interns take part each summer, and each receives a $1,500 stipend and one meal daily." },
  // https://indianactsi.org/education/student/seed-stem/
  "indiana-clinical-and-translational-sciences-institute-seed-stem": { blurb: "An eight-week summer program from the Indiana CTSI that pairs Indiana high school sophomores, juniors and seniors with faculty mentors on research projects. Students work in labs at sites such as IU School of Medicine, IU Indianapolis and Eli Lilly, Monday through Friday, and finish by presenting a research poster. Applicants need at least one high school chemistry course, and need-based stipends of up to $4,000 are available." },
  // https://research.nd.edu/our-services/research-engagement/programs/high-school-research-internships/
  "university-of-notre-dame-research-high-school-research-internshi": { blurb: "A school-year research internship run by Notre Dame Research that places local high school juniors and seniors in Notre Dame STEM faculty labs for high school credit. Each week students do research in a campus lab with a graduate or postdoctoral student mentor and attend Friday group classes. In May they present their completed projects at a poster presentation, and participants are selected by their schools." },
  // https://sare.cellbio.jhmi.edu/
  "johns-hopkins-initiative-for-careers-in-science-and-medicine-sum": { blurb: "An eight-week summer biomedical research internship at the Johns Hopkins School of Medicine for high school students from low-income or under-resourced backgrounds. Scholars do mentored lab work on the East Baltimore campus along with coursework in scientific writing, data analysis, math and bioethics. Household income must be at or below 200% of the federal poverty level, and those who complete the program receive a $3,000 stipend; housing is not provided." },
  // https://www.medschool.umaryland.edu/ramp/
  "university-of-maryland-school-of-medicine-research-and-mentoring": { blurb: "A two-year research and mentoring program at the University of Maryland School of Medicine for Baltimore City 11th and 12th graders interested in biology, chemistry, medicine or related fields. Year one pairs a five-week summer program with school-year research rotations, and year two is an applied summer research experience. Applicants must be at least 16, and students can be paid through YouthWorks plus up to $500 for rotations." },
  // https://www.ibbr.umd.edu/internship-application
  "institute-for-bioscience-and-biotechnology-research-ibbr-univers": { blurb: "A paid summer lab internship at the University of Maryland Institute for Bioscience and Biotechnology Research for Montgomery County Public Schools students. Interns spend eight weeks mentored by IBBR scientists and typically finish with a poster presentation, with an option to continue during the school year for MCPS credit. Applicants must be at least 16, rising juniors or seniors, and authorized to work in the U.S." },
  // https://www.nasa.gov/goddard/stem/space-club-scholars-program/
  "nasa-goddard-space-flight-center-and-national-space-club-goddard": { blurb: "A six-week summer program run by NASA Goddard Space Flight Center with the National Space Club and Foundation, in which high school students work onsite on projects five days a week. Applicants must be in grade 10, 11 or 12, at least 16 by the start date, U.S. citizens with a minimum 3.0 unweighted GPA, and live within 50 miles of Goddard in Greenbelt, Maryland, or the Wallops Flight Facility in Virginia." },
  // https://hollingscancercenter.musc.edu/outreach/sc-cheer-yes
  "musc-hollings-cancer-center-sc-cheer-youth-enjoy-science-yes-pro": { blurb: "A two-year cancer and biomedical research program at MUSC Hollings Cancer Center for local high school and undergraduate students. Students complete seven-week paid research internships over consecutive summers at $15 an hour, with cancer education, scientific communication and leadership training, and can earn up to 15 college credit hours. High school applicants are rising sophomores and juniors at partner Charleston schools with at least a 2.5 GPA." },
  // https://ccuinbre.com/ccu-hchec-sponsored-research/
  "coastal-carolina-university-score-high-school-research-program": { blurb: "A paid summer research program at Coastal Carolina University in which high school students from Horry County schools conduct research on the CCU campus. Each student works closely with a faculty mentor and an undergraduate student, and past participants have published their work and presented at conferences. A grant supports seven high school students each session, and applicants must be over 16 and complete an application and interview." },
  // https://web.uri.edu/rinsfepscor/shore/
  "rhode-island-nsf-epscor-shore-summer-high-school-opportunities-f": { blurb: "A five-week summer research fellowship run by Rhode Island NSF EPSCoR that pairs high school students with researchers at Rhode Island College. Fellows spend about 20 hours a week on scientific research projects and explore STEM opportunities across the state. The fellowship is open to high school students age 16 and older, and fellows receive a stipend when they complete the program." },
  // https://diversity.biomed.brown.edu/community-engagement/pathways-medicine-high-school-mentorship-program
  "warren-alpert-medical-school-of-brown-university-pathways-to-med": { blurb: "A mentorship program at the Warren Alpert Medical School of Brown University that pairs Rhode Island high school students in grades 9 through 12 with medical students. Core programming is 6-7 sessions of 1 to 2 hours, mostly on Saturdays from September to December in Providence. Topics include patient interviewing, clinical skills such as suturing, an anatomy lab and career panels, and students 16 and older can join shadowing." },
  // https://jacobsinstitute.org/next-gen-internship/
  "jacobs-institute-next-gen-summer-high-school-internship": { blurb: "A paid summer STEM and medical innovation internship at the Jacobs Institute in Buffalo, New York. In a 2-week program for 20 students, interns hear lectures from a neurosurgeon, use an endovascular simulator and work in small groups to research a health care problem and present a solution. Eight students continue for 5 more weeks of lab skills and lab placement; the 2-week stipend is $599.60, and the 7-week track adds $16.00 an hour." },
  // https://cancerresearch.uci.edu/high-school-students/summer-youth-science-fellowship-program/
  "uc-irvine-cancer-research-institute-youth-science-fellowship-pro": { blurb: "A free six-week summer research program at the UC Irvine Cancer Research Institute for Orange County high school students, described as serving rising seniors. Each fellow works in a different UCI lab under a mentor for about 30 hours a week, typically Monday through Friday, and attends seminars and professional development workshops. The program ends with a poster symposium, and about 20 students are accepted each year." },
  // https://seismolab.caltech.edu/about/outreach-and-internships/earthquake-fellows
  "caltech-seismological-laboratory-high-school-earthquake-fellows": { blurb: "A four-month research program at the Caltech Seismological Laboratory for local 10th and 11th grade students. Fellows build a seismometer, install it at home or school and analyze its data across Saturday sessions in May and June, a roughly four-week summer research block and end-of-summer Saturdays, about 130 hours in all. Applicants need three years of high school math, and fellows are loaned a computer and keep their seismometer." },
  // https://summer.ucla.edu/summer-programs/summer-college-immersion-program/scip/
  "ucla-summer-sessions-summer-college-immersion-program-scip": { blurb: "A six-week, in-person summer program from UCLA Summer Sessions in which high school students heading into junior or senior year take one or two UCLA courses alongside undergraduates. Students also attend required co-curricular workshops and lectures. Applicants need a minimum 3.8 unweighted GPA; costs include a $350 registration fee, a $1,675 program fee and $385 per unit, and California students may qualify for Summer Scholars Support." },
  // https://tarpits.org/tar-teens-internship
  "la-brea-tar-pits-natural-history-museums-of-los-angeles-county-t": { blurb: "A paid internship from the Natural History Museums of Los Angeles County for nine high school juniors and seniors who live in or attend school in Boyle Heights or Hancock Park. Interns develop an interpretive paleo-science project and share it with museum guests, meeting on select Saturdays in April and May and then for six weeks in June and July at about 24 hours a week. Transportation is provided, and a work permit is required." },
  // https://www.usna.edu/Admissions/Programs/index.php
  "united-states-naval-academy-naval-academy-summer-stem-program": { blurb: "A week-long residential summer STEM camp at the U.S. Naval Academy for students who will be rising 9th to 11th graders. Students from around the country stay in Bancroft Hall and explore topics such as rocket flight, machine learning, biotechnology, cryptography and cybersecurity. Sessions run in June, admission is competitive, and the fee for the 2025 program was $750." },
  // https://www.dfhcc.harvard.edu/research/cancer-disparities/students/cure-overview
  "dana-farber-harvard-cancer-center-continuing-umbrella-of-researc": { blurb: "A paid, full-time summer cancer research internship from the Harvard Cancer Consortium (DF/HCC) that lasts 7 to 11 weeks. Each student works with a research mentor and attends seminars, responsible conduct of research training and journal clubs, ending with an abstract and a final presentation. High school sophomores, juniors and seniors who are 16 at the start and live or attend school in Massachusetts are eligible." },
  // https://www.umass.edu/uww/pre-college
  "umass-amherst-university-without-walls-pre-college-summer-progra": { blurb: "Summer pre-college programs from UMass Amherst University Without Walls, with academic intensives in more than 25 topics including STEM, art and design, and business. Most courses are two weeks long and run online or residentially at Amherst and the Charles River Campus in Newton, Massachusetts. Options also include a six-week Research Intensive for rising juniors and seniors, and residential students live in a residence hall." },
  // https://www.cmu.edu/pre-college/academic-programs/ai_scholars.html
  "carnegie-mellon-university-pre-college-programs-ai-scholars": { blurb: "A free four-week residential summer program at Carnegie Mellon University in Pittsburgh where high school students explore AI fundamentals through Python coding, data, algorithms and evaluation. Scholars complete group projects, take field trips to tech companies and present at a final symposium. Sponsors cover tuition, housing, meals and select field trips. Applicants must be in 11th grade, at least 16 by the start date, and U.S. citizens or permanent residents." },
  // https://hsph.harvard.edu/fellowship-special-program/data-science-in-action/
  "harvard-t-h-chan-school-of-public-health-data-science-in-action": { blurb: "A free two-week summer camp run by the Harvard T.H. Chan School of Public Health's Department of Biostatistics that introduces high school students to machine learning and programming. Working in teams, students learn Python and program algorithms, including a neural network that recognizes images and drives a toy car. Each team gets a laptop and a Raspberry Pi. Rising freshmen through seniors are eligible, and stipends are available for students from low-income families." },
  // https://summerinstitutes.spcs.stanford.edu/
  "stanford-pre-collegiate-studies-stanford-pre-collegiate-summer-i": { blurb: "An online summer enrichment program from Stanford Pre-Collegiate Studies in which students in grades 8-11 take one single-subject course. Each session runs two weeks, Monday through Friday, with required live daily class meetings. Course subjects include bioscience, business, computer science, engineering, mathematics, philosophy and creative writing. Courses are ungraded and not for credit, and financial aid is available." },
  // https://fisher.wharton.upenn.edu/management-technology-summer-institute/
  "university-of-pennsylvania-jerome-fisher-program-management-and": { blurb: "A three-week, for-credit summer program at the University of Pennsylvania run by the Jerome Fisher Program in Management & Technology with Penn Engineering and Wharton. Rising high school seniors, plus a few rising juniors, take classes from Penn faculty, build a prototype and develop a go-to-market plan, earning one Penn credit unit. The program selects 75 participants, the on-campus program fee is $11,999, and need-based scholarships fund a select number of students." },
  // https://www.ctd.northwestern.edu/3-week-academic-summer-camps
  "northwestern-center-for-talent-development-three-week-academic-s": { blurb: "Three-week accelerated summer courses for students in grades 9-12 from Northwestern University's Center for Talent Development, offered as day or residential camps along with online options. Students choose enrichment, advanced enrichment or accelerated courses, and honors and AP courses can earn high school credit. Eligibility is based on above-grade-level SAT or ACT scores or an admission portfolio. Tuition ranges from $1,005 to $6,105, and financial aid is available." },
  // https://precollege.sps.columbia.edu/programs/summer-programs/online-summer
  "columbia-university-school-of-professional-studies-columbia-pre": { blurb: "Online summer courses for high school students from Columbia University's Pre-College Programs, offered in one-week and two-week formats. Students in the two-week program can take more than one course. The one-week program costs $2,868 and a two-week course costs $4,018, totals that include the program fee plus activities, health services and technology fees. Need-based aid worth 25% to 50% of the course cost is available for a single course." },
  // https://mity.org/summer-programs/expand-your-mind-eym/
  "minnesota-institute-for-talented-youth-expand-your-mind": { blurb: "A two-week summer program from the Minnesota Institute for Talented Youth on the Macalester College campus in St. Paul for rising 9th through 12th graders. Students take one class per session from nearly 30 offerings in areas such as the arts, sciences, math, law and entrepreneurship, with classes capped at 16 students. Students can commute or live on campus; 2026 rates were $875 per session for commuters and $2,200 for residents, and financial aid is available." },
  // https://education.ucdavis.edu/young-scholars-program
  "uc-davis-school-of-education-uc-davis-young-scholars-program": { blurb: "A six-week residential summer research program at UC Davis where about 40 high-achieving high school students work one-on-one with faculty in biological, agricultural, environmental and natural science labs. Each student completes an individual project, writes a journal-quality paper and presents at a symposium, earning five units of University Group Study Credit. Applicants must be rising juniors or seniors, and fee waivers support students who cannot afford the cost." },
  // https://www.txst.edu/mathworks/mathworks-camps/hsmc.html
  "texas-state-university-mathworks-honors-summer-math-camp-hsmc": { blurb: "A six-week residential math camp run by Mathworks at Texas State University in San Marcos where high school students study number theory and real analysis and conduct original research. Second- and third-year students work with research mentors on original projects. The camp selects about 40 students, and the 2027 session runs June 20 to July 31. The $6,600 cost covers room, board, books and supplies, and need-based scholarships are available." },
  // https://pty.vanderbilt.edu/for-students/vsa/
  "vanderbilt-programs-for-talented-youth-vanderbilt-summer-academy": { blurb: "A residential summer program at Vanderbilt University in Nashville run by Programs for Talented Youth for academically advanced students in grades 7-12. Students take one intensive course taught mostly by Vanderbilt content experts, with up to six hours a day of academic learning, and live in a first-year residence hall with trained staff. Sessions last one or two weeks in June and July depending on grade, and tuition covers meals and activities." },
  // https://goodwillnorthfl.org/mayors-youth-at-work-partnership-myawp/
  "goodwill-of-north-florida-and-city-of-jacksonville-kids-hope-all": { blurb: "A paid internship program in Jacksonville run by Goodwill of North Florida and funded through the City of Jacksonville's Kids Hope Alliance. Participants get paid internships and work-readiness training, with a job coach who handles placement and training, plus help opening a bank account and learning financial management. It is open to Duval County residents ages 16-21 who are enrolled in school and out-of-school youth ages 16-24, and internship slots are limited." },
  // https://college.mayo.edu/academics/health-sciences-education/pathways-into-healthcare-careers-program-florida/
  "mayo-clinic-school-of-health-sciences-pathways-into-healthcare-c": { blurb: "A free three-day program at Mayo Clinic in Jacksonville where rising high school juniors and seniors and undergraduates from the Duval County region explore more than 20 allied health careers. Students take part in hands-on simulation work and networking. The program runs in July for about 60 students, meals are provided, and students from public, private, charter or home-based schools who are U.S. citizens or permanent residents are eligible." },
  // https://realitychangers.org/collegetown/
  "reality-changers-college-town": { blurb: "A free after-school and summer college-readiness program from Reality Changers in San Diego for first-generation students in grades 8 through 11. Students meet at least once a week for dinner, homework help, tutoring and coaching on personal goals, with options such as a 3-week residential camp at UC San Diego, coding camp, ACT and SAT prep and career field trips. Applicants must attend school in San Diego County and be low-income or qualify for free or reduced lunch." },
  // https://www.sdmart.org/teens/
  "san-diego-museum-of-art-teen-council": { blurb: "A school-year teen council at the San Diego Museum of Art where high school students work with museum community engagement staff and peers to share ideas, develop programming and help create the museum's Young Art exhibition. Members also help select works for the exhibition and lead free community art workshops. The council meets monthly on Zoom with several in-person opportunities, the term runs from October through June, and space is limited to 12 teens." },
  // https://www.barrowneuro.org/for-physicians-researchers/research/training-programs/high-school-research-program/
  "barrow-neurological-institute-summer-high-school-internship-prog": { blurb: "A five-week summer internship at Barrow Neurological Institute in Phoenix for active high school students from any school in the country. Interns work part-time in a Barrow lab or support department under faculty or clinician mentorship, attend weekly seminars and finish with a symposium. The program runs in June and July, and applicants must be 16 or older at the start. Applying requires a recommendation letter, a one-page letter of intent and an online application." },
  // https://chs.asu.edu/future-students/summer-programs/summer-health-institute
  "arizona-state-university-college-of-health-solutions-burton-fami": { blurb: "A free one-week residential health careers program run by Arizona State University's College of Health Solutions and Creighton University on ASU's Downtown Phoenix campus for students finishing their junior year. Participants spend three hours a day in simulation at Creighton's medical school practicing suturing and IVs, meet members of the health care team and tour local facilities. Housing, food, materials and instruction are free, and participants cover their own travel." },
  // https://college.mayo.edu/academics/office-of-education-engagement-and-outreach/programs/mayo-clinic-cares/
  "mayo-clinic-office-of-education-engagement-and-outreach-mayo-cli": { blurb: "A free summer pathway program at Mayo Clinic in Phoenix that introduces Arizona high school students to health care careers and follows up with ongoing mentorship. Students attend six program days in June, with in-person and virtual options. Applicants must be current sophomores or juniors at an Arizona high school, and no prior clinical experience is needed. The program is competitive and hosted 40 students from 30 Phoenix-area schools in 2024." },
  // https://eller.arizona.edu/departments-research/schools-departments/accountancy/bcap
  "university-of-arizona-eller-college-of-management-and-ey-busines": { blurb: "A one-week residential summer program in Tucson run by EY and the University of Arizona's Eller College of Management Dhaliwal-Reidy School of Accountancy for current high school juniors. Participants live in campus housing, take courses in accounting, marketing, ethics and business communication, visit the EY Phoenix office and compete in a case study. The program is held in June, and all costs are covered by an EY scholarship." },
  // https://www.midwestern.edu/community-media/health-careers-institute-az
  "midwestern-university-health-careers-institute-for-high-school-s": { blurb: "A free five-day summer program at Midwestern University's Glendale, Arizona campus where high school juniors and seniors explore health professions. Students attend hands-on workshops across health fields led by Midwestern faculty and student mentors, from 8 a.m. to 4 p.m. each day in July. Admission is competitive, with 64 students selected from around Arizona, and rural students can receive scholarships covering hotel costs, meals and transportation." },
  // https://nasep.arizona.edu/about-nasep
  "university-of-arizona-office-of-early-academic-outreach-native-a": { blurb: "A free year-long program run by the University of Arizona's Office of Early Academic Outreach that helps Native American high school students prepare for college and STEM careers. It begins with a week-long summer stay on the Tucson campus with STEM workshops, followed by a fall research project, enrichment events during the school year and a closing banquet. Participants present research posters at the Arizona regional and state science fairs." },
  // https://access.asu.edu/summer-programs/access-leadership-institute
  "arizona-state-university-access-asu-leadership-institute": { blurb: "A residential summer leadership program on Arizona State University's Tempe campus for rising high school juniors and seniors who want to grow as leaders and make a difference in their communities. Students live in residence halls, eat in dining halls and take workshops such as public speaking and voting literacy while building leadership and professional skills. The only program cost is a $50 nonrefundable deposit due upon acceptance." },
  // https://www.hofstra.edu/academics/ce/summer-camp/specialty_pre_medical_careers_camp.html
  "hofstra-university-summer-camps-careers-in-healthcare-and-medici": { blurb: "A one-week, full-day summer camp at Hofstra University for students entering grades 9 through 12 who are interested in healthcare careers, also listed as MedPathways. The curriculum covers pre-medical advising, audiology, physician assistant studies, nursing, cardiovascular and perfusion science, physical therapy and exercise science, plus college and career counseling workshops. Regular tuition is $780 per week, and transportation costs an extra fee." },
  // https://www.wbw.org/our-programs/summer/
  "foundation-for-private-enterprise-education-washington-business": { blurb: "A one-week summer business camp for high school students, held mostly on college campuses in Washington State. Students form a company in teams of 8 to 12, take executive roles such as CEO, CFO and CMO, work with a business professional mentor and pitch ideas to investors. Overnight and day programs are offered, students can earn two college credits from Renton Technical College, and fees range from $600 to $1,350, with most students receiving scholarships." },
  // https://bovardscholars.usc.edu/
  "university-of-southern-california-usc-bovard-scholars": { blurb: "A free college access program at the University of Southern California for high-achieving rising high school seniors with financial need. Scholars attend a three-week summer intensive on USC's University Park Campus, then receive one-on-one support through senior year from a personal Admissions Coach. The program covers career exploration, admission and financial aid guidance, test prep and leadership, and serves up to 100 students each year." },
  // https://cse.umn.edu/mathcep/ima-mathcep-math-modeling-camp
  "university-of-minnesota-mathcep-ima-mathcep-math-modeling-camp": { blurb: "A non-residential summer math modeling camp on the University of Minnesota's Minneapolis campus, run by the Institute for Mathematics and its Applications with MathCEP. Under the supervision of educators and University faculty, students work in teams on open-ended modeling problems, develop practical solutions and present results to their peers. Applicants must have completed a year-long single-variable calculus course, and graduating seniors are eligible." },
  // https://mathroots.mit.edu/
  "mit-primes-mathroots": { blurb: "A free two-week residential summer program at MIT, run by MIT PRIMES jointly with MIT Admissions, that serves as a mathematical talent accelerator for high-potential high school students. Through classes, group work and invited lectures, students explore creative problem solving, proof techniques and ideas beyond the standard curriculum. It is open to U.S. citizens or students attending high school in the U.S., and students pay for their own transportation." },
  // https://www.arteffectlmc.org/competition/overview
  "lowell-milken-center-for-unsung-heroes-arteffect-student-art-com": { blurb: "A free annual art competition for students in grades 6 to 12, who create an original visual artwork about an approved Unsung Hero from history along with a 500 to 1,000 word Impact Statement. Eligible work includes 2D and 3D media such as digital art, drawings, paintings, prints, sculpture and textiles. A jury of experts in art education, art history, design, fine arts and museums judges entries, and awards total over $35,000 each year." },
  // https://www.sju.edu/departments/dss/analyticscompetition
  "saint-josephs-university-high-school-analytics-and-data-visualiz": { blurb: "A team competition run by the Department of Decision and System Sciences in Saint Joseph's University's Haub School of Business, in which high school students explore a dataset, build visualizations and present to judges from academia and industry. Teams of 3 to 5 students from the same high school, each with a faculty or staff advisor, compete over multiple rounds ending in a one-day final event on campus. No specific coursework or skill set is required." },
  // https://www.sar.org/joseph-s-rumbaugh-historical-oration-contest/
  "national-society-sons-of-the-american-revolution-joseph-s-rumbau": { blurb: "A public speaking contest run by the National Society Sons of the American Revolution for students in grades 9 through 12 from public, parochial, private or home schools. Students deliver a memorized five- to six-minute oration, without notes or props, on an event, person or document from the Revolutionary War and connect it to present-day America. Contests start at local chapters and advance through state rounds to a national final with prizes of $8,000, $5,000 and $3,000." },
  // https://cba.k-state.edu/academics/departments/finance/hs-investment-management.html
  "kansas-state-university-college-of-business-ksu-high-school-inve": { blurb: "A virtual portfolio competition run by the Department of Finance in Kansas State University's College of Business, in which high school teams of up to five invest $1,000,000 using real market data on StockTrak from February to May. Judging considers total returns, risk-adjusted returns and the quality of each team's strategy documentation and presentation. Scholarship prizes are $1,000 per team member for first place, $750 for second and $500 for third." },
  // https://news.siu.edu/2026/01/011326-hundreds-of-visiting-students-to-compete-at-sius-accounting-challenge.php
  "southern-illinois-university-school-of-accountancy-annual-accoun": { blurb: "A free annual on-campus competition hosted by Southern Illinois University's School of Accountancy in Carbondale for high school and community college students. Students answer 50 multiple choice and true-false questions on accounting fundamentals in two divisions, then compete in four-person team challenges. Top individual scorers can earn scholarships worth up to $500 if they attend SIU and major in accounting, and winning teams and their schools receive trophies." },
  // https://www.ithaca.edu/academics/school-business/high-school-investment-competition
  "ithaca-college-school-of-business-high-school-investment-competi": { blurb: "A virtual investing competition run by the Ithaca College School of Business for teams of three to six students in grades 9 to 12 with a faculty advisor. Each team manages $1,000,000 in virtual money from November to April, trading NYSE and NASDAQ stocks priced above $5 per share, with no short selling and a limit of 1,000 trades. Prizes of $3,000, $2,000 and $1,000 for the top three teams are split between the students and their high school." },
  // https://www.stevens.edu/school-business-high-school-programs-trading-day
  "stevens-institute-of-technology-school-of-business-stevens-tradi": { blurb: "A trading competition for high school sophomores and juniors run by the Stevens Institute of Technology School of Business. It pairs a month-long virtual investing contest in February on the StockTrak simulator with live on-campus finals in April, where top finishers trade in the Hanlon Financial Systems Center in Hoboken. The fee is $25 per student, finalists pay their own travel costs, and all participants receive a certificate." },
  // https://jasna.org/about/jasna-post/2026-essay-contest-open/
  "jane-austen-society-of-north-america-jasna-essay-contest": { blurb: "An annual essay contest run by the Jane Austen Society of North America that includes a high school division, in which students write about Jane Austen and her work. First-, second- and third-place winners in each division receive cash scholarships of $1,000, $500 and $250, and first-place winners are also offered complimentary registration and two nights' lodging at the society's Annual General Meeting." },
  // https://www.stockmarketgame.org/capitol-hill-challenge.html
  "sifma-foundation-capitol-hill-challenge": { blurb: "A free, invitation-only national investing competition run by the SIFMA Foundation through The Stock Market Game that pairs Members of Congress with public schools in their districts, with priority for schools with the highest need. Up to two middle or high schools per district can each enter up to 15 teams of 3 to 5 students, who manage a hypothetical $100,000 online portfolio of stocks, bonds, mutual funds and cash from January to April." },
  // https://jausa.ja.org/events/opportunity/national-ja-stock-market-challenge
  "junior-achievement-usa-national-ja-stock-market-challenge": { blurb: "A national stock market competition for top high school teams from Junior Achievement areas, who qualify by completing a JA investing program and a local competition. Teams of two to four students start with $1,000,000 and trade through floor traders in a fast-paced simulation of 90 trading days in 90 minutes, and the team with the highest net worth wins. The 2026 national event was held in June at Boston University." },
  // https://jindal.utdallas.edu/top-trader-2/
  "ut-dallas-naveen-jindal-school-of-management-top-trader-stock-ma": { blurb: "An online summer stock trading competition for high school students run by the Naveen Jindal School of Management at UT Dallas. Each participant receives a virtual $1,000,000 and tries to grow the portfolio's value from June through July. Entrants must be legal residents or citizens with a valid Social Security number, registration costs $50, and prizes range from $1,200 for first place to $600 for seventh place." },
  // https://www.nei.nih.gov/about/education-and-outreach/eye-future-teen-video-contest/how-enter
  "national-eye-institute-nih-eye-on-the-future-teen-video-contest": { blurb: "A video contest from the National Eye Institute (NIH) in which U.S. high school students in grades 9-12 make a 30-second to three-minute video about eye health and vision science. Students can enter alone or in a group of up to three, upload the video to YouTube as unlisted and email the link with a signed registration form. Non-citizens can join a team, but only U.S. citizens or permanent residents can win prize money." },
  // https://www.stmarys-ca.edu/academics/schools/kalmanovitz-school-of-education/centers-institutes/center-environmental-literacy/river-of-words
  "saint-marys-college-of-california-river-of-words-poetry-and-art": { blurb: "A free annual poetry and art contest on nature and place, hosted by the Center for Environmental Literacy at Saint Mary's College of California, for students ages 5 to 19. Each participant may submit up to 5 poems and 5 art pieces, with poems capped at 32 lines in English or Spanish. Entries are judged in four grade-based categories, and winners and finalists are published in an annual anthology." },
  // https://www.theblank.com/ypfsubmissions
  "the-blank-theatre-young-playwrights-festival": { blurb: "A national playwriting competition run by The Blank Theatre in Hollywood for writers 19 or younger who live or attend school in the U.S. Writers or co-writing teams may submit up to three plays online or by mail with no submission fee, and the festival bars any use of AI in writing the script. Winning plays are professionally produced with public performances in July." },
  // https://legaljournal.princeton.edu/high-school-essay-contest/
  "princeton-legal-journal-high-school-essay-contest": { blurb: "An annual legal essay contest run by the Princeton Legal Journal, a Princeton undergraduate publication, for current high school students. Each year has a new theme on the U.S. Constitution (in 2026, religious liberty), and essays run 1,500 to 3,000 words excluding footnotes. There is a $15 submission fee, and the top three essays are published by the journal." },
  // https://vpse.upenn.edu/smp/apply/
  "university-of-pennsylvania-provosts-summer-mentorship-program-sm": { blurb: "A four-week summer college and career preparatory program at the University of Pennsylvania for Philadelphia high school students in 9th or 10th grade with at least a 3.0 GPA. Students are placed in one of five Penn schools, such as Medicine, Nursing, Engineering, Law or Dental Medicine, and get mentoring plus sessions on financial literacy, study skills, SAT preparation and personal statements. The program runs in July." },
  // https://sifmafoundation.org/investwrite/competition
  "sifma-foundation-investwrite-essay-competition": { blurb: "A national essay competition from the SIFMA Foundation for students in grades 4-12 whose classes play The Stock Market Game. Students answer an investing prompt, with high school essays running 500 to 1000 words, and teachers who are registered advisors submit entries in fall and spring sessions. Judges score essays on rationale, understanding of the subject and writing style, and entry is free." },
  // https://www.newyorkfed.org/outreach-and-education/high-school/high-school-fed-challenge
  "federal-reserve-bank-of-new-york-high-school-fed-challenge": { blurb: "A national research and writing competition from the Federal Reserve, hosted by the New York Fed, in which teams of students in grades 9-12 write economics podcast scripts of 1,500 to 2,500 words. The 2026-2027 theme is the economics of housing, each school may enter one team, and students need no prior economics coursework. Federal Reserve reviewers select papers to publish in the Journal of Future Economists." },
  // https://www.worldof8billion.org/video-contest/rules-and-guidelines/
  "population-connection-world-of-8-billion-student-video-contest": { blurb: "A free short video contest from Population Connection for students in grades 6 to 12, who make a video of up to 60 seconds showing how population growth affects a topic and suggesting a sustainable solution. The 2026-2027 topics are city planning, fresh water use and extreme weather. Students may work alone or in groups, and in the high school division first place for each topic wins $1,200." },
  // https://www.projectparadigm.org/rules
  "project-paradigm-the-paradigm-challenge": { blurb: "A youth innovation contest from Project Paradigm, a Los Angeles-based sponsor, for students ages 4 to 18, with a 14-18 division, in which teams design solutions to real-world problems. Each age division awards $10,000 for first place, $2,000 for second and $1,000 for third, and one first-place team is named Grand Prize winner and splits $100,000. The top 100 entries receive cash, and new challenge projects come out every two years." },
  // https://activities.tjhsst.edu/tjioi/
  "thomas-jefferson-high-school-for-science-and-technology-tj-invit": { blurb: "A competitive programming contest run by the Computer Team at Thomas Jefferson High School for Science and Technology in Northern Virginia. Teams of up to three students solve problems ranging from USACO Bronze to USACO Platinum level, using only the contest grader and a development environment. The contest takes place in May, both in person and online, and past problem sets are posted on the contest site." },
  // https://www.shu.edu/undergraduate-admissions/pirates-pitch-competition.html
  "seton-hall-university-pirates-pitch-competition-for-high-school": { blurb: "A Shark Tank-style pitch competition run by Seton Hall University's Stillman School of Business for high school sophomores, juniors and seniors with a GPA of 3.0 or higher. Students submit a business proposal of 350 words or less or a three-minute video pitch. The top 10 finalists give five-minute pitches to judges on the South Orange, N.J. campus in November and compete for $50,000 in cash prizes and scholarships." },
  // https://programs.thecrimson.com/harvard-crimson-business-comp
  "the-harvard-crimson-harvard-crimson-business-competition": { blurb: "A business case competition run by The Harvard Crimson for students in grades 6-12, who compete individually or in teams of up to 4. There is a $50 registration fee per preliminary submission. Students who qualify for the Global Championship Round pay a non-refundable $300 per-person fee and must attend in person at Harvard." },
  // https://lassonde.utah.edu/hsuec/
  "university-of-utah-lassonde-entrepreneur-institute-tim-draper-hi": { blurb: "A statewide business idea competition for Utah students ages 14-18, managed by the Lassonde Entrepreneur Institute at the University of Utah and sponsored by Tim Draper. Students who have graduated high school or are enrolled full-time in college courses cannot take part. After judging, the top 20 teams advance to a final round in March, and the competition offers $30,000 in cash and scholarships." },
  // https://bigideasd.com/competition/
  "big-idea-south-dakota-big-idea-competition": { blurb: "A business idea competition for high school students in South Dakota, North Dakota and Minnesota that aims to promote entrepreneurship and encourage students to start a business. Students enter individually or in teams of up to three with a written plan of up to 1,075 words covering the concept, market, competition and operations, plus an optional marketing design. Prizes include cash and scholarships, and the final competition is held in December." },
  // https://jacobsoninstitute.org/innovatorcompetition
  "university-of-iowa-jacobson-institute-innovator-competition": { blurb: "A free online pitch competition from the Jacobson Institute at the University of Iowa, held each fall and spring for high school students in grades 9-12 who are U.S. citizens or live in the U.S. or its territories. Students pitch an idea, product or business, and no business coursework is required. Winners share $3,000 in seed capital, with $1,500 for first place, $1,000 for second and $500 for third." },
  // https://www.stjohns.edu/academics/schools/peter-j-tobin-college-business/tobins-experiential-opportunities/high-school-pitch-competition-2026
  "st-johns-university-tobin-college-of-business-high-school-pitch": { blurb: "A Shark Tank-style pitch competition run by the Tobin College of Business at St. John's University, where high school students present business ideas alone or in teams of up to three. Each team is paired with a St. John's business student mentor. Teams give a 3-minute expo-style pitch, the top 5 then pitch to expert judges with Q&A, and the 2026 event in March awarded $2,500, $1,500 and $1,000 to the top three." },
  // https://www.uvm.edu/admissions/vermont-pitch-challenge
  "university-of-vermont-vermont-pitch-challenge": { blurb: "A business pitch competition run by the University of Vermont for high school students in grades 10-12 worldwide, who submit business proposals online at no cost. Finalists pitch at a final event in April. The grand prize is a full scholarship to UVM for each team member, contingent on admission, while second and third place receive $5,000 and fourth and fifth place receive $1,000." },
  // https://www.aretelabs.com/math-madness
  "aretelabs-math-madness": { blurb: "A team-based online math competition from AreteLabs, run jointly with the American Mathematics Competitions, with a high school tier for grades 9-12 aligned primarily to AMC 10/12. Teams of at least 5 students from the same school play 30-minute matches through a practice round, 4 league rounds and 6 bracket rounds. A teacher registers the team, and fees run from $165 for 5-10 players to $375 for unlimited players." },
  // https://www.asan.com/annual-math-contest
  "american-scholastic-mathematics-association-american-scholastic": { blurb: "A school-based math contest from the American Scholastic Mathematics Association, with a senior division for grades 9-12 and a junior/intermediate division for grades 7-9. Schools receive sealed question sets, and each team takes a seven-question test in 35 minutes on six dates from November through April, with awards mailed in May. The entry fee is $100 per division or $200 for both." },
  // https://www.legion.org/get-involved/scholarships/the-american-legion-legacy-scholarship
  "the-american-legion-american-legion-legacy-scholarship": { blurb: "A needs-based scholarship from The American Legion for children of service members who died on active duty on or after Sept. 11, 2001, or of post-9/11 veterans with a combined VA disability rating of 50% or higher. It covers the gap left after other grants and pays up to $20,000 for children of the fallen or up to $5,000 for children of disabled veterans, renewable up to six times. It funds undergraduate, graduate or trade school study." },
  // https://pridefoundation.org/find-funding/scholarships/
  "pride-foundation-pride-foundation-scholarship": { blurb: "A college scholarship program from Pride Foundation for LGBTQ+ student leaders who live in Alaska, Idaho, Montana, Oregon or Washington, though they may study elsewhere. One application considers students for more than 60 funds, covering community college, trade programs, four-year college and graduate school, regardless of school, major or GPA. In 2026 the foundation awarded $1,032,500 to 121 students." },
  // https://www.createrealimpact.com/
  "impact-teen-drivers-create-real-impact-contest": { blurb: "A free creative contest from the nonprofit Impact Teen Drivers that asks full-time students ages 14-22 to share positive solutions for reducing crashes caused by reckless and distracted driving. Entries focus on solutions rather than scare tactics and can address distractions beyond phones, such as eating or adjusting music. A high school campaign category has schools create a 30-second PSA video, graphics and social media posts." },
  // https://www.rocketrychallenge.org/
  "aerospace-industries-association-and-national-association-of-roc": { blurb: "A national student rocketry contest in which teams of three to ten students design, build and fly an original model rocket carrying a raw egg to a set altitude and flight time, then return it safely. The rocket must be entirely the students' own work, with no adult help. The top 100 teams advance to the National Finals in Virginia each May, where students compete for more than $100,000 in awards." },
  // https://cmimc.math.cmu.edu/
  "carnegie-mellon-university-carnegie-mellon-informatics-and-mathe": { blurb: "A student-run math and computer science competition at Carnegie Mellon University for high school students. Teams of up to 6 compete in individual and team rounds on a Saturday each spring on campus, with optional mini-events on Friday night, and students without a full team can ask to be merged with others. A separate programming contest for teams of up to 3 takes place in late April." },
  // https://lemelson.mit.edu/inventeams
  "massachusetts-institute-of-technology-lemelson-mit-inventeams": { blurb: "A year-long invention grant from the Lemelson-MIT Program for teams of high school students, teachers and community mentors. Each selected InvenTeam receives $7,500 and year-long support to build a technological invention that solves a problem the students choose from their own community. A STEM educator at a high school or nonprofit educational organization applies on the team's behalf." },
  // https://med.uth.edu/bmb/high-school-summer-research-program/summer-research-program-application/
  "uthealth-houston-mcgovern-medical-school-high-school-summer-rese": { blurb: "A four-week summer research program in the Department of Biochemistry and Molecular Biology at McGovern Medical School in Houston for rising juniors and seniors interested in biomedical science or medicine. Students do bench research with faculty and student mentors, attend seminars and get career advice in June and July. Applicants must be at least 16, and the $4,000 fee covers registration and lab coats; housing and parking are not provided." },
  // https://www.uaf.edu/rahi/
  "university-of-alaska-fairbanks-rural-alaska-honors-institute-rah": { blurb: "A free six-week residential college program at the University of Alaska Fairbanks for Alaska Native and rural Alaska students who have finished their junior or senior year with at least a 3.0 GPA. Students live on campus, earn up to 10 college credits, volunteer in Fairbanks and explore interior Alaska. Room, board and travel to Fairbanks are covered, and the program has run since 1983." },
  // https://wvde.us/academics/middle-secondary-education/student-events-programs-initiatives/governors-schools/governors-honors-academy
  "west-virginia-department-of-education-governors-honors-academy": { blurb: "A three-week residential summer program from the West Virginia Department of Education for state high school students who will be seniors the next year. About 175 students are selected each year, and state funds cover tuition, room, board and instructional materials. The 2026 session ran in July at West Virginia University, and applicants need at least a 3.5 GPA or a place in the top 10% of their class." },
  // https://summer.virginia.edu/uva-advance
  "university-of-virginia-uva-advance": { blurb: "A four-week residential summer program at the University of Virginia where rising high school juniors and seniors take small, intensive classes taught by UVA faculty and earn six transferable undergraduate credits. All students live together in one residence hall, and the session runs from July into August. Applicants need a GPA of at least 3.5 in a college prep curriculum and must be ages 15 to 18 during the program." },
  // https://geog.umd.edu/high-school-hub/high-school-internship-program-hip
  "university-of-maryland-high-school-internship-program-in-geograp": { blurb: "A paid six-week summer internship run remotely by the University of Maryland Department of Geographical Sciences for high school juniors and seniors from the DC, Maryland and Virginia region. Each intern is paired with a faculty mentor, works 10 hours per week on a research project in areas such as climate change or geospatial analysis, presents a poster, and receives a $900 stipend. Interns must be authorized to work in the U.S." },
  // https://medicine.illinois.edu/diversity/pathway-programs-and-partnerships/spheres-high-school-research-program
  "carle-illinois-college-of-medicine-spheres-high-school-research": { blurb: "A paid summer research program at the Carle Illinois College of Medicine for high school students curious about science and health careers. Scholars join a faculty member and mentors on a research project in labs across the University of Illinois Urbana-Champaign campus, prepare for a medical career, and present at a final symposium in late July. The program pays a $2,400 stipend and is co-hosted by the Department of Bioengineering." },
  // https://www.outreach.olemiss.edu/pre-college/summer-college/arise@um.html
  "university-of-mississippi-arise-research-program": { blurb: "A summer STEM research program at the University of Mississippi for high school students entering junior or senior year. Students name the STEM field they want to explore and are placed in a faculty research lab or field project for the summer, with workshops and lectures alongside the research. Some students receive full or partial funding, and recent graduates at community colleges apply through a separate track." },
  // https://apply.nmt.edu/portal/summer_stem
  "new-mexico-institute-of-mining-and-technology-summer-stem-experi": { blurb: "A one-week residential summer program at New Mexico Tech in Socorro for students entering sophomore, junior or senior year of high school. Students live on campus and take classes, with sessions offered in June and July. The $675 per-session price covers food, housing, classes and activities, and applicants need at least a 2.75 cumulative GPA and completed Algebra 1." },
  // https://belinblank.education.uiowa.edu/students/swo/
  "belin-blank-center-university-of-iowa-summer-writing-online": { blurb: "A three-week online creative writing program from the University of Iowa's Belin-Blank Center for high school students in grades 9 to 11. Classes are fully live, with 3.5 hours of interactive class time each day in July, covering fiction, poetry and screenwriting with faculty from the Iowa Writers' Workshop plus author talks. The cost is $295, with financial aid and payment plans for families who qualify." },
  // https://www.bethelks.edu/summer-camps/
  "bethel-college-summer-science-institute": { blurb: "A donor-subsidized summer research institute at Bethel College in North Newton, Kansas, for high school students who have completed grades 10 to 12. Held on campus in the first week of June, it offers in-person and online options with several research groups, in past years covering topics such as astronomy, robotics, chemistry and molecular genetics. Students present their findings at the end, and financial aid is available." },
  // https://www.creighton.edu/healthsciences/diversity/research/summer-research-institute
  "creighton-university-health-sciences-multicultural-and-community": { blurb: "A summer research institute from Creighton University Health Sciences that introduces students to health-sciences research. In its six-week high school community-based track, sophomores through seniors are trained in health disparities and carry out research projects at a community organization in Omaha from June into July, earning a $1,200 stipend. Applicants need at least a 2.5 GPA, and on-campus housing is offered." },
  // https://precollege.nd.edu/leadership-seminars/
  "university-of-notre-dame-leadership-seminars": { blurb: "A 10-day summer program on the University of Notre Dame campus for about 150 rising seniors who show leadership in their communities, with sessions in June and July. The university pays tuition, housing and meals, and students can earn one transferable college credit. Applicants must be at least 16 and are generally in the top 10% of their class; families cover travel plus a $75 application fee and a $150 enrollment fee." },
  // https://new.sewanee.edu/sywc/
  "university-of-the-south-sewanee-young-writers-conference": { blurb: "A two-week summer creative writing conference at the University of the South in Sewanee, Tennessee, for high school writers. Students join small workshops in poetry, fiction, playwriting or creative nonfiction. Applicants are in 9th, 10th or 11th grade when they apply and under 18 during the conference, and they live in Humphreys Hall with college-student counselors. Financial aid is available." },
  // https://precollege.brown.edu/programs/bell-program/alaska
  "brown-university-brown-environmental-leadership-lab-alaska": { blurb: "A 12-day off-campus summer program from Brown Pre-College, based in Anchorage, for students finishing grades 10 to 12 who are 16 to 18. Students study environmental science, ecology and leadership, including how climate change affects Alaska Native culture and the land, and each builds an Action Plan for a local issue back home. Students live in University of Alaska Anchorage residence halls in July, and food, housing and site fees are included." },
  // https://meded.georgetown.edu/diversityequityandinclusion/high-school-summer-internships/gep/
  "georgetown-university-school-of-medicine-high-school-summer-inte": { blurb: "Georgetown University School of Medicine runs summer internships for local high school students, led by the six-week Gateway Exploration Program for rising sophomores, juniors and seniors interested in medicine or health careers. Interns are matched to medical departments, where they shadow and work with mentors. Students apply through their school system, which has included D.C. public schools and Prince William County schools, and interview virtually." },
  // https://www.childrensnational.org/about-us/health-equity/investing-in-the-future-of-healthcare/research-opportunities
  "childrens-national-hospital-meteor-research-program": { blurb: "A seven-week summer research internship at Children's National Hospital in Washington, D.C., for high school students from the D.C. area, who take part alongside STEM teachers-in-training from George Washington University. Interns learn the basics of neuroscience and research through lectures and a mentored placement in a clinical or translational research lab, then present their projects at the end. A stipend helps with travel costs." },
  // https://www.colorado.edu/sciencediscovery/biomedical-research-bootcamp-grades-10-12
  "cu-science-discovery-university-of-colorado-boulder-biomedical-r": { blurb: "A two-week, non-credit summer class from CU Science Discovery for students entering grades 10 to 12, held at the CU Anschutz Medical Campus in Denver. Students learn basic lab methods, tour research facilities, study research ethics and careers, and write their own research proposal. The class runs 9am to 4pm and is taught by CU faculty and scientists. Scholarship support is available for families who need it." },
  // https://omrf.org/training-outreach/summer-scholars/
  "oklahoma-medical-research-foundation-fleming-scholars-program": { blurb: "A paid eight-week summer research internship at the Oklahoma Medical Research Foundation in Oklahoma City, founded in 1956. High school seniors and college students who are Oklahoma residents and at least 16 work in OMRF labs in June and July for $15.50 per hour. Scholars living more than 40 miles away get housing on the Oklahoma City University campus, and breakfast is provided on workdays." },
  // https://www.okcollegestart.org/High_School_Planning/Summer_Academies/_default.aspx
  "oklahoma-state-regents-for-higher-education-stem-summer-academie": { blurb: "Free STEM summer academies sponsored by the Oklahoma State Regents for Higher Education and hosted at colleges and universities across Oklahoma. Students live on campus or commute while studying topics such as drones, robotics, renewable energy, engineering, water quality, nanotechnology and cryptography. Grade ranges vary by academy, from rising 8th graders to seniors, and students apply through each host school." },
  // https://medicine.ouhsc.edu/about/office-of-access-and-community-engagement/high-school-students/spark-summer-program
  "university-of-oklahoma-college-of-medicine-spark-summer-program": { blurb: "A free, in-person summer workshop at the OU College of Medicine on the OU Health campus in Oklahoma City for students enrolled in or recently graduated from an Oklahoma high school. Students take part in hands-on medical activities and talk with faculty from different specialties and with medical students. Priority goes to upperclassmen and graduating seniors, and no transportation or housing help is offered." },
  // https://www.ouhealth.com/stephenson-cancer-center/cancer-research/cancer-research-professional-education-training/high-school-undergraduate-programs/
  "ou-health-stephenson-cancer-center-high-school-cancer-research-p": { blurb: "Summer cancer research programs for Oklahoma high school students at OU Health Stephenson Cancer Center in Oklahoma City. BRIDGE is an eight-week summer program for rising juniors and seniors, and YES Oklahoma places up to 12 Native American rising juniors and seniors in an intensive lab internship that can earn college credit. CURE Jr. is a one-day event where 30+ students explore cancer research careers." },
  // https://centers.louisville.edu/brown-cancer-center/prospective-students/summer-research-program
  "university-of-louisville-brown-cancer-center-high-school-summer": { blurb: "A paid summer cancer research program at the University of Louisville's Brown Cancer Center for high school students in the Louisville and Jefferson County area. Students spend about two weeks on wet-lab work, including a drug discovery project, then seven weeks in a mentored lab for at least 30 hours a week, and present at a poster showcase. Applicants must be 16 and have taken an advanced science course. The stipend is $3,500." },
  // https://lipscomb.edu/academics/programs/summer-scholars
  "lipscomb-university-summer-scholars-at-lipscomb-university": { blurb: "An 8-day, in-person summer program at Lipscomb University in Nashville for high-achieving rising seniors. Students who complete it earn three hours of transferable college credit. Applicants are current juniors with at least a 3.0 GPA and a qualifying ACT, SAT or CLT score, or a 3.5 GPA if applying test-optional. The program runs in July and costs $1,300." },
  // https://www.wvutech.edu/camps/stem
  "wvu-tech-camp-stem": { blurb: "A week-long residential STEM camp for high school students on the WVU Tech campus in Beckley, West Virginia. Students take STEM classes, work on special projects and go on field trips, taught by instructors from engineering, mathematics, the basic sciences and forensic investigation. They live in a residence hall with WVU Tech student counselors. The $500 fee covers meals, housing and field trips, and scholarships are available." },
  // https://precollege-summer.uconn.edu/
  "university-of-connecticut-uconn-pre-college-summer": { blurb: "A residential summer program at the University of Connecticut for rising sophomores, juniors and seniors ages 14 to 17. Students take one-week, non-credit courses on the Storrs campus, with some courses at regional campuses and a two-week credit course, in subjects from nursing and accounting to marine biology and 3D modeling. All students live on campus. One Storrs course costs $2,250." },
  // https://goews.georgia.gov/governors-honors-program
  "georgia-governors-office-of-education-and-workforce-strategy-gov": { blurb: "A four-week residential summer program run by the state of Georgia for gifted sophomores and juniors from public, independent, charter and home schools. Students are nominated in one academic or arts subject, such as engineering, mathematics, music or visual arts, and spend four hours a day in that major plus an afternoon elective, without grades. The state covers tuition, fees and boarding." },
  // https://stem.idaho.gov/idsef/
  "idaho-stem-action-center-idaho-science-and-engineering-fairs-ids": { blurb: "Idaho's science and engineering fair program for students in grades 9 to 12, run by the Idaho STEM Action Center and affiliated with the Regeneron International Science and Engineering Fair. Students do original research, alone or in teams of up to 3, and present it to judges at the Northern, Western or Eastern Idaho regional fair. Regional winners earn an all-expense trip to the international fair." },
  // https://newmanu.edu/academics/scholars-programs/investigative-summer-science-program
  "newman-university-investigative-summer-stem-program-issp": { blurb: "A residential summer STEM camp at Newman University in Wichita for high school sophomores, juniors and seniors with at least a 3.0 GPA and one science course. Students work in small groups on projects in biology, chemistry, computer science, mathematics and agricultural technology, then present to faculty. The week in June earns two hours of college credit and costs $425 with early registration or $450 after." },
  // https://biology.indiana.edu/about/outreach/k-12-students/holland-summer-science-programs/holland-sep.html
  "indiana-university-bloomington-jim-holland-summer-enrichment-pro": { blurb: "A summer biology program at Indiana University Bloomington for students in grades 8 to 10 with at least a 3.0 GPA. Through lectures, discussions and lab work, students explore genetics, evolution, environmental and molecular biology and plant sciences with IU faculty and Indiana high school teachers. The program runs for a week in July on the Bloomington campus, and accepted students pay a $125 registration fee." },
  // https://mmia.medicine.iu.edu/
  "indiana-university-school-of-medicine-molecular-medicine-in-acti": { blurb: "A free two-day program at the Indiana University School of Medicine in Indianapolis, run with the Herman B Wells Center for Pediatric Research and the Riley Children's Foundation. Indiana high school students in grades 10 to 12 work in IU labs on topics such as cancer, diabetes, immunology and cytogenetics and meet scientists and clinicians. Students need a teacher nomination and must attend both days." },
  // https://www.fscj.edu/academics/workforce-education/grant-programs/stepping-stones
  "florida-state-college-at-jacksonville-stepping-stones-program": { blurb: "A career training program at Florida State College at Jacksonville for seniors from low-income, high-needs schools in the Jacksonville area who are unsure of their next step. Selected students spend the summer after graduation in one of six credential tracks, earning an industry certification through tuition-free accelerated training. Students receive a stipend and free transportation." },
  // https://annieruthfoundation.org/programs/summer-internship/
  "annieruth-foundation-annieruth-foundation-summer-internship-prog": { blurb: "A paid summer internship program from the AnnieRuth Foundation for high school juniors and seniors in Duval County and nearby counties in Florida. Students first complete 40 hours of classroom instruction, a 1,000-word career essay, a community service project and an interview with HR professionals, then work part-time in professional settings that match their career goals. Students keep at least a 2.0 GPA." },
  // https://www.jsu.edu/gasp/
  "jacksonville-state-university-gamecock-arts-and-sciences-program": { blurb: "A series of one-week summer camps run by Jacksonville State University's College of Arts, Humanities, and Sciences that give community members a taste of college-level art and performance activities. Sessions cover creative writing, choral for musical theatre, visual art, game development and film, taught by faculty, staff, students and community partners. Each camp costs $150, most are for ages 11 to 18, and registration closes when a camp is full." },
  // https://www.massgeneral.org/neurology/education-and-training/youth-research-and-education
  "massachusetts-general-hospital-mgh-youth-neurology-education-and": { blurb: "A paid summer internship at Massachusetts General Hospital, funded by the Biogen Foundation, where Massachusetts high school and undergraduate students do mentored neurology research in MGH labs. Interns work 40 hours a week and join a weekly speaker series with longitudinal career support. The high school cohort is for rising seniors and recent graduates, with a focus on students from underrepresented backgrounds who live in Massachusetts." },
  // https://www.sdstate.edu/natural-resource-management/natural-resources-high-school-camp
  "south-dakota-state-university-natural-resources-high-school-camp": { blurb: "A residential camp at South Dakota State University's Oak Lake Field Station for students entering grades nine through 12, run by the Department of Natural Resource Management. Campers try bird identification, lake ecology, camera trapping, radio telemetry and small mammal and reptile trapping with faculty, graduate students and agency biologists. The $300 fee covers meals, housing and a hat, and space is limited to 20 male and 20 female participants." },
  // https://www.sdstate.edu/mathematics-statistics/sdsu-data-science-camp
  "south-dakota-state-university-sdsu-data-science-camp": { blurb: "A free four-day summer camp in the Department of Mathematics and Statistics at South Dakota State University for up to 20 students in ninth through twelfth grade. Campers learn basic statistics and R programming, use AI tools to build simple browser games, and complete a data science project they present to families on the last day. Food and lodging in campus residence halls are covered, and the camp is held in late July." },
  // https://www.usd.edu/Academics/Colleges-and-Schools/sanford-school-of-medicine/Office-of-Medical-Education/Healthcare-Summer-Careers-Camp
  "university-of-south-dakota-sanford-school-of-medicine-healthcare": { blurb: "A summer camp at the University of South Dakota Sanford School of Medicine in Vermillion for students who will be high school juniors or seniors in the fall. Campers meet health care professionals, get hands-on experience with medical demonstrations, tour nearby medical facilities and stay on campus. Tuition is $100 per student, limited need-based financial aid is available, and only 40 applications are accepted each year." },
  // https://research.rice.edu/rstem/architecture-immersion
  "rice-university-school-of-architecture-rice-architecture-summer": { blurb: "A tuition-free residential architecture workshop at Rice University for Houston-area 10th and 11th graders who are at least sixteen, run with the Rice Center for STEM Engagement. Students try model making, freehand drawing and other creative production, and get guidance on applying to architecture school and building a portfolio. The twelve-day June program includes room and board, with preference for students from Title I high schools." },
  // https://rockford.medicine.uic.edu/education/high-school-college-programs/biomedical-sciences-summer-programs/
  "university-of-illinois-college-of-medicine-rockford-summer-progr": { blurb: "Free summer programs run by the Department of Biomedical Sciences at the University of Illinois College of Medicine Rockford for students at Rockford-area high schools. Options include a one-week STEM day camp for students who are 16 and a paid two-month research internship with a stipend sponsored by Thermo Fisher Scientific. The internship takes seven students each summer, and applicants write a 500-word essay." },
  // https://cemast.illinoisstate.edu/students/high-school/il-summer-research/
  "illinois-state-university-illinois-state-university-research-exp": { blurb: "A two-week summer research program at Illinois State University, run by CeMaST, that replaced the Illinois Summer Research Academy. High school students work one or two to a faculty member on STEM research in the lab and in the field after two days of orientation. It takes place in late July, the $100 cost includes daily lunches and a t-shirt, and limited scholarships are available." },
  // https://ent.rowan.edu/communityprograms/tlae.html
  "rowan-university-think-like-an-entrepreneur-summer-academy": { blurb: "A free, non-residential entrepreneurship academy at Rowan University for rising high school juniors and seniors, supported by the TD Charitable Foundation. Teams create a company centered on one of the United Nations Sustainable Development Goals and compete for prizes, and participants earn 3 college credits that can be used at Rowan or transferred. It runs in late June or early July, and transportation and housing are not provided." },
  // https://summer.mst.edu/browse/cyberminercamp/
  "missouri-university-of-science-and-technology-cyber-miner-camp": { blurb: "A residential summer camp at Missouri S&T in Rolla for students aged 16 to 18 that spans computer engineering, computer science and information science and technology. Campers build and program a robot, take apart and reassemble a computer, join an AI forum and learn about microcontrollers. The $600 fee covers all meals, housing and camp materials, and the camp returns in summer 2027 with room for 60 students." },
  // https://besthealthcareinstitute.org/programs/
  "best-healthcare-institute-best-healthcare-institute": { blurb: "A summer program in St. Louis, founded in 2008, that prepares high school students from more than 50 area high schools for healthcare careers. Students study math, science and ACT/SAT skills, attend healthcare lectures and site visits, and work on personal branding and leadership, earning a merit-based stipend of up to $400 or $500. Applicants need a 3.0 GPA, and the program is held on WashU's Danforth Campus." },
  // https://precollege.washu.edu/high-school-summer-institutes
  "washington-university-in-st-louis-high-school-summer-institutes": { blurb: "Two-week residential, noncredit summer institutes at Washington University in St. Louis for rising sophomores, juniors and seniors, run by Arts & Sciences Pre-College Programs. Each institute has a theme, such as ancient studies, performing arts, research development or environmental studies, and uses lectures, discussions, small group work and final projects without letter grades. Classes typically have 15 to 20 students." },
  // https://www.maryville.edu/summerprograms/
  "maryville-university-summer-pre-college-programs-at-maryville-un": { blurb: "Short summer pre-college programs at Maryville University in St. Louis, most of them for rising high school juniors and seniors. Options include the Saints Science Academy, a Cybersecurity Summer Institute, a Health Professions Summer Institute, the Rawlings Sport Business Management Summer Institute and a design and visual art portfolio workshop. Fees range from $65 to $700 depending on the program." },
  // https://botanicgardens.uw.edu/education/youth-family/summer-camp/youth-summer-internship/
  "university-of-washington-botanic-gardens-youth-summer-internship": { blurb: "A paid summer internship at the University of Washington Botanic Gardens, based at the Washington Park Arboretum in Seattle, for teens ages 16 to 18. Interns meet environmental professionals, work with children in outdoor education settings and complete a team project at the Arboretum. It runs from late June to early August with days of no more than 6 hours, pays a $2,000 stipend, and needs no previous environmental experience." },
  // https://www.soiltosociety.org/summer-research-opportunity
  "washington-state-university-soil-to-society-summer-research-prog": { blurb: "A paid laboratory research internship with Washington State University's Soil to Society project, which focuses on health and nutrition, for U.S. high school students in 9th through 12th grade. Interns spend 200-240 hours assisting a research team, then write a two-page research abstract and present at a poster symposium. They earn a $1200 stipend and WSU non-degree credit, need a 3.5 GPA and a teacher letter, and arrange their own housing and transport." },
  // https://openstudio.millerhull.com/summer-internship
  "miller-hull-partnership-open-studio-summer-internship": { blurb: "One full-time, paid summer internship at Miller Hull's Seattle architecture studio for an under-resourced high school student who has completed 11th or 12th grade. The intern works in a professional environment, may tour construction sites and attend team meetings, builds a portfolio and gives a presentation on the last day. The placement lasts 4 weeks in late July and August, and transit costs to the studio are covered." },
  // https://med.fsu.edu/outreach/summer-institute
  "florida-state-university-college-of-medicine-summer-institute-at": { blurb: "A residential mini medical school at the Florida State University College of Medicine for students who have completed their sophomore or junior year of high school. Students shadow physicians, visit rural health centers, attend faculty lectures on topics such as medical ethics, and get college admissions and financial aid advice. Sessions of up to 20 students run Sunday through Friday in June and July, and the 2026 fee of $1,650 covered registration, supplies, room and board." },
  // https://www.eckerd.edu/precollege/
  "eckerd-college-pre-college-at-eckerd": { blurb: "One-week residential summer programs at Eckerd College in St. Petersburg where high school students study topics such as marine science, animal studies, coastal and wildlife ecology, sharks and rays, premed pathways and nature and environmental filmmaking. Programs run in June, and the fee covers sessions, labs, field trips, meals and lodging. Eligibility varies by program, and some are limited to students entering 11th or 12th grade." },
  // https://www.unr.edu/ltmc/camp-information
  "university-of-nevada-reno-lake-tahoe-music-camp": { blurb: "A sleep-away summer music camp run by the University of Nevada, Reno for music students completing 6th through 12th grade. Campers play in concert bands, and jazz band is audition based. The camp is held at the Nevada State 4-H Camp in Stateline on the South Shore of Lake Tahoe, with meals, cabin-style dormitory housing and instruction from university faculty and professional musicians included, and it ends with a final concert for families." },
  // https://nsil.sites.unlv.edu/GUIC.html
  "university-of-nevada-las-vegas-guic-summer-camp": { blurb: "A five-week summer camp at UNLV's Howard R. Hughes College of Engineering, funded by the National Science Foundation, that trains 40 students entering grades 7 to 12 in Arduino programming and robotics design. Three weeks of training are followed by two weeks of project development, covering Vex V5 robotics and the Internet of Things with design kits built by the project team. Teams are co-mentored by college students and STEM teachers." },
  // https://eohsi.rutgers.edu/thedprogram/
  "rutgers-environmental-and-occupational-health-sciences-institute": { blurb: "A one-week, non-residential lab program at the Rutgers Environmental and Occupational Health Sciences Institute in Piscataway that introduces high school students to toxicology and environmental health. Students cover lab ethics, experimental design, genetics, pharmacogenetics and clinical toxicology. It runs in July for students entering grades 10 to 12 who have taken biology, and the fee is $975, with some need-based aid available." },
  // https://research-office.njms.rutgers.edu/training-programs/high-school
  "rutgers-new-jersey-medical-school-high-school-student-research-i": { blurb: "High school research internships at Rutgers New Jersey Medical School in Newark, where students join the lab of a faculty member who agrees to host them. Positions are arranged by the students themselves, who must be at least 16, secure a host faculty commitment, submit proposal, sponsorship, parental consent and insurance forms, and hold New Jersey working papers. Rutgers also runs related programs such as the paid Pathway to Scientist Program." },
  // https://www.uwgb.edu/freshwater-scholars/
  "university-of-wisconsin-green-bay-freshwater-scholars-program": { blurb: "A summer water science research program at UW-Green Bay where high school students are matched with a UW-Green Bay mentor doing freshwater-centered research. Students commit to 120 hours of work over the summer and receive a $1,750 stipend paid in two installments. Current high school students, including graduating seniors, may apply, and selection includes an interview. Funding comes from the Freshwater Collaborative of Wisconsin, and housing is not provided." },
  // https://morgridge.org/community/programs/rural-summer-science-camp/
  "morgridge-institute-for-research-rural-summer-science-camp": { blurb: "A free residential science camp at the Morgridge Institute for Research in Madison for high school students and science teachers from rural Wisconsin schools, run with the Wisconsin Rural Schools Alliance. During a summer week, students work on topics such as protein structure, fruit fly genetics and cheese chemistry and stay in university dorms. Each school sends a sponsoring science teacher, and the camp typically enrolls 75 students." },
  // https://engineering.wisc.edu/engineering-summer-program/
  "university-of-wisconsin-madison-college-of-engineering-engineeri": { blurb: "A free three-week residential summer program run by the UW-Madison College of Engineering for high school students interested in engineering. Students live in Dejope Hall with housing and meals included, work on design and problem-solving in teams, and attend faculty-led sessions on college admissions and financial aid. It runs in July for current sophomores and juniors who are U.S. citizens or permanent residents with at least a 3.0 unweighted GPA." },
  // https://hs.sas.upenn.edu/summer-programs/academies/3-week/neuroscience
  "university-of-pennsylvania-neuroscience-research-academy": { blurb: "A three-week residential summer academy at the University of Pennsylvania where high school students study the biology of the brain, from neurons and sensory systems to memory and emotion. Students attend twice-daily lectures with Penn neuroscience faculty, join a journal club and a neuroethics club, and do lab work. It runs from July into August, and School District of Philadelphia students may be able to attend free with a scholarship." },
  // https://bioresearchacademy.com/
  "bioresearch-academy-bioresearch-academy": { blurb: "A residential summer program in central Boston, near the Charles River, that trains high school students in biological research and prepares them for science competitions and independent projects. Students pair designed exercises with lab experiments built on experimental design and real data, with feedback from academic staff. It runs from June into July, and 2026 tuition of $9,950 covered housing, lab materials, 3 meals a day and group activities." },
  // https://www.cooperhewitt.org/design-competition-how-to-enter/
  "cooper-hewitt-smithsonian-design-museum-national-high-school-des": { blurb: "An annual design competition from Cooper Hewitt, Smithsonian Design Museum, open to students in grades 9 through 12 and homeschoolers across the United States. Working alone or in teams of up to three, students respond to a yearly challenge by documenting an existing design in their community and sketching an original solution. Selected finalists take part in mentoring activities and travel to New York City and Washington, D.C. to present their designs to judges." },
  // https://www.stanfordacm.org/proco
  "stanford-acm-proco-programming-contest": { blurb: "A programming contest run by Stanford ACM for high school students, modeled on the college-level ACM-ICPC and aimed at Bay Area students exploring computer science. Teams of one to three students solve 9 to 15 algorithmic problems, with submissions judged on hidden test cases. Separate Novice and Advanced divisions group newer and more experienced programmers, and the contest is held in person at Stanford each winter." },
  // https://www.mathcon.org/apps/pages/FAQ
  "mathcon-mathcon": { blurb: "A two-round math competition for students in grades 4-12. Students first take an online test, and the top 628 scorers advance to an in-person final in Chicago with a 100-minute test and awards, for which registration is $115. Each year one senior finalist receives a Future Leaders Scholarship of $2,000 per year for 4 years of college, chosen for leadership and empathy as well as math scores." },
  // https://mualphatheta.org/rcml-contest
  "mu-alpha-theta-mu-alpha-theta-contests": { blurb: "Contest program of the national high school and two-year college mathematics honor society, centered on the free Rocket City Math League. This international contest serves middle school, high school and two-year college students, who compete at levels tied to their math course. Each level has three 30-minute tests of 10 questions in the spring, and a school sponsor registers the team, proctors the tests and enters scores online." },
  // https://sites.math.washington.edu/~mathcircle/olympiad/
  "university-of-washington-uw-math-olympiad": { blurb: "A free oral math competition run by the University of Washington math circle for grades 6-10, where students explain their solutions to judges in person rather than writing them up. Held in June, it follows the tradition of Russian oral olympiads, with separate problem sets for grades 6-7 and 8-10 and extra problems for students who solve three of the first set. Registration is required, and satellite events have run in the Bay Area and New York City." },
  // https://education.marssociety.org/competition/
  "the-mars-society-mars-engineering-design-competition": { blurb: "An online team design competition from the Mars Society for students aged 13-19 from around the world. From June into July, teams plan an 18-month Mars surface mission, including its habitat, surface vehicles, scientific instruments, power system, crew and exploration plan, working in Science, Engineering and Human Operations departments. Registration for the 2026 competition was $99." },
  // https://nss.org/contests/
  "national-space-society-nss-gerard-k-oneill-space-settlement-cont": { blurb: "An annual contest from the National Space Society in which students design an orbital space settlement, working individually or in small or large groups. It is open to students up to 12th grade, ages 11-18, from anywhere in the world, with categories by grade from 7th grade and younger through 12th grade. Winners are recognized at the society's international conference, and the 2024 contest drew over 5,200 entries from 28 countries." },
  // https://materovcompetition.org/
  "marine-advanced-technology-education-center-mate-rov-competition": { blurb: "An underwater robotics competition from the Marine Advanced Technology Education Center in which student teams build remotely operated vehicles to complete mission tasks modeled on ocean industry work. Teams enter classes by age and experience, from SCOUT for beginners through NAVIGATOR and RANGER to EXPLORER for experienced high school and college teams. Regional events lead to a world championship, which drew 86 student teams in 2026." },
  // https://www.rubegoldberg.org/rube-goldberg-contests/the-rube-goldberg-machine-contest/
  "rube-goldberg-institute-rube-goldberg-machine-contest": { blurb: "A team contest from the Rube Goldberg Institute in which students build a deliberately complicated machine that completes a simple task announced each school year. The High School division covers grades 9-12, alongside elementary, middle school and adult divisions, and each team performs three runs that are averaged for scoring. Regional events from January through March lead to national finals, and the institute also runs online and cartoon contests." },
  // https://www.researchcomp.org/faqs
  "sarc-high-school-academic-research-competition-sarc": { blurb: "An online research competition for high school students aged 13-18 and recent graduates on a gap year, where individuals submit a 1-2 page research proposal on any subject. Participants can attend expert-led bootcamps and webinars, and the top 50 proposals advance to a round where finalists submit a 1.5-3 minute pitch video. It runs in April and May, registration has been $15 to $20, and 2026 prizes were $1,000, $750 and $550." },
  // https://www.councilforeconed.org/californias-scripps-ranch-high-school-crowned-cees-2025-national-personal-finance-challenge-champions/
  "council-for-economic-education-national-personal-finance-challen": { blurb: "A nationwide team competition from the Council for Economic Education that tests high school students on earning income, spending, saving, investing, credit and risk. Teams first compete in state rounds, which include a written online test and a case-based financial plan for a fictional family, and winners advance to a national final in Atlanta in June. Finalist teams receive cash prizes, and in 2025 each first-place team member and coach received $2,000." },
  // https://www.financialskillschallenge.com/
  "bank-of-america-and-junior-achievement-financial-skills-challeng": { blurb: "A free online financial literacy simulation run by Bank of America in which middle and high school students make real-life money decisions, from budgeting to unexpected expenses. Players start as college students with part-time jobs and later move into full-time work, paying costs such as rent, insurance and loans. The six-hour game includes lessons and badges, students who finish every lesson and month earn a Financial Skills Certification, and regional contests recognize top players." },
  // https://yeausa.org/about/introduction/
  "young-entrepreneurs-academy-young-entrepreneurs-academy": { blurb: "A year-long program run locally through chambers of commerce in which students in grades 6-12 turn an idea into a real business or social venture. Students generate business ideas, conduct market research, write business plans and pitch to a panel of investors who can provide start-up capital, with volunteer business mentors working one-on-one with each venture. Top students go on to a national competition for college scholarships and start-up money." },
  // https://nationalinnovatorchallenge.org/faq/
  "national-innovator-challenge-u-s-national-innovator-challenge": { blurb: "A national innovation competition for K-12 students, held virtually so students anywhere in the U.S. can take part. Students work alone or in teams of up to three to develop an invention or venture concept through unstructured problem-solving tied to core STEM standards, then submit it for judging. Students enter through a partner organization or the Independent Innovator Challenge, registration is $30 per student with scholarships available, and top innovators advance to Nationals." },
  // https://www.waicy.org/about/
  "waicy-world-artificial-intelligence-competition-for-youth-waicy": { blurb: "An annual global AI competition for students aged 6 to 18 who build projects that tackle real-world problems such as climate change, human rights and public healthcare. Entrants work alone or in teams and can take part remotely, with tracks that have included an AI Showcase, large language models, and AI-generated images and videos. Entry is free, and judges award winners by category, including high school divisions, at a final event held in December." },
  // https://www.mathleague.org/hsevents.php
  "mathleague-org-math-league-high-school-contests": { blurb: "A series of school-year math contests for high school students run by mathleague.org, with individual and team rounds held in person, online in a live proctored Zoom meeting, or on demand. Qualifying contests run mostly from October through March, and top scorers are invited to state championships in April and May. State winners advance to the U.S. National High School Championship in May and then to an International Championship in July. Qualifying rounds cost $30 or less per student." },
  // https://scz.org/event/zookeeper-apprentice-program
  "sedgwick-county-zoo-zookeeper-apprentice-program": { blurb: "A summer apprentice program at the Sedgwick County Zoo in Wichita where students 14 and older learn what zookeepers do, with some class time but mostly hands-on work out in the zoo. Each session runs Monday through Friday from 8 a.m. to noon for two weeks, and tickets cost $160 for members and $180 for non-members. Staff evaluate students weekly on work ethic, attitude and work quality, and those who score well are invited to the next level, Intermediate ZAP." },
  // https://fwmoa.org/careers-and-internships/
  "fort-wayne-museum-of-art-fall-semester-internship-at-fort-wayne": { blurb: "An unpaid volunteer internship at the Fort Wayne Museum of Art for area high school students, with one intern chosen each fall and spring semester. The intern learns how the museum runs, with a focus on the education department, and may help with tours, educational activities or research alongside museum staff. Priority goes to rising juniors and seniors, and selected candidates must pass a background check. The museum's other internships are for college and graduate students." },
  // https://www.stonybrook.edu/commcms/istem/students/grades_5-12/summer/explorations_forensics_camp.php
  "stony-brook-university-institute-for-stem-education-explorations": { blurb: "A five-day summer forensic science camp at Stony Brook University's Institute for STEM Education for students who have finished 9th grade and have not taken a formal forensics course. Students work in the lab on toxicology, DNA fingerprinting and blood typing, ending with processing a mock crime scene. The camp costs $750, is capped at 24 students and runs in July, and housing is not offered. Applicants submit two teacher recommendations, essays and a transcript." },
  // https://tippie.uiowa.edu/undergraduate/admissions/high-school-students/gateway-summer-program
  "university-of-iowa-tippie-college-of-business-gateway-summer-pro": { blurb: "A free one-week residential business program at the University of Iowa's Tippie College of Business for high school juniors heading into their senior year. Students live on campus, take part in business simulations and meet Tippie students, professors and business professionals. Sponsors including Deere & Company cover the costs, scholarships support participants later admitted to Tippie, and the program aims to reach students underrepresented in business, including women and first-generation students." },
  // https://www.design.iastate.edu/future-students/k-12-experiences/k12outreach/
  "iowa-state-university-college-of-design-design-dimensions-summer": { blurb: "A one-week summer design camp run by Iowa State University's College of Design for high school students, offered as a residential camp or a day camp in June. Campers take daily on-campus workshops led by College of Design faculty in fields such as architecture, graphic design, industrial design, interior design, illustration, game design and landscape architecture. The camp also introduces 2D, 3D and 4D thinking and design technology, including AI tools." },
  // https://iowasummermusiccamps.uiowa.edu/
  "university-of-iowa-iowa-summer-music-camps": { blurb: "Summer music camps run by the University of Iowa School of Music for school musicians who have finished sixth grade or later, with residential and commuter options. Camps cover band, orchestra, choir, jazz and instruments such as flute, saxophone, horn, clarinet, trumpet, piano and percussion, taught by School of Music faculty, graduate students and guest artists. Sessions run in June, commuters pay $375, residents pay $685 to $750 including housing and meals, and scholarships are offered." },
  // https://med.miami.edu/centers-and-institutes/hihg/education-and-training/division-of-genomic-education/educational-programs/jj-vance-memorial-summer-internship
  "university-of-miami-miller-school-of-medicine-jj-vance-memorial": { blurb: "A paid eight-week summer research internship at the University of Miami Miller School of Medicine's John P. Hussman Institute for Human Genomics for high school juniors from Miami-Dade and Broward counties. Interns are paired with faculty, postdocs or staff to contribute to real research, working weekdays from 9:00 AM to 5:00 PM, and present their work at a closing luncheon. Applicants need strong performance in biological or computational sciences, and pay is about $15 per hour." },
  // https://precollege.dcie.miami.edu/summer-programs/academies/credit/index.html
  "university-of-miami-pre-college-summer-scholars": { blurb: "A three-week summer credit program at the University of Miami for high school students completing grades 10 or 11, running from late June into July. Students take two 3-credit courses within one academic specialty for a total of 6 credit hours, graded on a 4.0 scale and recorded on an official UM student record. The program does not offer financial aid or payment plans, though the Vista Scholarship covers residential tuition and fees for eligible low-income domestic students." },
  // https://magic.mdc.edu/summer-camp/
  "miami-dade-college-magic-summer-camp": { blurb: "Week-long summer camps in animation and game design at Miami Dade College's Miami Animation & Gaming International Complex for students ages 14-19. Animation campers learn character design, 3D modeling and character animation in Autodesk Maya, while game design campers build explorable PC environments in Unreal Engine 5 or create an interactive video game. Camps run in June and July at $395 per week, with grant support from the Bosch Community Fund." },
  // https://umiamihealth.org/en/patient-,-a-,-visitors/patients-,-a-,-families/volunteering-at-uhealth/high-school-summer-programs/high-school-student-research-trainee
  "university-of-miami-health-system-high-school-student-research-t": { blurb: "A free summer research traineeship at the University of Miami Health System where high school students at least 16 years old train under a faculty sponsor, whom they must secure before applying. Trainees work in groups of at least two, up to 20 hours a week on a schedule set with their supervisor, and training is in person only. Students cover their own transportation and complete a background check, drug screening and online training modules." },
  // https://a4lmiami.org/artworks-internships-in-the-arts/
  "arts-for-learning-miami-artworks-internships-in-the-arts": { blurb: "A paid summer arts internship run by Arts for Learning Miami for students in grades 9-12 who are at least 14, with no prior arts experience required. Interns work alongside a Master Teaching Artist in an artistic co-op of their choice to create works of art while building workforce skills, with college advisement and goal-setting workshops. It runs Monday through Friday from 9:00 AM to 3:30 PM in June and July and pays $14.00 an hour to Florida residents." },
  // https://cts.fiu.edu/education/high-school-summer-internship-program/
  "florida-international-university-center-for-translational-scienc": { blurb: "A five-week summer biomedical research internship at Florida International University's Center for Translational Science for high school juniors and seniors who live and attend school in St. Lucie County. Interns work in labs under scientists studying areas such as aging, neuroscience, drug discovery, and mitochondria and metabolism, then present a scientific poster at a closing luncheon. Students can earn over 100 volunteer hours and must attend all five weeks." },
  // https://business.howard.edu/undergraduate/student-life/high-school-summer-enrichment-pre-business-program
  "howard-university-school-of-business-high-school-summer-enrichme": { blurb: "A two-week residential summer program at Howard University School of Business for high school students interested in a business degree. Students choose one of six tracks (Accounting, Information Systems, Actuarial Science, Music Business, Finance or Entrepreneurship) and learn through classes, company visits, group projects, workshops and networking. Tuition is $2,000 and covers housing, meals, instruction, site visits and a gala, with limited need-based reductions and waivers." },
  // https://diversity.smhs.gwu.edu/programs/community-outreach-programs/dc-happ
  "george-washington-university-school-of-medicine-and-health-scien": { blurb: "A four-week summer pre-college program at the George Washington University School of Medicine and Health Sciences for DC-area high school students interested in health careers. Each year, sixteen rising 11th and 12th graders from public and public charter schools in DC, Maryland and Virginia explore health professions, practice clinical skills such as drawing blood and intubation, and complete a public health project. Scholars also get college application guidance and can later shadow professionals at GW Hospital." },
  // https://latino.si.edu/yap
  "smithsonian-institution-young-ambassadors-program": { blurb: "A national leadership program from the Smithsonian Latino Center for graduating high school seniors, aimed at developing community-minded Latino leaders in the arts, sciences and humanities. Students attend a one-week seminar in Washington, D.C., then complete a four-week internship at a museum or cultural institution in cities across the United States and Puerto Rico. Applicants need a minimum weighted GPA of 3.25, and participants receive $2,350 toward higher education after the program." },
  // https://www.utsa.edu/pace/community-art/youth/pre-college-art-studio-experience.html
  "university-of-texas-at-san-antonio-pre-college-art-studio-experi": { blurb: "A week-long summer studio intensive for teens ages 15 to 18, run by UTSA's community art program (PaCE) at the University of Texas at San Antonio. Students choose one of four media pairings, such as Ceramics and Painting or Drawing and Printmaking, and spend three hours each morning on one medium and three hours each afternoon on the second. The workshop is geared toward college-level experience and developing work for portfolio presentations. The 2026 session ran 9:00am to 4:00pm on the Main Campus for $400." },
  // https://cheop.unc.edu/pre-college-programs/project-uplift-and-uplift-plus/about-project-uplift/
  "university-of-north-carolina-at-chapel-hill-project-uplift": { blurb: "A summer college access program run by Carolina Higher Education Opportunity Programs (CHEOP) at UNC-Chapel Hill for rising high school seniors. Each summer about 1,000 students attend one of several sessions on campus, where they learn about admissions, interact with faculty, staff and current students, and join educational and social activities. Applicants from all U.S. states and territories are eligible, and the cost is $80 per participant." },
  // https://cheop.unc.edu/pre-college-programs/project-uplift-and-uplift-plus/about-uplift-plus/
  "university-of-north-carolina-at-chapel-hill-uplift-plus": { blurb: "A two-week residential companion to Project Uplift, run by Carolina Higher Education Opportunity Programs at UNC-Chapel Hill for rising high school seniors who are North Carolina residents. There is no separate application, so students indicate interest on the Project Uplift application, and the program runs on campus in late June and early July. The total cost is $1,350, including a $100 non-refundable deposit, and scholarships are not available." },
  // https://nchcap.unc.edu/pre-college/health-careers-day-on-the-hill/
  "north-carolina-health-careers-access-program-health-careers-day": { blurb: "A one-day event on the UNC-Chapel Hill campus, run by the North Carolina Health Careers Access Program (NC-HCAP), for North Carolina high school students interested in health careers. Students attend presentations and interactive sessions with representatives from various health professional schools. It takes place in the fall, and the $50 registration fee covers workshop materials and lunch but not parking. Business casual attire is encouraged." },
  // https://uncw.edu/academics/colleges/chhs/pre-health/iheal.html
  "university-of-north-carolina-wilmington-iheal-healthcare-leaders": { blurb: "A free four-day, three-night residential health care camp at UNC Wilmington, organized by the College of Health and Human Services and Pre-Health Programs for rising ninth graders from New Hanover, Bladen, Brunswick, Columbus, Duplin and Pender counties. Campers take part in simulations and workshops in CHHS labs, such as respiratory therapy intubations, Anatomage and virtual reality. Former campers can attend alumni seminars each fall and spring during high school." },
  // https://www.ctbar.org/public/k-12/law-camp
  "connecticut-bar-association-cba-law-camp": { blurb: "A free week-long day camp run by the Connecticut Bar Association for Connecticut high school students interested in law, held in July at the UConn School of Law in Hartford. Campers join panel discussions, mentorship and advocacy training, prepare for a mock trial competition, observe court proceedings, and meet attorneys, judges and law students. The camp aims to serve students who have overcome adversity or would be the first in their family to join the legal profession." },
  // https://marktwainhouse.org/nfwc/
  "the-mark-twain-house-and-museum-nook-farm-writers-collaborative": { blurb: "A six-week paid summer creative writing apprenticeship at The Mark Twain House & Museum in Hartford, Connecticut, for teens ages 14 to 18. Apprentices meet at the museum from late June through July to build their creative writing. Each participant earns an $800 stipend, paid in two installments and contingent on attendance and successful completion of the program." },
  // https://www.hhs.k-state.edu/summerhealthprogram/
  "kansas-state-university-health-professions-exploration-program": { blurb: "A week-long summer program run by Kansas State University's College of Health and Human Sciences for incoming high school juniors and seniors interested in health care careers. Students meet K-State faculty, alumni, current students and health professions advisors and explore fields such as medicine, nursing, physical therapy, nutrition and sports medicine. Participants stay in campus residence halls, and 20 students are selected for each June session." },
  // https://apdesign.k-state.edu/academics/visit-opportunities/summer-design-experience.html
  "kansas-state-university-college-of-architecture-planning-and-des": { blurb: "A three-day, faculty-led summer program from Kansas State University's College of Architecture, Planning & Design for high school students. Participants work on projects in the college's design labs across architecture, industrial design, interior architecture, landscape architecture, and regional and community planning, ending with a final project display. The 2026 session in June cost $800, and a limited number of need-based scholarships are offered." },
  // https://cresis.ku.edu/aatee
  "university-of-kansas-center-for-remote-sensing-and-integrated-sy": { blurb: "A free two-week summer camp at the University of Kansas in Lawrence, run by the Center for Remote Sensing and Integrated Systems (CReSIS) as the first phase of Project ARISE, for rising seniors in Kansas. Students work on drone piloting, model car programming, applied physics, Python and robot operating systems. Room, board and tuition are covered by a Department of Defense grant, and students from military families and rural high schools are prioritized." },
  // https://www.fhsu.edu/music-and-theatre/musiccamp/
  "fort-hays-state-university-high-plains-music-camp": { blurb: "A week-long summer music camp at Fort Hays State University in Hays, Kansas, for students in grades 6 through 13, held in late June. Each camper joins one large ensemble, such as band or string orchestra, and one small ensemble, with solo opportunities and evening concerts that are free to the public. Overnight campers pay $580 for room, board, instruction and recreation, and day campers pay $370." },
  // https://www.unmc.edu/student-success/pathway-programs/sharp/index.html
  "university-of-nebraska-medical-center-summer-high-school-advance": { blurb: "A 10-week summer research program at the University of Nebraska Medical Center in Omaha, run with the Division of Student Success, for high school sophomores or juniors who are at least 16. Students work in a lab, receive training in biomedical techniques, and create a research poster to present their findings at the end of the program. Applicants must be U.S. citizens or permanent residents with a cumulative GPA of 3.0 or above." },
  // https://www.unomaha.edu/college-of-business-administration/prep-academy/about-us/prep-academy-summer-camps.php
  "university-of-nebraska-omaha-college-of-business-administration": { blurb: "Free summer business camps run by the University of Nebraska Omaha College of Business Administration Prep Academy for high school students in grades 10-12. Camps cover digital and social media marketing, economics, banking and finance, and accounting, and several are overnight. Meals and snacks are included, each camp has 25 spots, and the only charge is a $20 non-refundable deposit at registration that can be waived by email." },
  // https://omahaplayhouse.com/education/internship/
  "omaha-community-playhouse-shfta-summer-internship": { blurb: "A paid summer internship at the Omaha Community Playhouse's Shirlee & Henry Fonda Theatre Academy for students who are at least 16 and a junior or senior in high school, with recent high school graduates also eligible. Interns assist teaching artists during the Summer Session by setting up and tearing down rooms, checking students in and out, and helping teaching artists and directors on camp days." },
  // https://engineering.ucdenver.edu/bioengineering/outreach/bolt-camp
  "university-of-colorado-denver-department-of-bioengineering-bolt": { blurb: "A four-day in-person summer camp on the CU Anschutz Medical Campus in Aurora, run by the University of Colorado Denver's bioengineering department, that introduces high school students to biomedical engineering and related careers. Student teams design, build and test a prototype for a design competition, with 3D printing, lab tours, and time with doctors, researchers and industry leaders. Tuition is $1,100 with supplies and meals included, and scholarships are available." },
  // https://artsandmedia.ucdenver.edu/prospective-students/lynx-camps
  "university-of-colorado-denver-college-of-arts-and-media-lynx-nat": { blurb: "Summer immersion camps at the University of Colorado Denver College of Arts & Media for students who have finished 8th grade and have not yet started college. One-week commuter camps in 2D animation, audio production, comic book character design and photography cost $650, while two-week camps in music industry, animation, game art and filmmaking cost $1,300 to $2,800 depending on commuting or living on campus. Need-based scholarships are available." },
  // https://architectureandplanning.ucdenver.edu/academics/high-school-programs/architecture-in-the-city
  "university-of-colorado-denver-college-of-architecture-and-planni": { blurb: "A noncredit workshop series from the University of Colorado Denver College of Architecture and Planning that introduces high school students to architecture and design. Each one-day workshop focuses on a single skill, such as sketching by hand, digital design or model-making, and sessions run through the school year from fall to winter. Each workshop costs $120, and students who complete all three earn a certificate." },
  // https://uofuhealth.utah.edu/huntsman/education-training/high-school/crhs
  "huntsman-cancer-institute-university-of-utah-cancer-research-hig": { blurb: "A compensated two-week virtual summer program from Huntsman Cancer Institute at the University of Utah, sponsored by the American Cancer Society, for rising high school sophomores and juniors in Utah, Nevada, Montana, Idaho or Wyoming. The first week covers cancer research with an at-home experiment kit, and the second covers career exploration. Students commit to 40 hours of virtual sessions and receive financial compensation up to $500." },
  // https://uofuhealth.utah.edu/huntsman/education-training/pathmaker/scholars
  "huntsman-cancer-institute-university-of-utah-pathmaker-scholars": { blurb: "A ten-week mentored summer cancer research program at Huntsman Cancer Institute at the University of Utah for advanced high school seniors and undergraduates. Scholars live on campus, learn laboratory techniques, and work on a project under a principal investigator, committing 40 hours per week and presenting at the Summer Research Symposium. Compensation is up to $4,000 depending on education level, and out-of-state students receive housing and a meal plan." },
  // https://www.ipho-new.org/statutes-syllabus/
  "ipho": { blurb: "An annual international physics competition for secondary school students, with the 2026 edition held in Bucaramanga, Colombia, in July. Each country normally sends five contestants and up to two delegation leaders. Contestants must attend general or technical secondary schools, must not have started university, and must be no older than 20 on June 30 of the competition year. The organizing committee covers each delegation's costs from arrival to departure." },
  // https://www.nyu.edu/admissions/high-school-and-middle-school-programs/high-school-programs/nyu-precollege/tuition-and-scholarships.html
  "nyu-precollege": { blurb: "NYU Precollege lets rising 11th and 12th grade high school students take regular NYU courses for credit during the summer, in the same classes as undergraduates. Students can earn up to 8 credits (2 classes), and most courses carry four credits. Applicants need a minimum 3.0 GPA. A 4-credit course costs $8,008, and students living on campus pay estimated housing and dining charges of $4,600." },
  // https://www.sps.nyu.edu/high-school-academy/programs/career-edge/courses/HIGH1-CE9049.html
  "acl": { blurb: "A one-week summer course at the NYU School of Professional Studies High School Academy for students who have finished grades 9, 10 or 11. It introduces legal careers, basic substantive law and litigation through lectures, speaker panels, mock trials and visits to courthouses and government agencies. Tuition is $2,579 per course, with optional housing and dining, and no financial aid is offered. Students receive an NYU transcript but no college credit." },
  // https://bronxmuseum.org/learn/teens/
  "bronx-museum-teen-council": { blurb: "A four-month paid after-school internship at The Bronx Museum for New York City high school students ages 14 to 19, offered in the fall and the spring. Teens meet twice a week at the museum, where they interview contemporary artists, help curate in-person and digital exhibitions, and create work for a zine. Participants receive a stipend, and each cohort includes about 12 to 14 students." },
  // https://www.fitnyc.edu/academics/precollege/index.php
  "fit-precollege": { blurb: "Non-credit courses at the Fashion Institute of Technology for students in grades 9 through 12 in business, fashion, visual arts, and design, including photography, illustration, and styling. Ten-day classes tied to FIT majors meet on Saturdays and help students build portfolios, while 4-day summer workshops focus on a single skill. A 10-day class costs $550, a summer workshop costs $440, and scholarships are available." },
  // https://www.nhbwinc.org/scholarships
  "csv-sch-dr-arnita-young-boswell-scholarship": { blurb: "A $1,000 scholarship from the National Hook-Up of Black Women, Inc. that recognizes African American graduating high school seniors who show academic achievement, community concern, and a plan to pursue further education. The award is named for the organization's founder, a former Joliet City Council member. Applicants should be involved in school and community activities, and the scholarship is one of several offered through NHBW's local chapters." },
  // https://www.exploravision.org/what-exploravision/
  "exploravision": { blurb: "A K-12 science competition from Toshiba and NSTA for U.S. and Canadian students, where teams of two, three, or four students work with a coach and an optional mentor. Teams research an existing technology and its history, then project what it could be like 10 or more years in the future and what breakthroughs it would need. Entries include a written project and a one-page Technology Launch Flyer, and winners can earn savings bonds." },
  // https://www.aphis.usda.gov/careers/students-grads/agdiscovery
  "usda-aphis-agdiscovery": { blurb: "A free summer outreach program from USDA APHIS that helps teenagers explore careers in agricultural sciences. This year it runs as a 5-day day camp at 10 partner universities, where students return home at the end of each day; earlier editions were 2-4 week residential programs on college campuses. Programs fall into four areas: agribusiness, plant, animal and combination. Grade and age requirements vary by university, and students apply directly to each campus." },
  // https://www.aaja.org/programs-and-initiatives/jcamp/
  "asian-american-journalists-association-jcamp": { blurb: "A free six-day summer journalism program from the Asian American Journalists Association for multicultural high school students from across the country. It is open to all high school sophomores and juniors, not only Asian American students, and accepts around 30 students per year. AAJA covers all costs, including domestic airfare, campus housing and meals. The program has run since 2001, and the most recent session was held in Minneapolis in June." },
  // https://www.bigelow.org/education/bloom.html
  "bigelow-laboratory-for-ocean-sciences-keller-bloom-program": { blurb: "A free one-week ocean science program at Bigelow Laboratory for Ocean Sciences in East Boothbay for 16 Maine high school juniors from public, private and home schools. The week starts with a research cruise on the Sheepscot River estuary, then moves to lab work with Bigelow scientists on phytoplankton, zooplankton and marine viruses, ending with a presentation to family and friends. Students live in chaperoned campus housing, and all meals are provided." },
  // https://barronprize.org/apply/
  "barron-prize-gloria-barron-prize-for-young-heroes": { blurb: "A national award that honors U.S. and Canadian young people ages 8 to 18 who have organized and led service projects that clearly benefit people or the planet. Winners receive $10,000 for higher education or their service project. Students apply alone or with one co-leader through a two-step process each spring: a pre-application, then a full application with a project essay, a lead reference letter and two more recommendation letters." },
  // https://www.usaaio.org/contest-rules
  "usa-artificial-intelligence-olympiad-usa-north-america-ai-olympi": { blurb: "An artificial intelligence olympiad for U.S. and Canadian high school students, run by USA Artificial Intelligence Olympiad. Students take a proctored online Round 1 exam in February, top scorers advance to Round 2, and Round 2 qualifiers attend the USAAIO camp, which leads to U.S. team selection for international AI olympiads. Contestants must be under 20 on the first day of the international competition and cannot be full-time university students." },
  // https://usad.org/
  "united-states-academic-decathlon-united-states-academic-decathlo": { blurb: "A team academic competition for high school students in which teams of nine compete in ten events: seven subject-area tests, an essay, speeches, an interview and the Super Quiz. Each team has three students in each GPA category (Honor, Scholastic and Varsity), and each event is worth 1,000 points per competitor." },
  // https://nationalspanishexam.org/exams/national-spanish-exam/
  "american-association-of-teachers-of-spanish-and-portuguese-aatsp": { blurb: "A national online Spanish exam and competition for middle and high school students, run by the American Association of Teachers of Spanish and Portuguese and taken through a registered teacher. Teachers reserve seats for their students at $6 per student during regular registration. Prizes are based on national percentile rankings, medals are mailed to the school, and medal winners may apply for AATSP student scholarships." },
  // https://www.cellbio.duke.edu/education-and-training/cell-biology-academy-ceba
  "duke-university-department-of-cell-biology-cell-biology-academy": { blurb: "A paid six-week summer research program in the Duke Department of Cell Biology for Research Triangle-area high school sophomores, juniors and seniors who are at least 15. Each student completes an independent research project under the guidance of a graduate student or postdoctoral scholar and presents it at a scientific poster session. Students are on site for a normal work day, about 9 AM to 5 PM, and receive $2,400 on completion." },
  // https://www.med.unc.edu/tarc/clinical-trials/tarc-tigers-program/
  "unc-thurston-arthritis-research-center-tarc-tigers-summer-resear": { blurb: "A paid summer program run by the clinical trials team at UNC's Thurston Arthritis Research Center for rising high school juniors and seniors who are 16 and older. Four students serve as Research Technicians, creating patient outreach materials, preparing lab kits, shadowing research coordinators on campus and handling office tasks. Pay is $12 to $15 an hour for about 25 to 30 hours a week." },
  // https://www.ncat.edu/caes/agricultural-research/rap-program.php
  "north-carolina-a-and-t-state-university-research-apprenticeship": { blurb: "A two-week residential summer program at North Carolina A&T State University for rising high school juniors and seniors interested in food, agricultural and environmental sciences. Participants live on campus and conduct independent research under the direction of research scientists. Applicants must be U.S. citizens with at least a 2.8 GPA, the only cost is a $25 non-refundable application fee, and students who enroll in its agricultural college receive a stipend." },
  // https://extendedstudies.ucsd.edu/sally-ride-science/k12-students/sally-ride-science-academy/high-school
  "uc-san-diego-extended-studies-sally-ride-science-academy": { blurb: "Summer STEAM courses for high school students in grades 9-12 from Sally Ride Science at UC San Diego Extended Studies. Topics include sustainable city design, astrobiology, robotics with JavaScript, startups and marine microbiology, taught in person in San Diego as full-day sessions or live online in morning or afternoon blocks. Sessions run in July, most courses carry 1.5 units, prices range from $200 to $495, and scholarships are available." },
  // https://yis.org/programs/stock-pitch-competition/
  "young-investors-society-global-stock-pitch-competition": { blurb: "A stock pitch competition run by the Young Investors Society for U.S. and international high school students, who compete alone or in teams of up to two. Each entry picks a public company, recommends a Buy or Sell, and submits a written report, a PowerPoint and a video of the presentation, then defends the analysis before a panel of industry professionals. The fee is $30 per person for U.S. students, and the top 100 teams are invited to a summit in New York City in May." },
  // https://stosselintheclassroom.org/video-contest/
  "stossel-in-the-classroom-stossel-in-the-classroom-video-contest": { blurb: "An annual video contest from Stossel in the Classroom in which students make a 1 to 3 minute video on one of the year's economics and civics prompts, such as presidential powers or digital privacy. The high school division is for grades 9-12, and U.S. and Canadian students and those at a U.S. military address enter on their own or through a teacher. First place earns $2,500, second $1,000 and five finalists $200 each." },
  // https://stosselintheclassroom.org/ai-challenge/
  "stossel-in-the-classroom-stossel-in-the-classroom-ai-challenge": { blurb: "A contest from Stossel in the Classroom for students in grades 8-12 who are at least 13, in which entrants use AI tools thoughtfully to build an argument on the year's prompts. U.S. and Canadian students and those at a U.S. military address may submit one entry in English. Prizes are $1,500 for first, $1,000 for second, $500 for third and $250 for each of 10 finalists, and entrants cannot also enter the essay contest." },
  // https://www.unr.edu/engineering/about/outreach/k-12/camps
  "university-of-nevada-reno-engineering-summer-camps-at-university": { blurb: "Summer engineering camps run by the University of Nevada, Reno College of Engineering for high school students ages 14 to 17. Campers explore the engineering design process with faculty, students and local engineers at a 6:1 student-teacher ratio, in camps such as an Aerospace Mini-Camp, Engineering Adventures and a civil and environmental engineering camp with a concrete canoe project. Fees have ranged from $215 to $450." },
  // https://ctsciencecenter.org/education/teens
  "connecticut-science-center-teen-innovation-program": { blurb: "A six-week summer program at the Connecticut Science Center in Hartford where teens, called Teen Innovation Ambassadors, work at the Center creating original STEM programs and exhibits for visitors. The program aims to build leadership and communication skills and a stronger sense of belonging in STEM. Applicants must first complete one full session of the Investigate! program or serve on the Teen Advisory Council for a full school year." },
  // https://meca.edu/academics/pre-college/
  "maine-college-of-art-and-design-pre-college-art-and-design-progr": { blurb: "A three-week residential summer art program at Maine College of Art & Design in Portland, Maine, for high school students ages 15 to 18. Students choose two studio majors from options such as Animation, Ceramics, Illustration, Painting and Printmaking, and all students also take figure drawing. Tuition is $5,000 for a shared room or $5,500 for a single room and covers housing, meals, studio instruction, most supplies and a final exhibition." },
  // https://www.mica.edu/academics/youth-and-teen-programs/programs-for-teens/portfolio-preparation-for-high-schoolers/
  "maryland-institute-college-of-art-programs-for-teens-at-mica": { blurb: "Pre-College Saturday and summer studios at Maryland Institute College of Art in Baltimore, where students in grades 9-12 build portfolios on MICA's main campus. Saturday classes meet in the morning or afternoon, and intensive one-week sessions run in summer. Rising juniors and seniors can join a summer residency that earns up to three college credits, and the free Art and Design College Accelerator Program serves 15 Baltimore City students from sophomore year on." },
  // https://exst.umd.edu/pre-college-programs/terp-young-scholars
  "university-of-maryland-pre-college-programs-at-the-university-of": { blurb: "Terp Young Scholars is the University of Maryland's three-week summer program where high school students take one three-credit university course in person or fully online. It is open to students entering grades 10 through 12 with an unweighted academic average of 3.0 or better. Grades and credits post to a UMD transcript, and courses cannot be taken pass-fail. Seniors can also take up to seven college credits during the year." },
  // https://www.babson.edu/summer-at-babson/high-school-learners/summer-study/
  "babson-college-summer-study-for-high-school-students": { blurb: "A three-week summer program at Babson College for rising high school juniors and seniors that earns 4 college credits through the Babson course EPS 1110 Introduction to the Entrepreneurial Experience. It runs in July and is offered fully online or in person, with the in-person version hosted at the New England Innovation Academy in Marlborough, Massachusetts. The application carries a $100 fee, which is waived for students applying for need-based aid." },
  // https://www.bentley.edu/precollege
  "bentley-university-pre-college-programs-at-bentley-university": { blurb: "Week-long summer pre-college programs at Bentley University for high school students interested in business, finance and analytics. Courses include Personal Finance and Wealth Management, Stock Market and Investment Research, Quant Risk Management, Social Entrepreneurship, Sports Business and Performance, and Business of Beauty and Social Influencers. Sessions run in June and July, students work with faculty, and some sections are offered for credit." },
  // https://www.brandeis.edu/precollege/programs/index.html
  "brandeis-university-precollege-programs-at-brandeis": { blurb: "Brandeis University in Waltham runs several precollege options for high school students. Genesis is a three-week residential Jewish learning program for ages 15-18 on the Brandeis campus, open to Jewish students of all genders and identities, with tuition of $5850. Students who have completed junior year can take regular college courses through Brandeis Summer School, and Precollege Online offers year-round courses for students ages 13 and up." },
  // https://www.smith.edu/academics/departments-programs-courses/precollege-programs
  "smith-college-precollege-programs-at-smith-college": { blurb: "Summer precollege programs at Smith College for students entering grades 9 through 12, held in July and mostly two weeks long. Options include a Summer Science & Engineering Program with lab courses taught by Smith faculty to groups of up to 17 students, a Creative Writing Workshop, a one-week College Readiness program and a climate course called Sustainable Futures. College credit is not offered, and tuition was $4,985 per two-week session in 2026." },
  // https://www.wpi.edu/academics/pre-collegiate/summer-programs
  "worcester-polytechnic-institute-summer-programs-at-wpi": { blurb: "Pre-collegiate summer STEM programs at Worcester Polytechnic Institute for high school students. Launch is a one-week, non-credit commuter program for grades 9-11 that costs $795, and Frontiers is a two-week residential program for grades 10-12 where students explore a STEM or business major plus a humanities, arts or business minor for $4,995 per session including housing and meals. Rising 11th and 12th graders can also take regular WPI summer courses for credit." },
  // https://www.mcad.edu/academics/continuing-education/pre-college/summer-session
  "minneapolis-college-of-art-and-design-pre-college-courses-at-mca": { blurb: "The Pre-College Summer Session at Minneapolis College of Art and Design is a two and a half week studio art and design program in July that earns 3 credits on an MCAD transcript. Majors include Animation, Character Design and Concept Art, Filmmaking and Painting, and most participants have just finished their junior or senior year. The total cost is $3,800, and MCAD also offers weeklong 1-credit Pre-College Studio Intensives for ages 15-18." },
  // https://www.slu.edu/science-and-engineering/about/pre-college-programs/index.php
  "saint-louis-university-stem-pre-college-programs": { blurb: "STEM programs run by Saint Louis University's School of Science and Engineering for middle and high school students in the St. Louis region. An Aviation Summer Academy, an Engineering Summer Academy and a STEM Immersion Experience introduce high school students to technology and careers in engineering, robotics and aviation. The school also hosts Introduce a Girl to Engineering Day each February and Billiken BEAMS, a balsa wood bridge-building contest for high school teams." },
  // https://ceps.unh.edu/outreach/tech-camp
  "university-of-new-hampshire-tech-camp": { blurb: "A summer STEM camp run by the University of New Hampshire's College of Engineering and Physical Sciences, with weeklong day and residential programs in July for students in grades 5-12. Commuters attend from 8:30am to 4:00pm, and overnight students stay on campus in university housing. The TechVenturers and TechLeaders tracks cost about $1,300 to $2,300 depending on commuter or overnight status, and families can apply for financial assistance." },
  // https://www.centenaryuniversityacademy.com/summeracademy
  "centenary-university-summer-academy-at-centenary-university": { blurb: "A one-week, non-credit residential summer academy at Centenary University for teens entering grades 9-12, with commuter students also welcome. Recent academies cover Criminal Psych, Vet Science and Fine Art, and courses are taught by Centenary University professors, with select classes led by professionals in the field. Instruction runs from 9 am to 4 pm, followed by evening activities, and overnight students receive three meals a day." },
  // https://www.fdu.edu/lifelong-learning-at-fdu/high-school-programs/dual-enrollment/
  "fairleigh-dickinson-university-early-college-programs-for-high-s": { blurb: "Fairleigh Dickinson University's early college programs let high school students earn FDU credit before they graduate. Through Dual Enrollment, which dates to 1984, students take credit-bearing FDU courses at their own high school, taught by qualified high school teachers, at more than 100 partner schools in New Jersey, New York and beyond. Early College Summer serves rising sophomores, juniors and seniors with courses online, in person or over Zoom." },
  // https://www.rider.edu/admissions/jterm-summer/summer-session/gifted-talented-program
  "rider-university-gifted-and-talented-program": { blurb: "A Rider University program that lets rising high school juniors and seniors take college courses for credit in summer. Students can earn up to 6 credits in each of the two 6-week summer sessions, taking accelerated courses on campus or online. Applicants submit an online application, an official transcript and a school recommendation letter, and a $35 technology fee applies per course. High school students are not eligible for summer housing." },
  // https://www.adelphi.edu/high-school-students/pre-college/
  "adelphi-university-summer-pre-college-at-adelphi": { blurb: "Summer pre-college programs at Adelphi University in Garden City, New York. Rising 10th to 12th graders can take a three-week course in July worth three transferable college credits, living on campus or commuting, with topics such as coding and AI, pre-law, psychology and music production. Rising 9th through 12th graders can instead join one-week, commuter-only academies such as the Business and Leadership Academy and the Careers in Healthcare Academy." },
  // https://www.alfred.edu/about/summers-at-alfred/summer-camps/
  "alfred-university-pre-college-programs-at-alfred-university": { blurb: "Alfred University runs pre-college summer programs for high school students, including art portfolio intensives and Engineering I and II. The five-day High School Art Portfolio sessions in July, Color and Drawing & Design, are open to rising sophomores through seniors, welcome beginners and cost $1,000 each. Students create finished works for their portfolios, and the Drawing & Design session moves into printmaking with a block print made in the university printshop." },
  // https://www.cuny.edu/academics/current-initiatives/p20/college-now/
  "city-university-of-new-york-college-now": { blurb: "A free dual enrollment program run by the City University of New York and the NYC Department of Education that lets New York City public high school students take college courses. Juniors and seniors with a GPA of 80 or higher can take credit courses at a partner CUNY campus, and some 10th graders can take non-credit college-readiness courses. Classes run in fall, spring and summer, online, hybrid or in person, mostly before or after school or on Saturdays." },
  // https://www.hofstra.edu/academics/summer-science-research-program/
  "hofstra-university-hofstra-summer-science-research-program": { blurb: "A four-week summer program at Hofstra University where high school students do full-time research with faculty mentors in fields including biology, chemistry, psychology and engineering. Applicants must be in 10th or 11th grade, at least 15 by the start, U.S. citizens or permanent residents, and have completed a year of a high school research course. The program runs in July, ends with a poster session, and cost $2,250 in 2026." },
  // https://www.ithaca.edu/summer-college-high-school-students
  "ithaca-college-summer-college-for-high-school-students": { blurb: "A residential summer program at Ithaca College in July where high school students take one undergraduate course for three college credits. It is open to students ages 14 to 18 entering grades 9 through 12, and course offerings change every year, with recent options in communications, environmental sciences, health and the natural sciences. The 2026 residential cost was $5,900, with a commuter rate of $4,368, and need-based scholarships cover up to 50% of the program fee." },
  // https://mercy.edu/academics/school-business/business-leadership-academy
  "mercy-university-summer-leadership-academy": { blurb: "A week-long summer program at Mercy University's School of Business for rising high school seniors, held mostly on the Westchester campus in Dobbs Ferry, New York, with a day in Manhattan. Students learn about leadership and careers in finance, accounting and marketing from executive faculty, visit Fortune 500 companies, compete in a Shark Tank competition and work with a faculty mentor. Tuition is free, and a $695 fee covers food and activities." },
  // https://www.nyit.edu/admissions/pre-college-programs/
  "new-york-institute-of-technology-pre-college-programs-at-new-yor": { blurb: "New York Tech offers several pre-college options for high school students. Its High School Summer Maker Academy is a weeklong, in-person program in the campus Maker Spaces for students ages 14 to 18, with workshops in 3-D modeling and printing, laser cutting, PCB design and Arduino coding, and it is limited to 20 students. High school students can also take college courses in the fall, spring or summer." },
  // https://www.rit.edu/artdesign/portfolio-prep
  "rochester-institute-of-technology-pre-college-portfolio-preparat": { blurb: "An annual two-week visual arts workshop at Rochester Institute of Technology, taught by School of Art drawing and painting faculty, that prepares the portfolios of rising high school juniors and seniors for admission to college art programs. Assignments include still lifes, figure and gesture drawing, self-portraits and printmaking. The workshop is held on the RIT campus, and scholarships are offered." },
  // https://www.sarahlawrence.edu/precollege/
  "sarah-lawrence-college-pre-college-programs-at-sarah-lawrence": { blurb: "Sarah Lawrence College runs summer precollege programs for high school students, most of them commuter-based, in creative writing, visual arts, musical theater, science research and ecology. Writers' Week, offered for more than 25 years, is a week of creative writing and performance. The three-week Painting From Poetry and Rising Artists Musical Theater intensives each earn 3 college credits and cost $6,150. Most programs serve rising 10th to 12th graders." },
  // https://www.skidmore.edu/precollege/
  "skidmore-college-pre-college-summer-program-at-skidmore": { blurb: "A five-week, credit-bearing summer program at Skidmore College where high school students take foundation-level courses from the college's summer session for full college credit. Residential students are rising juniors or seniors aged 16 or 17 who take two courses and live in a hall set aside for the program, while commuters can be rising sophomores through seniors aged 15 to 18. Scholarships are awarded for financial need and academic merit." },
  // https://precollege.syr.edu/programs-courses/summer-college-residential/
  "syracuse-university-summer-college": { blurb: "Syracuse University's long-running pre-college program lets high school students take college-level courses, for credit or noncredit. On-campus students take a course, live in a residence hall and eat in a dining hall in July, and there are also online and commuter options in Los Angeles and New York City. The on-campus program is open to students 15 or older with a 3.0 GPA, and partial merit and need-based scholarships are offered." },
  // https://pharmacy.buffalo.edu/summercamp.html
  "university-at-buffalo-school-of-pharmacy-and-pharmaceutical-scie": { blurb: "A three-day summer institute at the University at Buffalo School of Pharmacy and Pharmaceutical Sciences for high school and college students interested in pharmacy. Students do lab work, patient-care simulations, mock vaccine administration and Narcan training, meet current pharmacy students and tour campus. Days run 9:00 a.m. to 3:00 p.m. in July, the cost is $150, no pharmacy background is needed, and applicants need at least a 3.0 GPA." },
  // https://www.rochester.edu/newscenter/pre-college-summer-courses-sneak-peek-campus-life-690682/
  "university-of-rochester-pre-college-programs-at-the-university-o": { blurb: "The University of Rochester runs one- to three-week summer courses for students in grades 9 to 12, taught by faculty and doctoral students from several of its schools. Most are half-day, while Explorations in Pathology and Mini Medical School are full-day, and options include business and engineering classes on campus and online classes in biotechnology and video game design. Rising 11th and 12th graders can also take credit courses." },
  // https://precollege.unca.edu/
  "university-of-north-carolina-at-asheville-pre-college-summer-pro": { blurb: "UNC Asheville runs one-week residential summer programs in June that introduce rising high school sophomores, juniors and seniors to college study. Each student picks a subject such as ceramics, creative writing, songwriting, engineering and mechatronics, meteorology, pre-med, river ecology, game design and AI, or app development, and lives in campus housing. The 2026 price of $1,460 to $1,840 covered lodging, meals, materials, activities and excursions." },
  // https://www.jou.ufl.edu/summermediainstitute/
  "university-of-florida-college-of-journalism-and-communications-s": { blurb: "A five-night, six-day summer workshop run by the University of Florida College of Journalism and Communications, where high school students are immersed in journalism and communications. Courses include broadcast reporting, anchoring and hosting, and social media, and a separate sports week covers sports broadcasting and play-by-play. Students live in campus dorms in Gainesville in June, and the program has run for over forty years." },
  // https://expandedlearning.ceismc.gatech.edu/summer-programs/sessions/high-school
  "georgia-institute-of-technology-high-school-sessions-at-ceismc": { blurb: "Georgia Tech's CEISMC runs Summer PEAKS, one- to two-week day programs in Atlanta where high school students take advanced sessions in design, engineering and applied problem-solving. Past high school topics include Hack-a-Drone and sensor design and AI. Days usually run 9 a.m. to 3 p.m., with extended care available for an extra fee, and the 2026 cost was $440 to $550 per program depending on topic and length." },
  // https://grady.uga.edu/outreach/
  "university-of-georgia-high-school-outreach-at-grady-college": { blurb: "The University of Georgia's Grady College runs journalism and media outreach for high school students. Its Summer Media Academy is a weeklong, in-person camp for ages 14 to 17 with tracks in advertising and PR, broadcast journalism, multimedia journalism, and entertainment and media studies, capped at 20 participants per week with limited need-based aid. Grady also founded the Georgia Scholastic Press Association, which runs a weeklong residential Georgia Journalism Academy." },
  // https://immersion.summer.wfu.edu/faq/
  "wake-forest-university-summer-immersion-program": { blurb: "A pre-college program at Wake Forest University where current 9th to 12th graders spend a week on the Winston-Salem campus studying a field such as AI, engineering, finance and investing, filmmaking, law, medicine or sports business. Sessions run Sunday to Friday in June and July with overnight stays, and each institute costs $3,500 per week, with limited need-based scholarships. Courses are non-credit, and participants receive a certificate of completion." },
  // https://www.ccad.edu/academics/college-preview
  "columbus-college-of-art-and-design-college-preview-program": { blurb: "A two-week summer program at Columbus College of Art & Design for high school students in grades 10 to 12, held in July, where each student chooses a major area of study. Students who complete it earn 3 non-major elective art credits and have their CCAD application fee waived. The 2026 cost was $3,600 for residential students, covering tuition, fees, and room and board, and $3,000 for commuters." },
  // https://drexel.edu/academics/pre-college-programs/summer-institutes
  "drexel-university-summer-institutes-at-drexel": { blurb: "Drexel University's pre-college summer institutes give motivated high school students a chance to explore college life, mostly on the University City campus in Philadelphia. Programs span arts and sciences, business and entrepreneurship, design, arts and media, engineering and computing, medicine, nursing and health professions, and public health. Examples include a one-week BIOMED Summer Academy and Camp Business, with commuter and residential sessions." },
  // https://www.gettysburg.edu/offices/conference-event-services/summer-programs/civil-war-summer-camp
  "gettysburg-college-summer-programs-at-gettysburg-college": { blurb: "Gettysburg College hosts summer camps for high school students, including the Young Civil War Historians Conference, a June camp run by its Civil War Institute for rising juniors and seniors. Students use battlefield landscapes, original documents and monuments as historical sources, and much of the week is spent exploring Gettysburg National Military Park. The camp fee is $1,395 plus a $50 application fee, and scholarships are available." },
  // https://www.susqu.edu/academics/summer-pre-college-programs/
  "susquehanna-university-summer-pre-college-programs-at-susquehann": { blurb: "Susquehanna University runs week-long summer pre-college programs where high school students work with faculty and student mentors in the arts, business, humanities and sciences. Options include a Summer Writers Workshop, a Publishing and Editing Institute, a Health Careers Institute, a residential Choral Institute and an Orchestra Summit, with sessions in June and July. Participants earn a visit grant that can be applied toward future Susquehanna tuition." },
  // https://www.clemson.edu/summer/camps/
  "clemson-university-summer-camps-at-clemson": { blurb: "Clemson's summer catalogue for high schoolers includes C-CATS, a weekend program for high-achieving middle and high school students from South Carolina, North Carolina and Georgia, held at Camp Hannon in Sunset, S.C. Students nominated by school counselors build test-taking, critical thinking and personal branding skills alongside team-building and high-adventure activities. The catalogue also lists a Finance Summer Immersion Program in July at $3,000 per student." },
  // https://www.landmark.edu/academics/summer
  "landmark-college-summer-programs-at-landmark-college": { blurb: "Landmark College, which specializes in students who learn differently, runs a High School Summer Program in July that introduces rising juniors and seniors ages 16 to 18 to college living and learning. Students take a Blueprint for Learning seminar on executive function, a writing class and an elective, and a social pragmatics track adds PEERS social skills instruction. A separate Summer College Readiness Program serves graduating seniors admitted to a four-year college." },
  // https://www.hollins.edu/academics/pre-college-experiences-camps/hollins-summer-program/
  "hollins-university-hollinsummer": { blurb: "A pre-college summer program at Hollins University that brings rising 9th to 12th grade young women to its Roanoke, Virginia, campus for a week in July. Students choose a track in creative writing, riding, sciences or leadership, and the writing track covers fiction, poetry and personal narrative. Residential tuition is $1,250 ($1,400 for riding), and day tuition is $550 ($900 for riding)." },
  // https://neurorobotics.ece.utah.edu/high-school-students/
  "university-of-utah-neurorobotics-summer-enrichment-program": { blurb: "A two-month summer research placement in the Utah NeuroRobotics Lab at the University of Utah, run by the lab's partner company NeuroRobotic Technologies. Only 1 to 2 high school students are selected each year, with priority for those preparing for undergraduate study at the University of Utah or from diverse backgrounds. Qualified applicants typically have AP or IB STEM courses and experience in programming, CAD or 3D printing, or microcontrollers. Tuition starts at $4000." },
  // https://www.redcross.org/local/utah/volunteer/leadership-development-camp.html
  "american-red-cross-of-utah-leadership-development-camp": { blurb: "A five-day overnight leadership camp run by the American Red Cross at Camp Pinecliff near Coalville, Utah, for residents of Utah and southwest Wyoming currently in 9th, 10th or 11th grade. Campers build skills in leadership, teamwork, public speaking and cultural understanding, and learn how the Red Cross responds to disasters. The fee is $300, with discounts for those who qualify, and graduates can apply to return as student staff." },
  // https://dpi.illinois.edu/tech-talent-development/high-school-and-community-college-student-programs/digital-scholars
  "discovery-partners-institute-university-of-illinois-digital-scho": { blurb: "A free six-week summer computing program run by the University of Illinois Discovery Partners Institute in downtown Chicago for rising 11th and 12th graders and incoming college freshmen. Students meet in person daily from 9:00 a.m. to 1:00 p.m. in tracks such as Data Science Discovery, Foundations of Computer Science and Coding, and iOS App Design. They also hear from tech entrepreneurs and civic leaders and attend weekly workshops on topics such as AI." },
  // https://www.architecture.org/events-programs/teen-fellows
  "chicago-architecture-center-teen-fellows": { blurb: "A free 15-month architecture program at the Chicago Architecture Center for incoming sophomores, juniors and seniors who attend high school in Chicago and the surrounding area. Participants take college courses at Harold Washington College, build physical models, learn design software such as Revit and Rhino, and visit architecture firms. Fellows meet on Saturdays in fall and spring, earn a stipend, and can intern at a local firm in the final summer." },
  // https://www.saic.edu/high-school-programs/early-college-program-summer-institute
  "school-of-the-art-institute-of-chicago-early-college-program-sum": { blurb: "A summer studio program at the School of the Art Institute of Chicago for high school students ages 15 to 18 who have completed their sophomore year. Classes run Monday through Friday from 9:00 a.m. to 4:00 p.m., with evening workshops and a final-day exhibition, and faculty guide students in building a portfolio. Students earn one college credit for each week attended, and tuition is $1,908 for a one-week session, with housing and meals billed separately." },
  // https://cmap.illinois.gov/engagement/future-leaders-in-planning/
  "chicago-metropolitan-agency-for-planning-future-leaders-in-plann": { blurb: "A free five-day summer program from the Chicago Metropolitan Agency for Planning that introduces high school students from Cook, DuPage, Kane, Kendall, Lake, McHenry and Will counties to urban and regional planning. Sessions at the agency's downtown Chicago office run from 10 a.m. to 4 p.m. and cover accessibility, climate planning, GIS, transportation funding and careers, ending with a final project open house. Meals, materials and public transit to sessions are included." },
  // https://www.utc.edu/health-education-and-professional-studies/school-of-education/about/grants-partnerships-and-affiliations/governors-school-for-prospective-teachers
  "university-of-tennessee-at-chattanooga-governors-school-for-pros": { blurb: "One of the Tennessee Governor's Schools, hosted at the University of Tennessee at Chattanooga for rising 11th and 12th graders from across the state who are nominated by high school faculty and are considering teaching. Students spend most of June on campus studying the myths and realities of the education profession, effective teaching strategies, and observation and critique of teaching. They also gain practical experience, such as teaching younger children at a camp." },
  // https://www.otis.edu/extension/youth-programs/summer-art/index.html
  "otis-college-of-art-and-design-summer-of-art": { blurb: "A four-week pre-college art and design program at Otis College of Art and Design for high school students ages 14.5 to 19, held in July. Classes run Monday through Friday from 9:00 a.m. to 4:45 p.m., and students choose a specialization, a drawing studio or both. Full-day students who complete the program can receive three college credits, housing with dining is available for an added cost, and scholarships consider need, portfolio and academic achievement." },
  // https://summer.ucla.edu/student-types/high-school-students/
  "university-of-california-los-angeles-high-school-summer-sessions": { blurb: "UCLA Summer Sessions lets high school students 15 years of age or older enroll in one or two regular UCLA courses alongside university students, with online, hybrid and in-person options. Approved subjects include anthropology, computer science, economics, film, music, psychology and Spanish, and students can take up to 10 units per session. Related options include the three-week Summer Precollege Focus Series and the six-week Summer College Immersion Program." },
  // https://www.summer.ucsb.edu/programs/pre-college
  "university-of-california-santa-barbara-pre-college-programs-at-u": { blurb: "UC Santa Barbara Summer Sessions runs pre-college programs that place high school students in university research and coursework. The Research Mentorship Program serves 10th and 11th graders with a minimum 3.80 weighted GPA, while Summer Research Academies admits 9th through 11th graders with a 3.60 weighted GPA minimum to a 4-unit university course in a STEM, humanities or social science track. Students can also take regular UCSB courses through open enrollment." },
  // https://www.pacific.edu/about-pacific/summer/precollege-summer-program
  "university-of-the-pacific-summer-high-school-institute": { blurb: "A two-week residential summer program on University of the Pacific's Stockton campus, offered in two sessions each summer. High school students take non-credit courses from college faculty in the arts, health and science, engineering and technology, business and athletics, working in Pacific's labs, studios, fields and makerspaces. Participants live in the same residence halls as college students, eat in the campus dining center and join evening recreation." },
  // https://www.newhaven.edu/admissions/pre-college/summer-youth/index.php
  "university-of-new-haven-summer-youth-academies": { blurb: "A series of week-long summer academies at the University of New Haven in July, with day programs from 8:30 a.m. to 4:30 p.m. and lunch included. Topics include crime scene investigation, health professions, Model United Nations, interior design and nutrition sciences, and some academies award college credit. Day rates range from $600 to $900, and some academies offer an overnight option in a residence hall with evening social activities." },
  // https://www.udel.edu/apply/undergraduate-admissions/precollege-programs/
  "university-of-delaware-pre-college-programs-at-the-university-of": { blurb: "The University of Delaware's hub for pre-college programs for high school students. Options include one-week noncredit summer programs in forensic science, neuroscience and autonomous driving, the residential Edge Summer College Program for rising juniors and seniors, and the free College Readiness Scholars Institute for Delaware students in grades 9 to 12. The list also includes dual enrollment and the Diamond Challenge entrepreneurship competition." },
  // https://www.scad.edu/academics/pre-college-programs
  "savannah-college-of-art-and-design-scad-pre-college-programs": { blurb: "Pre-college art and design programs at the Savannah College of Art and Design for high school students. Rising Star is a four-week residential program in Savannah and Atlanta where rising seniors take two college-level classes for credit. Summer Seminars are one-week non-credit workshops for students finishing 9th through 11th grade, with a US$100 fee per session, and eligible students can also take university courses through joint enrollment." },
  // https://www.spelman.edu/academics/summer-programs/index.html
  "spelman-college-summer-programs-at-spelman-college": { blurb: "Spelman College runs residential pre-college summer programs for high school students each June and July. The two-week College Prep Institute offers college application, test prep and leadership workshops at $3,150 per session, and the four-week Early College Program lets 11th-grade girls earn college credit in English, Biology or Dance. Spelman does not offer scholarships or financial aid for summer program enrollment." },
  // https://www.iit.edu/academics/pre-college-programs/summer/residential/computational-science-course
  "illinois-institute-of-technology-elevate-college-prep-summer-pro": { blurb: "A summer computational science course in Illinois Tech's Elevate College Prep program for rising 10th to 12th graders, offered in residential and daytime formats in July. Students integrate math and science with computation using tools such as Mathematica, through hands-on activities and minimal lecturing, and Algebra II is recommended. Completers earn two college credits for SCI 111, and residential students must be at least 15 years old." },
  // https://www.wku.edu/cpd/summercamps.php
  "western-kentucky-university-summer-camps-at-wku": { blurb: "Western Kentucky University's Continuing and Professional Development office lists summer camps for middle and high school students in June and July. Options include a residential High School Personal Finance Camp for grades 10 to 12, Python coding camps for grades 7 to 11, Leaders in Law for ages 14 to 18, and Camp CARE, a $199 healthcare day camp for ages 13 to 15. A Criminal Justice Camp and the Hilltopper Summer Music Camp are also listed." },
  // https://www.lsu.edu/summer/highschool.php
  "louisiana-state-university-summer-camps-for-teens-at-lsu": { blurb: "LSU's summer catalogue for high school students, covering academic, music and athletic camps on campus. Options include a one-week residential architecture camp for students entering grades 10 through 12, the Cain Center's High School Summer Academy for ages 15 to 18, residential engineering programs for grades 9 to 12, and the LSU Bands Summer Music Camp. Selected 9th to 11th graders can also join faculty research teams through the High School Summer Research program." },
  // https://www.xula.edu/pre-college-programs/
  "xavier-university-of-louisiana-pre-college-programs-at-xavier-un": { blurb: "Xavier University of Louisiana runs summer pre-college programs in math and science for middle and high school students. The Star Programs, including CHEMStar, BIOStar, PHYStar and two MATHStar courses, prepare students the summer before they take the matching course and cost $600 to $650. SOAR X is a four-week residential program for rising 11th and 12th graders that succeeds the SOAR program founded in 1977, and the STEM Academy serves rising 6th to 8th graders." },
  // https://www.summer.uw.edu/who-can-attend/us-high-school-students
  "university-of-washington-high-school-summer-sessions-at-uw": { blurb: "University of Washington Summer Sessions let U.S. high school students enroll in regular UW courses for college credit. Students who have completed eighth grade by June 30 can apply, and the UW suggests 100-level courses for most high schoolers, with higher-level courses open when prerequisites are met. Students under 18 need a signed parent or guardian form, and credits are generally transferable to other schools." },
  // https://sites.krieger.jhu.edu/brbt/about/
  "johns-hopkins-university-biophysics-research-for-baltimore-teens": { blurb: "A paid summer research internship at Johns Hopkins University where Baltimore City public high school students work in biophysics research labs on the Homewood Campus. Interns prepare reagents and materials for biophysical studies, then move into microbiology techniques and DNA and protein engineering, while taking coursework in scientific writing, data analysis, mathematics and bioethics. The program runs from early July to early August, 25 hours per week, Monday to Friday." },
  // https://www.colorado.edu/business/oda/programs-high-school-students/business-leadership-program
  "university-of-colorado-boulder-leeds-school-of-business-business": { blurb: "A free, week-long summer program run by the Opening Doors to Achievement office at CU Boulder's Leeds School of Business for Colorado high school juniors. Students work in teams to build a marketing campaign for corporate partners and present it in a case competition, and the winning team earns a $1,000 scholarship to Leeds. Applicants must live in Colorado or attend a Colorado high school, and the program takes place in late June." },
  // https://www.mines.edu/undergraduate-admissions/summer-mines-engineering-and-training-summet/
  "colorado-school-of-mines-summet-program": { blurb: "A one-week residential engineering, science and technology program at Colorado School of Mines for rising high school seniors who are prospective first-generation college students. Students work in groups on a main design project, join mini-workshops with departments such as mechanical engineering and chemistry, and tour the Edgar Experimental Mine. There is no application fee, and after a $50 confirmation fee Mines covers other costs, including room and board." },
  // https://engineering.arizona.edu/k12/k12_SEA
  "university-of-arizona-college-of-engineering-engineering-camps-f": { blurb: "The Summer Engineering Academy at the University of Arizona College of Engineering is a series of summer camps where high school students take on engineering design challenges. Camp themes include service through engineering, women in engineering, semiconductors, grand challenges and disaster response, with residential and day options in June and July. Most camps are open to grades 8 to 11 or 10 to 11, and no prior engineering experience is required." },
  // https://wyse.grainger.illinois.edu/summer-programs/summer-camps
  "university-of-illinois-grainger-college-of-engineering-wyse-summ": { blurb: "Worldwide Youth in Science and Engineering, the pre-college outreach unit of the Grainger College of Engineering at the University of Illinois Urbana-Champaign, runs engineering summer camps for rising 7th to 12th graders of all genders. Camps come in residential and commuter formats, including a week-long camp that introduces rising 9th to 12th graders to the disciplines of engineering, listed at $1,500 for residential and $750 for commuter students." },
  // https://spartanyouth.msu.edu/
  "michigan-state-university-spartan-youth-programs": { blurb: "Michigan State University's central directory of youth programs, listing summer and other learning options for students through high school that can be searched by program. High school listings include the residential High School Engineering Institute for grades 9 to 12, the Math, Science, Technology, and Leadership program, the residential Physics of Atomic Nuclei program in late July, a Teacher Education Academy, dual enrollment, Model United Nations and sports camps." },
  // https://www.umt.edu/trio-upward-bound/services/summer.php
  "university-of-montana-upward-bound-summer-academy": { blurb: "A free six-week college prep program run by TRIO Upward Bound at the University of Montana that simulates the college experience for students at Big Sky, Browning, Heart Butte, Hellgate and Sentinel high schools. Students take classes that help with their upcoming high school curriculum, and incoming juniors and seniors take College Success, a 2-credit college course, at no cost. Participants are generally potential first-generation or income-eligible students aged 13 to 19." },
  // https://jabsom.hawaii.edu/research/trainees/high-school-and-undergraduate-opportunities-in-research.html
  "university-of-hawaii-john-a-burns-school-of-medicine-high-school": { blurb: "The medical school's page of research placements for high school and undergraduate students in Hawaii. For high school juniors and seniors it lists Pacific STEP-UP, an NIH/NIDDK funded program of about 8 weeks from mid-June to mid-August in which students work with an investigator near home and take an all-paid trip to the NIH campus in Bethesda, Maryland to present their work. The Queen's Medical Center Summer Research Internship listed there is for undergraduates." },
  // https://labor.hawaii.gov/wdd/intern/hele-imua/
  "hawaii-department-of-labor-and-industrial-relations-hele-imua-st": { blurb: "A paid internship program run by the Hawaii Department of Labor and Industrial Relations Workforce Development Division that places students and recent graduates in internships of up to 12 weeks, mainly in state government. Applicants must be Hawaii residents aged 16 or older who attend a public high school or accredited college, or finished one within the past year, with a cumulative GPA of at least 2.5. Interns are paid by the department." },
  // https://chu.house.gov/congressional-youth-advisory-council
  "congresswoman-judy-chu-congressional-youth-advisory-council-cyac": { blurb: "A youth council run by the office of Congresswoman Judy Chu for high school students who live in California's 28th District and are entering grades 9 through 12. Members discuss issues facing young people and work with her staff and community leaders on how the federal government can help. The council holds eight sessions during the school year, mostly on Zoom from 4 to 5 p.m. Pacific, with a final required session in person, and terms last one year." },
  // https://walton.uark.edu/future-students/summer-programs.php
  "sam-m-walton-college-of-business-university-of-arkansas-fleische": { blurb: "The Fleischer Scholars Program is a free six-day summer program on the University of Arkansas campus in Fayetteville for first-generation Arkansas high school juniors interested in studying business. Participants explore business career paths, build an entrepreneurial mindset, visit local companies and network with Walton College students, faculty and alumni. Selection weighs first-generation status, academic performance, leadership, community service and financial need." },
  // https://inl.gov/education/stem/students/summer-camps/
  "idaho-national-laboratory-stem-scholars-summer-camps": { blurb: "Free summer camps run by Idaho National Laboratory's STEM Scholars program for students in grades one through 12, held in four-day sessions during June and July. High school camps have included CyberCore, which covers computer programming, networking and cybersecurity, and a Clean Energy camp on topics from electric vehicles and advanced batteries to rare earth elements and bioenergy. Learning materials are provided, and high demand has led the lab to use a lottery." },
  // https://www.uwyo.edu/physics/summer-science-camps.html
  "university-of-wyoming-physics-and-astronomy-summer-science-camps": { blurb: "The Teton STEM Academy is a summer camp run by the University of Wyoming Department of Physics and Astronomy for students entering grades 9 through 11 with interest and academic potential in math, science, astronomy and space. Applicants need at least a B average in science and mathematics, passing state test scores in those subjects, and essays. The camp runs in July, and the department page lists a $75 registration fee." },
  // https://www.jshs.org/region/virtual/
  "junior-science-and-humanities-symposium-virtual-jshs": { blurb: "The Virtual Region of the Junior Science and Humanities Symposium, a research competition, serves students in grades 9 to 12 who cannot attend an in-person event or do not live in a JSHS region. Public, private and home school students who are U.S. citizens or lawful permanent residents can take part, and there is no cost to register or participate. Students may enter only one region, and regional finalists are invited to the national symposium." },
  // https://www.msfinancialaid.org/mtag/
  "mississippi-office-of-state-financial-aid-mississippi-tuition-as": { blurb: "A need-based state grant for Mississippi residents enrolling full-time at approved in-state colleges in a program leading to a first certificate, associate's or bachelor's degree. Students eligible for less than the maximum Federal Pell Grant can receive up to $500 per year as freshmen and sophomores and up to $1,000 per year as juniors and seniors. Applicants need a cumulative GPA of 2.5, and awards last up to 8 semesters or degree completion." },
  // https://www.builddakotascholarships.com/about/
  "build-dakota-build-dakota-scholarship": { blurb: "A scholarship for students accepted into eligible high-need programs at South Dakota's four technical colleges, paying for required program costs such as tuition, fees, books, equipment, technology and tools, but not housing or living expenses. In-state and out-of-state students of all ages can apply. Recipients complete the FAFSA, enroll full time, finish on schedule and commit to work in South Dakota in their field for three years after graduation." },
  // https://sternberg.fhsu.edu/education-outreach/science-camps/high-school.html
  "sternberg-museum-of-natural-history-fort-hays-state-university-s": { blurb: "Summer field and lab science camps run by the Sternberg Museum of Natural History at Fort Hays State University, where high school students prospect for and excavate fossils and work with specimens in the lab. Programs include a two-week field paleontology camp based at the museum in Kansas, trips to fossil sites in Utah, Nevada and North Dakota, and cave fieldwork in Tennessee. Fees vary by program, and scholarships of $200 per week go to households earning $149,999 or less." },
  // https://www.fieldmuseum.org/activity/high-school-science-and-digital-learning-internship
  "field-museum-high-school-science-and-digital-learning-internship": { blurb: "A paid summer internship at the Field Museum in Chicago where 15 Chicagoland high school students meet museum researchers and then choose one to work with on a 5-week project. Interns also learn technology and digital media skills and take part in professional development. The internship runs from mid-June to late July, Monday through Thursday from 10 a.m. to 4 p.m., and pays $17.25 per hour." },
  // https://www.mfa.org/programs/teen-programs/teen-arts-council
  "mfa-boston-teen-arts-council": { blurb: "A paid leadership program at the Museum of Fine Arts, Boston, for students in grade 10, 11, or 12 who live in Boston or attend Boston Public Schools. Members act as museum ambassadors, design teen experiences, and run teen-led tours, the Beyond the Soundcheck performance series, and an end-of-year Teen Night. The council pays $15 per hour and meets Thursdays from 4 to 6:30 pm from October to May, plus Sunday events in the spring." },
  // https://www.nga.gov/educational-resources/teen-programs
  "nga-teen-leadership-collective": { blurb: "A paid program at the National Gallery of Art for up to six teens ages 15 to 19 who live in Washington, DC. Participants work with other teens and Gallery staff to design and contribute to a public workshop, with artmaking, group discussions, mindfulness, and visits with local creatives about careers. The group meets on Saturdays in the fall, and teens can earn up to $1,000. No prior art experience is required." },
  // https://www.meritbaltimore.org/scholarapp
  "merit-health-leadership-academy": { blurb: "A three-year program run by MERIT Health Leadership Academy at CollegeBound Foundation for Baltimore City public high school sophomores interested in health careers. Scholars attend Saturday classes during the school year, complete paid summer internships in hospitals and labs, and receive mentorship and college admissions guidance, including a sophomore trip to visit colleges. Applicants need an unweighted GPA of at least 3.0." },
  // https://thesca.org/program/urban-green/seattle
  "student-conservation-association-urban-green-seattle": { blurb: "A paid summer conservation program from the Student Conservation Association where high school students and recent graduates work on crews in Seattle-area parks and natural areas. Crews typically work 35 hours per week under two adult crew leaders on conservation projects around western Washington, including environmental education field trips. Positions run from July to August." },
  // https://thesca.org/program/urban-green/atlanta
  "student-conservation-association-urban-green-atlanta": { blurb: "A paid summer crew program from the Student Conservation Association for Atlanta high school students ages 14 to 18. Crew members build and rehabilitate trails, manage natural resources and improve parks at national and state park sites around Atlanta, with some Saturday workdays and special events. An adult field leader aged 21 or older supervises and trains the crew, and the 2026 crew ran in June and July at $13 an hour." },
  // https://thesca.org/program/urban-green/cleveland
  "student-conservation-association-urban-green-cleveland": { blurb: "Paid six-week summer crew positions from the Student Conservation Association for Cleveland high school students ages 14 to 18, running June to August. Each crew focuses on its own goals, such as removing invasive species, restoring habitat, building or maintaining trails, and urban forestry. Adult crew leaders supervise and train the crews in the field, and past crews have built trails with Cleveland Metroparks." },
  // https://thesca.org/program/urban-green/pittsburgh
  "student-conservation-association-urban-green-pittsburgh": { blurb: "A six-week paid summer program from the Student Conservation Association for Pittsburgh high school students ages 14 to 18, from late June to early August. Crews of 10 members and two adult leaders work 30 hours a week, Monday through Friday, improving trails, removing invasive species and tending community gardens. It runs with the City of Pittsburgh's Learn and Earn program, and successful participants may qualify for fall and spring jobs." },
  // https://thesca.org/program/pennsylvania-outdoor-corps
  "student-conservation-association-pennsylvania-outdoor-corps": { blurb: "Paid conservation crews on Pennsylvania public lands, run by the Student Conservation Association with the state Department of Conservation and Natural Resources. High school students ages 15 to 18 serve on summer youth crews led by trained field leaders, gaining paid service experience and job training. In 2025 the program fielded 18 summer youth crews, including an American Sign Language crew based in Pittsburgh and Philadelphia." },
  // https://ato.montana.edu/ywp/youth/
  "yellowstone-writing-project-montana-state-university-youth-writi": { blurb: "A multi-day unschooled writing workshop at Montana State University in Bozeman, led by Yellowstone Writing Project teachers and junior counselors. Campers write in several genres, share their work with teacher consultants who are licensed educators, and can publish in a group anthology before a closing showcase. The July camp runs 9:00 a.m. to 3:00 p.m. for students entering grades 5 to 12, with commuter tuition from $350 and a residential option." },
  // https://serve.mt.gov/commission-initiatives/youth-serve-montana-scholarships
  "governors-office-of-community-service-montana-youth-serve-montan": { blurb: "A college scholarship from the Governor's Office of Community Service for Montana high school seniors who volunteer, funded with Reach Higher Montana and the Montana Campus Network for Civic Engagement. The 2026-27 cycle offers $1,500 to up to 90 seniors who completed 100 or more service hours in the prior 12 months. Recipients must attend a Montana Campus Network member college and complete a FAFSA, and the award is paid to the college's financial aid office." },
  // https://regionalcampuses.uams.edu/health-careers/high-school-students/mash/
  "uams-regional-campuses-m-a-s-h-summer-enrichment-camp": { blurb: "A free two-week summer enrichment camp run by UAMS Regional Campuses and sponsored by Arkansas Farm Bureau at sites across Arkansas. Students in 11th or 12th grade who have completed a biology course take part in CPR training, heart dissection, suturing workshops, field trips and volunteer service. Selection is based on recommendation letters, achievements, extracurricular activities and an essay, and some sites require a 3.0 GPA." },
  // https://www.salk.edu/about/education-outreach/programs/
  "salk-institute-for-biological-studies-salk-education-outreach-hi": { blurb: "Education programs at the Salk Institute in La Jolla for high school students. High School Science Day is a free day of science talks, lab activities and a career panel for 150 to 250 Southern California students each year. The Heithoff-Brody High School Summer Scholars program is an eight-week paid summer internship where students 16 and older who live and attend school in San Diego County do research with Salk mentors and present at a symposium." },
  // https://summer.harvard.edu/high-school-programs/secondary-school-program/
  "harvard-university-harvard-summer-school-high-school-programs": { blurb: "Harvard Summer School's programs for high school students include the Secondary School Program, where students take college-credit courses taught by Harvard faculty. Students pick a 4-week session with one accelerated course or a 7-week session with one or two courses, on campus, online or as commuters, from more than 200 courses. Students must be at least 16, and 2027 costs range from $4,180 to $15,980 depending on format and credits." },
  // https://precollege.berkeley.edu/
  "university-of-california-berkeley-uc-berkeley-pre-college-schola": { blurb: "A summer program at UC Berkeley where high school students take college-level courses during the summer sessions. The residential track houses students on campus with meals, excursions and activities while they take two lower-division courses, and the commuter track serves Bay Area students who return home each day. Applicants must have completed 10th or 11th grade, hold a 3.0 average and be at least 16, and fees are charged per unit." },
  // https://www.shoalsmarinelaboratory.org/academics
  "shoals-marine-laboratory-cornell-university-and-the-university-o": { blurb: "College-level marine science courses for high school students at Shoals Marine Laboratory on Appledore Island, Maine, run jointly by Cornell and the University of New Hampshire. Options include Marine Environmental Science for 4 Cornell credits, a shark, skate and ray biology course for two credits, and a lab course where students design intertidal research projects. Students who have completed grades 10, 11 or 12 can apply, and cost varies by credits and course length." },
  // https://precollege.dartmouth.edu/programs/precollege-summer-scholars
  "dartmouth-college-dartmouth-precollege-summer-scholars": { blurb: "A non-credit, two-week summer program on the Dartmouth campus in Hanover where high school students take one intensive course per session, taught mostly by Dartmouth faculty and staff. Recent subjects include business, data science, medicine, creative writing, entrepreneurship, AI and clean energy. Residential students live in campus halls, commuter and hybrid options exist, and the program is for rising 10th to 12th graders ages 15 to 18." },
  // https://www.prepare-ri.org/internships
  "prepareri-prepareri-internship-program": { blurb: "A paid summer internship program for juniors at Rhode Island public and public charter high schools, funded by the Governor's Workforce Board and run by Skills for Rhode Island's Future, which matches students with employers. Interns start with a 40-hour paid work-readiness bootcamp, then work at least 150 hours over 6 weeks in July and August. Students must be at least 16, earn college credit, and take part at no cost." },
  // https://arts.princeton.edu/about/opportunities/high-school-contests/ten-minute-play-contest/
  "lewis-center-for-the-arts-princeton-university-princeton-univers": { blurb: "An annual playwriting contest from Princeton University's Lewis Center for the Arts, open only to 11th graders in the U.S. or the international equivalent, including home-schooled students. Each student may submit one play in English of up to 10 pages, and AI-generated plays are not allowed. A guest playwright judges, recent prizes were $500, $250 and $100, and the contest closes once 250 entries arrive." },
  // https://www.ymcala.org/programs/youth/government/model-legislature-court/
  "ymca-california-ymca-youth-and-government": { blurb: "A statewide civic education program run through local YMCAs, where California students in 9th to 12th grade join the Model Legislature and Court. Delegates write bills and argue court cases, meet weekly with their local group and gather twice a year for statewide events at Camp Roberts and in Sacramento, where they elect a Youth Governor. Costs vary by delegation, and financial assistance is available through local YMCAs." },
  // https://www.ymcayag.org/ct/
  "ymca-connecticut-ymca-youth-and-government": { blurb: "A model state government program for Connecticut middle and high school students, who usually join through a school or local YMCA delegation. Students take legislative, judicial, executive, media and lobbyist roles at a March state conference that includes a day at the State Capitol in Hartford. Student fees run from $435 to $750 depending on room type, financial aid of $50 to $250 is available, and no student is turned away for financial reasons." },
  // https://www.dcyag.org/get-involved/
  "ymca-district-of-columbia-ymca-youth-and-government": { blurb: "A civic program of the YMCA of Metropolitan Washington where high school students learn how public policy is made, taking roles such as mayor, council member, board of education member and press. Delegations from high schools and YMCAs attend a one-day fall Youth Summit on bill writing, mock trial and press corps, then a two-day spring Legislative Weekend. It is open to students in grades 9 to 12 in the Washington area." },
  // https://www.ymcayag.org/ma-hs/
  "ymca-massachusetts-ymca-youth-and-government": { blurb: "A model state government program for Massachusetts high school students in grades 9 to 12, with a separate middle school assembly. Students join through a school or YMCA delegation and take legislative, executive or media roles, and legislators write and debate a bill on a state policy issue at a spring assembly in Boston. Registration is $425, covering training, hotel rooms for both nights and both dinners, and need-based scholarships are available." },
  // https://www.nmyag.org/about
  "ymca-new-mexico-ymca-youth-and-government": { blurb: "A non-partisan civics program for New Mexico high school students run by the YMCA of Central New Mexico. Most delegates join the House or Senate in the Legislative Branch, while others argue appellate cases before a mock Supreme Court or apply for the Media or the Governor's or Attorney General's cabinets. The year includes orientation, regional training and a spring conference, with overnight programs at Glorieta Adventure Camps." },
  // https://sstfi.org/register/
  "state-science-and-technology-fair-of-iowa-state-science-and-tech": { blurb: "Iowa's statewide science fair, run by Iowa 4-H and Iowa State University Extension and affiliated with Regeneron ISEF. Students in grades 6 to 12 who live in or attend school in Iowa, including homeschoolers, present original research projects, and no qualifying fair is required first. The fair is held each spring at Hilton Coliseum in Ames, and top projects can earn trips to Regeneron ISEF." },
  // https://www.umt.edu/montana-science-fair/fair-info/
  "university-of-montana-montana-science-fair": { blurb: "Montana's ISEF-affiliated science fair, held at the University of Montana in Missoula since 1955. High school students in grades 9 to 12 compete in Division I, and middle schoolers in grades 6 to 8 compete in Division II, presenting research projects to judges each March. Top Division I finishers can earn expenses-paid trips to ISEF, and the registration fee is $30 per student." },
  // https://sites.google.com/student.nmt.edu/nmsef/home
  "new-mexico-tech-new-mexico-science-and-engineering-fair": { blurb: "New Mexico's state science and engineering fair, hosted each April at New Mexico Tech in Socorro for middle and high school students from across the state. Students follow their own interests and design experiments that follow the scientific method, then present posters to judges. Recent fairs have drawn more than 250 students, and the best projects go on to represent New Mexico at the International Science and Engineering Fair (ISEF)." },
  // https://www.mathily.org/facts.html
  "mathily-mathily": { blurb: "A five-week residential summer program at Bryn Mawr College for mathematically talented high school students, built around discrete mathematics and inquiry-based teaching. Students work on combinatorics, graph theory, affine geometry and theoretical linear algebra, with classes about seven hours a day, six days a week, led by a Ph.D. mathematician. Admission is selective and includes an exam assessing readiness." },
  // https://www.naqt.com/hsnct/
  "naqt-national-academic-quiz-tournaments": { blurb: "The quiz bowl organization behind local, state and national tournaments for American high schools, where teams buzz in to answer academic questions. Teams qualify for the High School National Championship Tournament by finishing in the top 15% at local varsity tournaments on NAQT questions or by winning non-NAQT state championships. The national event is held in Atlanta at the end of each school year, and 320 teams competed in 2026." },
  // https://usagermanyscholarship.org/about-cbyx/
  "cbyx-congress-bundestag-youth-exchange": { blurb: "A fully funded exchange scholarship from the U.S. Department of State and the German Bundestag that sends American high school students to Germany for an academic year. Students live with a host family, attend a German high school, take language lessons and visit the Bundestag. The scholarship covers round-trip travel, medical benefits, host-family lodging and meals, tuition if required and a small monthly stipend, and 210 scholarships are available." },
  // https://think.mit.edu/static_files/THINK_Program_Guidelines_2026.pdf
  "mit-think-scholars": { blurb: "A STEM research and invention proposal competition run by MIT undergraduates as part of MIT TechX. Full-time high school students with permanent U.S. residency submit a project proposal, alone or in pairs, explaining how funding and mentorship would help. Up to six finalists receive an all-expenses-paid trip to MIT, weekly mentorship from MIT students and up to $1,000 to carry out the project in the spring, documented in weekly progress reports." },
  // https://med.stanford.edu/che/smysp.html
  "stanford-medical-youth-science-program-smysp": { blurb: "A tuition-free, five-week summer program in science and medicine on Stanford's campus for low-income, first-generation high school juniors who live in Northern California. Participants are mentored throughout by medical professionals, faculty and college students as they explore medicine and health. The program, funded by donations, invites 24 students each year and runs from June into July." },
  // https://www.questbridge.org/apply-to-college/programs/college-prep-scholars-program
  "questbridge-college-prep-scholars": { blurb: "A program from QuestBridge for high-achieving high school juniors from low-income backgrounds, with typical households earning under $65,000 for a family of four. Scholars can win full scholarships to college summer programs at schools such as Rice, UChicago and Yale, and $1,000 Quest for Excellence Awards for things like a laptop or campus visits. They also get a head start on the National College Match, which offers full four-year scholarships at 55 college partners." },
  // https://www.artandwriting.org/programs/national-student-poets-program/
  "national-student-poets-program": { blurb: "A national honor from the Alliance for Young Artists & Writers and the Institute of Museum and Library Services that names five high school poets each year, each representing a region of the country. Students in grades 10 or 11 who earn a Gold Key for poetry in the Scholastic Art & Writing Awards may be invited to apply. Selected poets serve a year as youth poetry ambassadors, leading service projects, workshops and readings, and each receives a $5,000 academic award." },
  // https://pprize.princeton.edu/faqs-0
  "princeton-prize-in-race-relations": { blurb: "An award run by Princeton University alumni volunteers that recognizes high school students for volunteer work advancing racial equity or understanding in their schools or communities. Any student in grades 9 to 12 at a U.S. school can apply for work done in the last 12 months, with a second part completed by an unrelated adult who knows the activity. Regional winners receive $2,500 and an all-expenses-paid trip to the Symposium on Race at Princeton." },
  // https://www.usafa.edu/admissions/summer-seminar/
  "usafa-summer-seminar": { blurb: "A summer program at the U.S. Air Force Academy in Colorado Springs that gives high school juniors a look at cadet life before they apply to a service academy. The $400 registration fee covers lodging, meals, supplies and seminar uniforms, while students fund and arrange their own travel to and from Colorado Springs. A limited number of scholarships may be available to help students attend." },
  // https://www.asmfoundation.org/students/materials-camps/eisenman/
  "asm-eisenman-materials-camp": { blurb: "A free one-week materials science camp run by the ASM Materials Education Foundation at ASM International headquarters in Materials Park, Ohio, for students entering 11th or 12th grade. Small teams carry out a forensic engineering investigation, identifying root causes and recommending fixes, with lab work, demonstrations and field trips guided by professional Materials Mentors. About 30 students are accepted each year, and meals and hotel lodging are covered." },
  // https://www.iacompetitions.com/vjvhistorybee/
  "national-history-bee-and-bowl": { blurb: "History quiz competitions run by International Academic Competitions, with the History Bee for individual students and the History Bowl for school teams. High school students compete at regional tournaments, and those finishing in the top 50% of their age division qualify for the National Championships, held each April in Arlington, Virginia. Online events are also offered, and competing in the Bee at nationals costs $159." },
  // https://www.csac.ca.gov/post/cal-grant-high-school-entitlement-award
  "cal-grant": { blurb: "California's main state college grant, run by the California Student Aid Commission. Through the High School Entitlement award, high school seniors and recent graduates who meet the requirements are guaranteed a Cal Grant, with no cap on the number of awards. Students apply by filing the FAFSA or California Dream Act Application (CADAA), and Cal Grant A requires a verified GPA of at least 3.0 while Cal Grant B requires 2.0, along with California residency and financial need." },
  // https://www.sachsfoundation.org/undergraduate-scholarships/
  "sachs-foundation-undergraduate-scholarship": { blurb: "A college scholarship from the Sachs Foundation for Black high school seniors who have been full-time Colorado residents for at least three years. Awards are based on academic merit, financial need and character, and are typically $10,000 to $12,500 a year, renewable for up to four years. Finalists attend a June program in Colorado Springs, where final award decisions are made." },
  // https://www.esuus.org/what-we-do/shakespeare-competition/national-shakespeare-competition-rules-and-eligibility/
  "esu-national-shakespeare-competition": { blurb: "A three-level performance competition from the English-Speaking Union of the United States in which high school students memorize and perform a Shakespeare monologue from the ESU's annual packet, adding a sonnet at later rounds. School winners advance to a local ESU Branch competition, and Branch winners perform for judges at the national round in New York City in late April. Judges are professionals in Shakespeare studies, production or education, and props are not allowed." },
  // https://www.hsfilmfest.com/2026-festival-schedule/2026/10/18/2026-teen-indie-awards
  "all-american-high-school-film-festival": { blurb: "An annual national film festival for high school filmmakers, held each October in New York City and capped by the Teen Indie Awards at Kings Theatre in Brooklyn, where all festival winners are announced. Students submit their films for official selection, and winners receive prizes and scholarships. Past awards have included a full-tuition AMDA acting scholarship for actors 16 or older in an official selection film." },
  // https://payag.wildapricot.org/
  "ymca-pennsylvania-ymca-youth-and-government": { blurb: "A statewide student-run model government program run by the State YMCA of Pennsylvania and open to students in grades 7-12. Students take part as legislators, judges, attorneys, lobbyists or members of the press, researching current events and writing bills through the year. Regional pre-legislative sessions are held in the east and west, and the year ends with a Model Convention at the Harrisburg Hilton Hotel and the Pennsylvania State Capitol in April." },
  // https://www.ymcayag.org/ri/
  "ymca-rhode-island-ymca-youth-and-government": { blurb: "A model state government program for students in grades 9-12, run by the Rhode Island Council for the Social Studies in partnership with the YMCA. Delegations led by an adult advisor write bills, attend a Committee Day at a host high school, then debate at State House Day in March. The cost is $250 per school, need-based scholarships are available, and students can join the Northeast team at the national conference or the appellate track of the National Judicial Competition." },
  // https://www.ymcagreenville.org/programs/outreach-development/sc-youth-government
  "ymca-south-carolina-ymca-youth-and-government": { blurb: "A statewide civics program run by the YMCA of Greenville that teaches students how state and national government works through conferences and trainings. More than 1,600 high school students attend the four-day High School Model Legislature and Court in Columbia each November, after a Leadership Training Conference in October. The high school conference costs approximately $545 per delegate, and need-based scholarships are available." },
  // https://www.seattleymca.org/programs/youthprograms/washington-youth-government
  "ymca-washington-ymca-youth-and-government": { blurb: "A YMCA civics program in which students in grades 8-12 write bills and debate them at the statewide Youth Legislature conference in Olympia each May. The program also runs a Mock Trial competition where teams work with legal professionals on civil or criminal cases. Through the YMCA of Greater Seattle, delegation fees are $175 for Y members and $225 for community members, conference fees are $500, and financial assistance is available." },
  // https://hillmanacademy.upmc.com/about-us/
  "upmc-hillman-cancer-center-upmc-hillman-cancer-center-academy": { blurb: "An eight-week summer research program at UPMC Hillman Cancer Center where high school students, mostly rising juniors and seniors, do cancer research in faculty-led labs at 6-8 sites across the University of Pittsburgh campus. Students work on research up to 37 hours per week and finish with a ten-minute oral presentation and a poster symposium. Applicants must be at least 15 years old by the start date, and no application fee or tuition has been charged." },
  // https://hi.umn.edu/summer-scholar
  "the-hormel-institute-university-of-minnesota-high-school-summer": { blurb: "An eight-week, in-person biomedical research program at the Hormel Institute, University of Minnesota, in Austin, Minnesota. A cohort of three to four students works on site 25 hours per week, learning everyday lab tasks, doing research and data analysis, attending professional development sessions and presenting a research poster. Students entering grades 11-12 or just graduated, with a 3.5 GPA or higher, can apply, and a $3,000 stipend is offered." },
  // https://www.medschool.lsuhsc.edu/cancer_center/education-and-training/education-and-training-for-high-school-students.aspx
  "lsu-lcmc-health-cancer-center-cancer-center-summer-research-inte": { blurb: "A full-time, eight-week summer research internship at the LSU LCMC Health Cancer Center in New Orleans, where high school interns work in cancer research labs with mentors. Interns learn lab techniques and finish with a poster session or oral symposium. Applicants must live in or near the New Orleans area, be high school juniors or seniors aged 16-18 when they apply, and attend a mandatory all-day orientation." },
  // https://www.aacr.org/professionals/education-and-training/aacr-cares-high-school-scholars-program/
  "american-association-for-cancer-research-aacr-cares-high-school": { blurb: "A national program from the American Association for Cancer Research that places high school students in a six-week summer research experience at a host cancer research institution, followed by a year of AACR mentorship. Students apply through the host institution and must be at least 16 and a rising junior or senior. Selected students receive a $4,000 stipend and attend a virtual pre-summer orientation and a virtual post-summer mentoring program." },
  // https://www.arkbar.com/?pg=mocktrial
  "arkansas-bar-association-arkansas-high-school-mock-trial-competi": { blurb: "A statewide competition run by the Arkansas Bar Association in which high school teams act as lawyers and witnesses in simulated civil trials before judges and juries, with attorneys and judges serving as scoring and presiding judges. The state competition is a single-weekend, round-robin event in Little Rock, held in early March, where each team competes in four rounds over two days. The state champion goes on to the national competition." },
  // https://www.iowabar.org/?pg=HSMockTrial
  "iowa-state-bar-association-iowa-high-school-mock-trial-competiti": { blurb: "A statewide tournament run by the Iowa State Bar Association's Center for Law and Civic Education with the ISBA's Young Lawyers Division, which has run for 44 years. High school teams try a case at regional rounds in cities such as Coralville, Waterloo, Council Bluffs and Davenport, and top teams advance to a state tournament in Des Moines in the spring, whose winner goes to nationals. More than 1,600 students take part, and the fee is $225 per team." },
  // https://msbar.org/event/statewide-mock-trial-competition/
  "the-mississippi-bar-mississippi-high-school-mock-trial-competiti": { blurb: "A competition sponsored since 1983 by the Young Lawyers Division of The Mississippi Bar for students in grades 9-12. Teams of three attorneys, three witnesses and a timekeeper compete at Southern, Central and Northern regionals in Gulfport, Jackson and Oxford, and top teams advance to a four-round statewide competition at the Hinds County Courthouse in Jackson. Each team needs an attorney sponsor, and the registration fee is $50." },
  // https://www.nebarfnd.org/civics-education/mock-trial
  "nebraska-state-bar-foundation-nebraska-high-school-mock-trial-co": { blurb: "A statewide high school competition, the Judge Lyle Strom High School Mock Trial Program, run by the Nebraska State Bar Foundation. Teams try an original case written each year by Nebraska attorneys, alternating between criminal and civil, at regional and state levels, and the Foundation helps the state winner attend the national championship. More than 1,000 students and teachers take part each year, and more than 400 legal professionals volunteer as coaches and judges." },
  // https://www.sband.org/page/HighSchoolMockTrial
  "state-bar-association-of-north-dakota-north-dakota-high-school-m": { blurb: "A statewide mock trial competition run by the State Bar Association of North Dakota for students in grades 9 to 12, in teams of 6 to 9 students. Teams argue both sides of a hypothetical case under the rules of evidence and competition of the National High School Mock Trial Competition, and the state round is held at the Burleigh County Courthouse in Bismarck in March. Registration is free, and SBAND helps teams find an attorney coach." },
  // https://id.nhd.org/
  "national-history-day-idaho-history-day-state-contest": { blurb: "The Idaho contest of National History Day, run by the Idaho State Historical Society for students in grades 4-12 from public, private, tribal, parochial and home schools. Students present history research projects at regional contests in six areas of Idaho, and the top two winners in each category of each age division advance to the state contest, held in the spring, most recently at the College of Idaho in Caldwell." },
  // https://nhd.org/en/affiliates/kansas/
  "national-history-day-kansas-history-day-state-contest": { blurb: "The Kansas affiliate contest of National History Day, coordinated by the Kansas History Day Foundation, with district contests and a state contest held in April at Seaman Middle School in Topeka. Kansas History Day began in 1982 under the Kansas Historical Society, which sponsored it until 2009. Kansas students go on to compete at the national finals, held each June at the University of Maryland in College Park." },
  // https://tennesseehistory.org/tennessee-history-day/getting-started-2/
  "national-history-day-tennessee-history-day-state-contest": { blurb: "A statewide competition run since 2009 by the Tennessee Historical Society for students in grades six through twelve. Senior students enter individual or group documentaries, exhibits, performances, websites or papers at regional contests around the state, and winners move on to the state contest and then to National History Day in Washington, D.C. Special awards include a $100 prize for the best senior project that uses primary sources." },
  // https://www.tshaonline.org/handbook/entries/texas-history-day
  "national-history-day-texas-history-day-state-contest": { blurb: "The Texas State Historical Association's state contest for National History Day. Senior division students in grades 9-12 enter a paper, exhibit, performance, website or documentary, and those who place first or second at a regional fair compete at a one-day event each spring at the Bullock Texas State History Museum and the University of Texas at Austin. In 2025, more than 1,031 students took part, and 82 represented Texas at the national contest." },
  // https://history.utah.gov/utah-history-day/
  "national-history-day-utah-history-day-state-contest": { blurb: "The Utah contest of National History Day, run by the Utah Historical Society for students in grades 4-12, who compete at local and regional contests before the top projects advance to the state contest in April. The top two entries in each Junior and Senior division category qualify for the national contest in June. The 2026 state contest at Westminster University drew more than 5,000 students statewide, and the program dates to 1980." },
  // https://www.sdsmt.edu/events/education-outreach/summer-camps/index.html
  "south-dakota-school-of-mines-and-technology-stem-summer-camps-at": { blurb: "South Dakota Mines runs STEM summer day camps for high school students, several also open to recent graduates, on topics such as mining, aerospace, robotics, computer science, pre-med, geology and chemistry. Activities range from touring an active gold mine to visiting clinical facilities. Camps are open to local teens and non-residents alike, housing is not included, and some camps are free while others, such as Geology Rocks! and Pre-Med @ Mines, cost $350." },
  // https://www.quanthub.com/intern/
  "quanthub-alabama-data-scholars-internship": { blurb: "Alabama Data Scholars is a paid, part-time summer internship program from QuantHub, made possible through Innovate Alabama, that places Alabama students in data science and AI roles with employer organizations across the state. Internships last 8 weeks and can be virtual, hybrid or on-site. A recent cohort included 35 high school scholars and 15 undergraduate scholars, and 2025 participants received a $1,200 stipend." },
  // https://www.masshist.org/press/NHD2026
  "national-history-day-massachusetts-history-day-state-contest": { blurb: "The Massachusetts contest of National History Day, run by the Massachusetts Historical Society. Students in the senior division, grades 9-12, compete individually or in groups in five categories: research paper, exhibit, performance, documentary or website. Regional competitions lead to a state competition, and first and second place winners at the state level advance to nationals. In a recent year, 5,418 students throughout Massachusetts took part." },
  // https://mathprize.atfoundation.org/experience/faq
  "math-prize-for-girls": { blurb: "A free math contest held at MIT each fall by the Advantage Testing Foundation and Jane Street, with $100,000 in cash prizes, including $50,000 for first place. It is open to U.S. and Canadian girls in 11th grade or below who took an official AMC 10 or AMC 12 the previous November. A $2,000 Youth Prize goes to the top performer in 9th grade or below, and 25 other top scorers receive honorable mention trophies." },
};

